-- Mental Health question bank: exactly 1050 hand-written NCLEX-style
-- questions (single-best-answer + select-all-that-apply), 50 per note. Every answer is grounded in
-- (and its rationale limited to) the source note listed for its topic:
--   Notes/MentalHealth/Legal-Ethical-Safety.html
--   Notes/MentalHealth/ECT.html
--   Notes/MentalHealth/Serotonin-Syndrome.html
--   Notes/MentalHealth/Parenting-Styles.html
--   Notes/MentalHealth/Mental-Health-Medications.html
--   Notes/MentalHealth/Guided-Imagery.html
--   Notes/MentalHealth/Core-Ethical-Principles.html
--   Notes/MentalHealth/Defense-Mechanisms.html
--   Notes/MentalHealth/Family-Systems-Theory.html
--   Notes/MentalHealth/Suicide-Risk-Assessment.html
--   Notes/MentalHealth/Delirium-Depression-Dementia.html
--   Notes/MentalHealth/Mental-Health-Overview.html
--   Notes/MentalHealth/Therapeutic-Relationships.html
--   Notes/MentalHealth/Personality-Disorders.html
--   Notes/MentalHealth/Anxiety-Disorders.html
--   Notes/MentalHealth/Eating-Disorders.html
--   Notes/MentalHealth/Substance-Abuse-Addiction.html
--   Notes/MentalHealth/Bipolar-Personality-Disorders.html
--   Notes/MentalHealth/Schizophrenia.html
--   Notes/MentalHealth/Cognitive-Impairments-ADHD.html
--   Notes/MentalHealth/Alzheimers-Disease.html
--
-- Maps each source path through note_catalog.note_id to the published test_topics
-- row(s) for that note (matching test.html's note-level topic grouping). All
-- missing/ambiguous mappings are reported before any deletion or insertion.
-- Safe to rerun: only rows carrying this script's category labels are replaced,
-- and the transaction aborts unless exactly 50 rows per topic (1050) exist after insert.
BEGIN;

CREATE TEMP TABLE _mh_sources (
  source_key text PRIMARY KEY,
  source_path text NOT NULL UNIQUE,
  category text NOT NULL UNIQUE
) ON COMMIT DROP;

INSERT INTO _mh_sources (source_key, source_path, category) VALUES
  ('legal', 'Notes/MentalHealth/Legal-Ethical-Safety.html', 'Mental Health NCLEX seed v1 - legal ethical safety'),
  ('ect', 'Notes/MentalHealth/ECT.html', 'Mental Health NCLEX seed v1 - ect'),
  ('serotonin', 'Notes/MentalHealth/Serotonin-Syndrome.html', 'Mental Health NCLEX seed v1 - serotonin syndrome'),
  ('parenting', 'Notes/MentalHealth/Parenting-Styles.html', 'Mental Health NCLEX seed v1 - parenting styles'),
  ('meds', 'Notes/MentalHealth/Mental-Health-Medications.html', 'Mental Health NCLEX seed v1 - mental health medications'),
  ('imagery', 'Notes/MentalHealth/Guided-Imagery.html', 'Mental Health NCLEX seed v1 - guided imagery'),
  ('ethics', 'Notes/MentalHealth/Core-Ethical-Principles.html', 'Mental Health NCLEX seed v1 - core ethical principles'),
  ('defense', 'Notes/MentalHealth/Defense-Mechanisms.html', 'Mental Health NCLEX seed v1 - defense mechanisms'),
  ('family', 'Notes/MentalHealth/Family-Systems-Theory.html', 'Mental Health NCLEX seed v1 - family systems theory'),
  ('suicide', 'Notes/MentalHealth/Suicide-Risk-Assessment.html', 'Mental Health NCLEX seed v1 - suicide risk assessment'),
  ('ddd', 'Notes/MentalHealth/Delirium-Depression-Dementia.html', 'Mental Health NCLEX seed v1 - delirium depression dementia'),
  ('overview', 'Notes/MentalHealth/Mental-Health-Overview.html', 'Mental Health NCLEX seed v1 - mental health overview'),
  ('therapeutic', 'Notes/MentalHealth/Therapeutic-Relationships.html', 'Mental Health NCLEX seed v1 - therapeutic relationships'),
  ('personality', 'Notes/MentalHealth/Personality-Disorders.html', 'Mental Health NCLEX seed v1 - personality disorders'),
  ('anxiety', 'Notes/MentalHealth/Anxiety-Disorders.html', 'Mental Health NCLEX seed v1 - anxiety disorders'),
  ('eating', 'Notes/MentalHealth/Eating-Disorders.html', 'Mental Health NCLEX seed v1 - eating disorders'),
  ('substance', 'Notes/MentalHealth/Substance-Abuse-Addiction.html', 'Mental Health NCLEX seed v1 - substance abuse addiction'),
  ('bipolar', 'Notes/MentalHealth/Bipolar-Personality-Disorders.html', 'Mental Health NCLEX seed v1 - bipolar personality disorders'),
  ('schizophrenia', 'Notes/MentalHealth/Schizophrenia.html', 'Mental Health NCLEX seed v1 - schizophrenia'),
  ('cognitive', 'Notes/MentalHealth/Cognitive-Impairments-ADHD.html', 'Mental Health NCLEX seed v1 - cognitive impairments adhd'),
  ('alzheimers', 'Notes/MentalHealth/Alzheimers-Disease.html', 'Mental Health NCLEX seed v1 - alzheimers disease');

CREATE TEMP TABLE _mh_seed_map (
  source_key text PRIMARY KEY,
  source_path text NOT NULL,
  category text NOT NULL,
  note_id uuid NOT NULL,
  note_title text NOT NULL,
  topic_id uuid NOT NULL,
  topic_aliases text[] NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE _mh_seed_config (test_id bigint NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  v_subject_id uuid;
  v_subject_count integer;
  v_note_count integer;
  v_topic_count integer;
  v_note_id uuid;
  v_note_title text;
  v_topic_id uuid;
  v_aliases text[];
  v_test_id bigint;
  v_errors text[] := ARRAY[]::text[];
  r record;
BEGIN
  SELECT count(*)
    INTO v_subject_count
    FROM test_subjects
   WHERE lower(btrim(name)) = 'mental health'
     AND is_active = true;
  IF v_subject_count <> 1 THEN
    v_errors := array_append(v_errors,
      format('Expected exactly one active test_subjects row named "Mental Health"; found %s.', v_subject_count));
  ELSE
    SELECT id INTO v_subject_id
      FROM test_subjects
     WHERE lower(btrim(name)) = 'mental health'
       AND is_active = true;
  END IF;

  SELECT id INTO v_test_id
    FROM tests
   WHERE is_active = true
   ORDER BY id
   LIMIT 1;
  IF v_test_id IS NULL THEN
    v_errors := array_append(v_errors, 'No active tests row is available for test_questions.test_id.');
  END IF;

  FOR r IN SELECT source_key, source_path, category FROM _mh_sources ORDER BY source_key LOOP
    SELECT count(*)
      INTO v_note_count
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_note_count = 0 THEN
      v_errors := array_append(v_errors,
        format('Missing active note_catalog mapping for %s.', r.source_path));
      CONTINUE;
    ELSIF v_note_count > 1 THEN
      v_errors := array_append(v_errors,
        format('Ambiguous active note_catalog mapping for %s (%s rows).', r.source_path, v_note_count));
      CONTINUE;
    END IF;

    SELECT note_id, title
      INTO v_note_id, v_note_title
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_subject_count <> 1 THEN
      v_errors := array_append(v_errors,
        format('Cannot resolve test_topics aliases for %s because the active Mental Health subject mapping is not unique.',
               r.source_path));
      CONTINUE;
    END IF;

    SELECT count(*)
      INTO v_topic_count
      FROM test_topics
     WHERE subject_id = v_subject_id
       AND note_id = v_note_id
       AND (status = 'published' OR status IS NULL);

    IF v_topic_count = 0 THEN
      v_errors := array_append(v_errors,
        format('No published test_topics row in Mental Health points to note %s (%s).',
               v_note_title, r.source_path));
      CONTINUE;
    END IF;

    -- Sibling topics are expected aliases in test.html's note-level merged row.
    -- Insert all 50 for this source under one deterministic sibling topic_id.
    SELECT t.id
      INTO v_topic_id
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL)
     ORDER BY t.display_order NULLS LAST, t.created_at, t.name, t.id
     LIMIT 1;

    -- Collect the actual underlying aliases for the mapping check/report context.
    SELECT array_agg(t.name ORDER BY t.display_order NULLS LAST, t.name, t.id)
      INTO v_aliases
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL);

    INSERT INTO _mh_seed_map
      (source_key, source_path, category, note_id, note_title, topic_id, topic_aliases)
    VALUES
      (r.source_key, r.source_path, r.category, v_note_id, v_note_title, v_topic_id, v_aliases);
  END LOOP;

  IF cardinality(v_errors) > 0 THEN
    RAISE EXCEPTION E'Mental Health seed mapping validation failed before any deletion/insertion:\n - %',
      array_to_string(v_errors, E'\n - ');
  END IF;

  IF (SELECT count(*) FROM _mh_seed_map) <> 21 THEN
    RAISE EXCEPTION 'Internal mapping check failed: expected 21 note mappings, found %.',
      (SELECT count(*) FROM _mh_seed_map);
  END IF;

  INSERT INTO _mh_seed_config (test_id) VALUES (v_test_id);
END $$;

-- Only rows from this script's unique category names are replaced.
DELETE FROM test_questions q
 USING _mh_seed_map m
 WHERE q.category = m.category;

INSERT INTO test_questions
  (test_id, topic_id, question, question_stem, options, correct_answer, rationale,
   category, is_multiple_choice, display_order, points, is_active)
SELECT c.test_id, m.topic_id, v.stem, v.stem, v.options, v.correct_answer, v.rationale,
       m.category, v.is_multi, v.display_order, 1, true
  FROM (VALUES
  ('legal', 1, 'A patient who signed in voluntarily 3 days ago for depression tells the nurse, "I want to go home today." The patient denies suicidal or homicidal thoughts and is eating and sleeping well. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"You can request discharge at any time; I''ll let your provider know.\""}, {"id": "b", "text": "\"Because you signed in yourself, you must stay for at least 72 hours.\""}, {"id": "c", "text": "\"You will need a court hearing before you are allowed to leave here.\""}, {"id": "d", "text": "\"Once admitted, patients lose the right to decide about their discharge.\""}]'::jsonb, '["a"]', 'A voluntary patient chose to be admitted and can request discharge at any time as a competent decision-maker. The 72-hour limit applies to emergency involuntary holds, and a legal process is required for long-term involuntary commitment, not for a voluntary patient''s discharge request.', false),
  ('legal', 2, 'The nurse in a psychiatric emergency service reviews five patients who are refusing admission. Which patients meet criteria for involuntary admission? Select all that apply.', '[{"id": "a", "text": "Cannot meet basic needs for food due to psychosis"}, {"id": "b", "text": "Is a danger to others after threatening a neighbor"}, {"id": "c", "text": "Refuses medication but is eating, working, and safe"}, {"id": "d", "text": "Remains a danger to self after attempting suicide"}, {"id": "e", "text": "Holds unusual beliefs but lives safely and pays bills"}]'::jsonb, '["a", "b", "d"]', 'Involuntary commitment requires danger to others (b), danger to self (d), or grave disability, meaning the person cannot meet basic needs (a). Refusing medication while safe (c) reflects the right to refuse treatment, and unusual beliefs in a person who lives safely (e) meet none of the three criteria.', true),
  ('legal', 3, 'Police bring a 50-year-old man with schizophrenia to the emergency department in January. He has been living in an unheated shed, has not eaten in several days, and denies thoughts of harming himself or others. He refuses admission. Which conclusion by the nurse is MOST accurate?', '[{"id": "a", "text": "He cannot be held involuntarily because he denies danger to self or others"}, {"id": "b", "text": "He may meet involuntary admission criteria because of grave disability"}, {"id": "c", "text": "He meets criteria only if he also has a documented history of violence"}, {"id": "d", "text": "He can be held after he agrees to take medication in the department"}]'::jsonb, '["b"]', 'Grave disability, being unable to meet basic needs such as food and shelter, is one of the three criteria for involuntary commitment, along with danger to self and danger to others. Denying thoughts of harm does not rule out commitment when grave disability is present.', false),
  ('legal', 4, 'A patient on a 72-hour involuntary hold angrily demands to call a lawyer to challenge the hold. A staff member tells him, "Involuntary patients can''t make calls until the hold ends." Which response by the nurse to the patient is BEST?', '[{"id": "a", "text": "\"You may consult an attorney at any time, even while on this hold.\""}, {"id": "b", "text": "\"You''ll be able to call a lawyer after the 72-hour hold is over.\""}, {"id": "c", "text": "\"Calls to a lawyer need approval from the court that ordered the hold.\""}, {"id": "d", "text": "\"We can call a lawyer for you if you first agree to stay voluntarily.\""}]'::jsonb, '["a"]', 'Patients have the right to legal counsel and may consult an attorney at any time, and patient rights remain intact even under an involuntary hold. Delaying the call or making it conditional on voluntary status violates that right.', false),
  ('legal', 5, 'A competent adult patient admitted voluntarily for depression refuses a scheduled dose of her oral antidepressant, stating she dislikes how it makes her feel. She is calm and denies any thoughts of harm. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Request an order for an IM dose, because she is refusing treatment"}, {"id": "b", "text": "Give the dose mixed in applesauce so that she receives her treatment"}, {"id": "c", "text": "Respect the refusal, since competent adults can decline medication"}, {"id": "d", "text": "Tell her she must take it while admitted or she will be discharged"}]'::jsonb, '["c"]', 'Competent adults have the right to refuse treatment and can decline medication; the only exception is immediate danger, which is not present. An IM dose or hidden medication would override her right to refuse.', false),
  ('legal', 6, 'A patient on an involuntary hold has refused all medications for 2 days. Today he throws a chair at a staff member and keeps swinging at anyone nearby despite verbal de-escalation and an offer of oral PRN medication. Which statement about his right to refuse treatment is MOST accurate?', '[{"id": "a", "text": "His refusal must be honored, since competent adults can decline medication"}, {"id": "b", "text": "Involuntary patients lose the right to refuse treatment once they are admitted"}, {"id": "c", "text": "He may be medicated only after a court hearing about his refusal of treatment"}, {"id": "d", "text": "Immediate danger is the exception, so IM medication may be given as ordered"}]'::jsonb, '["d"]', 'The right to refuse treatment has an exception for immediate danger, and chemical restraint (IM medication) is used when the patient is a danger after less restrictive measures fail. Involuntary patients do not lose their rights simply by being admitted, so the refusal mattered until the danger arose.', false),
  ('legal', 7, 'A 24-year-old patient admitted on a 72-hour emergency hold after threatening suicide asks the nurse, "Can they just keep me here for a month until I''m better?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Yes, the unit staff can extend the emergency hold as long as needed.\""}, {"id": "b", "text": "\"Only if you agree, because involuntary holds end after 24 hours.\""}, {"id": "c", "text": "\"Long-term commitment requires a legal process beyond this hold.\""}, {"id": "d", "text": "\"Yes, your parents may sign to extend the hold for as long as needed.\""}]'::jsonb, '["c"]', 'An involuntary emergency hold can be up to 72 hours, and long-term commitment requires a legal process. Staff or family cannot simply extend the hold, and emergency holds are not limited to 24 hours.', false),
  ('legal', 8, 'The mother of a 26-year-old patient on the psychiatric unit calls and says, "I''m his mother and I pay his bills. I need to know what medications he''s taking." The patient has not signed a release. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Since you''re his parent, I can share his medication list with you.\""}, {"id": "b", "text": "\"I can confirm his diagnosis, but not the medications he is taking.\""}, {"id": "c", "text": "\"I''ll share it if you can verify his date of birth and home address.\""}, {"id": "d", "text": "\"I can''t share any information without his written consent.\""}]'::jsonb, '["d"]', 'Information cannot be shared without written consent, and this includes information to family, even parents of adult patients. Confirming the diagnosis or verifying identity does not replace the patient''s written consent.', false),
  ('legal', 9, 'A patient tells the nurse, "I''m going to kill my ex-wife, Lisa, when I get out Friday. I know where she works. But you can''t tell anyone; this is confidential." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"A threat against an identifiable person must be shared to protect her.\""}, {"id": "b", "text": "\"You''re right; anything you tell me stays confidential under HIPAA.\""}, {"id": "c", "text": "\"I''ll keep it private if you promise not to act on these feelings.\""}, {"id": "d", "text": "\"I''ll share it only if you are still angry on the day of your discharge.\""}]'::jsonb, '["a"]', 'Under the Tarasoff rule, a specific, credible threat against an identifiable person creates a duty to warn the potential victim and notify law enforcement; confidentiality yields to public safety. Promising secrecy or delaying disclosure leaves the identified person unprotected.', false),
  ('legal', 10, 'An adult patient with mania is shouting and kicking chairs but has not harmed anyone. The nurse plans care using the least restrictive approach. Which interventions should the nurse try BEFORE a show of force? Select all that apply.', '[{"id": "a", "text": "IM medication as a chemical restraint"}, {"id": "b", "text": "Voluntary room restriction to a quiet area"}, {"id": "c", "text": "Verbal de-escalation with open body language"}, {"id": "d", "text": "A physical hold by trained staff members"}, {"id": "e", "text": "Voluntary oral PRN medication"}]'::jsonb, '["b", "c", "e"]', 'The least restrictive sequence is verbal de-escalation (c), voluntary oral PRN medication (e), and voluntary room restriction or a quiet area (b), followed by a show of force. Physical holds (d) and chemical restraint with IM medication (a) come after a show of force and are reserved for greater danger.', true),
  ('legal', 11, 'During a unit meeting, a new nurse asks about a patient who yelled, "Everyone in this place is going to be sorry!" after a pass was denied. He named no person, has no plan, and calmed after talking with staff. Which response by the charge nurse about the duty to warn is BEST?', '[{"id": "a", "text": "\"No; it requires a specific, credible threat to an identifiable person.\""}, {"id": "b", "text": "\"Yes, any angry statement requires warning the staff and law enforcement.\""}, {"id": "c", "text": "\"Yes, but only the patient''s family needs to be warned about his anger.\""}, {"id": "d", "text": "\"No, the duty to warn applies just to patients on an involuntary hold.\""}]'::jsonb, '["a"]', 'The Tarasoff duty to warn applies when a patient makes a specific, credible threat against an identifiable person. A general angry statement with no named target or plan does not meet this standard, and the duty is not limited to involuntary patients.', false),
  ('legal', 12, 'On a busy day, the nurse on an adult psychiatric unit receives four requests for information about a patient who has not signed any release. Which request is the nurse MOST clearly permitted to honor?', '[{"id": "a", "text": "Court-ordered disclosure of the patient''s treatment records"}, {"id": "b", "text": "The patient''s father asking for her diagnosis and her medication list"}, {"id": "c", "text": "The patient''s employer asking for her expected return-to-work date"}, {"id": "d", "text": "A coworker asking whether she is a patient on the unit this week"}]'::jsonb, '["a"]', 'Court-ordered disclosure is one of the situations in which information can be shared without consent. Employer requests and information to family, even parents of adults, cannot be shared without written consent.', false),
  ('legal', 13, 'A patient admitted for alcohol detoxification tells the nurse, "If my boss finds out I''m in rehab, I''ll lose my job." Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Your employer can get your records if he calls and asks the unit staff directly.\""}, {"id": "b", "text": "\"Records from detox have the same protection as any other medical record.\""}, {"id": "c", "text": "\"We are required to notify an employer when a patient enters treatment.\""}, {"id": "d", "text": "\"Substance abuse records have extra protection and need written consent.\""}]'::jsonb, '["d"]', 'Employer requests cannot be honored without written consent, and substance abuse records carry extra confidentiality protection under 42 CFR Part 2. Saying detox records have the same protection as other records understates that added protection.', false),
  ('legal', 14, 'The nurse observes a UAP caring for an adult patient in 4-point restraints after an assault on staff. Which actions by the UAP require follow-up? Select all that apply.', '[{"id": "a", "text": "Checks on the patient every 15 minutes"}, {"id": "b", "text": "Ties the straps to the bed''s side rails"}, {"id": "c", "text": "Checks circulation in the hands and feet"}, {"id": "d", "text": "Places the patient in a prone position"}, {"id": "e", "text": "Offers the patient water and the bathroom"}]'::jsonb, '["b", "d"]', 'Restraints are tied to a fixed part of the bed frame, not side rails (b), and prone restraint is never used because of aspiration/asphyxiation risk (d). Checking circulation (c), offering water and the bathroom (e), and checking every 15 minutes (a) are expected restraint care.', true),
  ('legal', 15, 'A home health nurse visits an 82-year-old patient with dementia who lives with her son. The nurse finds bruises on both upper arms, soiled bedding, and no food in the home. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Report the findings to Child Protective Services as a family matter"}, {"id": "b", "text": "Report suspected elder abuse or neglect to Adult Protective Services"}, {"id": "c", "text": "Wait to report until the son has confirmed how the bruises happened"}, {"id": "d", "text": "Notify only the state health department about the living conditions"}]'::jsonb, '["b"]', 'Elder abuse or neglect must be reported, and the report goes to Adult Protective Services. Child Protective Services handles child abuse, the state health department receives communicable disease reports, and suspicion is enough to report.', false),
  ('legal', 16, 'A 19-year-old patient is treated in the emergency department for a gunshot wound to the leg. He begs the nurse, "Please don''t call the police; I''ll get in trouble." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"I''ll keep it confidential, since you are an adult and did not consent.\""}, {"id": "b", "text": "\"I can only report it if you sign a written consent form for the police.\""}, {"id": "c", "text": "\"I would report it if you had shot yourself, but not otherwise.\""}, {"id": "d", "text": "\"Gunshot wounds must be reported to law enforcement, even if you ask.\""}]'::jsonb, '["d"]', 'Gunshot wounds are on the list of mandatory reports, and law enforcement receives reports as required. Mandatory reports do not depend on the patient''s consent or on how the wound happened.', false),
  ('legal', 17, 'While treating a 6-year-old for a fractured arm, the nurse notices bruises in different stages of healing on the child''s back. The father says the child is "just clumsy," which the nurse doubts. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Report the suspected abuse to Child Protective Services"}, {"id": "b", "text": "Wait until the abuse is confirmed before making a report"}, {"id": "c", "text": "Report the findings to Adult Protective Services for review"}, {"id": "d", "text": "Ask the father for written consent before sharing findings"}]'::jsonb, '["a"]', 'Suspected child abuse or neglect must be reported to Child Protective Services; the nurse does not need proof. Adult Protective Services handles elder abuse, and mandatory reports do not require consent.', false),
  ('legal', 18, 'A patient admitted on a 72-hour involuntary hold asks the nurse, "What rights do I still have while I''m locked up in here?" Which rights should the nurse include in the response? Select all that apply.', '[{"id": "a", "text": "Consult an attorney at any time"}, {"id": "b", "text": "Request discharge at any time"}, {"id": "c", "text": "Send and receive mail and make phone calls"}, {"id": "d", "text": "Vote, because institutionalization does not remove it"}, {"id": "e", "text": "Decline medication unless there is immediate danger"}]'::jsonb, '["a", "c", "d", "e"]', 'Patient rights remain intact even under an involuntary hold, including legal counsel (a), communication by mail and phone (c), voting (d), and refusing treatment except in immediate danger (e). Requesting discharge at any time (b) belongs to voluntary admission, not an involuntary hold.', true),
  ('legal', 19, 'A patient with bipolar disorder is pacing the hallway, speaking loudly, and clenching his fists after a tense phone call. He has not struck or threatened anyone. Which intervention should the nurse use FIRST?', '[{"id": "a", "text": "Offer an IM PRN medication to calm him quickly"}, {"id": "b", "text": "Gather several staff around him as a show of force"}, {"id": "c", "text": "Escort him to his room and keep him there until calm"}, {"id": "d", "text": "Verbal de-escalation with a calm tone and choices"}]'::jsonb, '["d"]', 'The least restrictive intervention is used first, and verbal de-escalation with a calm tone, open body language, and choices is the first step. IM medication is chemical restraint, and a show of force or enforced room restriction is more restrictive than needed.', false),
  ('legal', 20, 'A nurse is planning care for a patient whose agitation is escalating on the unit. Which sequence of interventions reflects the least restrictive approach, from FIRST to last?', '[{"id": "a", "text": "Verbal de-escalation, show of force, oral PRN, physical hold, then quiet area"}, {"id": "b", "text": "Oral PRN, verbal de-escalation, physical hold, quiet area, show of force"}, {"id": "c", "text": "Verbal de-escalation, oral PRN, quiet area, show of force, physical hold"}, {"id": "d", "text": "Quiet area, verbal de-escalation, physical hold, show of force, oral PRN"}]'::jsonb, '["c"]', 'The escalation order is verbal de-escalation, voluntary oral PRN medication, voluntary room restriction/quiet area, show of force, and then physical holds as the last resort before restraints. The other sequences place more restrictive steps ahead of less restrictive ones.', false),
  ('legal', 21, 'An adult patient who punched a peer has been placed in restraints after less restrictive measures failed. The nurse is completing the required documentation. Which information must the nurse include? Select all that apply.', '[{"id": "a", "text": "Less restrictive alternatives tried"}, {"id": "b", "text": "That staffing was too short for alternatives"}, {"id": "c", "text": "The patient''s response to restraint"}, {"id": "d", "text": "The behavior that required restraint"}, {"id": "e", "text": "That restraint was the consequence for hitting"}]'::jsonb, '["a", "c", "d"]', 'Documentation includes the behavior requiring restraint (d), less restrictive alternatives tried (a), and the patient''s response (c). Restraints are never used as punishment (e) or for staff convenience (b), so these are not valid entries.', true),
  ('legal', 22, 'A 15-year-old patient was placed in restraints at 1400 with a valid order after assaulting a peer. At 1545 the patient is still kicking and spitting at staff and remains a danger to others. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Obtain a renewed order before 1600 if restraint is still needed"}, {"id": "b", "text": "Continue the restraints until 1800, when the current order expires"}, {"id": "c", "text": "Release the restraints now, since adolescents need hourly renewal"}, {"id": "d", "text": "No renewal is needed once the 1-hour in-person evaluation is done"}]'::jsonb, '["a"]', 'Restraint orders for patients 9–17 years old are renewed every 2 hours, so an order applied at 1400 must be renewed by 1600. The 4-hour interval (1800) applies to adults, hourly renewal applies to children under 9, and the in-person evaluation does not replace order renewal.', false),
  ('legal', 23, 'An adult patient was placed in restraints at 0915 after attacking a staff member, and the nurse is planning the next hour of care. Which requirement is the PRIORITY to complete by 1015?', '[{"id": "a", "text": "Renewal of the restraint order"}, {"id": "b", "text": "Trial release of one limb"}, {"id": "c", "text": "In-person evaluation of the patient"}, {"id": "d", "text": "Transfer of the patient to seclusion"}]'::jsonb, '["c"]', 'An in-person evaluation is required within 1 hour of restraint application, so it is due by 1015. For adults the order is renewed every 4 hours, so renewal is not due until 1315.', false),
  ('legal', 24, 'The charge nurse audits records for five patients who stayed in restraints because they remained a danger. Which order renewals followed the required schedule? Select all that apply.', '[{"id": "a", "text": "A 35-year-old whose order was renewed every 4 hours"}, {"id": "b", "text": "A 12-year-old whose order was renewed every 2 hours"}, {"id": "c", "text": "An 8-year-old whose order was renewed every 2 hours"}, {"id": "d", "text": "A 17-year-old whose order was renewed every 4 hours"}, {"id": "e", "text": "A 6-year-old whose order was renewed every 1 hour"}]'::jsonb, '["a", "b", "e"]', 'Orders are renewed every 4 hours for adults (a), every 2 hours for ages 9–17 (b), and every 1 hour for children under 9 (e). The 8-year-old (c) needed hourly renewal, and the 17-year-old (d) needed renewal every 2 hours, not 4.', true),
  ('legal', 25, 'A UAP caring for an adult patient in 4-point restraints reports, "I''ve been checking on him every 30 minutes, and his hands look fine." Which instruction by the nurse is BEST?', '[{"id": "a", "text": "\"Checking every 30 minutes is fine as long as his hands look pink and warm.\""}, {"id": "b", "text": "\"Check every 15 minutes: circulation, breathing, ROM, and hygiene.\""}, {"id": "c", "text": "\"Checking once an hour is enough while the patient is sleeping.\""}, {"id": "d", "text": "\"Only nurses check restraints, so you no longer need to look in.\""}]'::jsonb, '["b"]', 'A patient in restraints is monitored every 15 minutes minimum, including circulation, breathing, ROM, and hygiene. Checks every 30 or 60 minutes are too infrequent, and looking at the hands alone misses breathing, ROM, and hygiene.', false),
  ('legal', 26, 'While restraints are being applied to a combative adult patient, a staff member holds the patient face down on the mattress and says, "Let''s restrain him like this so he can''t kick." Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Stop the prone restraint because of the aspiration and asphyxiation risk"}, {"id": "b", "text": "Allow the position briefly because the patient is a danger to others"}, {"id": "c", "text": "Continue as planned, but check his breathing every 15 minutes"}, {"id": "d", "text": "Ask the staff to secure the restraints to the bed''s side rails more quickly"}]'::jsonb, '["a"]', 'Prone restraint is never used because of aspiration and asphyxiation risk, so the nurse stops it immediately. Danger to others justifies restraint but not the prone position, and side rails are not used to secure restraints.', false),
  ('legal', 27, 'An adult patient who was restrained for assaulting staff has now been calm for 30 minutes and no longer poses a danger. Which actions should the nurse take when releasing the restraints? Select all that apply.', '[{"id": "a", "text": "Wait for the order to expire first"}, {"id": "b", "text": "Position the patient prone to rest"}, {"id": "c", "text": "Offer food, water, and the bathroom"}, {"id": "d", "text": "Keep one wrist restrained for an hour"}, {"id": "e", "text": "Assess the skin under the restraints"}]'::jsonb, '["c", "e"]', 'At release, the nurse offers food, water, and the bathroom (c) and assesses the skin (e). Restraints are removed as soon as the patient is calm and no longer a danger, not partially (d) or after the order expires (a), and the prone position (b) is never used because of aspiration/asphyxiation risk.', true),
  ('legal', 28, 'An adult patient restrained 2 hours ago for assaulting a peer has been calm for 45 minutes, follows directions, and asks to be released. The current order is valid for 2 more hours. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Keep the restraints on until the order expires to prevent a relapse"}, {"id": "b", "text": "Release one limb each hour to see whether the patient stays calm"}, {"id": "c", "text": "Ask the provider to renew the order so he stays restrained overnight"}, {"id": "d", "text": "Release the patient now that he is calm and no longer a danger"}]'::jsonb, '["d"]', 'Restraints are released as soon as the patient is calm and no longer a danger, regardless of the time left on the order. Keeping them on to prevent relapse or overnight would be restraint without immediate danger.', false),
  ('legal', 29, 'On a night shift with two staff out sick, a nurse says, "Let''s leave the patient in Room 4 in restraints until morning so we can keep up with everyone else." The patient has been calm and cooperative for an hour. Which response by the charge nurse is BEST?', '[{"id": "a", "text": "\"Restraints are never used for staff convenience; release the patient.\""}, {"id": "b", "text": "\"That''s reasonable as long as we check the patient every 15 minutes.\""}, {"id": "c", "text": "\"We can keep them on if the provider renews the order before midnight.\""}, {"id": "d", "text": "\"Let''s switch to a physical hold instead, since it is less restrictive.\""}]'::jsonb, '["a"]', 'Restraints are NEVER used as punishment or for staff convenience, and a calm patient who is no longer a danger is released. Frequent checks or a renewed order do not make convenience restraint acceptable.', false),
  ('legal', 30, 'A nurse is deciding whether restraints may be used for a patient with mania who is throwing furniture at peers. Which conditions must be present before restraints are applied? Select all that apply.', '[{"id": "a", "text": "Patient is an immediate danger to self or others"}, {"id": "b", "text": "Staff are too busy to provide close supervision"}, {"id": "c", "text": "Less restrictive measures have failed or are not feasible"}, {"id": "d", "text": "Patient needs a consequence for breaking unit rules"}, {"id": "e", "text": "Ordered by a physician or licensed independent practitioner"}]'::jsonb, '["a", "c", "e"]', 'Restraints are used only when the patient is an immediate danger to self or others (a), less restrictive measures have failed or are not feasible (c), and there is an order from a physician or licensed independent practitioner (e). Staff convenience (b) and punishment (d) are never reasons for restraint.', true),
  ('legal', 31, 'A patient curses loudly at the nurse after being told visiting hours have ended. He stays seated, makes no threats, and has not harmed anyone. A staff member suggests placing him in restraints. Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "\"Restraints are appropriate because he is upsetting the other patients.\""}, {"id": "b", "text": "\"We can restrain him if the provider gives an order within the hour.\""}, {"id": "c", "text": "\"Restraints require an immediate danger to self or others.\""}, {"id": "d", "text": "\"Restraints are fine as long as we monitor him every 15 minutes.\""}]'::jsonb, '["c"]', 'Restraints are used only when the patient is an immediate danger to self or others and less restrictive measures have failed. Cursing without threats or harm does not meet that standard, so an order or frequent monitoring would not make restraint appropriate.', false),
  ('legal', 32, 'A nurse is observing a newly hired nurse secure a combative adult patient''s wrist restraints to the bed. Which action by the new nurse requires IMMEDIATE correction?', '[{"id": "a", "text": "Tying the straps to a fixed part of the bed frame"}, {"id": "b", "text": "Checking circulation after applying the restraints"}, {"id": "c", "text": "Tying the restraint without a quick-release knot or clip"}, {"id": "d", "text": "Keeping the patient supine rather than in a prone position"}]'::jsonb, '["c"]', 'Restraints must be secured with a quick-release knot or quick-release clip only. Tying to a fixed part of the bed frame, checking circulation, and avoiding prone restraint are all correct practices.', false),
  ('legal', 33, 'An 8-year-old child on a pediatric psychiatric unit is placed in restraints at 1015 with a valid order after repeatedly banging his head against a wall. He remains a danger to himself. By which time is the NEXT order renewal required?', '[{"id": "a", "text": "1045"}, {"id": "b", "text": "1115"}, {"id": "c", "text": "1215"}, {"id": "d", "text": "1415"}]'::jsonb, '["b"]', 'Restraint orders for children under 9 years are renewed every 1 hour, so a 1015 application needs renewal by 1115. 1215 reflects the 2-hour interval for ages 9–17, and 1415 the 4-hour interval for adults.', false),
  ('legal', 34, 'During one emergency department shift, the nurse cares for the following patients. Which situations require the nurse to make a mandatory report? Select all that apply.', '[{"id": "a", "text": "An adult with schizophrenia asking for discharge"}, {"id": "b", "text": "A 4-year-old with suspected neglect"}, {"id": "c", "text": "An adult with depression refusing medication"}, {"id": "d", "text": "An adult who discloses past cocaine use"}, {"id": "e", "text": "A teen with a gunshot wound to the arm"}]'::jsonb, '["b", "e"]', 'Suspected child abuse or neglect (b) and gunshot wounds (e) are mandatory reports. A competent adult refusing medication (c) is exercising a right, substance use history (d) has extra confidentiality protection, and a discharge request (a) is not a reportable event.', true),
  ('legal', 35, 'During environmental rounds on a unit that has several patients at risk for suicide, the nurse notes the following. Which finding requires IMMEDIATE follow-up?', '[{"id": "a", "text": "Patients eating lunch with plastic utensils"}, {"id": "b", "text": "A stairwell door left unlocked"}, {"id": "c", "text": "Non-breakable mirrors installed in bathrooms"}, {"id": "d", "text": "Shoelaces removed from a new patient''s shoes"}]'::jsonb, '["b"]', 'A safe environment requires locked doors to stairwells, exits, and outdoor areas, so an unlocked stairwell door is an immediate hazard. Plastic utensils, non-breakable fixtures, and removing shoelaces are all expected safety measures.', false),
  ('legal', 36, 'Over one week, the nurse on an adult psychiatric unit encounters the following situations involving patients who have not signed any release. In which situations may the nurse share information without the patient''s written consent? Select all that apply.', '[{"id": "a", "text": "Court-ordered disclosure of a patient''s records"}, {"id": "b", "text": "An adult patient''s father asking about her diagnosis"}, {"id": "c", "text": "Reporting a patient''s communicable disease"}, {"id": "d", "text": "An employer asking when a patient can return to work"}, {"id": "e", "text": "Mandatory reporting of suspected elder abuse"}]'::jsonb, '["a", "c", "e"]', 'Information can be shared without consent for court-ordered disclosure (a), communicable disease reporting (c), and mandatory child/elder abuse reporting (e). Information to family, even parents of adults (b), and employer requests (d) cannot be shared without written consent.', true),
  ('legal', 37, 'During a room check, the nurse finds 9 tablets wrapped in a tissue inside the pillowcase of a patient admitted with depression and suicidal ideation. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Leave the tablets and ask the patient about them at the next med pass"}, {"id": "b", "text": "Document the finding and recheck the room at the end of the shift"}, {"id": "c", "text": "Remove the medications and notify the provider"}, {"id": "d", "text": "Ask the patient''s roommate whether the tablets belong to him"}]'::jsonb, '["c"]', 'Rooms are checked for hoarded medications, and dangerous items are removed while the provider is notified. Leaving the tablets in place or delaying action keeps the means available to a patient at risk.', false),
  ('legal', 38, 'A patient tells the nurse, "When I''m discharged, I''m going to shoot my supervisor, Mark. I already bought the gun." The nurse reports the statement to the provider. Which actions are required under the duty to warn? Select all that apply.', '[{"id": "a", "text": "Notify law enforcement"}, {"id": "b", "text": "Wait for a court order to disclose"}, {"id": "c", "text": "Warn the potential victim"}, {"id": "d", "text": "Warn only the patient''s family"}, {"id": "e", "text": "Keep it confidential under HIPAA"}]'::jsonb, '["a", "c"]', 'A specific, credible threat against an identifiable person creates a legal duty to warn the potential victim (c) AND notify law enforcement (a). Warning only family (d), keeping it confidential (e), or waiting for a court order (b) fails to protect the third party, because confidentiality yields to public safety.', true),
  ('legal', 39, 'A patient on a medical unit who was admitted after a fall says, "I''m going to jump out that window as soon as you leave." The nurse is alone with the patient. Which action by the nurse requires follow-up by the charge nurse?', '[{"id": "a", "text": "Removing the patient''s belt and the cord from the blinds"}, {"id": "b", "text": "Leaving the patient alone to call the provider"}, {"id": "c", "text": "Notifying the provider immediately by phone from the room"}, {"id": "d", "text": "Documenting the patient''s statement and interventions"}]'::jsonb, '["b"]', 'The first safety step for a suicidal patient is to stay with the patient and never leave the patient alone. Removing belts and cords, notifying the provider from the room, and documenting are all correct immediate safety steps.', false),
  ('legal', 40, 'A patient on an involuntary hold has been yelling at staff. A staff member says, "He loses phone privileges, and his mail gets held until he behaves." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"That''s appropriate, because involuntary patients have limited rights.\""}, {"id": "b", "text": "\"Holding his mail is fine, but he should still be allowed phone calls.\""}, {"id": "c", "text": "\"Patients keep the right to send and receive mail and make calls.\""}, {"id": "d", "text": "\"We need a court order before he can have his phone and mail back.\""}]'::jsonb, '["c"]', 'Patients have the right to communicate, including sending and receiving mail and making phone calls, and patient rights remain intact even under an involuntary hold. Withholding either one as a consequence for behavior violates that right.', false),
  ('legal', 41, 'A nurse is preparing the unit before admitting a patient at high risk for suicide. Which measures are part of a safe environment? Select all that apply.', '[{"id": "a", "text": "Remove belts, shoelaces, neckties, and cords"}, {"id": "b", "text": "Serve meals with plastic utensils"}, {"id": "c", "text": "Use non-breakable room fixtures"}, {"id": "d", "text": "Keep stairwell doors unlocked during the day"}, {"id": "e", "text": "Check the room for sharps and hoarded medications"}]'::jsonb, '["a", "b", "c", "e"]', 'A safe environment includes removing belts, shoelaces, neckties, and cords (a), plastic utensils during meals (b), non-breakable room fixtures (c), and checking rooms for sharps and hoarded medications (e). Doors to stairwells, exits, and outdoor areas stay locked (d).', true),
  ('legal', 42, 'A patient admitted 10 days ago has no individualized plan of care. A staff member explains, "He''s just here to be kept safe until his hold ends." Which patient right is MOST directly being violated?', '[{"id": "a", "text": "Right to informed consent"}, {"id": "b", "text": "Right to legal counsel"}, {"id": "c", "text": "Right to confidentiality"}, {"id": "d", "text": "Right to treatment"}]'::jsonb, '["d"]', 'The right to treatment means patients must receive appropriate, individualized care, and this right remains intact under an involuntary hold. Informed consent, legal counsel, and confidentiality are separate rights not described in this situation.', false),
  ('legal', 43, 'A cooperative patient with depression who denies suicidal thoughts and has followed all unit rules is scheduled to be moved to a locked high-security unit because "there is an open bed there." Which statement BEST supports the nurse''s advocacy for this patient?', '[{"id": "a", "text": "\"Any patient may be moved to a locked unit whenever a bed is available.\""}, {"id": "b", "text": "\"Care should use the minimal restrictions necessary for his safety.\""}, {"id": "c", "text": "\"He can be moved only after he is placed on an involuntary hold.\""}, {"id": "d", "text": "\"Unit placement is a staff decision and does not involve his rights.\""}]'::jsonb, '["b"]', 'Patients have the right to the least restrictive environment, meaning minimal restrictions necessary for safety. Bed availability is not a reason for added restriction, and placement decisions do involve this right.', false),
  ('legal', 44, 'A night nurse asks the provider for a standing IM sedation order for a patient who is restless but not dangerous, "so the unit stays quiet overnight." Which ethical principle is MOST threatened by this request?', '[{"id": "a", "text": "Veracity"}, {"id": "b", "text": "Justice"}, {"id": "c", "text": "Nonmaleficence"}, {"id": "d", "text": "Fidelity"}]'::jsonb, '["c"]', 'Nonmaleficence, "first, do no harm," includes avoiding unnecessary sedation or over-medication. Veracity concerns honesty, justice concerns fair and equal treatment, and fidelity concerns keeping promises.', false),
  ('legal', 45, 'A 30-year-old woman tells the emergency department nurse that her partner hit her last night, and she asks the nurse not to tell anyone. Which statement by the nurse BEST reflects reporting requirements for this situation?', '[{"id": "a", "text": "\"Federal law requires me to call the police about this right away.\""}, {"id": "b", "text": "\"Partner violence is reported to Adult Protective Services.\""}, {"id": "c", "text": "\"Whether I must report partner violence varies by state law.\""}, {"id": "d", "text": "\"Partner violence can''t be reported unless you sign a consent.\""}]'::jsonb, '["c"]', 'Reporting of intimate partner violence varies by state. Adult Protective Services receives elder abuse reports, and the requirement is set by state law rather than by the patient''s consent or a single federal rule.', false),
  ('legal', 46, 'Before a patient signs consent for a new long-acting injectable medication, the nurse learns that the provider explained its risks and benefits but did not discuss any other options. The patient is ready to sign. Which action by the nurse is BEST?', '[{"id": "a", "text": "Witness the signature, since the risks and benefits were explained"}, {"id": "b", "text": "Notify the provider, since consent requires understanding alternatives"}, {"id": "c", "text": "Have the patient sign now and discuss other options at the next visit"}, {"id": "d", "text": "Tell the patient there are no other options, so signing is the only path"}]'::jsonb, '["b"]', 'The right to informed consent requires that the patient understand the risks, benefits, and alternatives before agreeing to treatment. Explaining risks and benefits alone is incomplete, so the provider is notified before the patient signs; discussing alternatives after signing defeats the purpose.', false),
  ('legal', 47, 'A woman found by police wandering on a highway overpass is brought to the emergency department on an emergency detention. She asks the nurse, "How long can you keep me, and do I have any say?" Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "\"You still keep your rights while you are on this hold.\""}, {"id": "b", "text": "\"This is a short-term hold for evaluation, typically 24 to 72 hours.\""}, {"id": "c", "text": "\"You may leave whenever you ask, as with a voluntary admission.\""}, {"id": "d", "text": "\"Only a judge can start a hold, so this one is not valid.\""}, {"id": "e", "text": "\"The hold lasts until your provider decides you are cured.\""}]'::jsonb, '["a", "b"]', 'Emergency detention is a short-term hold for evaluation, typically 24–72 hours (b), and the patient still retains rights under an involuntary hold (a). Leaving on request (c) applies to voluntary admission, a physician or law enforcement may initiate the hold (d), and long-term commitment requires a legal process rather than an open-ended hold (e).', true),
  ('legal', 48, 'A man brought to the emergency department after threatening to jump from a roof tells the nurse, "That ER doctor can''t hold me here. Only a judge can do that." Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"You''re right; you are free to leave until a judge orders a hold.\""}, {"id": "b", "text": "\"A physician or law enforcement may start a short-term hold.\""}, {"id": "c", "text": "\"A hold can be started only if you sign a voluntary admission.\""}, {"id": "d", "text": "\"A psychiatrist on the unit is the one who must start an emergency hold.\""}]'::jsonb, '["b"]', 'An emergency detention is a short-term hold for evaluation that a physician or law enforcement may initiate. A legal process is needed for long-term commitment, not to begin an emergency hold.', false),
  ('legal', 49, 'A voluntary patient admitted for depression demands discharge and says, "Fine, I''ll leave, and when I get home I''m going to finish what I started." He attempted an overdose last week. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Process the discharge, since voluntary patients may leave at any time"}, {"id": "b", "text": "Tell him he must stay because he signed himself in as a voluntary patient"}, {"id": "c", "text": "Let him leave, but call his family and ask them to watch him at home"}, {"id": "d", "text": "Notify the provider, since danger to self meets involuntary criteria"}]'::jsonb, '["d"]', 'A voluntary patient can usually request discharge at any time, but danger to self is a criterion for involuntary admission, so the provider is notified. Simply processing the discharge or relying on family ignores the danger, and voluntary status alone does not oblige him to stay.', false),
  ('legal', 50, 'The nurse is reviewing mandatory reports filed at a community clinic this month. Which reports were directed to the correct agency? Select all that apply.', '[{"id": "a", "text": "Suspected elder neglect to Adult Protective Services"}, {"id": "b", "text": "Suspected child abuse to Adult Protective Services"}, {"id": "c", "text": "Communicable disease to the state health department"}, {"id": "d", "text": "Suspected child neglect to Child Protective Services"}, {"id": "e", "text": "Gunshot wound to the state health department"}]'::jsonb, '["a", "c", "d"]', 'Elder abuse or neglect goes to Adult Protective Services (a), communicable diseases to the state health department (c), and child abuse or neglect to Child Protective Services (d). Child abuse does not go to APS (b), and gunshot wounds are reported to law enforcement (e).', true),
  ('ect', 1, 'A patient is brought to the recovery area 5 minutes after ECT. The patient is drowsy, does not respond to name, and has no gag reflex yet; heart rate is 112/min and blood pressure is higher than baseline. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Reorient the patient to name, location, and date"}, {"id": "b", "text": "Give acetaminophen as ordered for expected headache"}, {"id": "c", "text": "Position the patient on the side until the gag reflex returns"}, {"id": "d", "text": "Offer small sips of water to relieve the patient''s dry mouth"}]'::jsonb, '["c"]', 'After ECT the priority is a patent airway, so the patient is positioned on the side until the gag reflex returns, with suction as needed. Transient hypertension and tachycardia are expected, reorientation and headache care come after the airway is secured, and the patient stays NPO until the gag reflex returns.', false),
  ('ect', 2, 'Twenty minutes after the patient''s first ECT treatment, the patient''s daughter finds her mother awake but asking repeatedly what day it is. The daughter asks the nurse, "Is something wrong with her brain?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Confusion right after ECT is expected and temporary.\""}, {"id": "b", "text": "\"I''ll notify the provider; this may be a serious reaction.\""}, {"id": "c", "text": "\"This means the seizure was longer than it needed to be.\""}, {"id": "d", "text": "\"Her memory of today will most likely never come back.\""}]'::jsonb, '["a"]', 'Confusion and disorientation are expected immediately after ECT, and the nurse reassures the patient and family because they are temporary. Treating this as a serious reaction, linking it to seizure length, or saying memory will not return are not supported and would alarm the family.', false),
  ('ect', 3, 'A nurse is caring for a patient in the recovery area 30 minutes after ECT. Which findings are expected at this time? Select all that apply.', '[{"id": "a", "text": "Difficulty forming new memories that lasts months"}, {"id": "b", "text": "Confusion and disorientation"}, {"id": "c", "text": "Headache"}, {"id": "d", "text": "Transient hypertension and tachycardia"}, {"id": "e", "text": "Muscle aches"}]'::jsonb, '["b", "c", "d", "e"]', 'Confusion and disorientation (b), headache (c), transient hypertension and tachycardia (d), and muscle aches from succinylcholine (e) are expected after ECT. Difficulty forming new memories (a) is anterograde amnesia, which is listed as a rare or serious concern rather than an expected effect.', true),
  ('ect', 4, 'A nurse is completing the pre-ECT checklist at 0730 for a patient scheduled for 0800. Which finding requires the nurse to contact the provider before the procedure?', '[{"id": "a", "text": "The patient voided 10 minutes ago"}, {"id": "b", "text": "An IV line was started and is patent"}, {"id": "c", "text": "The patient was given scheduled benzodiazepines at 0600"}, {"id": "d", "text": "Baseline vital signs have been recorded"}]'::jsonb, '["c"]', 'Benzodiazepines are held as ordered before ECT because they raise the seizure threshold and reduce effectiveness, so a dose given this morning must be reported. Voiding, IV access, and baseline vital signs are all required parts of the checklist.', false),
  ('ect', 5, 'A patient is scheduled for ECT at 0800. During the pre-procedure check, the nurse learns of four events from the night before. Which event requires IMMEDIATE follow-up?', '[{"id": "a", "text": "The patient had a snack by mouth at 2200"}, {"id": "b", "text": "The patient removed dentures and contact lenses at 0700"}, {"id": "c", "text": "The patient took an approved pill with a small sip of water at 0600"}, {"id": "d", "text": "The patient had juice by mouth at 0300"}]'::jsonb, '["d"]', 'Patients are NPO for 6–8 hours before ECT because of anesthesia; juice at 0300 is only 5 hours before an 0800 procedure. A snack at 2200 is 10 hours before, approved medications may be taken with small sips of water, and removing dentures and contact lenses is required.', false),
  ('ect', 6, 'A nurse is preparing a patient for transfer to the ECT suite. Which actions should the nurse take? Select all that apply.', '[{"id": "a", "text": "Leave dentures in place to support the airway"}, {"id": "b", "text": "Remove the patient''s hairpins and jewelry"}, {"id": "c", "text": "Remove the patient''s nail polish"}, {"id": "d", "text": "Have the patient empty the bladder"}, {"id": "e", "text": "Remove the patient''s contact lenses"}]'::jsonb, '["b", "c", "d", "e"]', 'Before ECT the nurse removes hairpins and jewelry (b), nail polish (c), and contact lenses (e), and has the patient void (d). Dentures (a) are also removed rather than left in place.', true),
  ('ect', 7, 'A patient with severe depression who has a court-appointed legal guardian is scheduled for ECT. The patient''s adult son arrives and offers to sign the consent form. Which action by the nurse is BEST?', '[{"id": "a", "text": "Accept the son''s signature because he is the closest relative"}, {"id": "b", "text": "Accept the patient''s verbal agreement because ECT is safe"}, {"id": "c", "text": "Obtain written informed consent from the legal guardian"}, {"id": "d", "text": "Proceed without consent because the depression is severe"}]'::jsonb, '["c"]', 'The patient or legal guardian must give written informed consent after the procedure, risks, benefits, and alternatives are explained. A relative who is not the guardian, verbal agreement, or proceeding without consent do not meet this requirement.', false),
  ('ect', 8, 'A nurse on an inpatient unit reviews four patients with depression whom the provider is evaluating for ECT. Which patient is the MOST appropriate candidate?', '[{"id": "a", "text": "A patient who began a first antidepressant 2 weeks ago"}, {"id": "b", "text": "A patient whose mood has improved on the current antidepressant"}, {"id": "c", "text": "A patient with mild depression who had an MI 3 weeks ago"}, {"id": "d", "text": "A patient with severe depression who failed 3 adequate antidepressant trials"}]'::jsonb, '["d"]', 'ECT is indicated for severe, treatment-resistant major depressive disorder that has failed 2 or more adequate antidepressant trials. A first trial of 2 weeks is not treatment resistance, an improving patient does not need ECT, and a recent MI is a relative contraindication.', false),
  ('ect', 9, 'A patient who is 22 weeks pregnant has severe depression and is scheduled for ECT. Her husband says, "I thought pregnant women couldn''t have this done." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Pregnancy is not a contraindication; ECT may be safer than some medications.\""}, {"id": "b", "text": "\"You''re right; the provider will need to cancel the treatment until after delivery.\""}, {"id": "c", "text": "\"Pregnancy is an absolute contraindication, but the depression is too severe to wait.\""}, {"id": "d", "text": "\"ECT is safe in pregnancy only if she has also failed 2 medication trials first.\""}]'::jsonb, '["a"]', 'Pregnancy is not a contraindication to ECT, and ECT may be safer than some medications for the fetus; pregnant patients are among those unable to tolerate medications for whom ECT is used. ECT has no absolute contraindications, so describing pregnancy as one is incorrect.', false),
  ('ect', 10, 'A nurse reviews the histories of four patients scheduled for ECT this week. Which history should the nurse report to the provider so benefit and risk can be weighed?', '[{"id": "a", "text": "Age 81 with intolerance to antidepressants"}, {"id": "b", "text": "Recent MI (3 weeks ago)"}, {"id": "c", "text": "Pregnancy at 18 weeks'' gestation"}, {"id": "d", "text": "Catatonia unresponsive to benzodiazepines"}]'::jsonb, '["b"]', 'A recent MI is a relative contraindication, so benefit and risk must be weighed. Elderly patients who cannot tolerate medications, pregnant patients, and patients with catatonia unresponsive to benzodiazepines are indications for ECT.', false),
  ('ect', 11, 'A nurse reviews the medical history of a patient referred for ECT. Which conditions are relative contraindications that the provider must weigh? Select all that apply.', '[{"id": "a", "text": "Postpartum psychosis"}, {"id": "b", "text": "Increased intracranial pressure"}, {"id": "c", "text": "Space-occupying brain lesion such as an AVM"}, {"id": "d", "text": "Pregnancy in the second trimester"}, {"id": "e", "text": "Aortic aneurysm"}]'::jsonb, '["b", "c", "e"]', 'Increased intracranial pressure (b), a space-occupying brain lesion such as a tumor or AVM (c), and aortic aneurysm (e) are relative contraindications. Postpartum psychosis (a) is an indication for ECT, and pregnancy (d) is not a contraindication.', true),
  ('ect', 12, 'A provider is considering ECT for several patients on a psychiatric unit. Which patients have indications for ECT? Select all that apply.', '[{"id": "a", "text": "A patient with catatonia unresponsive to benzodiazepines"}, {"id": "b", "text": "A patient with postpartum psychosis"}, {"id": "c", "text": "A patient with acute mania unresponsive to medications"}, {"id": "d", "text": "A patient with mild depression improving on a first antidepressant"}, {"id": "e", "text": "A patient with medication-resistant schizophrenia with a mood component"}]'::jsonb, '["a", "b", "c", "e"]', 'Indications include catatonia unresponsive to benzodiazepines (a), postpartum psychosis (b), acute mania unresponsive to medications (c), and medication-resistant schizophrenia, especially with a mood component (e). Mild depression improving on a first antidepressant (d) is not severe or treatment-resistant.', true),
  ('ect', 13, 'A patient with severe depression has stopped eating and tells staff she has a plan to end her life. The provider orders ECT, and her brother asks, "Why not just try another antidepressant?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"ECT works faster than medication when an immediate response is needed.\""}, {"id": "b", "text": "\"ECT is used here because it has fewer side effects than antidepressants.\""}, {"id": "c", "text": "\"ECT is used because she has failed every medication that exists.\""}, {"id": "d", "text": "\"ECT permanently cures depression, so no further treatment is needed.\""}]'::jsonb, '["a"]', 'ECT is indicated for acute suicidal risk when an immediate response is needed because it is faster than medication. ECT has expected side effects, the indication here is not failure of every medication, and some patients need maintenance ECT to prevent relapse.', false),
  ('ect', 14, 'A patient with bipolar depression who takes lithium is scheduled for ECT tomorrow morning. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Give lithium as usual, because it supports seizure activity"}, {"id": "b", "text": "Hold lithium as ordered, because it causes bradycardia during ECT"}, {"id": "c", "text": "Give lithium with a full glass of water, because it prevents nausea"}, {"id": "d", "text": "Hold lithium as ordered, because it increases CNS effects post-ECT"}]'::jsonb, '["d"]', 'Lithium is held before ECT as ordered because it increases CNS effects after ECT. It is not given to support seizures, a full glass of water would break NPO, and bradycardia is what pre-procedure atropine helps prevent rather than a reason to hold lithium.', false),
  ('ect', 15, 'A nursing student asks why a patient''s anticonvulsant is being held before ECT. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "It increases CNS effects after the procedure"}, {"id": "b", "text": "It increases oral and respiratory secretions"}, {"id": "c", "text": "It raises the seizure threshold and reduces effectiveness"}, {"id": "d", "text": "It must be stopped weeks ahead because of hypertensive risk"}]'::jsonb, '["c"]', 'Benzodiazepines and anticonvulsants are held because they raise the seizure threshold and reduce the effectiveness of ECT. Increased CNS effects is the reason lithium is held, and stopping weeks ahead describes MAOIs.', false),
  ('ect', 16, 'A patient scheduled for ECT receives atropine before the procedure. The patient asks what the injection is for. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"It prevents violent muscle contractions during the seizure.\""}, {"id": "b", "text": "\"It puts you to sleep so you are unaware of the procedure.\""}, {"id": "c", "text": "\"It reduces oral secretions and prevents bradycardia.\""}, {"id": "d", "text": "\"It protects you from low oxygen while you are not breathing.\""}]'::jsonb, '["c"]', 'Atropine, an anticholinergic, reduces oral and respiratory secretions and prevents bradycardia during the procedure. Succinylcholine prevents violent muscle contractions, the short-acting anesthetic causes unconsciousness, and oxygen by mask protects from hypoxia during apnea.', false),
  ('ect', 17, 'Two hours after ECT, a patient says, "My whole body aches. Did they hurt me while I was asleep?" Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Aches mean you had a strong convulsion, so I''ll report it.\""}, {"id": "b", "text": "\"Aches come from the atropine you received before treatment.\""}, {"id": "c", "text": "\"Aches are a rare, serious effect that the provider must assess.\""}, {"id": "d", "text": "\"Aches come from the muscle relaxant; I can give an analgesic.\""}]'::jsonb, '["d"]', 'Muscle aches are a common effect caused by succinylcholine, the muscle relaxant, and analgesics are given as needed. Modern ECT does not cause dramatic convulsions, muscle aches are common rather than rare, and atropine is given to reduce secretions and prevent bradycardia.', false),
  ('ect', 18, 'A nursing student observing an ECT treatment notices only slight twitching of the patient''s feet when the stimulus is delivered and asks whether the treatment worked. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Minimal movement is expected because succinylcholine prevents violent contractions"}, {"id": "b", "text": "Minimal movement means the muscle relaxant dose was too high and must be reported"}, {"id": "c", "text": "Minimal movement shows that no seizure occurred, so the stimulus will be repeated"}, {"id": "d", "text": "Minimal movement means the anesthetic is wearing off before the seizure begins"}]'::jsonb, '["a"]', 'Succinylcholine prevents violent muscular contractions, so body movement is minimal, with slight twitching in the feet; the EEG, not visible movement, confirms the seizure. Modern ECT does not cause dramatic convulsions.', false),
  ('ect', 19, 'A nurse reviews the EEG record from four patients'' ECT treatments. For which patient does the EEG confirm an adequate seizure?', '[{"id": "a", "text": "Seizure lasting 12 seconds"}, {"id": "b", "text": "Seizure lasting 18 seconds"}, {"id": "c", "text": "Seizure lasting 22 seconds"}, {"id": "d", "text": "Seizure lasting 28 seconds"}]'::jsonb, '["d"]', 'The EEG confirms a seizure of 25 seconds or longer, so only the 28-second seizure meets the threshold. Seizures of 12, 18, and 22 seconds fall below 25 seconds.', false),
  ('ect', 20, 'A 70-year-old patient beginning ECT for severe depression tells the nurse, "My biggest fear is losing my memory." Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Bilateral placement causes the least memory impairment.\""}, {"id": "b", "text": "\"Right-side placement causes less memory impairment.\""}, {"id": "c", "text": "\"Electrode placement has no effect on memory problems.\""}, {"id": "d", "text": "\"Unilateral placement is more effective for severe cases.\""}]'::jsonb, '["b"]', 'Unilateral electrode placement on the right side causes less memory impairment than bilateral placement. Bilateral placement may be more effective for severe depression, but it causes more memory impairment.', false),
  ('ect', 21, 'A patient has just been moved to the recovery area after ECT and the nurse begins recovery monitoring. Which parameters should the nurse monitor? Select all that apply.', '[{"id": "a", "text": "Seizure duration on the EEG"}, {"id": "b", "text": "Vital signs"}, {"id": "c", "text": "Lithium level before discharge"}, {"id": "d", "text": "Oxygenation"}, {"id": "e", "text": "Level of consciousness"}]'::jsonb, '["b", "d", "e"]', 'Recovery monitoring includes vital signs (b), oxygenation (d), and level of consciousness (e). The EEG confirms seizure duration (a) during the procedure, not in recovery, and lithium (c) is held before ECT rather than monitored in recovery.', true),
  ('ect', 22, 'A nurse is orienting a new graduate to the ECT suite. Which pairings of a procedure step with its purpose are correct? Select all that apply.', '[{"id": "a", "text": "Propofol: confirms that a seizure occurred"}, {"id": "b", "text": "Oxygen by mask: protects from hypoxia during apnea"}, {"id": "c", "text": "Atropine: reduces oral and respiratory secretions"}, {"id": "d", "text": "Succinylcholine: induces general anesthesia"}, {"id": "e", "text": "EEG: reduces memory impairment after treatment"}]'::jsonb, '["b", "c"]', 'Atropine reduces oral and respiratory secretions and prevents bradycardia (c), and oxygen by mask before and after protects from hypoxia during the apnea caused by the muscle relaxant (b). Propofol (a) is the short-acting anesthetic, succinylcholine (d) is the muscle relaxant, and the EEG (e) confirms the seizure; right-sided unilateral placement is what reduces memory impairment.', true),
  ('ect', 23, 'Fifteen minutes after ECT, a patient''s blood pressure is higher than the pre-procedure baseline and the heart rate is 108/min. The airway is patent and the patient is drowsy. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Notify the provider immediately of a hypertensive emergency"}, {"id": "b", "text": "Continue monitoring vital signs every 15 minutes until stable"}, {"id": "c", "text": "Reassure the patient and stop vital signs once the patient is awake"}, {"id": "d", "text": "Hold all of the patient''s medications for the next 24 hours"}]'::jsonb, '["b"]', 'Transient hypertension and tachycardia are expected after ECT, so the nurse continues monitoring vital signs every 15 minutes until stable. Calling this an emergency misreads an expected finding, and stopping vital signs when the patient wakes ignores the q15 minute requirement.', false),
  ('ect', 24, 'Twenty minutes after ECT, a patient is awake and asks for a glass of water. The nurse checks and finds the gag reflex has not yet returned. Which action by the nurse is BEST?', '[{"id": "a", "text": "Give small sips of water to keep the mouth moist"}, {"id": "b", "text": "Give the water with the patient sitting fully upright"}, {"id": "c", "text": "Keep the patient NPO until the gag reflex returns"}, {"id": "d", "text": "Give ice chips instead because they melt slowly"}]'::jsonb, '["c"]', 'The patient stays NPO until the gag reflex returns to prevent aspiration. Sips of water, upright positioning, or ice chips still place fluid in the mouth before the gag reflex returns.', false),
  ('ect', 25, 'Forty minutes after ECT, a patient who is still disoriented to the date stands up and says, "I''m going to the bathroom by myself." Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Let the patient walk alone to promote independence"}, {"id": "b", "text": "Assist the patient to walk and stay with the patient"}, {"id": "c", "text": "Ask the patient to wait until the next day to get up"}, {"id": "d", "text": "Give acetaminophen before the patient walks to the bathroom"}]'::jsonb, '["b"]', 'Confusion after ECT creates a fall risk, so the nurse assists with ambulation and does not leave the patient unattended. Walking alone ignores the fall risk, and acetaminophen is for headache, not fall prevention.', false),
  ('ect', 26, 'One hour after ECT, a patient who is alert and oriented reports a headache rated 5 on a 0–10 scale. Vital signs are stable. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Notify the provider because headache is a serious complication"}, {"id": "b", "text": "Explain that the headache means the treatment did not work"}, {"id": "c", "text": "Administer acetaminophen as ordered for the expected headache"}, {"id": "d", "text": "Hold any analgesic until the next scheduled treatment session"}]'::jsonb, '["c"]', 'Headache is a common, expected effect after ECT, and the nurse administers acetaminophen as ordered. It is not listed among the rare or serious concerns and does not indicate treatment failure.', false),
  ('ect', 27, 'A nurse is monitoring patients in the ECT recovery area. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "A headache 1 hour after treatment"}, {"id": "b", "text": "Gurgling respirations in a patient with no gag reflex"}, {"id": "c", "text": "Confusion about the date 20 minutes after treatment"}, {"id": "d", "text": "Transient arrhythmias on the cardiac monitor"}, {"id": "e", "text": "Muscle aches 2 hours after treatment"}]'::jsonb, '["b", "d"]', 'Transient arrhythmias are a rare, serious cardiovascular concern (d), and gurgling respirations without a gag reflex threaten the airway, which is the priority and requires side-lying positioning and suction (b). Confusion (c), headache (a), and muscle aches (e) are common, expected effects.', true),
  ('ect', 28, 'A nurse in the ECT recovery area receives four patients. Which patient should the nurse assess FIRST?', '[{"id": "a", "text": "A patient 15 minutes after ECT who is drowsy with gurgling secretions"}, {"id": "b", "text": "A patient 30 minutes after ECT who asks where she is and what day it is"}, {"id": "c", "text": "A patient 1 hour after ECT who reports a headache and some nausea"}, {"id": "d", "text": "A patient 2 hours after ECT who reports muscle aches and fatigue"}]'::jsonb, '["a"]', 'Ensuring a patent airway is the priority after ECT, so the drowsy patient with gurgling secretions is assessed first for positioning and suction. Confusion, headache, nausea, muscle aches, and fatigue are common, expected effects.', false),
  ('ect', 29, 'A nurse is reinforcing teaching with a patient receiving outpatient ECT. Which statement by the patient indicates a need for further teaching?', '[{"id": "a", "text": "\"My sister will drive me to and from each treatment.\""}, {"id": "b", "text": "\"I''ll drive home on ECT days if I feel alert.\""}, {"id": "c", "text": "\"I''ll wait until another day to sign my new lease.\""}, {"id": "d", "text": "\"I''ll have only my approved pills with a sip of water.\""}]'::jsonb, '["b"]', 'Patients should not drive on ECT days, regardless of how alert they feel. Having a family member accompany the patient, avoiding important decisions on ECT days, and taking only approved medications with small sips of water are correct.', false),
  ('ect', 30, 'The mother of a young adult scheduled for a first ECT treatment asks the nurse, "Will he feel the electricity going through his brain?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"He''ll feel a brief shock, but it is over within seconds.\""}, {"id": "b", "text": "\"He''ll be awake, but a numbing drug blocks most of the pain.\""}, {"id": "c", "text": "\"He''ll feel the seizure, but the muscle relaxant limits it.\""}, {"id": "d", "text": "\"ECT is not painful; he will be asleep and won''t feel it.\""}]'::jsonb, '["d"]', 'ECT is performed under general anesthesia, so it is not painful; the patient is asleep and does not feel it. The patient is not awake or numbed, and the patient does not feel the seizure.', false),
  ('ect', 31, 'The wife of a patient who has had 2 ECT treatments says, "He doesn''t seem any better yet. I''m afraid it isn''t working." Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Improvement is usually seen after the first treatment.\""}, {"id": "b", "text": "\"Improvement is usually seen only with maintenance ECT.\""}, {"id": "c", "text": "\"Improvement is usually seen only after all 12 sessions.\""}, {"id": "d", "text": "\"Improvement is usually seen after 3–6 sessions.\""}]'::jsonb, '["d"]', 'Improvement is usually seen after 3–6 sessions, so no improvement after 2 treatments is not yet a sign that ECT is failing. A typical course is 6–12 sessions, and maintenance ECT is used to prevent relapse.', false),
  ('ect', 32, 'The family of a patient beginning a course of ECT asks how the treatments will be scheduled. Which statement by a family member indicates understanding of the teaching?', '[{"id": "a", "text": "\"He''ll have a treatment every day for 2 weeks in a row.\""}, {"id": "b", "text": "\"He''ll have one treatment a week for about 12 weeks.\""}, {"id": "c", "text": "\"He''ll have 6 to 12 treatments, 3 times each week.\""}, {"id": "d", "text": "\"He''ll have one treatment each month for 6 months.\""}]'::jsonb, '["c"]', 'A typical course is 6–12 sessions given 3 times per week (Monday–Wednesday–Friday). Daily or weekly schedules do not match the typical course, and monthly treatments describe maintenance ECT.', false),
  ('ect', 33, 'A patient whose depression improved after a course of ECT learns the provider has ordered monthly treatments. The patient asks, "Why do I need more if I''m better now?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Monthly maintenance ECT helps prevent a relapse.\""}, {"id": "b", "text": "\"Monthly ECT is needed to restore your lost memory.\""}, {"id": "c", "text": "\"Monthly ECT means the first course did not work.\""}, {"id": "d", "text": "\"Monthly ECT replaces the need for any follow-up.\""}]'::jsonb, '["a"]', 'Some patients need maintenance ECT monthly to prevent relapse. It is not given to restore memory, it does not mean the first course failed, and it does not replace follow-up.', false),
  ('ect', 34, 'After finishing a course of 10 ECT treatments, a patient says, "There are gaps in what I remember from the past few weeks. Will I be like this forever?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"These gaps are permanent, but they are usually small.\""}, {"id": "b", "text": "\"Memory typically improves after the treatment course ends.\""}, {"id": "c", "text": "\"Memory problems after ECT are rare, so tell your provider.\""}, {"id": "d", "text": "\"These gaps will get worse if you have maintenance ECT.\""}]'::jsonb, '["b"]', 'Long-term memory effects of ECT are generally temporary, and memory typically improves after the treatment course ends. Short-term memory gaps are common during the course, so they are neither permanent nor rare.', false),
  ('ect', 35, 'A nurse is teaching the family of a patient receiving ECT about side effects. Which effects should the nurse describe as rare or serious concerns rather than common, expected effects? Select all that apply.', '[{"id": "a", "text": "Nausea after a treatment"}, {"id": "b", "text": "Fatigue on treatment days"}, {"id": "c", "text": "Difficulty forming new memories"}, {"id": "d", "text": "Headache after a treatment"}, {"id": "e", "text": "Losing memories from before ECT"}]'::jsonb, '["c", "e"]', 'Retrograde amnesia, losing memories from before ECT (e), and anterograde amnesia, difficulty forming new memories (c), are rare or serious concerns. Nausea (a), fatigue (b), and headache (d) are common, expected side effects.', true),
  ('ect', 36, 'A nurse is completing the pre-procedure checklist for a patient scheduled for ECT. Which items must be completed before the patient goes to the procedure? Select all that apply.', '[{"id": "a", "text": "Written informed consent is signed"}, {"id": "b", "text": "NPO for 6–8 hours before the procedure"}, {"id": "c", "text": "The scheduled anticonvulsant dose is given"}, {"id": "d", "text": "IV access is established"}, {"id": "e", "text": "Baseline vital signs are recorded"}]'::jsonb, '["a", "b", "d", "e"]', 'Before ECT the nurse confirms written informed consent (a), NPO for 6–8 hours (b), IV access (d), and baseline vital signs (e). Anticonvulsants (c) are held as ordered because they raise the seizure threshold.', true),
  ('ect', 37, 'A nurse is preparing a patient for ECT scheduled in 2 days. Which finding in the medication history requires follow-up with the provider?', '[{"id": "a", "text": "The patient''s MAOIs have not been discontinued"}, {"id": "b", "text": "The lithium dose is being held as ordered"}, {"id": "c", "text": "Atropine is ordered before the procedure"}, {"id": "d", "text": "Approved medications are ordered with sips of water"}]'::jsonb, '["a"]', 'MAOIs are typically discontinued weeks before ECT, so an MAOI that has not been discontinued must be reported. Holding lithium as ordered, giving atropine before the procedure, and taking approved medications with small sips of water are expected parts of preparation.', false),
  ('ect', 38, 'The son of an 84-year-old patient with severe depression asks why ECT was recommended after his mother had serious side effects from several antidepressants. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"ECT is used because it has no risks from general anesthesia.\""}, {"id": "b", "text": "\"ECT is used mainly because older adults recover faster from it.\""}, {"id": "c", "text": "\"ECT is used only after a patient has had a recent stroke.\""}, {"id": "d", "text": "\"ECT is used when patients are unable to tolerate medications.\""}]'::jsonb, '["d"]', 'ECT is indicated for patients unable to tolerate medications, including elderly patients. Recent stroke is a relative contraindication, and ECT carries risks of general anesthesia.', false),
  ('ect', 39, 'A patient scheduled for ECT at 0900 asks the nurse on the evening before, "Can I still take my morning pills?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Take all your usual pills with a full glass of water.\""}, {"id": "b", "text": "\"Take only your approved pills with a small sip of water.\""}, {"id": "c", "text": "\"Skip every pill, including the approved ones, that morning.\""}, {"id": "d", "text": "\"Take your pills with a light breakfast before 0700.\""}]'::jsonb, '["b"]', 'Patients are NPO 6–8 hours before each treatment and take only approved medications with small sips of water. A full glass of water or a breakfast breaks NPO, and skipping approved medications is not required.', false),
  ('ect', 40, 'The daughter of a patient with severe depression says, "Mom had a stroke last month. Does that mean she can never have ECT?" Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"A recent stroke is an absolute contraindication to ECT.\""}, {"id": "b", "text": "\"A recent stroke is a relative contraindication; risks are weighed.\""}, {"id": "c", "text": "\"A recent stroke does not need to be considered before ECT.\""}, {"id": "d", "text": "\"A recent stroke means only bilateral placement can be used.\""}]'::jsonb, '["b"]', 'ECT has no absolute contraindications; a recent stroke is a relative contraindication, so the benefit and risk must be weighed for the patient. It is not ignored, and electrode placement is not determined by stroke history.', false),
  ('ect', 41, 'After the fourth ECT treatment of a planned course, a patient says, "I can''t remember what I had for dinner yesterday." Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Short-term memory impairment is expected during the treatment course"}, {"id": "b", "text": "Retrograde amnesia has developed and the course must be stopped"}, {"id": "c", "text": "The patient has a sign of a transient arrhythmia from treatment"}, {"id": "d", "text": "The memory loss means the right-side placement is not working"}]'::jsonb, '["a"]', 'Short-term memory impairment is a common, expected effect during the treatment course, and memory typically improves after the course ends. Retrograde amnesia refers to losing memories before ECT, and memory loss is not a sign of arrhythmia or of placement failure.', false),
  ('ect', 42, 'A nurse is checking a patient on the morning of ECT. Which finding requires the nurse to intervene before the patient is transferred?', '[{"id": "a", "text": "The patient voided 10 minutes ago"}, {"id": "b", "text": "The patient has had nothing by mouth for 8 hours"}, {"id": "c", "text": "The patient is wearing nail polish and contact lenses"}, {"id": "d", "text": "The patient has a patent IV line in the left arm"}]'::jsonb, '["c"]', 'Hairpins, jewelry, nail polish, contact lenses, and dentures must be removed before ECT. Voiding, 8 hours NPO, and established IV access all meet pre-ECT requirements.', false),
  ('ect', 43, 'A nurse reviews the medication list of a patient scheduled for ECT tomorrow. Which medications should the nurse expect to hold as ordered? Select all that apply.', '[{"id": "a", "text": "Atropine"}, {"id": "b", "text": "Benzodiazepines"}, {"id": "c", "text": "Anticonvulsants"}, {"id": "d", "text": "Lithium"}, {"id": "e", "text": "Approved medications taken with sips of water"}]'::jsonb, '["b", "c", "d"]', 'Lithium (d), benzodiazepines (b), and anticonvulsants (c) are held as ordered because they may interfere with seizure threshold. Atropine (a) is given before the procedure to reduce secretions and prevent bradycardia, and approved medications (e) may be taken with small sips of water.', true),
  ('ect', 44, 'Thirty minutes after ECT, a confused patient insists on walking to the lounge. Which actions by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Give oral fluids before the gag reflex is checked"}, {"id": "b", "text": "Let the patient walk alone with the door open"}, {"id": "c", "text": "Stay with the patient and do not leave unattended"}, {"id": "d", "text": "Explain that confusion means a serious problem"}, {"id": "e", "text": "Assist the patient with ambulation"}]'::jsonb, '["c", "e"]', 'Confusion creates a fall risk, so the nurse assists with ambulation (e) and does not leave the patient unattended (c). Walking alone (b) ignores the fall risk, fluids (a) are held until the gag reflex returns, and confusion (d) is expected and temporary.', true),
  ('ect', 45, 'A nurse reviews the reports of four patients with depression who are being prepared for ECT. Which findings should the nurse report to the provider before the procedure? Select all that apply.', '[{"id": "a", "text": "Wearing dentures and contact lenses"}, {"id": "b", "text": "Had coffee by mouth 3 hours before"}, {"id": "c", "text": "Recent MI (4 weeks ago)"}, {"id": "d", "text": "Is pregnant at 24 weeks'' gestation"}, {"id": "e", "text": "Voided just before transfer"}]'::jsonb, '["b", "c"]', 'Coffee 3 hours before the procedure (b) violates the 6–8 hour NPO requirement for anesthesia, and a recent MI (c) is a relative contraindication that requires weighing benefit and risk. Dentures and contact lenses (a) are simply removed by the nurse, pregnancy (d) is not a contraindication, and voiding (e) is required.', true),
  ('ect', 46, 'A patient is waking in the recovery area after ECT and asks, "Where am I?" Which information should the nurse include when reorienting the patient? Select all that apply.', '[{"id": "a", "text": "The patient''s name"}, {"id": "b", "text": "That the procedure is about to begin"}, {"id": "c", "text": "The location"}, {"id": "d", "text": "That the confusion signals a complication"}, {"id": "e", "text": "That the procedure is over"}]'::jsonb, '["a", "c", "e"]', 'Reorientation tells the patient their name (a), location (c), the date, and that the procedure is over (e), such as "You just finished your treatment." Saying the procedure is about to begin (b) is inaccurate and disorienting, and confusion immediately after ECT is expected, not a sign of a complication (d).', true),
  ('ect', 47, 'The family of a patient beginning ECT asks about memory effects. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "\"Bilateral placement causes less memory impairment.\""}, {"id": "b", "text": "\"Memory loss is always permanent with bilateral placement.\""}, {"id": "c", "text": "\"Memory loss means the treatment should be stopped.\""}, {"id": "d", "text": "\"Memory typically improves after the course ends.\""}, {"id": "e", "text": "\"Right unilateral placement causes less memory impairment.\""}]'::jsonb, '["d", "e"]', 'Memory typically improves after the treatment course ends (d), and right-sided unilateral placement causes less memory impairment than bilateral placement (e). Bilateral placement causes more memory impairment (a), long-term memory effects are generally temporary (b), and short-term memory impairment during the course is expected (c).', true),
  ('ect', 48, 'A patient scheduled for a first ECT treatment says, "I saw a movie where people thrash around and scream during shock treatment. I''m terrified." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Movies are accurate, but the convulsions last only seconds.\""}, {"id": "b", "text": "\"The convulsions are strong, but restraints will keep you safe.\""}, {"id": "c", "text": "\"You''ll be awake but numb, so you won''t feel much pain at all.\""}, {"id": "d", "text": "\"Modern ECT doesn''t cause dramatic convulsions; you''ll be asleep.\""}]'::jsonb, '["d"]', 'Modern ECT does not cause the dramatic convulsions depicted in popular media; it is performed under general anesthesia with muscle relaxants, and the patient is asleep and does not feel it. The patient is not awake, and media portrayals are not accurate.', false),
  ('ect', 49, 'A nurse is preparing a patient for a first ECT treatment. Which explanations should the nurse give the patient? Select all that apply.', '[{"id": "a", "text": "\"You will be awake so you can report pain.\""}, {"id": "b", "text": "\"Your body will convulse strongly during it.\""}, {"id": "c", "text": "\"You won''t feel the seizure.\""}, {"id": "d", "text": "\"You may wake with brief confusion and memory loss.\""}, {"id": "e", "text": "\"You will be asleep during the treatment.\""}]'::jsonb, '["c", "d", "e"]', 'The nurse explains that the patient will be asleep (e), won''t feel the seizure (c), and may wake with brief confusion and memory loss that is expected and temporary (d). ECT is done under general anesthesia, so the patient is not awake (a), and modern ECT does not cause dramatic convulsions (b).', true),
  ('ect', 50, 'A family member asks the nurse what they should do on the day of each outpatient ECT treatment. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Accompany him; no driving or important decisions today.\""}, {"id": "b", "text": "\"Drop him off; he can drive himself home once he feels alert.\""}, {"id": "c", "text": "\"Plan important family decisions for the evening after treatment.\""}, {"id": "d", "text": "\"Give him a light breakfast so he has energy for the treatment.\""}]'::jsonb, '["a"]', 'A family member or friend should accompany the patient, and the patient should not drive or make important decisions on ECT days. Driving home, making important decisions that evening, and eating before treatment conflict with the teaching and NPO requirement.', false),
  ('serotonin', 1, 'A client who takes sertraline (Zoloft) for depression was prescribed tramadol for back pain yesterday. Today the client is agitated, confused, diaphoretic, and tachycardic, with hyperthermia, ankle clonus, and hyperreflexia. Which explanation for these findings is MOST likely?', '[{"id": "a", "text": "Expected adverse effects of starting tramadol for pain"}, {"id": "b", "text": "Neuroleptic malignant syndrome from the drugs"}, {"id": "c", "text": "Serotonin syndrome from the drug combination"}, {"id": "d", "text": "Anxiety and restlessness from the new back pain"}]'::jsonb, '["c"]', 'Sertraline (SSRI) and tramadol (opioid) are both serotonergic, and the findings match the triad of mental status changes, autonomic instability, and neuromuscular abnormalities. NMS is caused by antipsychotics and lacks the clonus and hyperreflexia that distinguish serotonin syndrome.', false),
  ('serotonin', 2, 'A client who takes venlafaxine (Effexor) has used an over-the-counter cough medicine containing dextromethorphan for 2 days and is now restless and confused. If a drug interaction is the cause, which additional findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "Diaphoresis"}, {"id": "b", "text": "Lead-pipe rigidity"}, {"id": "c", "text": "Diarrhea"}, {"id": "d", "text": "Clonus"}, {"id": "e", "text": "Hyperreflexia"}]'::jsonb, '["a", "c", "d", "e"]', 'Venlafaxine (SNRI) plus dextromethorphan can cause serotonin syndrome: diaphoresis and diarrhea reflect autonomic instability, and hyperreflexia and clonus are neuromuscular abnormalities. Lead-pipe rigidity is the muscle sign of NMS, not serotonin syndrome.', true),
  ('serotonin', 3, 'A client who takes tranylcypromine (Parnate) received fentanyl during surgery. Two hours later in the postanesthesia unit the client is agitated, diaphoretic, and hyperthermic, with myoclonus of both legs. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Stop all serotonergic drugs"}, {"id": "b", "text": "Apply a cooling blanket"}, {"id": "c", "text": "Give cyproheptadine by NG tube"}, {"id": "d", "text": "Give a benzodiazepine for agitation"}]'::jsonb, '["a"]', 'An MAOI plus an opioid such as fentanyl can cause serotonin syndrome, and discontinuing ALL serotonergic agents immediately is the most critical step. Cooling, cyproheptadine, and benzodiazepines are appropriate treatments but come after stopping the offending drugs.', false),
  ('serotonin', 4, 'A client takes both sertraline and haloperidol. Twelve hours after the sertraline dose was increased, the client develops a fever and abnormal muscle findings. Which finding MOST strongly supports serotonin syndrome rather than NMS?', '[{"id": "a", "text": "Elevated temperature"}, {"id": "b", "text": "Clonus and hyperreflexia"}, {"id": "c", "text": "Agitation of any degree"}, {"id": "d", "text": "Markedly elevated CK"}]'::jsonb, '["b"]', 'Clonus and hyperreflexia are the key differentiators of serotonin syndrome from NMS. Fever occurs in both conditions, agitation is present in both (though more prominent in serotonin syndrome), and a markedly elevated CK points toward NMS.', false),
  ('serotonin', 5, 'A client started on haloperidol 10 days ago has a severe fever, lead-pipe rigidity, normal reflexes, decreased bowel sounds, and a markedly elevated CK. Which medication should the nurse anticipate as the BEST choice?', '[{"id": "a", "text": "Cyproheptadine by NG tube"}, {"id": "b", "text": "Lorazepam for agitation"}, {"id": "c", "text": "Methylene blue IV"}, {"id": "d", "text": "Dantrolene"}]'::jsonb, '["d"]', 'Gradual onset after an antipsychotic with lead-pipe rigidity, normal reflexes, and a markedly elevated CK indicates NMS, treated by stopping the antipsychotic and giving dantrolene or bromocriptine. Cyproheptadine is the serotonin antagonist used for serotonin syndrome.', false),
  ('serotonin', 6, 'The nurse reconciles home medication lists on admission. Which client medication combinations require IMMEDIATE follow-up with the provider? Select all that apply.', '[{"id": "a", "text": "Sertraline with paroxetine during a switch"}, {"id": "b", "text": "Sertraline with sumatriptan for migraines"}, {"id": "c", "text": "Phenelzine with linezolid for an infection"}, {"id": "d", "text": "Fluoxetine with St. John''s Wort"}, {"id": "e", "text": "Haloperidol with lorazepam for agitation"}]'::jsonb, '["a", "b", "c", "d"]', 'SSRI + triptans, MAOI + linezolid, SSRI + St. John''s Wort, and two SSRIs together are all listed as dangerous serotonergic combinations. Haloperidol is an antipsychotic (dopamine antagonist) and lorazepam is used to treat agitation, so that pair is not a serotonergic combination.', true),
  ('serotonin', 7, 'A client stopped sertraline (Zoloft) 7 days ago because of poor response. The provider prescribes tranylcypromine (Parnate) to begin today. Which action by the nurse is BEST?', '[{"id": "a", "text": "Hold the MAOI; wait 14 days after the SSRI"}, {"id": "b", "text": "Give the MAOI; a 7-day washout is sufficient"}, {"id": "c", "text": "Give the MAOI and monitor for clonus"}, {"id": "d", "text": "Hold the MAOI; wait 5 weeks after the SSRI"}]'::jsonb, '["a"]', 'The nurse must wait 14 days after stopping an SSRI before starting an MAOI; violating this rule can cause fatal serotonin syndrome. The 5-week wait applies only to fluoxetine because of its long half-life.', false),
  ('serotonin', 8, 'A client is switching from fluoxetine to phenelzine (Nardil) for treatment-resistant depression. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll tell any new provider that I take an MAOI.\""}, {"id": "b", "text": "\"I''ll avoid St. John''s Wort while on these drugs.\""}, {"id": "c", "text": "\"I stopped fluoxetine 14 days ago, so I can start now.\""}, {"id": "d", "text": "\"Taking these two together could be fatal.\""}]'::jsonb, '["c"]', 'The MAOI washout after fluoxetine is 5 weeks, not 14 days, so starting now risks fatal serotonin syndrome. The MAOI + SSRI combination is the most dangerous and can be fatal, so the other statements are correct.', false),
  ('serotonin', 9, 'A client stopped phenelzine (Nardil) 10 days ago because of side effects and asks to begin sertraline today, as the provider suggested at the last visit. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"You can start now; the wait applies only after an SSRI.\""}, {"id": "b", "text": "\"Sertraline must wait until 14 days after the MAOI.\""}, {"id": "c", "text": "\"Start at a low dose and report any tremor.\""}, {"id": "d", "text": "\"Start it now; cyproheptadine will prevent problems.\""}]'::jsonb, '["b"]', 'The washout rule runs both ways: wait 14 days after stopping an MAOI before starting an SSRI, so 10 days is too soon. Cyproheptadine is a treatment for serotonin syndrome, not a reason to skip the washout.', false),
  ('serotonin', 10, 'The nurse reviews planned medication changes on a psychiatric unit. Which client changes should the nurse hold and clarify with the provider? Select all that apply.', '[{"id": "a", "text": "Sertraline stopped 7 days ago; MAOI to start today"}, {"id": "b", "text": "Fluoxetine stopped 3 weeks ago; MAOI to start today"}, {"id": "c", "text": "Phenelzine stopped 16 days ago; sertraline to start today"}, {"id": "d", "text": "Escitalopram stopped 15 days ago; MAOI to start today"}, {"id": "e", "text": "Phenelzine stopped 5 days ago; sertraline to start today"}]'::jsonb, '["a", "b", "e"]', 'Seven days after sertraline and 5 days after phenelzine are shorter than the 14-day washout, and 3 weeks after fluoxetine is shorter than its 5-week washout. Sixteen days after phenelzine and 15 days after escitalopram both meet the 14-day rule.', true),
  ('serotonin', 11, 'Several hours after the offending drugs were stopped, a client being treated for serotonin syndrome remains severely agitated, with muscle rigidity and hyperthermia. Which medication should the nurse expect to give as the BEST choice for these symptoms?', '[{"id": "a", "text": "Bromocriptine by mouth"}, {"id": "b", "text": "Dantrolene"}, {"id": "c", "text": "Sumatriptan"}, {"id": "d", "text": "Lorazepam (Ativan)"}]'::jsonb, '["d"]', 'Benzodiazepines such as lorazepam or diazepam are used for agitation, hyperthermia, seizures, and muscle rigidity in serotonin syndrome. Bromocriptine and dantrolene are NMS treatments, and sumatriptan is a serotonergic triptan that worsens the problem.', false),
  ('serotonin', 12, 'A client being treated for serotonin syndrome is confused and cannot swallow safely, and the provider prescribes cyproheptadine (Periactin). Which action by the nurse is BEST?', '[{"id": "a", "text": "Administer it by NG tube"}, {"id": "b", "text": "Hold it until swallowing improves"}, {"id": "c", "text": "Request dantrolene instead"}, {"id": "d", "text": "Give it with a triptan for headache"}]'::jsonb, '["a"]', 'Cyproheptadine is a serotonin antagonist that may be given orally or by NG tube, so the dose need not be delayed. Dantrolene is an NMS treatment, and a triptan is serotonergic.', false),
  ('serotonin', 13, 'A client taking an SSRI and a triptan has agitation, clonus, and hyperthermia, and the offending drugs have been stopped. Which medications should the nurse anticipate for this client? Select all that apply.', '[{"id": "a", "text": "Lorazepam (Ativan)"}, {"id": "b", "text": "Bromocriptine"}, {"id": "c", "text": "Haloperidol for agitation"}, {"id": "d", "text": "Cyproheptadine (Periactin)"}, {"id": "e", "text": "Dantrolene"}]'::jsonb, '["a", "d"]', 'Serotonin syndrome is treated with cyproheptadine (serotonin antagonist) and benzodiazepines such as lorazepam for agitation and hyperthermia. Dantrolene and bromocriptine are NMS treatments, and haloperidol is an antipsychotic—the drug class that causes NMS.', true),
  ('serotonin', 14, 'A client on fluoxetine who was started on linezolid is agitated, tremulous, hyperthermic, and hyperreflexic. The nurse has held all serotonergic medications. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Give an antihypertensive from the PRN orders"}, {"id": "b", "text": "Plan to restart the drugs at lower doses tomorrow"}, {"id": "c", "text": "Notify the provider of the findings"}, {"id": "d", "text": "Give sumatriptan for the client''s headache"}]'::jsonb, '["c"]', 'The priority sequence is to stop the offending drug(s), notify the provider, and begin supportive measures. Antihypertensives are given as needed for severe hypertension, which is not described, and sumatriptan is serotonergic.', false),
  ('serotonin', 15, 'A client''s serotonergic drugs were stopped 18 hours ago for mild serotonin syndrome, and the tremor is lessening. The client''s daughter asks how long recovery usually takes. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Symptoms usually last several weeks.\""}, {"id": "b", "text": "\"Most mild cases resolve within 24 hours.\""}, {"id": "c", "text": "\"Recovery depends on giving dantrolene.\""}, {"id": "d", "text": "\"It improves after the drug is restarted.\""}]'::jsonb, '["b"]', 'Most mild cases resolve within 24 hours of stopping the offending drug, which fits this client''s improving tremor. Dantrolene is an NMS treatment, and restarting the drug would bring the problem back.', false),
  ('serotonin', 16, 'A client with severe serotonin syndrome develops respiratory compromise, and the blood pressure remains severely elevated. Which interventions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Intubation and mechanical ventilation"}, {"id": "b", "text": "Bromocriptine by mouth for rigidity"}, {"id": "c", "text": "Antihypertensives as needed"}, {"id": "d", "text": "Resume the SSRI at a lower dose"}, {"id": "e", "text": "Dantrolene IV for hyperthermia"}]'::jsonb, '["a", "c"]', 'Intubation and mechanical ventilation are used for respiratory compromise in severe cases, and antihypertensives are given as needed for severe hypertension. Bromocriptine and dantrolene are NMS treatments, and resuming the SSRI contradicts stopping all serotonergic drugs.', true),
  ('serotonin', 17, 'A client who takes escitalopram for anxiety calls the clinic asking whether an over-the-counter cough medicine containing dextromethorphan is safe to use for a cold. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Yes; over-the-counter products do not interact.\""}, {"id": "b", "text": "\"Yes, but take half of the usual dose.\""}, {"id": "c", "text": "\"Yes, as long as you take it at bedtime.\""}, {"id": "d", "text": "\"Avoid it; it adds serotonergic activity.\""}]'::jsonb, '["d"]', 'Dextromethorphan in cough medicines is a serotonergic drug, and combining it with an SSRI such as escitalopram increases serotonin syndrome risk. Over-the-counter status does not make it safe, and lowering the dose or changing the timing does not remove the interaction.', false),
  ('serotonin', 18, 'A client who takes sertraline says, "I started St. John''s Wort last week to give my mood an extra boost." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"That combination can cause serotonin syndrome.\""}, {"id": "b", "text": "\"Herbal products are natural, so they are safe.\""}, {"id": "c", "text": "\"Take them at different times of the day.\""}, {"id": "d", "text": "\"Double the herb if your mood stays low.\""}]'::jsonb, '["a"]', 'St. John''s Wort is a serotonergic herbal supplement, and SSRI + St. John''s Wort is listed among the dangerous combinations. Calling herbal products safe is false reassurance, and separating doses does not prevent the interaction.', false),
  ('serotonin', 19, 'A client being discharged on fluoxetine has received counseling about drug interactions. Which client statements indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"I''ll tell my provider I use sumatriptan for migraines.\""}, {"id": "b", "text": "\"I''ll avoid MDMA (Ecstasy) at parties.\""}, {"id": "c", "text": "\"I can start an MAOI the day after stopping this.\""}, {"id": "d", "text": "\"I''ll check cough medicines for dextromethorphan.\""}, {"id": "e", "text": "\"St. John''s Wort is a safe herbal mood booster.\""}]'::jsonb, '["a", "b", "d"]', 'Dextromethorphan in cough medicines, triptans such as sumatriptan, and MDMA (Ecstasy) are serotonergic and dangerous with an SSRI. St. John''s Wort is also serotonergic, and an MAOI cannot be started until 5 weeks after fluoxetine is stopped.', true),
  ('serotonin', 20, 'A client who takes paroxetine (Paxil) used sumatriptan three times this week for migraines. The client is now restless and tremulous, with diarrhea and hyperreflexia. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Give another sumatriptan dose for the headache"}, {"id": "b", "text": "Encourage oral fluids to replace diarrhea losses"}, {"id": "c", "text": "Hold both drugs and notify the provider"}, {"id": "d", "text": "Apply ice packs and recheck in an hour"}]'::jsonb, '["c"]', 'SSRI + triptans is a dangerous combination, and these findings suggest serotonin syndrome; the first priority is stopping the offending drugs and notifying the provider. Fluids and cooling are supportive measures that follow, and more sumatriptan adds serotonergic activity.', false),
  ('serotonin', 21, 'A client who takes sertraline (Zoloft) for depression is admitted with an infection, and the provider orders linezolid. Which action by the nurse is BEST?', '[{"id": "a", "text": "Give the linezolid with food as ordered"}, {"id": "b", "text": "Clarify: linezolid has MAOI properties"}, {"id": "c", "text": "Give linezolid and monitor the CK level"}, {"id": "d", "text": "Give it; linezolid is only an antibiotic"}]'::jsonb, '["b"]', 'Linezolid is an antibiotic with MAOI properties, so combining it with an SSRI risks serotonin syndrome and the order must be clarified. Monitoring the CK does not prevent the interaction, and calling it only an antibiotic ignores its MAOI properties.', false),
  ('serotonin', 22, 'A client who takes phenelzine (Nardil) is being evaluated in urgent care for an injury. Which medications would place this client at risk for serotonin syndrome if given? Select all that apply.', '[{"id": "a", "text": "Fentanyl"}, {"id": "b", "text": "Cyproheptadine"}, {"id": "c", "text": "Tramadol"}, {"id": "d", "text": "Lorazepam"}, {"id": "e", "text": "Meperidine"}]'::jsonb, '["a", "c", "e"]', 'Tramadol, meperidine, and fentanyl are serotonergic opioids, and MAOI + tramadol/meperidine is among the most dangerous combinations. Lorazepam and cyproheptadine are used to treat serotonin syndrome.', true),
  ('serotonin', 23, 'A client who takes duloxetine (Cymbalta) is scheduled for a procedure in which methylene blue will be given. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Proceed, since methylene blue is only a dye"}, {"id": "b", "text": "Give duloxetine with the procedure medications"}, {"id": "c", "text": "Monitor CK levels after the procedure"}, {"id": "d", "text": "Report the duloxetine to the provider"}]'::jsonb, '["d"]', 'Methylene blue is listed with the MAOIs, and duloxetine is an SNRI; an MAOI with an SNRI is the most dangerous combination, so the provider must be informed. Monitoring the CK afterward does not prevent the interaction.', false),
  ('serotonin', 24, 'A febrile client takes both an SSRI and an antipsychotic. The nurse auscultates hyperactive bowel sounds, and the client has had several loose stools today. Which interpretation of this finding is MOST accurate?', '[{"id": "a", "text": "It favors serotonin syndrome over NMS"}, {"id": "b", "text": "It favors NMS over serotonin syndrome"}, {"id": "c", "text": "It fits both conditions equally"}, {"id": "d", "text": "It suggests the antipsychotic is the cause"}]'::jsonb, '["a"]', 'Bowel sounds are increased (diarrhea) in serotonin syndrome but decreased in NMS. An antipsychotic cause would point toward NMS, which this finding does not support.', false),
  ('serotonin', 25, 'A client taking both an antipsychotic and an SSRI is admitted with fever and altered mental status. Which findings favor neuroleptic malignant syndrome over serotonin syndrome? Select all that apply.', '[{"id": "a", "text": "Onset within hours of a dose change"}, {"id": "b", "text": "Lead-pipe rigidity"}, {"id": "c", "text": "Hyperreflexia"}, {"id": "d", "text": "Markedly elevated CK"}, {"id": "e", "text": "Normal or decreased reflexes"}]'::jsonb, '["b", "d", "e"]', 'NMS shows lead-pipe rigidity, a markedly elevated CK, and normal or decreased reflexes. Hyperreflexia and rapid onset within hours point to serotonin syndrome, whose CK is normal to mildly elevated.', true),
  ('serotonin', 26, 'A client admitted with fever and muscle rigidity has a history showing the symptoms developed gradually over 2 weeks after an antipsychotic was started. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Gradual onset points to serotonin syndrome"}, {"id": "b", "text": "Onset timing cannot help tell them apart"}, {"id": "c", "text": "Gradual onset over days to weeks suggests NMS"}, {"id": "d", "text": "Symptoms this slow indicate a mild serotonin reaction"}]'::jsonb, '["c"]', 'NMS has a gradual onset over days to weeks and is caused by antipsychotics, whereas serotonin syndrome is rapid—hours to 24 hours—after a serotonergic drug change. Onset timing is one of the listed differences between the two.', false),
  ('serotonin', 27, 'Two febrile clients on a psychiatric unit have altered mental status. Client A has a normal CK; Client B has a markedly elevated CK and lead-pipe rigidity. Which conclusion by the nurse is MOST accurate?', '[{"id": "a", "text": "Client A more likely has NMS"}, {"id": "b", "text": "Client B more likely has NMS"}, {"id": "c", "text": "Both most likely have serotonin syndrome"}, {"id": "d", "text": "CK does not differentiate the two"}]'::jsonb, '["b"]', 'NMS features lead-pipe rigidity and a high (markedly elevated) CK, while serotonin syndrome has a normal to mildly elevated CK. CK level is one of the listed differences, so it does help differentiate the two.', false),
  ('serotonin', 28, 'A client who takes phenelzine (Nardil) returns from surgery with orders for several PRN medications. Which order should the nurse question FIRST?', '[{"id": "a", "text": "Lorazepam for anxiety"}, {"id": "b", "text": "IV fluids for maintenance"}, {"id": "c", "text": "Oxygen by nasal cannula"}, {"id": "d", "text": "Meperidine for pain"}]'::jsonb, '["d"]', 'MAOI + tramadol/meperidine is one of the most dangerous combinations for serotonin syndrome. Lorazepam, IV fluids, and oxygen are not serotonergic and are even part of serotonin syndrome treatment.', false),
  ('serotonin', 29, 'The family of a client who takes fluoxetine and started tramadol 6 hours ago calls the nurse with concerns. Which reported findings are consistent with a dangerous interaction between these drugs? Select all that apply.', '[{"id": "a", "text": "Decreased bowel sounds"}, {"id": "b", "text": "Tremor and incoordination"}, {"id": "c", "text": "Agitation and restlessness"}, {"id": "d", "text": "New confusion"}, {"id": "e", "text": "Myoclonus (muscle jerks)"}]'::jsonb, '["b", "c", "d", "e"]', 'Fluoxetine plus tramadol can cause serotonin syndrome within hours: agitation, restlessness, and confusion are mental status changes, and myoclonus, tremor, and incoordination are neuromuscular abnormalities. Bowel sounds are increased (diarrhea) in serotonin syndrome; decreased bowel sounds fit NMS.', true),
  ('serotonin', 30, 'An adolescent who takes sertraline is brought to the emergency department from a party with agitation, hyperthermia, diaphoresis, and clonus. Which question is MOST important for the nurse to ask?', '[{"id": "a", "text": "\"Did you take Ecstasy (MDMA) or other drugs?\""}, {"id": "b", "text": "\"Have you started an antipsychotic recently?\""}, {"id": "c", "text": "\"When did you last eat a full meal?\""}, {"id": "d", "text": "\"Have you had trouble sleeping this week?\""}]'::jsonb, '["a"]', 'MDMA (Ecstasy), LSD, and cocaine are serotonergic, and with an SSRI they can cause the rapid hyperthermia, agitation, and clonus described. An antipsychotic would point to NMS, which develops gradually and lacks clonus.', false),
  ('serotonin', 31, 'The nurse receives report on four clients on a medical-psychiatric unit. Which client should the nurse see FIRST?', '[{"id": "a", "text": "A client on sertraline asking whether St. John''s Wort is safe to add"}, {"id": "b", "text": "A client recovering from mild serotonin syndrome whose tremor is fading"}, {"id": "c", "text": "A client on venlafaxine with clonus and hyperthermia after a dose increase"}, {"id": "d", "text": "A client on haloperidol for 3 weeks with stable vital signs and no rigidity"}]'::jsonb, '["c"]', 'Clonus and hyperthermia soon after a dose increase suggest serotonin syndrome, which has rapid onset and can progress quickly to death. The question about St. John''s Wort needs teaching, and the recovering client is improving as expected.', false),
  ('serotonin', 32, 'A client who takes sertraline is being admitted, and the nurse reviews the client''s other medications and substance use. Which items increase this client''s risk of serotonin syndrome? Select all that apply.', '[{"id": "a", "text": "Duloxetine"}, {"id": "b", "text": "Cocaine use"}, {"id": "c", "text": "Sumatriptan"}, {"id": "d", "text": "Imipramine"}, {"id": "e", "text": "Haloperidol"}]'::jsonb, '["a", "b", "c", "d"]', 'Triptans (sumatriptan), TCAs (imipramine), SNRIs (duloxetine), and cocaine are serotonergic and add to the SSRI. Haloperidol is an antipsychotic (dopamine antagonist), the drug class that causes NMS rather than serotonin syndrome.', true),
  ('serotonin', 33, 'The spouse of a client admitted with serotonin syndrome asks what caused it. The client recently added tramadol to daily venlafaxine. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"It is an allergic reaction to the tramadol.\""}, {"id": "b", "text": "\"The drugs together caused too much serotonin activity.\""}, {"id": "c", "text": "\"It is caused by stopping venlafaxine too quickly.\""}, {"id": "d", "text": "\"It is a common side effect of venlafaxine alone at any dose.\""}]'::jsonb, '["b"]', 'Serotonin syndrome is a drug-induced excess of serotonergic activity, typically from drug interactions such as an SNRI plus tramadol. It is not an allergy, and it results from adding serotonergic drugs, not stopping them.', false),
  ('serotonin', 34, 'A client who began duloxetine plus an over-the-counter cough medicine with dextromethorphan yesterday reports feeling anxious and shaky, and the nurse notes mild tremor and tachycardia. The client asks to "sleep it off." Which response by the nurse is BEST?', '[{"id": "a", "text": "Let the client rest and recheck in the morning"}, {"id": "b", "text": "Reassure that these are expected side effects"}, {"id": "c", "text": "Give an extra duloxetine dose to ease the anxiety"}, {"id": "d", "text": "Notify the provider; this can progress quickly"}]'::jsonb, '["d"]', 'Early findings after combining two serotonergic drugs suggest serotonin syndrome, which can progress quickly to death if not treated, so the provider is notified now. Waiting until morning or reassuring the client delays treatment.', false),
  ('serotonin', 35, 'A client being treated for serotonin syndrome suddenly develops a generalized seizure. Which medication should the nurse prepare to give IMMEDIATELY?', '[{"id": "a", "text": "Lorazepam (Ativan)"}, {"id": "b", "text": "Bromocriptine"}, {"id": "c", "text": "Cyproheptadine by mouth"}, {"id": "d", "text": "Sumatriptan"}]'::jsonb, '["a"]', 'Benzodiazepines such as lorazepam or diazepam treat seizures in serotonin syndrome. Cyproheptadine is a serotonin antagonist but is not given by mouth to a seizing client, and bromocriptine is an NMS treatment.', false),
  ('serotonin', 36, 'All serotonergic drugs have been stopped for a client with tachycardia, hyperthermia, and diaphoresis, and the provider has been notified. Which supportive measures should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Restart the SSRI at a lower dose"}, {"id": "b", "text": "Dantrolene infusion"}, {"id": "c", "text": "IV fluids as ordered"}, {"id": "d", "text": "Cardiac monitoring"}, {"id": "e", "text": "Oxygen therapy"}]'::jsonb, '["c", "d", "e"]', 'Supportive care for serotonin syndrome includes IV fluids, oxygen, and cardiac monitoring. Restarting the SSRI contradicts stopping all serotonergic drugs, and dantrolene is an NMS treatment.', true),
  ('serotonin', 37, 'The parent of an adolescent being treated for serotonin syndrome asks why cyproheptadine (Periactin) was ordered. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "\"It relaxes muscles like dantrolene does.\""}, {"id": "b", "text": "\"It replaces the serotonin the body lost.\""}, {"id": "c", "text": "\"It acts as a serotonin antagonist.\""}, {"id": "d", "text": "\"It lowers the CK level in the blood.\""}]'::jsonb, '["c"]', 'Cyproheptadine is a serotonin antagonist used to treat serotonin syndrome, which is a state of excess serotonin. Dantrolene is used for NMS, and replacing serotonin would worsen the problem.', false),
  ('serotonin', 38, 'A client with serotonin syndrome has hyperthermia, and the nurse has assigned unlicensed assistive personnel (UAP) to help with care. Which UAP action requires IMMEDIATE intervention by the nurse?', '[{"id": "a", "text": "Placing ice packs as directed by the nurse"}, {"id": "b", "text": "Covering the client with extra warm blankets"}, {"id": "c", "text": "Reporting new muscle jerking to the nurse"}, {"id": "d", "text": "Keeping the cooling blanket in place"}]'::jsonb, '["b"]', 'Hyperthermia is managed with cooling measures such as ice packs and cooling blankets, so adding warm blankets must be stopped. Reporting new muscle jerking (myoclonus) is appropriate.', false),
  ('serotonin', 39, 'The nurse assesses a client with suspected serotonin excess after a new drug was added. Which findings belong to the neuromuscular abnormalities of the classic triad? Select all that apply.', '[{"id": "a", "text": "Hypertension"}, {"id": "b", "text": "Incoordination"}, {"id": "c", "text": "Tachycardia"}, {"id": "d", "text": "Restlessness"}, {"id": "e", "text": "Myoclonus"}]'::jsonb, '["b", "e"]', 'Incoordination and myoclonus are neuromuscular abnormalities. Tachycardia and hypertension are autonomic instability, and restlessness is a mental status change.', true),
  ('serotonin', 40, 'A client was told to switch from paroxetine to sertraline. At a follow-up visit the client is restless and diaphoretic with a tremor and reports taking both pills every day "to be safe." Which action is the nurse''s PRIORITY?', '[{"id": "a", "text": "Reinforce taking both pills until the switch ends"}, {"id": "b", "text": "Advise taking the two pills at different times"}, {"id": "c", "text": "Teach that sweating is expected with sertraline"}, {"id": "d", "text": "Report taking two SSRIs together to the provider"}]'::jsonb, '["d"]', 'Two SSRIs together is a dangerous combination, and restlessness, diaphoresis, and tremor suggest serotonin syndrome, so the provider must be notified. Separating the doses does not remove the interaction, and calling sweating expected is false reassurance.', false),
  ('serotonin', 41, 'The nurse compares two febrile clients. Client 1 is markedly agitated with myoclonus. Client 2 is less agitated and has severe, uniform resistance to passive movement. Which client MOST likely has serotonin syndrome?', '[{"id": "a", "text": "Client 1, given prominent agitation and myoclonus"}, {"id": "b", "text": "Client 2, given the severe, uniform muscle resistance"}, {"id": "c", "text": "Client 1, because fever is present"}, {"id": "d", "text": "Client 2, because agitation is less marked"}]'::jsonb, '["a"]', 'Serotonin syndrome shows prominent agitation and myoclonus with rhythmic contractions, while NMS has lead-pipe rigidity (severe, uniform resistance) and less marked agitation. Fever occurs in both, so it does not distinguish them.', false),
  ('serotonin', 42, 'A client with severe serotonin syndrome becomes increasingly drowsy, with shallow, labored respirations and falling oxygen saturation despite oxygen therapy. Which action should the nurse anticipate NEXT?', '[{"id": "a", "text": "Giving the cyproheptadine dose by mouth"}, {"id": "b", "text": "Applying a cooling blanket and ice packs"}, {"id": "c", "text": "Preparing for intubation and ventilation"}, {"id": "d", "text": "Giving an ordered antihypertensive medication"}]'::jsonb, '["c"]', 'Intubation and mechanical ventilation are used when respiratory compromise occurs in severe cases. Oral cyproheptadine is unsafe in a drowsy client with failing respirations, and cooling or antihypertensives do not address the airway.', false),
  ('serotonin', 43, 'A client is being treated for serotonin syndrome after all offending drugs were stopped. Which new findings require IMMEDIATE report to the provider? Select all that apply.', '[{"id": "a", "text": "Decreasing tremor"}, {"id": "b", "text": "Normal temperature"}, {"id": "c", "text": "Seizure activity"}, {"id": "d", "text": "Respiratory compromise"}, {"id": "e", "text": "Severe hypertension"}]'::jsonb, '["c", "d", "e"]', 'Seizures, respiratory compromise, and severe hypertension are complications that need benzodiazepines, intubation, or antihypertensives. A decreasing tremor and normal temperature show improvement, as most mild cases resolve within 24 hours.', true),
  ('serotonin', 44, 'A client who takes escitalopram began linezolid 12 hours ago. The client''s temperature, heart rate, and blood pressure are elevated, and the client is diaphoretic. Which interpretation of these findings is MOST accurate?', '[{"id": "a", "text": "Neuromuscular abnormalities from excess serotonin"}, {"id": "b", "text": "Autonomic instability from excess serotonin"}, {"id": "c", "text": "Mental status changes from excess serotonin"}, {"id": "d", "text": "Expected effects of the antibiotic alone"}]'::jsonb, '["b"]', 'Hyperthermia, tachycardia, hypertension, and diaphoresis make up the autonomic instability part of the triad, caused here by linezolid (MAOI properties) with an SSRI. Neuromuscular abnormalities are clonus, hyperreflexia, tremor, and myoclonus.', false),
  ('serotonin', 45, 'A client who uses sumatriptan for migraines is starting sertraline and asks when a dangerous interaction would MOST likely show up. Which response by the nurse is accurate?', '[{"id": "a", "text": "After several weeks of taking both drugs together"}, {"id": "b", "text": "After the first month of combined therapy"}, {"id": "c", "text": "Gradually over days to weeks of therapy"}, {"id": "d", "text": "Within 24 hours of a new drug or dose increase"}]'::jsonb, '["d"]', 'Serotonin syndrome typically has a rapid onset within 24 hours of starting a new drug or increasing a dose. Gradual onset over days to weeks describes NMS.', false),
  ('serotonin', 46, 'Twelve hours after all serotonergic drugs were stopped and cyproheptadine was given, the nurse reassesses a client with serotonin syndrome. Which finding BEST indicates the treatment is effective?', '[{"id": "a", "text": "Clonus and hyperreflexia have resolved"}, {"id": "b", "text": "Bowel sounds are increased with new diarrhea"}, {"id": "c", "text": "Agitation has become more prominent"}, {"id": "d", "text": "Temperature has risen further"}]'::jsonb, '["a"]', 'Clonus and hyperreflexia are hallmark signs of serotonin syndrome, so their resolution shows improvement; most mild cases resolve within 24 hours of stopping the drug. Increased bowel sounds with diarrhea, worsening agitation, and rising temperature are ongoing signs of the syndrome.', false),
  ('serotonin', 47, 'A client recovering from serotonin syndrome caused by sertraline plus tramadol receives discharge teaching. Which client statements indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "\"I''ll ask my provider before adding any migraine drug.\""}, {"id": "b", "text": "\"St. John''s Wort is fine because it is herbal.\""}, {"id": "c", "text": "\"I''ll tell every provider that I take an SSRI.\""}, {"id": "d", "text": "\"I''ll ask before taking any new pain medicine.\""}, {"id": "e", "text": "\"I''ll take tramadol again if my back pain returns.\""}]'::jsonb, '["b", "e"]', 'Tramadol is a serotonergic opioid, and St. John''s Wort is a serotonergic herbal supplement that is dangerous with an SSRI, so both statements need correction. Checking before adding triptans or new pain medicines and telling providers about the SSRI are correct.', true),
  ('serotonin', 48, 'A client who takes amitriptyline for depression is prescribed tramadol after a dental extraction. Which concern is the PRIORITY to report to the health care provider?', '[{"id": "a", "text": "Risk of NMS from the combination"}, {"id": "b", "text": "Lead-pipe rigidity from tramadol"}, {"id": "c", "text": "Serotonin syndrome from the combination"}, {"id": "d", "text": "No concern, because TCAs are not serotonergic"}]'::jsonb, '["c"]', 'TCAs such as amitriptyline and opioids such as tramadol are both serotonergic, so the combination raises serotonin syndrome risk. NMS and lead-pipe rigidity are linked to antipsychotics, not this combination.', false),
  ('serotonin', 49, 'A client taking haloperidol, with no serotonergic drugs on the medication list, has developed fever, lead-pipe rigidity, and a markedly elevated CK over the past week. Which prescription should the nurse question FIRST?', '[{"id": "a", "text": "Dantrolene"}, {"id": "b", "text": "Cyproheptadine"}, {"id": "c", "text": "Bromocriptine"}, {"id": "d", "text": "Cooling measures"}]'::jsonb, '["b"]', 'These findings indicate NMS, treated by stopping the antipsychotic and giving dantrolene, bromocriptine, and supportive care. Cyproheptadine is the serotonin antagonist used for serotonin syndrome, a condition with a different cause.', false),
  ('serotonin', 50, 'The nurse reviews medication lists for clients on a psychiatric unit. Which client''s medication combination carries the HIGHEST risk for a fatal serotonergic reaction?', '[{"id": "a", "text": "Sertraline with sumatriptan"}, {"id": "b", "text": "Fluoxetine with St. John''s Wort"}, {"id": "c", "text": "Escitalopram with dextromethorphan"}, {"id": "d", "text": "Phenelzine with venlafaxine"}]'::jsonb, '["d"]', 'An MAOI (phenelzine) plus any SSRI/SNRI (venlafaxine) is the most dangerous combination and can be fatal. The other pairs are also risky serotonergic combinations but are not ranked as most dangerous.', false),
  ('parenting', 1, 'At a well-child visit, the father of a 10-year-old says, "I make the rules in my house and nobody argues. If he questions one, he loses every privilege for a week — I don''t owe him an explanation." The child sits silently and does not answer the nurse''s questions. Which parenting style is the father MOST likely using?', '[{"id": "a", "text": "Authoritative"}, {"id": "b", "text": "Permissive / indulgent"}, {"id": "c", "text": "Authoritarian"}, {"id": "d", "text": "Uninvolved / neglectful"}]'::jsonb, '["c"]', 'Authoritarian parenting is cold and strict, with punitive discipline, no explanations ("my way or no way"), and one-way communication in which the child is not encouraged to question. Authoritative parents are also demanding but explain reasons for rules and consider the child''s input.', false),
  ('parenting', 2, 'The mother of a 6-year-old tells the nurse, "I''m more her friend than her parent. She picks her own bedtime, and when she hits her brother I don''t punish her — I hate seeing her upset." The mother is affectionate and attentive throughout the visit. Which parenting style is MOST evident?', '[{"id": "a", "text": "Permissive / indulgent"}, {"id": "b", "text": "Authoritarian"}, {"id": "c", "text": "Uninvolved / neglectful"}, {"id": "d", "text": "Authoritative"}]'::jsonb, '["a"]', 'Permissive/indulgent parenting is warm and friend-like with few rules, rarely enforces consequences, avoids confrontation, and gives the child much control over decisions. Uninvolved parents also set few rules but are detached and indifferent, unlike this attentive mother.', false),
  ('parenting', 3, 'A school nurse notes that an 11-year-old frequently comes to school without lunch, wears the same clothes for days, and says, "My mom doesn''t really care where I go after school." The mother does not return calls and has never attended a conference. Which parenting style do these findings MOST suggest?', '[{"id": "a", "text": "Authoritarian"}, {"id": "b", "text": "Permissive / indulgent"}, {"id": "c", "text": "Authoritative"}, {"id": "d", "text": "Uninvolved / neglectful"}]'::jsonb, '["d"]', 'Uninvolved/neglectful parenting is detached, indifferent, and emotionally unavailable, with no expectations, minimal supervision, and basic needs that may not even be met. Permissive parents also have few rules but are very warm and nurturing.', false),
  ('parenting', 4, 'A nurse is observing parents at a pediatric clinic. Which parent behaviors are consistent with the authoritative parenting style? Select all that apply.', '[{"id": "a", "text": "Explains to a child why the bedtime rule matters for school"}, {"id": "b", "text": "Rarely enforces consequences to avoid a confrontation"}, {"id": "c", "text": "Considers the child''s input in two-way communication"}, {"id": "d", "text": "Gives punitive consequences with no explanation"}, {"id": "e", "text": "Lets the child feel the natural consequences of choices"}]'::jsonb, '["a", "c", "e"]', 'Authoritative discipline is firm but fair and explains reasons for rules (a), communication is two-way with the child''s input considered (c), and natural consequences are used (e). Rarely enforcing consequences (b) is permissive, and punitive consequences with no explanation (d) are authoritarian.', true),
  ('parenting', 5, 'A father sets a firm 9 p.m. curfew for his 15-year-old, explains that it is for her safety, discusses exceptions with her when she asks, and follows through consistently when she breaks it. Which parenting style is the father MOST likely using?', '[{"id": "a", "text": "Permissive / indulgent"}, {"id": "b", "text": "Authoritative"}, {"id": "c", "text": "Authoritarian"}, {"id": "d", "text": "Uninvolved / neglectful"}]'::jsonb, '["b"]', 'Authoritative parenting is warm and firm: clear expectations, consistent rules, explanations for rules, and open two-way communication. Authoritarian parents are equally demanding but give no explanations and do not encourage the child to question.', false),
  ('parenting', 6, 'A 19-year-old college freshman was raised by parents who enforced strict, rigid rules with punishment and never explained their reasons. His roommate reports that since leaving home he has been skipping classes and breaking every dorm rule. Which explanation is MOST consistent with his upbringing?', '[{"id": "a", "text": "Authoritarian parenting can lead to defiance when removed from parental control"}, {"id": "b", "text": "Permissive parenting leads to difficulty with authority and following rules"}, {"id": "c", "text": "Authoritative parenting leads to self-reliance that rejects outside rules"}, {"id": "d", "text": "Uninvolved parenting leads to delinquency because of a lack of supervision"}]'::jsonb, '["a"]', 'Children of authoritarian parents are obedient but may be more prone to defiance when removed from parental control. Permissive parenting also causes difficulty with authority, but this student''s parents were strict and rigid, not lenient.', false),
  ('parenting', 7, 'A 7-year-old''s parents are warm and loving but rarely set or enforce rules; the teacher reports that the child cannot wait his turn, grabs toys from classmates, and argues with the teacher about classroom rules. The nurse should anticipate which additional risk as the child reaches adolescence?', '[{"id": "a", "text": "Lowest self-esteem and emotional regulation of all styles"}, {"id": "b", "text": "Obedience combined with anxiety and low self-esteem"}, {"id": "c", "text": "Higher risk of substance abuse and risky behaviors"}, {"id": "d", "text": "Attachment issues and difficulty forming relationships"}]'::jsonb, '["c"]', 'The child shows permissive-parenting outcomes (poor self-regulation and impulse control, difficulty with authority), and permissive parenting also carries a higher risk of substance abuse and risky behaviors. The lowest self-esteem of all styles and attachment issues are outcomes of uninvolved parenting.', false),
  ('parenting', 8, 'A 4-year-old is brought to the clinic by a neighbor, who reports that the child is often left alone for hours, has missed meals, and has an untreated wound on her leg. The mother, reached by phone, says, "She''s fine; she takes care of herself." Which nursing action is the PRIORITY?', '[{"id": "a", "text": "Report the situation as a mandatory reporter"}, {"id": "b", "text": "Refer the mother to a community parenting class"}, {"id": "c", "text": "Teach the mother about authoritative parenting"}, {"id": "d", "text": "Screen the mother for parenting stress at follow-up"}]'::jsonb, '["a"]', 'Uninvolved/neglectful parenting that results in harm or unmet needs creates a mandatory reporter obligation, which takes priority. Parenting classes, teaching, and stress screening are appropriate later but do not address a child whose basic needs are not being met.', false),
  ('parenting', 9, 'A 9-year-old''s parents are very warm and nurturing but set few expectations and avoid confrontation. Which outcomes should the nurse anticipate in this child? Select all that apply.', '[{"id": "a", "text": "Poor self-regulation and impulse control"}, {"id": "b", "text": "Lowest self-esteem of all parenting styles"}, {"id": "c", "text": "Difficulty following rules in school"}, {"id": "d", "text": "May be creative, social, and have high self-esteem"}, {"id": "e", "text": "Obedient but anxious, with low self-reliance"}]'::jsonb, '["a", "c", "d"]', 'Permissive parenting is associated with poor self-regulation and impulse control (a), difficulty with authority and following rules in school (c), and children who may be creative, social, and have high self-esteem (d). The lowest self-esteem of all styles (b) follows uninvolved parenting, and obedient but anxious children (e) follow authoritarian parenting.', true),
  ('parenting', 10, 'A family who recently immigrated brings their 8-year-old for a well-child visit. The parents describe strict rules, high expectations, and expected obedience; the child is clean, well nourished, up to date on care, and doing well in school. Which interpretation by the nurse is MOST appropriate?', '[{"id": "a", "text": "The family is neglectful and should be reported to protect the child"}, {"id": "b", "text": "The parents should be told to change to the authoritative style today"}, {"id": "c", "text": "Some cultures are more authoritarian, which is not always harmful"}, {"id": "d", "text": "The child''s needs are met, so parenting style does not need assessing"}]'::jsonb, '["c"]', 'Nurses should consider cultural variations — some cultures are traditionally more authoritarian, which is not always neglectful or harmful. This child''s needs are being met, so there is no basis for a report, but parenting style is still assessed at well-child visits.', false),
  ('parenting', 11, 'A first-time parent of a 3-year-old asks the nurse, "There''s so much conflicting advice. Which approach to parenting should I aim for?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Keep strict rules and expect obedience without long explanations.\""}, {"id": "b", "text": "\"Combine warmth with clear rules, and explain the reasons for them.\""}, {"id": "c", "text": "\"Let her lead; being her friend with few rules builds her confidence.\""}, {"id": "d", "text": "\"Step back and let her learn independence with minimal supervision.\""}]'::jsonb, '["b"]', 'Authoritative parenting — warm and firm, with clear expectations and explanations for rules — is the recommended, evidence-based model to promote; warmth plus structure is the best combination. Few rules (permissive) leads to poor self-regulation, and strict obedience without explanations is authoritarian.', false),
  ('parenting', 12, 'During a well-child visit, a single mother of three says she has been yelling at her children constantly, "can''t keep up with anything," and has been drinking wine every night to cope. The children appear clean and well fed. Which nursing action is the NEXT priority?', '[{"id": "a", "text": "Report the mother as a mandatory reporter for neglect"}, {"id": "b", "text": "Teach the mother the four parenting styles today"}, {"id": "c", "text": "Reassure her that all parents feel this way at times"}, {"id": "d", "text": "Screen for parenting stress, mental health, and substance use"}]'::jsonb, '["d"]', 'Nurses screen for parenting stress, mental health disorders, and substance use because all of these affect parenting style. The children''s needs appear met, so a neglect report is not indicated at this point, and reassurance alone ignores the risk factors she describes.', false),
  ('parenting', 13, 'A father is nurturing and accepting of his 12-year-old son''s feelings but sets almost no rules, and the son decides his own screen time, homework schedule, and bedtime. On Baumrind''s two dimensions, how should the nurse classify this father''s parenting BEST?', '[{"id": "a", "text": "High responsiveness and low demandingness"}, {"id": "b", "text": "Low responsiveness and high demandingness"}, {"id": "c", "text": "High responsiveness and high demandingness"}, {"id": "d", "text": "Low responsiveness and low demandingness"}]'::jsonb, '["a"]', 'Responsiveness (warmth) is how much the parent responds to the child''s emotional needs, and demandingness (control) is how much the parent enforces rules. A nurturing father with almost no rules is high responsiveness and low demandingness — the permissive/indulgent style.', false),
  ('parenting', 14, 'A nurse is reviewing parent behaviors documented in four families. Which parent behaviors indicate the authoritarian style? Select all that apply.', '[{"id": "a", "text": "Treats the child as a friend and avoids conflict"}, {"id": "b", "text": "Answers a child''s \"Why?\" with \"Because I said so\""}, {"id": "c", "text": "Provides minimal supervision and seems indifferent"}, {"id": "d", "text": "Dictates rules and does not invite the child''s questions"}, {"id": "e", "text": "Explains rules and considers the child''s opinion"}]'::jsonb, '["b", "d"]', 'Authoritarian parenting is "Because I said so" — cold and strict — with one-way communication in which the parent dictates and the child is not encouraged to question (b, d). Friend-like conflict avoidance (a) is permissive, indifference with minimal supervision (c) is uninvolved, and explaining rules with the child''s input (e) is authoritative.', true),
  ('parenting', 15, 'Two fathers in a parenting group both enforce strict curfews for their teenagers. Father A explains why the curfew matters and listens to his daughter''s view; Father B says, "Rules are rules — you don''t get a say." Which statement by the nurse is MOST accurate?', '[{"id": "a", "text": "Both fathers are authoritarian because both are highly demanding"}, {"id": "b", "text": "Father A is authoritative and Father B is authoritarian"}, {"id": "c", "text": "Father A is permissive and Father B is authoritative"}, {"id": "d", "text": "Both fathers are authoritative because both set clear rules"}]'::jsonb, '["b"]', 'Both authoritative and authoritarian parenting are highly demanding; the difference is warmth and communication. Father A explains reasons and considers the child''s input (authoritative), while Father B uses one-way communication with no explanation (authoritarian).', false),
  ('parenting', 16, 'A mother lets her 8-year-old stay up as late as he wants and eat whatever he chooses, but she rarely speaks to him, does not know his teacher''s name, and seems indifferent when he cries during the visit. Which parenting style is MOST evident?', '[{"id": "a", "text": "Permissive / indulgent"}, {"id": "b", "text": "Authoritarian"}, {"id": "c", "text": "Authoritative"}, {"id": "d", "text": "Uninvolved"}]'::jsonb, '["d"]', 'Both permissive and uninvolved parenting are low in demandingness, but this mother is detached and indifferent (very low warmth), which defines uninvolved/neglectful parenting. A permissive parent would be very warm, nurturing, and friend-like.', false),
  ('parenting', 17, 'A nurse is teaching parents of preschoolers about Baumrind''s two dimensions of parenting. Which parent behaviors reflect HIGH demandingness? Select all that apply.', '[{"id": "a", "text": "Enforces consistent rules with clear expectations"}, {"id": "b", "text": "Lets the child set her own bedtime each night"}, {"id": "c", "text": "Is nurturing and accepting of the child''s feelings"}, {"id": "d", "text": "Expects obedience to strict rules and structure"}, {"id": "e", "text": "Provides minimal supervision during the day"}]'::jsonb, '["a", "d"]', 'Demandingness (control) is how much the parent expects and enforces compliance through rules, structure, and discipline: enforcing consistent rules with clear expectations (a) and expecting obedience to strict rules (d). Letting the child set bedtime (b) and minimal supervision (e) are low demandingness, and being nurturing and accepting (c) describes responsiveness (warmth), not demandingness.', true),
  ('parenting', 18, 'A 12-year-old with anxiety and low self-esteem cannot choose what to order at a restaurant without asking a parent and says, "I just do what I''m told so I don''t get punished." Which parenting style MOST likely contributed to this presentation?', '[{"id": "a", "text": "Authoritarian"}, {"id": "b", "text": "Permissive / indulgent"}, {"id": "c", "text": "Authoritative"}, {"id": "d", "text": "Uninvolved / neglectful"}]'::jsonb, '["a"]', 'Children of authoritarian parents tend to be obedient but may struggle with independent decision-making and have lower self-esteem and higher rates of anxiety. Uninvolved parenting produces the lowest self-esteem but is not associated with punishment-driven obedience.', false),
  ('parenting', 19, 'A school nurse evaluates a 10-year-old who is creative, popular with classmates, and confident, but who interrupts constantly, cannot control impulses, and argues whenever teachers enforce rules. Which parenting style at home MOST likely explains this combination?', '[{"id": "a", "text": "Authoritative"}, {"id": "b", "text": "Authoritarian"}, {"id": "c", "text": "Permissive / indulgent"}, {"id": "d", "text": "Uninvolved / neglectful"}]'::jsonb, '["c"]', 'Children of permissive parents may be creative, social, and have high self-esteem, yet show poor self-regulation and impulse control and difficulty with authority. Authoritative parenting also produces high self-esteem, but with good self-regulation and fewer behavioral problems.', false),
  ('parenting', 20, 'A community health nurse is reviewing four families during home visits. Which child is at HIGHEST risk for poor outcomes based on the parenting style described?', '[{"id": "a", "text": "A child whose parents explain rules and enforce them consistently"}, {"id": "b", "text": "A child whose parents are detached and provide minimal supervision"}, {"id": "c", "text": "A child whose parents are warm and lenient and set very few rules"}, {"id": "d", "text": "A child whose parents are strict, punitive, and expect obedience"}]'::jsonb, '["b"]', 'Uninvolved/neglectful parenting — detached, with minimal supervision — has the worst outcomes and is the most harmful style. Strict, punitive (authoritarian) and lenient (permissive) parenting carry risks, but not the worst outcomes.', false),
  ('parenting', 21, 'A nurse is assessing a 13-year-old whose parents are emotionally unavailable, set no expectations, and rarely know where she is. Which outcomes is this adolescent at increased risk for? Select all that apply.', '[{"id": "a", "text": "High self-esteem with creativity and social skills"}, {"id": "b", "text": "Attachment issues and difficulty forming relationships"}, {"id": "c", "text": "Poor academic performance and behavioral problems"}, {"id": "d", "text": "Higher rates of delinquency and substance abuse"}, {"id": "e", "text": "Lowest self-esteem and emotional regulation of all styles"}]'::jsonb, '["b", "c", "d", "e"]', 'Uninvolved parenting is associated with attachment issues (b), poor academic performance and behavioral problems (c), higher rates of delinquency and substance abuse (d), and the lowest self-esteem and emotional regulation of all styles (e). Creativity, social skills, and high self-esteem (a) may occur with permissive parenting.', true),
  ('parenting', 22, 'After a parenting class, the mother of a 5-year-old makes several statements to the nurse. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll set clear rules and explain to him why each one matters.\""}, {"id": "b", "text": "\"I can be warm and supportive while still being firm with him.\""}, {"id": "c", "text": "\"I''ll listen to his input, but I''ll follow through on the rules.\""}, {"id": "d", "text": "\"Being his friend with few rules will give him the best outcomes.\""}]'::jsonb, '["d"]', 'Being friend-like with few rules is permissive parenting, which leads to poor self-regulation and impulse control; authoritative parenting (warm + firm) produces the best outcomes. The other statements describe authoritative parenting accurately.', false),
  ('parenting', 23, 'The parents of a 2-year-old with frequent tantrums tell the nurse they alternate between giving in and yelling, feel exhausted, and want to "do better." The child is healthy, well cared for, and meeting milestones. Which nursing action is BEST?', '[{"id": "a", "text": "Report the parents for neglect as a mandatory reporter"}, {"id": "b", "text": "Reassure the parents that the tantrums will resolve with age"}, {"id": "c", "text": "Refer the parents to parenting classes as appropriate"}, {"id": "d", "text": "Advise the parents to use stricter punishment without explanation"}]'::jsonb, '["c"]', 'Nurses refer families to parenting classes or family therapy as appropriate, which fits motivated parents with inconsistent discipline. A report is not indicated because the child''s needs are met, and punishment without explanation is authoritarian.', false),
  ('parenting', 24, 'A nurse is evaluating a 16-year-old whose parents have used warm, firm, and fair parenting with consistent rules and open communication. Which outcomes would the nurse expect in this adolescent? Select all that apply.', '[{"id": "a", "text": "High self-esteem and self-reliance"}, {"id": "b", "text": "Socially competent and academically successful"}, {"id": "c", "text": "Obedient but struggles with independent decisions"}, {"id": "d", "text": "Good decision-making skills"}, {"id": "e", "text": "Better mental health with fewer behavioral problems"}]'::jsonb, '["a", "b", "d", "e"]', 'Authoritative parenting produces high self-esteem and self-reliance (a), social competence and academic success (b), good decision-making skills (d), and better mental health with fewer behavioral problems (e). Obedience with difficulty making independent decisions (c) is an authoritarian outcome.', true),
  ('parenting', 25, 'A mother is described by her children as cold and demanding; she enforces many rigid rules and rarely shows affection, but she is always aware of where they are. On Baumrind''s two dimensions, how should the nurse classify this mother''s parenting MOST accurately?', '[{"id": "a", "text": "High responsiveness and high demandingness"}, {"id": "b", "text": "Low responsiveness and high demandingness"}, {"id": "c", "text": "High responsiveness and low demandingness"}, {"id": "d", "text": "Low responsiveness and low demandingness"}]'::jsonb, '["b"]', 'Cold, less nurturing parenting with strict, rigid rules is low responsiveness and high demandingness — the authoritarian style. Low responsiveness with low demandingness describes uninvolved parents, who provide minimal supervision.', false),
  ('parenting', 26, 'During well-child visits on the same afternoon, the nurse assesses four children. Which finding requires the nurse''s IMMEDIATE follow-up?', '[{"id": "a", "text": "A 6-year-old whose parents are strict and expect obedience but meet all needs"}, {"id": "b", "text": "A 5-year-old whose warm parents admit they rarely enforce bedtime rules"}, {"id": "c", "text": "A 7-year-old whose parents explain their rules and use natural consequences"}, {"id": "d", "text": "A 3-year-old with minimal supervision whose basic needs are not met"}]'::jsonb, '["d"]', 'Uninvolved/neglectful parenting that results in unmet needs is reportable and creates a mandatory reporter obligation. Strict parenting with needs met may reflect cultural variation and is not always harmful, and permissive or authoritative parenting does not require immediate action.', false),
  ('parenting', 27, 'A nurse is conducting a well-child visit for a 4-year-old and family. According to recommended nursing practice regarding parenting styles, which actions should the nurse take? Select all that apply.', '[{"id": "a", "text": "Assess the family''s parenting style during the visit"}, {"id": "b", "text": "Screen for parenting stress, mental health, and substance use"}, {"id": "c", "text": "Report any strict, authoritarian family as neglectful"}, {"id": "d", "text": "Promote authoritative parenting as the recommended model"}, {"id": "e", "text": "Consider cultural variations when evaluating parenting"}]'::jsonb, '["a", "b", "d", "e"]', 'Nurses assess parenting style at well-child visits (a), screen for parenting stress, mental health disorders, and substance use (b), promote authoritative parenting (d), and consider cultural variations (e). Some cultures are traditionally more authoritarian, which is not always neglectful or harmful, so reporting every strict family (c) is inappropriate.', true),
  ('parenting', 28, 'The father of an 8-year-old who repeatedly leaves his bicycle out in the rain asks the nurse how to respond. Which advice BEST reflects the parenting style with the best child outcomes?', '[{"id": "a", "text": "Explain reasons for rules and use natural consequences"}, {"id": "b", "text": "Take the bike away for a month and do not discuss the decision"}, {"id": "c", "text": "Buy a new bike if it rusts so the child is not disappointed"}, {"id": "d", "text": "Leave the decision about the bike entirely up to the child"}]'::jsonb, '["a"]', 'Authoritative discipline is firm but fair, explains reasons for rules, and uses natural consequences, which produces the best outcomes. Removing the bike without discussion is punitive authoritarian discipline, and replacing it avoids consequences, as in permissive parenting.', false),
  ('parenting', 29, 'A 15-year-old in a juvenile detention center tells the nurse that his parents were "never around," never set rules, and did not notice when he stopped going to school. Which risks should the nurse anticipate are MOST closely associated with this upbringing?', '[{"id": "a", "text": "Obedience with anxiety and difficulty making decisions"}, {"id": "b", "text": "Creativity and high self-esteem with poor impulse control"}, {"id": "c", "text": "Mental health disorders, delinquency, and substance abuse"}, {"id": "d", "text": "Self-reliance with strong self-regulation and social skills"}]'::jsonb, '["c"]', 'Uninvolved/neglectful parenting is associated with higher rates of mental health disorders, delinquency, and substance abuse. Creativity and high self-esteem with poor impulse control describe permissive parenting, where parents are warm rather than absent.', false),
  ('parenting', 30, 'After a teaching session on parenting styles, the parents of a 9-year-old make several statements. Which statements indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"Warmth plus structure is the best combination for our son.\""}, {"id": "b", "text": "\"If we punish without explaining, he''ll learn to obey and be fine.\""}, {"id": "c", "text": "\"We should explain the reasons behind our rules to him.\""}, {"id": "d", "text": "\"We need clear expectations and rules that are consistent.\""}, {"id": "e", "text": "\"Letting him decide most things himself will build self-control.\""}]'::jsonb, '["a", "c", "d"]', 'Warmth plus structure is the best combination (a), and authoritative parents explain reasons for rules (c) and set clear expectations with consistent rules (d). Punishing without explanation (b) is authoritarian and linked to anxiety and low self-esteem; letting the child control most decisions (e) is permissive and linked to poor self-regulation.', true),
  ('parenting', 31, 'A mother tells the nurse, "I always explain my rules to my 7-year-old and we talk about everything, but when he breaks a rule I just can''t bring myself to follow through." She is warm and affectionate during the visit. Which interpretation is MOST accurate?', '[{"id": "a", "text": "Authoritative, because she explains her rules and communicates openly"}, {"id": "b", "text": "Permissive, because she rarely enforces consequences for her rules"}, {"id": "c", "text": "Authoritarian, because she sets rules and expects her son to follow them"}, {"id": "d", "text": "Uninvolved, because her rules have no expectations behind them"}]'::jsonb, '["b"]', 'Although she communicates openly, a parent who rarely enforces consequences and avoids confrontation is low in demandingness — the permissive style. Authoritative parents pair explanations with consistent rules that are actually enforced.', false),
  ('parenting', 32, 'A nurse in a pediatric clinic is caring for four children of similar age. Based on the parenting style described, which child is MOST likely to show self-reliance, self-regulation, and good decision-making?', '[{"id": "a", "text": "The child whose parents dictate rules and expect obedience"}, {"id": "b", "text": "The child whose parents are lenient and avoid confrontation"}, {"id": "c", "text": "The child whose parents provide minimal supervision"}, {"id": "d", "text": "The child whose parents are warm, firm, and explain rules"}]'::jsonb, '["d"]', 'Authoritative parenting (warm + firm, explaining reasons) produces high self-esteem, self-reliance, self-regulation, and good decision-making skills. Children of authoritarian parents are obedient but may struggle with independent decision-making.', false),
  ('parenting', 33, 'A school nurse reviews concerns about several students and their parents. Which situations require the nurse to make a report as a mandatory reporter? Select all that apply.', '[{"id": "a", "text": "Strict immigrant parents expect obedience; the child is well cared for"}, {"id": "b", "text": "Detached parents with minimal supervision leave a child without food"}, {"id": "c", "text": "Warm, lenient parents let their 9-year-old choose her own bedtime"}, {"id": "d", "text": "Firm parents ground a teen for a week after explaining their reasons"}, {"id": "e", "text": "Indifferent parents leave a child''s injury untreated, causing harm"}]'::jsonb, '["b", "e"]', 'Uninvolved/neglectful parenting that results in harm or unmet basic needs — no food and minimal supervision (b) or an untreated injury (e) — is reportable. Strict cultural parenting with needs met (a) is not always neglectful or harmful, and lenient (c) or firm, explained discipline (d) does not create a reporting obligation.', true),
  ('parenting', 34, 'A 14-year-old tells the nurse, "At home I''m not allowed to ask questions. My dad tells us the rules and that''s it — if I ask why, I get punished." Which communication pattern is the nurse MOST likely to document?', '[{"id": "a", "text": "One-way communication in which the parent dictates"}, {"id": "b", "text": "Open, two-way communication with the child''s input"}, {"id": "c", "text": "Very open communication with the child controlling decisions"}, {"id": "d", "text": "Minimal to absent communication between parent and child"}]'::jsonb, '["a"]', 'Authoritarian communication is one-way — the parent dictates and the child is not encouraged to question. Open, two-way communication with the child''s input considered is authoritative, and minimal to absent communication is uninvolved.', false),
  ('parenting', 35, 'A nurse is caring for a 13-year-old whose parents have used strict, rigid rules and punishment without explanation since early childhood. Which outcomes should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Lower self-esteem and self-reliance"}, {"id": "b", "text": "Poor self-regulation from too few rules"}, {"id": "c", "text": "Higher rates of anxiety and depression"}, {"id": "d", "text": "Struggles with independent decision-making"}, {"id": "e", "text": "Creative, social, and high self-esteem"}]'::jsonb, '["a", "c", "d"]', 'Authoritarian parenting is associated with lower self-esteem and self-reliance (a), higher rates of anxiety and depression (c), and obedience with difficulty making independent decisions (d). Poor self-regulation from too few rules (b) and being creative, social, and high in self-esteem (e) are permissive outcomes.', true),
  ('parenting', 36, 'The parents of a 16-year-old tell the nurse their daughter chose her own school, sets the family''s weekend plans, and decides her own curfew. The parents describe themselves as "her biggest fans" and avoid saying no. Which parenting style is MOST evident?', '[{"id": "a", "text": "Authoritative"}, {"id": "b", "text": "Permissive / indulgent"}, {"id": "c", "text": "Authoritarian"}, {"id": "d", "text": "Uninvolved / neglectful"}]'::jsonb, '["b"]', 'In permissive/indulgent parenting, communication is very open and the child has much control over decisions; parents are warm and avoid confrontation. Authoritative parents consider the child''s input but keep clear expectations and consistent rules.', false),
  ('parenting', 37, 'The nurse is reviewing observations of parents during a pediatric clinic session. Which parent behaviors reflect low demandingness? Select all that apply.', '[{"id": "a", "text": "Sets a homework rule and follows through each night"}, {"id": "b", "text": "Lets the child have much control over decisions"}, {"id": "c", "text": "Expects obedience to rigid rules without discussion"}, {"id": "d", "text": "Explains the reason for a bedtime and enforces it"}, {"id": "e", "text": "Has no expectations and rarely knows where the child is"}]'::jsonb, '["b", "e"]', 'Demandingness is how much the parent expects and enforces compliance. Giving the child control over every decision (b, permissive) and having no expectations with minimal supervision (e, uninvolved) are low demandingness. Following through on rules (a), rigid rules (c), and enforced, explained rules (d) are high demandingness.', true),
  ('parenting', 38, 'A father of a 6-year-old says, "I was raised with tough discipline and no explanations, and I turned out fine. Isn''t strict the best way?" Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Yes. Strict parenting gives children the best outcomes of any style.\""}, {"id": "b", "text": "\"Strict without explanation can lead to obedience but also anxiety.\""}, {"id": "c", "text": "\"Strict parenting is neglectful and must be stopped right away.\""}, {"id": "d", "text": "\"Strictness doesn''t matter, as long as children have their needs met.\""}]'::jsonb, '["b"]', 'Authoritarian parenting tends to produce children who are obedient but anxious with low self-esteem; authoritative parenting (warm + firm) gives the best outcomes. Strict parenting is not automatically neglectful, so calling it neglect is inaccurate.', false),
  ('parenting', 39, 'A nurse observes four parent–child interactions in the waiting room. Which observation BEST demonstrates high responsiveness (warmth)?', '[{"id": "a", "text": "A father tells his crying son to stop because the rule is no crying"}, {"id": "b", "text": "A mother scrolls on her phone while her daughter cries beside her"}, {"id": "c", "text": "A father reminds his son of the rule about waiting quietly in line"}, {"id": "d", "text": "A mother responds to her child''s emotional needs with comfort"}]'::jsonb, '["d"]', 'Responsiveness is how much the parent responds to the child''s emotional needs — nurturing and accepting versus cold or rejecting. Reminding a child of a rule reflects demandingness (control), not warmth, and ignoring a crying child shows very low warmth.', false),
  ('parenting', 40, 'A nurse is assessing a 7-year-old''s mother who is friend-like and nurturing with her son. Which additional findings are consistent with the permissive/indulgent style? Select all that apply.', '[{"id": "a", "text": "She sets few expectations and few consistent rules"}, {"id": "b", "text": "She rarely enforces consequences when he misbehaves"}, {"id": "c", "text": "She gives punishments without explaining her reasons"}, {"id": "d", "text": "She avoids confrontation with him whenever possible"}, {"id": "e", "text": "She lets him have much control over family decisions"}]'::jsonb, '["a", "b", "d", "e"]', 'Permissive parents have low demands with few expectations or consistent rules (a), rarely enforce consequences (b), avoid confrontation (d), and give the child much control over decisions (e). Punishment without explanation (c) is authoritarian discipline.', true),
  ('parenting', 41, 'A family with a 15-year-old describes daily screaming matches; the mother is being treated for depression, and the father works two jobs. The teen''s grades are falling, but the parents say they want help. The nurse has completed screening. Which action is the BEST next step?', '[{"id": "a", "text": "Make a mandatory report for uninvolved parenting"}, {"id": "b", "text": "Tell the parents to be stricter so the teen obeys"}, {"id": "c", "text": "Refer the family to family therapy as appropriate"}, {"id": "d", "text": "Advise the teen to spend more time away from home"}]'::jsonb, '["c"]', 'After screening for parenting stress and mental health disorders, nurses refer to parenting classes or family therapy as appropriate. There is no indication of unmet basic needs that would require a report, and becoming stricter without warmth is authoritarian.', false),
  ('parenting', 42, 'A nurse is comparing outcomes among children raised with different parenting styles. Which child is MOST likely to have the lowest self-esteem and emotional regulation?', '[{"id": "a", "text": "A child of strict parents who give no explanations"}, {"id": "b", "text": "A child of warm parents who rarely set rules"}, {"id": "c", "text": "A child of warm parents who are firm and fair"}, {"id": "d", "text": "A child of detached parents with no structure"}]'::jsonb, '["d"]', 'Uninvolved/neglectful parenting (cold + no structure) produces the lowest self-esteem and emotional regulation of all styles. Authoritarian parenting also lowers self-esteem, but uninvolved parenting has the worst outcomes.', false),
  ('parenting', 43, 'A nurse interviews a 10-year-old''s parents. Which statements by the parents suggest that the uninvolved/neglectful style is present? Select all that apply.', '[{"id": "a", "text": "\"We don''t really talk; he does his own thing.\""}, {"id": "b", "text": "\"We explain our rules, and he knows we mean it.\""}, {"id": "c", "text": "\"There''s no food at home most days this month.\""}, {"id": "d", "text": "\"We''re strict, and he has to obey without arguing.\""}, {"id": "e", "text": "\"We let him decide nearly everything, but we''re close.\""}]'::jsonb, '["a", "c"]', 'Uninvolved parenting involves minimal to absent communication (a), and basic needs may not even be met (c). Explained, enforced rules (b) are authoritative, strict obedience (d) is authoritarian, and a warm parent who lets the child decide (e) is permissive.', true),
  ('parenting', 44, 'A nurse is talking with the father of a 5-year-old whose parents expect obedience to many strict rules. Which observation by the nurse BEST distinguishes this authoritarian style from the authoritative style?', '[{"id": "a", "text": "The father expects the child to follow household rules"}, {"id": "b", "text": "The father enforces rules consistently every day"}, {"id": "c", "text": "The father gives no explanations and is less nurturing"}, {"id": "d", "text": "The father sets clear expectations for the child"}]'::jsonb, '["c"]', 'Both styles are high in demandingness, with expectations and enforced rules; the difference is that authoritarian parents are low in warmth (less nurturing) and give no explanations. Clear expectations and consistent rules are features of authoritative parenting too.', false),
  ('parenting', 45, 'A 12-year-old raised by authoritarian parents has just started middle school. Which findings would the nurse expect in this child? Select all that apply.', '[{"id": "a", "text": "Less social competence with peers"}, {"id": "b", "text": "Very high self-esteem and self-reliance"}, {"id": "c", "text": "Behavioral problems at school"}, {"id": "d", "text": "Obedience to adult rules"}, {"id": "e", "text": "Impulsivity from having very few rules"}]'::jsonb, '["a", "c", "d"]', 'Children of authoritarian parents show less social competence (a), higher rates of behavioral problems (c), and obedience (d). High self-esteem and self-reliance (b) follow authoritative parenting, and impulsivity from few rules (e) follows permissive parenting.', true),
  ('parenting', 46, 'A nurse observes a parent and an 8-year-old during an injection. Which parent statement BEST reflects open, two-way communication characteristic of authoritative parenting?', '[{"id": "a", "text": "\"Do what the nurse says now, or you''ll lose your tablet tonight.\""}, {"id": "b", "text": "\"You decide if you want the shot today; I''ll go along with it.\""}, {"id": "c", "text": "\"I''ll be in the hall on my phone — call if you need anything.\""}, {"id": "d", "text": "\"The shot keeps you healthy. What would help you feel calmer?\""}]'::jsonb, '["d"]', 'Authoritative communication is open and two-way, explaining reasons and considering the child''s input. A threat without explanation is authoritarian, leaving the decision to the child is permissive, and leaving the room shows minimal communication (uninvolved).', false),
  ('parenting', 47, 'A nursing student summarizes Baumrind''s framework after a pediatric clinical day. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"Uninvolved parenting is the style with the most harmful outcomes.\""}, {"id": "b", "text": "\"Warmth and structure together produce the best child outcomes.\""}, {"id": "c", "text": "\"Permissive parenting is high in warmth but low in demandingness.\""}, {"id": "d", "text": "\"Authoritarian parenting is the evidence-based model to promote.\""}]'::jsonb, '["d"]', 'Authoritative — not authoritarian — parenting is the recommended, evidence-based model to promote to parents. The other statements are accurate: uninvolved is most harmful, warmth plus structure is the best combination, and permissive is high responsiveness with low demandingness.', false),
  ('parenting', 48, 'A nurse is planning care for families seen in a pediatric clinic. Which findings should prompt the nurse to screen a parent further because they affect parenting style? Select all that apply.', '[{"id": "a", "text": "A mother reports high parenting stress"}, {"id": "b", "text": "A father with substance use that may affect parenting style"}, {"id": "c", "text": "A mother explains her rules and enforces them consistently"}, {"id": "d", "text": "A parent with known mental health disorders"}, {"id": "e", "text": "A mother is warm and responsive to her child''s feelings"}]'::jsonb, '["a", "b", "d"]', 'Parenting stress (a), substance use (b), and mental health disorders (d) all affect parenting style and warrant screening. Explaining and enforcing rules (c) and being warm and responsive (e) are features of authoritative parenting and are not risk findings.', true),
  ('parenting', 49, 'A nurse is reviewing the quick comparison of parenting styles with a group of new parents. Which parent''s description of their household matches the style associated with "Low self-regulation, impulsive" children?', '[{"id": "a", "text": "\"We''re strict and punitive, and we don''t explain our decisions.\""}, {"id": "b", "text": "\"We''re lenient and avoid confrontation with our kids.\""}, {"id": "c", "text": "\"We''re firm and fair, and we always explain our rules.\""}, {"id": "d", "text": "\"We''re detached and don''t get involved in their lives.\""}]'::jsonb, '["b"]', 'In the comparison table, permissive parenting (high warmth, low control, lenient, avoids confrontation) is associated with low self-regulation and impulsive children. Detached parenting is uninvolved and has the worst outcomes — insecure and at-risk.', false),
  ('parenting', 50, 'A teen tells the school nurse that his parents are "nice but never make me do anything," and he has started vaping and skipping classes with friends. Which parenting style and outcome does the nurse MOST likely identify?', '[{"id": "a", "text": "Authoritarian, with defiance when away from parental control"}, {"id": "b", "text": "Authoritative, with self-reliance and good decision-making"}, {"id": "c", "text": "Uninvolved, with the lowest self-esteem of all the styles"}, {"id": "d", "text": "Permissive, with a higher risk of substance abuse and risky behaviors"}]'::jsonb, '["d"]', 'Warm parents who set few demands are permissive, and permissive parenting carries a higher risk of substance abuse and risky behaviors. Uninvolved parents are cold and detached, not "nice."', false),
  ('meds', 1, 'A client who has taken phenelzine (Nardil) for treatment-resistant depression calls the clinic 2 hours after a wine-and-cheese party. The client reports a severe headache, neck stiffness, palpitations, and nausea. Which complication is the nurse MOST concerned about?', '[{"id": "a", "text": "Discontinuation syndrome from a missed dose"}, {"id": "b", "text": "Serotonin syndrome from a drug interaction"}, {"id": "c", "text": "Hypertensive crisis from tyramine intake"}, {"id": "d", "text": "Anticholinergic toxicity from the MAOI"}]'::jsonb, '["c"]', 'Wine and aged cheese are tyramine-rich foods, and tyramine plus an MAOI causes hypertensive crisis with severe headache, neck stiffness, palpitations, and N/V that can cause stroke. Serotonin syndrome is the MAOI risk with SSRIs/SNRIs, not with tyramine-rich foods.', false),
  ('meds', 2, 'A client started on tranylcypromine (Parnate) for treatment-resistant depression is choosing dinner items from the hospital menu. Which selections require the nurse to intervene before the tray is ordered? Select all that apply.', '[{"id": "a", "text": "Fresh roasted turkey breast"}, {"id": "b", "text": "Fava beans with garlic"}, {"id": "c", "text": "Tap beer with dinner"}, {"id": "d", "text": "Plain steamed white rice"}, {"id": "e", "text": "Crackers with aged cheeses"}]'::jsonb, '["b", "c", "e"]', 'Aged cheeses, fava beans, and wine/beer (especially tap) are on the MAOI tyramine avoid list, and MAOI plus tyramine-rich foods causes a lethal hypertensive crisis. Fresh roasted turkey and plain rice are not among the tyramine-rich foods (aged cheeses, cured meats, fermented foods, wine/beer, soy products, fava beans, bananas, avocados) the client must avoid.', true),
  ('meds', 3, 'A client with bipolar I disorder has taken lithium for 6 months. This morning the client reports nausea, diarrhea, and a coarse tremor, and the serum lithium level is 1.7 mEq/L. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Hold the next lithium dose and notify the provider"}, {"id": "b", "text": "Give the scheduled dose with food to lessen GI distress"}, {"id": "c", "text": "Start a low-sodium diet to limit fluid retention"}, {"id": "d", "text": "Give the dose because the level is therapeutic"}]'::jsonb, '["a"]', 'A lithium level above 1.5 mEq/L is toxic, and coarse tremor with GI distress are early toxicity signs (1.5–2.0); diarrhea and vomiting are also reasons to hold lithium. A low-sodium diet is to be avoided because it raises the risk of toxicity.', false),
  ('meds', 4, 'The nurse reviews morning drug levels for clients on a mood-disorder unit. Which client''s result requires IMMEDIATE follow-up with the health care provider?', '[{"id": "a", "text": "Lithium 1.1 mEq/L in a client taking it for mania prevention"}, {"id": "b", "text": "Carbamazepine 9 mcg/mL in a client with rapid cycling"}, {"id": "c", "text": "Valproic acid 118 mcg/mL in a client with bipolar disorder"}, {"id": "d", "text": "Lithium 0.7 mEq/L in a client with schizoaffective disorder"}]'::jsonb, '["c"]', 'The valproate drug level range is 50–100 mcg/mL, so 118 mcg/mL is above range. Lithium 1.1 mEq/L is close to the top but still within the 0.6–1.2 therapeutic range, and carbamazepine 9 mcg/mL is within 4–12 mcg/mL.', false),
  ('meds', 5, 'During a home visit, a client who has been stable on lithium for a year describes several recent changes. Which changes increase this client''s risk for lithium toxicity? Select all that apply.', '[{"id": "a", "text": "Fever with decreased fluid intake"}, {"id": "b", "text": "Taking NSAIDs (ibuprofen) for chronic pain"}, {"id": "c", "text": "Thiazides added for hypertension"}, {"id": "d", "text": "A low-sodium diet to lose weight"}, {"id": "e", "text": "Drinking extra fluids to stay hydrated"}]'::jsonb, '["a", "b", "c", "d"]', 'NSAIDs and thiazides raise lithium levels and cause toxicity; a low-sodium diet is also to be avoided. Fever and decreased fluid intake are reasons to hold lithium because toxicity risk increases. Drinking extra fluids is correct behavior because hydration is critical with lithium.', true),
  ('meds', 6, 'The nurse is teaching a client who is newly prescribed lithium for bipolar II disorder. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll keep drinking plenty of fluids every day.\""}, {"id": "b", "text": "\"I''ll get blood tests for my kidneys and thyroid.\""}, {"id": "c", "text": "\"I''ll call if I start vomiting or have diarrhea.\""}, {"id": "d", "text": "\"I''ll switch to a low-sodium diet for my heart.\""}]'::jsonb, '["d"]', 'A low-sodium diet is to be avoided with lithium because it increases the risk of toxicity. Hydration is critical, renal function and thyroid are monitored, and vomiting or diarrhea is a reason to hold lithium, so those statements are correct.', false),
  ('meds', 7, 'A client receiving lithium is brought to the emergency department by family. The client is confused, has ataxia and slurred speech, and reports tinnitus. No seizures have occurred. Which serum lithium range is MOST consistent with these findings?', '[{"id": "a", "text": "1.5–2.0 mEq/L"}, {"id": "b", "text": "2.0–2.5 mEq/L"}, {"id": "c", "text": "0.6–1.2 mEq/L"}, {"id": "d", "text": "Greater than 2.5 mEq/L"}]'::jsonb, '["b"]', 'Confusion, ataxia, slurred speech, and tinnitus are moderate toxicity signs (2.0–2.5). Early toxicity (1.5–2.0) shows coarse tremor and GI distress, and seizures, coma, and dysrhythmias mark severe toxicity above 2.5.', false),
  ('meds', 8, 'A client taking valproic acid (Depakote) for bipolar disorder and migraine prevention has new bruising on both arms and petechiae on the lower legs. Which laboratory result is the PRIORITY for the nurse to review?', '[{"id": "a", "text": "CBC for thrombocytopenia"}, {"id": "b", "text": "Serum sodium for hyponatremia"}, {"id": "c", "text": "Thyroid function studies"}, {"id": "d", "text": "Fasting glucose and lipids"}]'::jsonb, '["a"]', 'Valproate monitoring includes a CBC for thrombocytopenia, which fits new bruising and petechiae. Serum sodium for hyponatremia relates to carbamazepine-induced SIADH, and thyroid studies are part of lithium monitoring.', false),
  ('meds', 9, 'A client has taken carbamazepine (Tegretol) for bipolar disorder and trigeminal neuralgia for 2 months. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Relief of trigeminal neuralgia pain"}, {"id": "b", "text": "Low serum sodium with confusion"}, {"id": "c", "text": "Drug level of 8 mcg/mL"}, {"id": "d", "text": "Drug level of 14 mcg/mL"}, {"id": "e", "text": "New severe rash on the trunk"}]'::jsonb, '["b", "d", "e"]', 'A level of 14 mcg/mL is above the 4–12 mcg/mL range. A severe rash may be Stevens-Johnson syndrome, and low sodium reflects SIADH → hyponatremia, both serious carbamazepine effects. A level of 8 mcg/mL is within range, and relief of trigeminal neuralgia is a therapeutic effect.', true),
  ('meds', 10, 'A client who began carbamazepine (Tegretol) for rapid-cycling bipolar disorder 3 weeks ago is newly confused and lethargic, and the serum sodium is reported as low. Which adverse effect is the MOST likely cause?', '[{"id": "a", "text": "Agranulocytosis detected on the CBC"}, {"id": "b", "text": "Stevens-Johnson syndrome with severe rash"}, {"id": "c", "text": "Hepatotoxicity detected on LFTs"}, {"id": "d", "text": "SIADH leading to hyponatremia"}]'::jsonb, '["d"]', 'Carbamazepine can cause SIADH → hyponatremia, which fits low sodium with confusion. Agranulocytosis and Stevens-Johnson syndrome are real carbamazepine risks but would not explain a low serum sodium.', false),
  ('meds', 11, 'A client admitted with acute mania has a new prescription for lamotrigine (Lamictal) with an accelerated schedule so the dose reaches its target within days. Which concern should the nurse report to the health care provider?', '[{"id": "a", "text": "Weekly serum drug levels will be needed"}, {"id": "b", "text": "Stevens-Johnson risk if titrated too fast"}, {"id": "c", "text": "Significant weight gain is expected early on"}, {"id": "d", "text": "Agranulocytosis requires a baseline CBC first"}]'::jsonb, '["b"]', 'Lamotrigine requires slow titration because of Stevens-Johnson syndrome risk if titrated too fast, and it is not for acute mania. It needs no routine serum monitoring and causes minimal weight gain; agranulocytosis monitoring belongs to carbamazepine and clozapine.', false),
  ('meds', 12, 'A 19-year-old college student started sertraline (Zoloft) for depression 10 days ago. At a follow-up visit the student reports mild nausea and decreased libido and says, "It isn''t working yet." Which assessment is the PRIORITY?', '[{"id": "a", "text": "Severity of the GI upset and nausea"}, {"id": "b", "text": "Effect on sexual function"}, {"id": "c", "text": "Suicidal thoughts and behaviors"}, {"id": "d", "text": "Expectations about time to effect"}]'::jsonb, '["c"]', 'The black box warning describes increased suicidal thoughts and behaviors in young adults up to age 24 during initial treatment, especially the first 1–4 weeks. GI upset and sexual dysfunction are common sertraline effects and full effect takes 2–6 weeks, but these are not the safety priority.', false),
  ('meds', 13, 'The nurse is planning assessments on an outpatient unit where several clients receive antidepressants. Which client situations call for the closest monitoring for suicidal thoughts and behaviors under the black box warning? Select all that apply.', '[{"id": "a", "text": "A 16-year-old client in week 1 of fluoxetine"}, {"id": "b", "text": "A 60-year-old client in week 1 of citalopram"}, {"id": "c", "text": "A 23-year-old client in week 3 of duloxetine"}, {"id": "d", "text": "A 35-year-old client in week 2 of venlafaxine"}, {"id": "e", "text": "A 22-year-old client stable on sertraline for 8 months"}]'::jsonb, '["a", "c"]', 'The black box warning applies to children, adolescents, and young adults up to age 24 during initial treatment, especially the first 1–4 weeks, which fits the 16-year-old in week 1 and the 23-year-old in week 3. The 35- and 60-year-olds are older than 24, and the 22-year-old is past initial treatment after 8 months.', true),
  ('meds', 14, 'A client stopped taking paroxetine (Paxil) abruptly 3 days ago because of cost. The client now reports flu-like symptoms, insomnia, nausea, poor balance, and odd sensory disturbances, and appears keyed up and hyperaroused. Which condition is MOST likely?', '[{"id": "a", "text": "Discontinuation syndrome"}, {"id": "b", "text": "Serotonin syndrome"}, {"id": "c", "text": "Neuroleptic malignant syndrome"}, {"id": "d", "text": "Hypertensive crisis"}]'::jsonb, '["a"]', 'Abrupt stopping of an SSRI, especially paroxetine, causes discontinuation syndrome (FINISH: Flu-like symptoms, Insomnia, Nausea, Imbalance, Sensory disturbances, Hyperarousal). Serotonin syndrome results from combining serotonergic drugs such as an SSRI with an MAOI, not from stopping one.', false),
  ('meds', 15, 'The nurse completes discharge teaching for a client newly prescribed escitalopram (Lexapro) for depression. Which client statements indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"I should avoid alcohol and St. John''s Wort.\""}, {"id": "b", "text": "\"I''ll taper with my provider, not stop abruptly.\""}, {"id": "c", "text": "\"It may take 2 to 6 weeks to feel the full effect.\""}, {"id": "d", "text": "\"If it lowers my sex drive, I''ll just stop taking it.\""}, {"id": "e", "text": "\"Once I feel better, I can stop it on my own.\""}]'::jsonb, '["a", "b", "c"]', 'SSRIs take 2–6 weeks for full therapeutic effect, alcohol and St. John''s Wort are to be avoided, and the drug must be tapered rather than stopped abruptly. Stopping because of sexual dysfunction is wrong—the client should discuss it with the provider before stopping—and stopping alone once feeling better risks discontinuation syndrome.', true),
  ('meds', 16, 'A 79-year-old client with hepatic impairment is admitted with depression. The admission orders include citalopram (Celexa) 40 mg orally once daily. Which action by the nurse is BEST?', '[{"id": "a", "text": "Give the dose and monitor for GI upset"}, {"id": "b", "text": "Clarify the dose because of QT prolongation"}, {"id": "c", "text": "Give the dose and check blood pressure"}, {"id": "d", "text": "Hold the dose until the serum sodium is reported"}]'::jsonb, '["b"]', 'Citalopram causes QT prolongation, so the maximum dose is 20 mg in elderly clients or those with hepatic impairment; 40 mg exceeds this and must be clarified. Giving the dose with GI or blood pressure monitoring ignores the dose limit.', false),
  ('meds', 17, 'A client with treatment-resistant depression stopped fluoxetine (Prozac) 3 weeks ago. The provider now prescribes phenelzine (Nardil) to start today. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Give the dose; the 14-day washout has been met"}, {"id": "b", "text": "Give the dose with a tyramine-free meal and observe"}, {"id": "c", "text": "Give the dose and monitor for discontinuation"}, {"id": "d", "text": "Hold the dose; washout after fluoxetine is 5 weeks"}]'::jsonb, '["d"]', 'The MAOI washout is 14 days for most serotonergic drugs but 5 weeks for fluoxetine, so 3 weeks is not enough and starting phenelzine risks serotonin syndrome. The 14-day rule is the tempting trap because it applies to other SSRIs.', false),
  ('meds', 18, 'A client with generalized anxiety disorder has been titrated to a high dose of venlafaxine (Effexor) over the past month. Which monitoring is MOST important for the nurse to trend at each visit?', '[{"id": "a", "text": "Monitoring for hypertension"}, {"id": "b", "text": "Monitoring for hepatotoxicity"}, {"id": "c", "text": "Monitoring for hyponatremia"}, {"id": "d", "text": "Monitoring for weight gain"}]'::jsonb, '["a"]', 'Venlafaxine raises BP at high doses, so blood pressure is trended. Hepatotoxicity is the concern with duloxetine (avoid in liver disease), and hyponatremia is linked to carbamazepine-induced SIADH.', false),
  ('meds', 19, 'A client is admitted to the intensive care unit after intentionally ingesting a large supply of amitriptyline (Elavil). The cardiac monitor shows new dysrhythmias. Which medication is the nurse MOST likely to prepare?', '[{"id": "a", "text": "Dantrolene IV infusion"}, {"id": "b", "text": "Benztropine (Cogentin) IM"}, {"id": "c", "text": "Sodium bicarbonate"}, {"id": "d", "text": "Propranolol (beta-blocker)"}]'::jsonb, '["c"]', 'TCAs are cardiotoxic in overdose, and sodium bicarbonate is used to treat the cardiac effects. Dantrolene treats NMS, benztropine treats dystonia or parkinsonism, and propranolol treats akathisia.', false),
  ('meds', 20, 'An older adult client started amitriptyline (Elavil) for neuropathic pain 2 weeks ago. Which findings does the nurse recognize as expected side effects of this drug? Select all that apply.', '[{"id": "a", "text": "Diarrhea and loose stools"}, {"id": "b", "text": "Urinary retention"}, {"id": "c", "text": "Blurry vision"}, {"id": "d", "text": "Breast enlargement (gynecomastia)"}, {"id": "e", "text": "Orthostatic hypotension"}]'::jsonb, '["b", "c", "e"]', 'Amitriptyline''s anticholinergic effects include urinary retention and blurry vision, and orthostatic hypotension is also a listed side effect. Anticholinergic effects cause constipation, not diarrhea, and gynecomastia comes from elevated prolactin with risperidone.', true),
  ('meds', 21, 'A client with major depression who disclosed suicidal ideation last week is being discharged with a prescription for imipramine (Tofranil). Which discharge consideration is the PRIORITY?', '[{"id": "a", "text": "Take doses in the morning to avoid insomnia"}, {"id": "b", "text": "Limit the prescription quantity dispensed"}, {"id": "c", "text": "Avoid tyramine-rich foods such as aged cheeses"}, {"id": "d", "text": "Arrange weekly CBC monitoring for 6 months"}]'::jsonb, '["b"]', 'TCAs are highly dangerous in overdose (cardiotoxicity, seizures, death), so in suicidal clients the prescription quantity is limited. Tyramine restriction belongs to MAOIs and weekly CBC monitoring to clozapine.', false),
  ('meds', 22, 'An older adult client with depression has lost weight over 2 months, has a poor appetite, and sleeps only 3 hours a night. Which antidepressant would the nurse expect to be the BEST fit for this client''s symptoms?', '[{"id": "a", "text": "Bupropion (Wellbutrin)"}, {"id": "b", "text": "Fluoxetine (Prozac)"}, {"id": "c", "text": "Venlafaxine (Effexor)"}, {"id": "d", "text": "Mirtazapine (Remeron)"}]'::jsonb, '["d"]', 'Mirtazapine is sedating, causes weight gain that is useful in underweight patients, and is good for sleep. Bupropion''s listed advantages are no sexual dysfunction and smoking cessation, not sleep or weight gain.', false),
  ('meds', 23, 'A 45-year-old client who takes trazodone at bedtime for insomnia calls the nurse line at 6 a.m. reporting a painful erection that has lasted since about 2 a.m. Which instruction should the nurse give FIRST?', '[{"id": "a", "text": "Go to the emergency department now"}, {"id": "b", "text": "Skip tonight''s dose and call the provider"}, {"id": "c", "text": "Apply ice and call back if it persists"}, {"id": "d", "text": "Take the next dose earlier in the evening"}]'::jsonb, '["a"]', 'Trazodone carries a risk of priapism (painful prolonged erection), which is a medical emergency requiring immediate care. Skipping the next dose or waiting delays emergency treatment.', false),
  ('meds', 24, 'The nurse reviews the histories of clients with new prescriptions for bupropion (Wellbutrin). Which client histories should the nurse report to the health care provider before therapy begins? Select all that apply.', '[{"id": "a", "text": "Bulimia nervosa with purging"}, {"id": "b", "text": "History of anorexia nervosa"}, {"id": "c", "text": "Current smoker who wants to quit"}, {"id": "d", "text": "Known seizure disorders"}, {"id": "e", "text": "Sexual dysfunction while on an SSRI"}]'::jsonb, '["a", "b", "d"]', 'Bupropion lowers the seizure threshold and is CONTRAINDICATED in seizure disorders, bulimia, and anorexia nervosa. Smoking cessation is a use of bupropion (Zyban), and it causes no sexual dysfunction, so those histories are reasons it may be chosen.', true),
  ('meds', 25, 'Four hours after a first IM dose of haloperidol (Haldol) for acute psychosis, a client''s neck twists sharply to one side and the eyes roll upward and stay fixed. Which medication should the nurse prepare to give IMMEDIATELY?', '[{"id": "a", "text": "Propranolol (beta-blocker) PO"}, {"id": "b", "text": "Benztropine (Cogentin) IM"}, {"id": "c", "text": "Valbenazine (Ingrezza)"}, {"id": "d", "text": "Dantrolene with cooling measures"}]'::jsonb, '["b"]', 'Sudden involuntary contractions of the neck and eyes (oculogyric crisis) are acute dystonia, treated with benztropine IM or diphenhydramine IM. Propranolol treats akathisia and valbenazine treats tardive dyskinesia.', false),
  ('meds', 26, 'A client started on fluphenazine (Prolixin) 1 week ago paces the hallway, repeatedly sits and stands, and says, "I feel like I have to keep moving. I can''t sit still." Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Give an extra dose of fluphenazine for agitation"}, {"id": "b", "text": "Document it as anxiety related to the psychosis"}, {"id": "c", "text": "Report akathisia; propranolol may be ordered"}, {"id": "d", "text": "Give benztropine IM for acute dystonia"}]'::jsonb, '["c"]', 'Restlessness with an inner urge to move and inability to sit still is akathisia, which is often mistaken for anxiety and is treated with beta-blockers (propranolol), benzodiazepines, or a lower dose. Documenting it as anxiety is the classic error.', false),
  ('meds', 27, 'A client has received haloperidol decanoate injections for 8 years. During an abnormal movement screening, which findings suggest an adverse effect that may be IRREVERSIBLE? Select all that apply.', '[{"id": "a", "text": "Shuffling gait and masked face"}, {"id": "b", "text": "Eyes fixed in an upward gaze"}, {"id": "c", "text": "Repetitive lip smacking"}, {"id": "d", "text": "Inner urge to keep moving"}, {"id": "e", "text": "Tongue protrusion"}]'::jsonb, '["c", "e"]', 'Late-onset repetitive lip smacking and tongue protrusion are tardive dyskinesia, which is IRREVERSIBLE. Shuffling gait and masked face are parkinsonism, an upward-fixed gaze is dystonia (oculogyric crisis), and an inner urge to move is akathisia—all treatable EPS.', true),
  ('meds', 28, 'A client on long-term haloperidol has developed grimacing and choreiform limb movements, and the provider reduces the dose. Which additional medication does the nurse anticipate as the BEST treatment?', '[{"id": "a", "text": "Benztropine (Cogentin) IM"}, {"id": "b", "text": "Diphenhydramine IM"}, {"id": "c", "text": "Amantadine by mouth"}, {"id": "d", "text": "Valbenazine (Ingrezza)"}]'::jsonb, '["d"]', 'Grimacing and choreiform limb movements after long-term use are tardive dyskinesia, managed by stopping or reducing the drug and giving valbenazine or deutetrabenazine. Benztropine, diphenhydramine, and amantadine treat dystonia or parkinsonism.', false),
  ('meds', 29, 'Three weeks after starting haloperidol, a client walks with a shuffling gait and has a masked face, slowed movements, and a tremor. Which order should the nurse anticipate as MOST appropriate?', '[{"id": "a", "text": "Amantadine by mouth"}, {"id": "b", "text": "Valbenazine (Ingrezza)"}, {"id": "c", "text": "Dantrolene IV"}, {"id": "d", "text": "Sodium bicarbonate IV"}]'::jsonb, '["a"]', 'Bradykinesia, tremor, masked face, and shuffling gait are drug-induced parkinsonism, treated with benztropine, amantadine, or a lower dose. Valbenazine is for tardive dyskinesia and dantrolene is for NMS.', false),
  ('meds', 30, 'Five days after a haloperidol dose increase, a client has a high fever, is confused, has fluctuating blood pressure and pulse, lead-pipe rigidity, and an elevated CK. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Give a PRN haloperidol dose for agitation"}, {"id": "b", "text": "Stop the antipsychotic immediately"}, {"id": "c", "text": "Give benztropine IM for the rigidity"}, {"id": "d", "text": "Give acetaminophen and recheck in an hour"}]'::jsonb, '["b"]', 'Fever, encephalopathy, vital sign instability, elevated CK, and lead-pipe rigidity days after a dose increase indicate NMS, which is life-threatening; the drug is stopped immediately, then dantrolene, bromocriptine, cooling, and supportive care follow. More haloperidol would worsen it.', false),
  ('meds', 31, 'A client who began quetiapine (Seroquel) 10 days ago is found to have a high fever. The nurse suspects a life-threatening reaction to the antipsychotic. Which additional findings support this suspicion? Select all that apply.', '[{"id": "a", "text": "Tongue protrusion"}, {"id": "b", "text": "Vital sign instability"}, {"id": "c", "text": "Confusion (encephalopathy)"}, {"id": "d", "text": "Elevated CK level"}, {"id": "e", "text": "Lead-pipe rigidity"}]'::jsonb, '["b", "c", "d", "e"]', 'NMS can occur with any antipsychotic and follows FEVER: Fever, Encephalopathy, Vital sign instability, Elevated CK/enzymes, and lead-pipe Rigidity. Tongue protrusion is a sign of tardive dyskinesia, not NMS.', true),
  ('meds', 32, 'A client taking chlorpromazine (Thorazine) is going on a supervised outdoor outing this afternoon. Which teaching points are MOST important for the nurse to reinforce? Select all that apply.', '[{"id": "a", "text": "Expect high sedation"}, {"id": "b", "text": "Photosensitivity — use sun protection"}, {"id": "c", "text": "Take each dose with food to increase absorption"}, {"id": "d", "text": "Report dizziness from orthostatic hypotension"}, {"id": "e", "text": "Keep weekly CBC appointments for 6 months"}]'::jsonb, '["a", "b", "d"]', 'Chlorpromazine is low potency with high sedation, orthostatic hypotension, and photosensitivity. Taking doses with food to increase absorption applies to ziprasidone, and weekly CBC monitoring for 6 months applies to clozapine.', true),
  ('meds', 33, 'A client with treatment-resistant schizophrenia is started on clozapine (Clozaril). The medication list shows the client also takes carbamazepine for a seizure disorder. Which concern should the nurse report to the health care provider as the PRIORITY?', '[{"id": "a", "text": "Additive hypotension with falls risk"}, {"id": "b", "text": "Serotonin syndrome from the combination"}, {"id": "c", "text": "Increased agranulocytosis risk"}, {"id": "d", "text": "Elevated prolactin and gynecomastia"}]'::jsonb, '["c"]', 'Clozapine plus carbamazepine is to be avoided because both carry agranulocytosis risk, which increases with the combination. Additive hypotension is the caution for antipsychotics with antihypertensives.', false),
  ('meds', 34, 'A client starting clozapine (Clozaril) for treatment-resistant schizophrenia receives medication teaching. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll need a CBC weekly for the first 6 months.\""}, {"id": "b", "text": "\"This drug may also lower my risk of suicide.\""}, {"id": "c", "text": "\"Higher doses can raise my risk of seizures.\""}, {"id": "d", "text": "\"Mandatory CBC monitoring stops after the first month.\""}]'::jsonb, '["d"]', 'Clozapine causes agranulocytosis and requires mandatory CBC monitoring weekly for 6 months, so stopping after 1 month is wrong. Clozapine reduces suicidality and causes dose-dependent seizures, so those statements are correct.', false),
  ('meds', 35, 'A client with a family history of sudden cardiac death is admitted to a psychiatric unit, and the baseline EKG has not been done yet. Which prescribed drugs warrant the nurse''s follow-up because of QT prolongation risk? Select all that apply.', '[{"id": "a", "text": "Citalopram (Celexa)"}, {"id": "b", "text": "Buspirone (Buspar)"}, {"id": "c", "text": "Ziprasidone (Geodon)"}, {"id": "d", "text": "Thioridazine (Mellaril)"}, {"id": "e", "text": "Quetiapine (Seroquel)"}]'::jsonb, '["a", "c", "d", "e"]', 'Ziprasidone (EKG before starting), thioridazine, quetiapine, and citalopram all carry QT prolongation risk. Buspirone''s concerns are its delayed onset and interactions with grapefruit and MAOIs, not QT prolongation.', true),
  ('meds', 36, 'A 16-year-old boy taking risperidone (Risperdal) for irritability associated with autism has developed breast enlargement, and his parent is worried. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "Elevated prolactin from the drug can cause this"}, {"id": "b", "text": "Metabolic syndrome is causing fat redistribution"}, {"id": "c", "text": "This is an early sign of tardive dyskinesia"}, {"id": "d", "text": "Low sodium from SIADH is causing tissue swelling"}]'::jsonb, '["a"]', 'Risperidone elevates prolactin, causing gynecomastia, amenorrhea, and sexual dysfunction. Metabolic syndrome is the hallmark concern of olanzapine, and SIADH is a carbamazepine effect.', false),
  ('meds', 37, 'A client with schizophrenia has taken olanzapine (Zyprexa) for 3 months and says, "None of my clothes fit anymore." Which assessments are MOST important for the nurse to include at this visit? Select all that apply.', '[{"id": "a", "text": "Weight"}, {"id": "b", "text": "Weekly CBC"}, {"id": "c", "text": "Glucose levels"}, {"id": "d", "text": "Retinal exams"}, {"id": "e", "text": "Lipids"}]'::jsonb, '["a", "c", "e"]', 'Olanzapine causes metabolic syndrome (significant weight gain, hyperglycemia, hyperlipidemia), so glucose, lipids, and weight are monitored. Weekly CBC is required for clozapine, and retinal pigmentation is a thioridazine concern.', true),
  ('meds', 38, 'A client with schizophrenia was switched to aripiprazole (Abilify) 2 months ago. The spouse reports the client has started gambling online and has lost a large part of their savings. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"This means the drug is helping the negative symptoms.\""}, {"id": "b", "text": "\"I''ll report this to the provider as a drug effect.\""}, {"id": "c", "text": "\"Gambling is common in schizophrenia and will pass.\""}, {"id": "d", "text": "\"Why didn''t you limit access to the bank accounts?\""}]'::jsonb, '["b"]', 'Aripiprazole can cause impulse control issues such as gambling, so new gambling is reported as a possible drug effect. Although aripiprazole is activating and good for negative symptoms, gambling is not evidence of that benefit, and a "why" question puts the spouse on the defensive.', false),
  ('meds', 39, 'A client with schizophrenia is to begin ziprasidone (Geodon) today. While preparing the first dose, the nurse reviews the chart. Which item should the nurse verify FIRST?', '[{"id": "a", "text": "Two hours of fasting before the dose"}, {"id": "b", "text": "A serum drug level before the dose"}, {"id": "c", "text": "An EKG before starting the drug"}, {"id": "d", "text": "Weekly CBC orders before the dose"}]'::jsonb, '["c"]', 'Ziprasidone causes QT prolongation, so an EKG is obtained before starting. It is taken with food to increase absorption, so fasting is wrong, and weekly CBC monitoring belongs to clozapine.', false),
  ('meds', 40, 'The nurse receives report on four clients on an inpatient psychiatric unit. Which client should the nurse see FIRST?', '[{"id": "a", "text": "A client taking buspirone for 1 week who reports the anxiety is no better"}, {"id": "b", "text": "A client taking sertraline for 5 days who reports mild nausea and GI upset"}, {"id": "c", "text": "A client taking olanzapine who has gained weight and asks for more snacks"}, {"id": "d", "text": "A client on clonazepam who drank alcohol on a pass and is now very sedated"}]'::jsonb, '["d"]', 'Benzodiazepines plus alcohol can cause lethal respiratory depression, so the sedated client is seen first. Buspirone takes 2–4 weeks to work, GI upset is common early with sertraline, and weight gain with olanzapine needs monitoring but is not immediately life-threatening.', false),
  ('meds', 41, 'A client who has taken alprazolam (Xanax) daily for 2 years tells the nurse, "I read these pills are addictive, so I''m going to stop them tomorrow." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Stopping abruptly can cause seizures; let''s call your provider.\""}, {"id": "b", "text": "\"That''s a good plan; dependence is a serious risk with this drug.\""}, {"id": "c", "text": "\"Why would you stop a medicine that is controlling your anxiety?\""}, {"id": "d", "text": "\"You''ll be fine stopping, since you''ve only taken it two years.\""}]'::jsonb, '["a"]', 'Benzodiazepines must not be stopped abruptly because withdrawal can be life-threatening (seizures). Agreeing with the plan endorses an unsafe abrupt stop, even though dependence is a real risk.', false),
  ('meds', 42, 'A client with generalized anxiety disorder is starting buspirone (Buspar) for long-term management. Which statements by the client indicate understanding of the teaching? Select all that apply.', '[{"id": "a", "text": "\"I should avoid grapefruit with this drug.\""}, {"id": "b", "text": "\"I should expect to feel very sleepy on it.\""}, {"id": "c", "text": "\"I can take an extra dose when I have a panic attack.\""}, {"id": "d", "text": "\"It may take 2 to 4 weeks before it starts working.\""}, {"id": "e", "text": "\"I need to watch for dependence on this drug.\""}]'::jsonb, '["a", "d"]', 'Buspirone takes 2–4 weeks to work and interacts with grapefruit. It is not effective for acute anxiety or panic, it is non-addictive, and it causes no sedation, so the other statements are wrong.', true),
  ('meds', 43, 'A client in recovery from opioid use disorder is scheduled for a dental procedure and reports intense procedural anxiety. Which anxiolytic is the BEST choice for the nurse to anticipate?', '[{"id": "a", "text": "Lorazepam (Ativan)"}, {"id": "b", "text": "Buspirone (Buspar)"}, {"id": "c", "text": "Hydroxyzine (Vistaril)"}, {"id": "d", "text": "Alprazolam (Xanax)"}]'::jsonb, '["c"]', 'Hydroxyzine is non-addictive, treats procedural anxiety, and is a safe alternative to benzos in a substance abuse history. Lorazepam and alprazolam carry dependence risk and are dangerous with opioids, and buspirone is not effective for acute anxiety.', false),
  ('meds', 44, 'The nurse teaches the parent of a 9-year-old child newly prescribed methylphenidate (Concerta) for ADHD. Which parent statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll give it after breakfast so his appetite isn''t affected.\""}, {"id": "b", "text": "\"If a dose is missed, I''ll double it at bedtime.\""}, {"id": "c", "text": "\"His height and weight will be checked regularly.\""}, {"id": "d", "text": "\"I''ll report any chest pain or palpitations he has.\""}]'::jsonb, '["b"]', 'Stimulants are not double dosed if missed and are taken in the morning to avoid insomnia, so a double bedtime dose is wrong on two counts. Giving after meals, monitoring growth, and reporting chest pain or palpitations are correct.', false),
  ('meds', 45, 'A 10-year-old child with ADHD has developed worsening motor tics while taking methylphenidate, and the parents ask about alternatives. Which medication is the BEST option for the nurse to anticipate?', '[{"id": "a", "text": "Guanfacine (Intuniv)"}, {"id": "b", "text": "Amphetamine/dextroamphetamine (Adderall)"}, {"id": "c", "text": "Lisdexamfetamine (Vyvanse)"}, {"id": "d", "text": "A higher methylphenidate dose"}]'::jsonb, '["a"]', 'Guanfacine is a non-stimulant α2 agonist used as an alternative to stimulants and is useful when tics are present. Stimulants such as methylphenidate may worsen tics, so other stimulants or a higher dose are poor choices.', false),
  ('meds', 46, 'A 32-year-old client asks about starting amphetamine/dextroamphetamine (Adderall) for adult ADHD. Which items in the client''s history should the nurse report to the health care provider? Select all that apply.', '[{"id": "a", "text": "Binge eating disorder"}, {"id": "b", "text": "Hypertension"}, {"id": "c", "text": "Bedwetting as a child"}, {"id": "d", "text": "Cardiovascular disease"}, {"id": "e", "text": "Glaucoma"}]'::jsonb, '["b", "d", "e"]', 'Adderall is to be avoided in cardiovascular disease, hypertension, and glaucoma. Binge eating disorder is an approved use of lisdexamfetamine, not a contraindication, and childhood enuresis is an indication for imipramine.', true),
  ('meds', 47, 'A 12-year-old with ADHD and an anxiety disorder is prescribed atomoxetine (Strattera) because an older sibling has misused stimulants. Which parent statement indicates understanding of the teaching?', '[{"id": "a", "text": "\"It should calm her down within the first hour.\""}, {"id": "b", "text": "\"It is a Schedule II drug, so I''ll lock it up.\""}, {"id": "c", "text": "\"It may take 4 to 6 weeks to fully work.\""}, {"id": "d", "text": "\"It works best if I give it only on school days.\""}]'::jsonb, '["c"]', 'Atomoxetine is a non-stimulant with no abuse potential that takes 4–6 weeks to work and is good for ADHD with anxiety. Schedule II status applies to the stimulants, not atomoxetine.', false),
  ('meds', 48, 'A 74-year-old client who takes an antihypertensive for long-standing hypertension is started on quetiapine (Seroquel) for psychosis. Which nursing action is the PRIORITY during the first days of therapy?', '[{"id": "a", "text": "Monitor serum prolactin each week"}, {"id": "b", "text": "Schedule weekly CBC monitoring"}, {"id": "c", "text": "Screen for lip smacking"}, {"id": "d", "text": "Check for additive hypotension"}]'::jsonb, '["d"]', 'Combining an antipsychotic with an antihypertensive calls for caution because of additive hypotension, a safety risk in an older adult. Prolactin is a risperidone concern, weekly CBC is for clozapine, and lip smacking is a late-onset tardive dyskinesia sign.', false),
  ('meds', 49, 'A client taking phenelzine (Nardil) comes to the emergency department with severe flank pain. Which prescription requires the nurse''s IMMEDIATE clarification?', '[{"id": "a", "text": "Tramadol for pain"}, {"id": "b", "text": "Lorazepam for anxiety"}, {"id": "c", "text": "Hydroxyzine for nausea"}, {"id": "d", "text": "IV fluids for hydration"}]'::jsonb, '["a"]', 'An MAOI combined with meperidine or tramadol can cause lethal serotonin syndrome, so the tramadol order must be clarified. Lorazepam and hydroxyzine are not listed as MAOI interactions.', false),
  ('meds', 50, 'A 28-year-old client with bipolar disorder tells the nurse she plans to become pregnant within the year. Which of her current or proposed medications should the nurse report to the health care provider as teratogenic? Select all that apply.', '[{"id": "a", "text": "Valproic acid (Depakote)"}, {"id": "b", "text": "Hydroxyzine (Vistaril)"}, {"id": "c", "text": "Paroxetine (Paxil)"}, {"id": "d", "text": "Carbamazepine (Tegretol)"}, {"id": "e", "text": "Lithium"}]'::jsonb, '["a", "c", "d", "e"]', 'Lithium (Ebstein anomaly), valproate (neural tube defects), paroxetine, and carbamazepine are all teratogenic. Hydroxyzine is described as a non-addictive antihistamine alternative to benzos and is not flagged as teratogenic.', true),
  ('imagery', 1, 'A client scheduled for surgery in two hours is restless, reports feeling "terrified," and has a heart rate of 112/min. Pre-operative medication is not yet ordered, and the nurse decides to use guided imagery. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Ask the client to choose a peaceful, pleasant scene"}, {"id": "b", "text": "Guide the client to feel, hear, and smell the scene"}, {"id": "c", "text": "Ensure privacy, dim the lights, and close the door"}, {"id": "d", "text": "Assess the client''s anxiety and heart rate afterward"}]'::jsonb, '["c"]', 'The first step of guided imagery is to prepare the environment: ensure privacy, dim lights, reduce noise, position comfortably, and close the door. Choosing a focus image comes after the environment is prepared and relaxation breathing has begun.', false),
  ('imagery', 2, 'A nurse has closed the door, dimmed the lights, and helped a client with chronic back pain into a comfortable reclining position for guided imagery. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Guide slow, deep diaphragmatic breathing"}, {"id": "b", "text": "Describe the warm sand and the sound of waves"}, {"id": "c", "text": "Ask the client to slowly open both eyes"}, {"id": "d", "text": "Document the client''s pain level and response"}]'::jsonb, '["a"]', 'After preparing the environment, the nurse guides relaxation breathing — slow, deep diaphragmatic breathing in through the nose and out through the mouth. Engaging the senses in a scene comes after a focus image is established.', false),
  ('imagery', 3, 'A nurse on an oncology and surgical unit is selecting clients who would benefit from guided imagery. Which clients are appropriate candidates? Select all that apply.', '[{"id": "a", "text": "A patient with cancer-related nausea"}, {"id": "b", "text": "A patient with active psychosis and hallucinations"}, {"id": "c", "text": "A patient with procedural anxiety before a dressing change"}, {"id": "d", "text": "A patient with severe cognitive impairment"}, {"id": "e", "text": "A patient with pre-operative anxiety"}]'::jsonb, '["a", "c", "e"]', 'Guided imagery is indicated for cancer-related nausea (a), procedural anxiety such as dressing changes (c), and pre-operative anxiety (e). It is avoided in active psychosis because imagery may worsen hallucinations (b), and a client with severe cognitive impairment may not be able to follow instructions (d).', true),
  ('imagery', 4, 'A client with schizophrenia who is responding to voices and states that the television is sending him messages asks the nurse for help "to calm down." A colleague suggests guided imagery. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Guided imagery is safe because it is non-pharmacological.\""}, {"id": "b", "text": "\"Imagery may worsen his hallucinations or delusions right now.\""}, {"id": "c", "text": "\"We can start if he picks a beach scene instead of the television.\""}, {"id": "d", "text": "\"Imagery works best when he engages all of his senses in it.\""}]'::jsonb, '["b"]', 'Guided imagery is contraindicated in active psychosis because altered reality perception means imagery may worsen hallucinations or delusions. Being non-pharmacological does not make it appropriate in this contraindication.', false),
  ('imagery', 5, 'Before a guided imagery session, a client with cancer pain has a heart rate of 104/min, respiratory rate of 24/min, and blood pressure of 148/92 mm Hg. Which set of findings after the session BEST indicates the expected relaxation response?', '[{"id": "a", "text": "HR 112/min, RR 26/min, BP 152/94 mm Hg"}, {"id": "b", "text": "HR 104/min, RR 24/min, BP 148/92 mm Hg"}, {"id": "c", "text": "HR 110/min, RR 18/min, BP 156/96 mm Hg"}, {"id": "d", "text": "HR 86/min, RR 16/min, BP 132/84 mm Hg"}]'::jsonb, '["d"]', 'The relaxation response is characterized by decreased heart rate, respiratory rate, and blood pressure, so all three values should fall. Option c shows a lower respiratory rate but a higher heart rate and blood pressure, which reflects sympathetic activity, not relaxation.', false),
  ('imagery', 6, 'A nurse is precepting a new graduate who is conducting guided imagery with an anxious client. Which actions by the new graduate are appropriate? Select all that apply.', '[{"id": "a", "text": "Uses a calm, slow, gentle voice"}, {"id": "b", "text": "Allows silences without rushing"}, {"id": "c", "text": "Plans for a session of about 10–20 minutes"}, {"id": "d", "text": "Fills every pause with talk to keep focus"}, {"id": "e", "text": "Asks what the client can see, hear, smell, and feel"}]'::jsonb, '["a", "b", "c", "e"]', 'During the session the nurse uses a calm, slow, gentle voice (a), allows silences (b), and plans a typical 10–20 minute session (c); asking what the client sees, hears, smells, and feels (e) engages the senses. Filling every pause (d) contradicts allowing silences and avoiding rushing.', true),
  ('imagery', 7, 'A client with PTSD after nearly drowning is referred for guided imagery to reduce anxiety. The nurse''s usual script describes a beach with waves. Which action by the nurse is BEST?', '[{"id": "a", "text": "Ask the client to choose a scene that feels safe and calm"}, {"id": "b", "text": "Use the beach script, because the ocean is calming to most"}, {"id": "c", "text": "Skip imagery because PTSD is a contraindication to its use"}, {"id": "d", "text": "Have the client picture the near-drowning to face the fear"}]'::jsonb, '["a"]', 'Significant trauma history requires trauma-informed precautions because some images, such as water for someone with drowning trauma, may trigger traumatic memories; the nurse asks the client to choose a place of safety and calm. PTSD itself is an indication (safe-place imagery), not a contraindication.', false),
  ('imagery', 8, 'A client admitted with depression tells the nurse, "I have a plan to end my life tonight." The client is tearful and agitated and asks the nurse to "do that relaxation thing." Which statement about guided imagery for this client is MOST accurate?', '[{"id": "a", "text": "It is the first-line intervention because it is non-addictive"}, {"id": "b", "text": "It should be avoided because the client has depression"}, {"id": "c", "text": "It is not appropriate as the primary or sole intervention"}, {"id": "d", "text": "It can replace other care if the client calms down quickly"}]'::jsonb, '["c"]', 'In an acute suicidal crisis, guided imagery is not appropriate as the primary or sole intervention. Depression itself is an indication (positive future imagery), so the problem is the acute crisis, not the diagnosis.', false),
  ('imagery', 9, 'A nurse completes a 15-minute guided imagery session with a client who has post-operative pain. Which actions should the nurse take to evaluate and document the session? Select all that apply.', '[{"id": "a", "text": "Compare the client''s pain level before and after"}, {"id": "b", "text": "Document the intervention and the client''s response"}, {"id": "c", "text": "Record the heart rate before and after the session"}, {"id": "d", "text": "Document only that the client fell asleep"}, {"id": "e", "text": "Wait until the next shift to assess anxiety"}]'::jsonb, '["a", "b", "c"]', 'The nurse assesses pain level, anxiety, HR, and patient report before and after (a, c) and documents the intervention and response in the nursing note (b). Documenting only sleep (d) omits the response measures, and anxiety is assessed before and after the session, not on a later shift (e).', true),
  ('imagery', 10, 'A nurse is planning guided imagery sessions for a client with generalized anxiety disorder who has limited time between therapy groups. Which session length should the nurse plan as typical?', '[{"id": "a", "text": "2 to 5 minutes"}, {"id": "b", "text": "10 to 20 minutes"}, {"id": "c", "text": "45 to 60 minutes"}, {"id": "d", "text": "At least 90 minutes"}]'::jsonb, '["b"]', 'A typical guided imagery session lasts 10–20 minutes, delivered with a calm, slow voice and without rushing. A 2–5 minute session would rush the steps, and sessions of 45 minutes or longer exceed the typical length.', false),
  ('imagery', 11, 'At the end of a guided imagery session, a client with chronic pain says, "I feel so relaxed," then immediately tries to stand to walk to the bathroom. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Start a second session so the client stays relaxed longer"}, {"id": "b", "text": "Let the client walk alone, since relaxation lowers pain"}, {"id": "c", "text": "Document the session as complete and leave the room"}, {"id": "d", "text": "Allow the client time to reorient before resuming activity"}]'::jsonb, '["d"]', 'In the return-and-reorient step, the nurse gently guides the client back and allows time before resuming activity. Leaving or letting the client get up immediately skips reorientation and the before-and-after evaluation.', false),
  ('imagery', 12, 'A nurse on an inpatient psychiatric unit reviews clients who have asked to join a guided imagery group. For which clients should guided imagery be avoided or used with caution? Select all that apply.', '[{"id": "a", "text": "A client with migraine headaches"}, {"id": "b", "text": "A client with active psychosis"}, {"id": "c", "text": "A client with a severe dissociative disorder"}, {"id": "d", "text": "A client with severe cognitive impairment"}, {"id": "e", "text": "A client in an acute suicidal crisis"}]'::jsonb, '["b", "c", "d", "e"]', 'Guided imagery is avoided or used with caution in active psychosis (b), severe dissociative disorders (c), severe cognitive impairment (d), and acute suicidal crisis, where it is not appropriate as the primary or sole intervention (e). Headache and migraine relief (a) is an indication.', true),
  ('imagery', 13, 'A nursing assistant asks the RN, "Don''t you need a provider''s order before doing guided imagery with that anxious patient?" Which response by the RN is MOST accurate?', '[{"id": "a", "text": "\"It may be started as an independent nursing action for comfort.\""}, {"id": "b", "text": "\"Yes, it can only be done after the provider writes an order.\""}, {"id": "c", "text": "\"It is outside nursing scope, so a therapist must perform it.\""}, {"id": "d", "text": "\"It may be done only by the patient after a therapist teaches it.\""}]'::jsonb, '["a"]', 'Guided imagery is within the nursing scope of practice and may be initiated as an independent nursing action for comfort and relaxation or as part of a care plan. Nurses can teach and facilitate it, so it is not limited to therapists.', false),
  ('imagery', 14, 'A client with pre-operative anxiety has chosen a forest as a peaceful scene. Which statement by the nurse BEST deepens the client''s response to the imagery?', '[{"id": "a", "text": "\"Picture a forest, and try not to think about your surgery.\""}, {"id": "b", "text": "\"Count slowly backward from 100 while you think of trees.\""}, {"id": "c", "text": "\"Feel the soft moss underfoot, hear the birds, smell the pine.\""}, {"id": "d", "text": "\"Imagine the forest exactly as I describe it, without changes.\""}]'::jsonb, '["c"]', 'Guiding the client to "be" in the scene using all senses — touch, sound, smell, sight — deepens the response. Telling the client to imagine the scene exactly as the nurse describes it ignores that the client chooses or suggests the focus image.', false),
  ('imagery', 15, 'A mental health nurse is planning guided imagery for several clients in an outpatient program. Which pairings of client problem and imagery approach are appropriate? Select all that apply.', '[{"id": "a", "text": "A client with a phobia: imagery used alone in place of exposure therapy"}, {"id": "b", "text": "A client with PTSD: safe-place imagery"}, {"id": "c", "text": "A client with insomnia: imagery avoided as contraindicated"}, {"id": "d", "text": "A client with depression: positive future imagery"}, {"id": "e", "text": "A client with GAD: imagery avoided because it is not indicated"}]'::jsonb, '["b", "d"]', 'PTSD is treated with safe-place imagery (b) and depression with positive future imagery (d). For phobias, imagery is combined with exposure therapy rather than used in place of it (a), and insomnia (c) and generalized anxiety disorder (e) are mental health indications, not contraindications.', true),
  ('imagery', 16, 'A client with generalized anxiety disorder who has learned guided imagery tells the nurse, "This works so well that I''m going to stop going to my therapy sessions." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"That''s a good plan, since imagery is evidence-based and safe.\""}, {"id": "b", "text": "\"Imagery is complementary; it is not a replacement for therapy.\""}, {"id": "c", "text": "\"You should stop imagery, because it is only meant for physical pain.\""}, {"id": "d", "text": "\"Imagery only works if a nurse leads every session with you.\""}]'::jsonb, '["b"]', 'Guided imagery is not a replacement for therapy but a complementary, evidence-based nursing intervention. It is indicated for generalized anxiety disorder, and patients are taught to use it independently, so the other responses are inaccurate.', false),
  ('imagery', 17, 'A client with migraine headaches asks the nurse, "How can just picturing a garden possibly help my pain?" Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "\"It distracts you, but it doesn''t change anything in your body.\""}, {"id": "b", "text": "\"It works only if you also take your pain medication with it.\""}, {"id": "c", "text": "\"It activates your fight-or-flight response to block the pain.\""}, {"id": "d", "text": "\"Your brain processes vivid images much like real experiences.\""}]'::jsonb, '["d"]', 'The brain processes vivid mental images similarly to real experiences, activating the parasympathetic nervous system and the relaxation response. Imagery reduces sympathetic (fight-or-flight) activity rather than activating it.', false),
  ('imagery', 18, 'A nurse is teaching a client with irritable bowel syndrome about the physiological effects of guided imagery. Which effects should the nurse include? Select all that apply.', '[{"id": "a", "text": "Decreased muscle tension"}, {"id": "b", "text": "Reduced cortisol (stress hormone)"}, {"id": "c", "text": "Increased sympathetic activity"}, {"id": "d", "text": "Increased endorphin release"}, {"id": "e", "text": "Decreased respiratory rate"}]'::jsonb, '["a", "b", "d", "e"]', 'Guided imagery activates the parasympathetic nervous system, decreasing HR, BP, muscle tension (a), and respiratory rate (e), and it reduces cortisol (b) and increases endorphin release (d). It reduces, rather than increases, sympathetic activity (c).', true),
  ('imagery', 19, 'A nurse has time to conduct one guided imagery session this afternoon. Which client is the MOST appropriate candidate?', '[{"id": "a", "text": "A client receiving chemotherapy who has nausea"}, {"id": "b", "text": "A client with dementia who cannot follow instructions"}, {"id": "c", "text": "A client with a severe dissociative disorder"}, {"id": "d", "text": "A client in acute suicidal crisis with a plan"}]'::jsonb, '["a"]', 'Evidence shows guided imagery is effective for chemotherapy nausea. Severe cognitive impairment, severe dissociative disorders, and acute suicidal crisis are situations in which imagery is avoided or not appropriate as the primary intervention.', false),
  ('imagery', 20, 'A client with dissociative identity disorder who frequently loses track of time and identity asks to join the unit''s guided imagery group to help with stress. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Yes — imagery is recommended for any kind of stress.\""}, {"id": "b", "text": "\"Yes, as long as you pick a pleasant place to imagine.\""}, {"id": "c", "text": "\"Imagery may worsen dissociative episodes, so we need caution.\""}, {"id": "d", "text": "\"No — imagery is only used for physical pain, not for stress.\""}]'::jsonb, '["c"]', 'Severe dissociative disorders call for avoiding or using caution with guided imagery because it may exacerbate dissociative episodes. Stress management is an indication in general, but the dissociative disorder changes the risk for this client.', false),
  ('imagery', 21, 'A nurse has taught a client with chronic pain how to use guided imagery at home. Which client statements indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"I''ll ensure privacy, reduce noise, and get in a comfortable position.\""}, {"id": "b", "text": "\"I''ll rush through it in a couple of minutes when I''m busy.\""}, {"id": "c", "text": "\"I''ll breathe in through my nose and out through my mouth.\""}, {"id": "d", "text": "\"I''ll engage all my senses: sight, sound, smell, and touch.\""}, {"id": "e", "text": "\"I''ll stop all of my other pain treatments now that I have this.\""}]'::jsonb, '["a", "c", "d"]', 'The client correctly plans to ensure privacy, reduce noise, and get into a comfortable position (a), use diaphragmatic breathing in through the nose and out through the mouth (c), and engage all the senses (d). Sessions should not be rushed (b), and imagery is complementary, not a replacement for other care (e).', true),
  ('imagery', 22, 'A client 6 hours after abdominal surgery reports pain of 6/10 and is anxious. The next dose of opioid analgesic is not due for 2 hours, and the provider has declined to change the order. Which nursing action is the PRIORITY?', '[{"id": "a", "text": "Tell the client to wait quietly until the next dose is due"}, {"id": "b", "text": "Use guided imagery as a non-pharmacological intervention"}, {"id": "c", "text": "Give the next opioid dose early to control the pain"}, {"id": "d", "text": "Contact the provider again to request a stronger opioid"}]'::jsonb, '["b"]', 'Guided imagery is non-pharmacological, non-addictive, and evidence-based — a strong priority intervention when medications aren''t appropriate — and it is indicated for acute pain management and post-operative anxiety. Asking the client to simply wait leaves the pain and anxiety unaddressed.', false),
  ('imagery', 23, 'A charge nurse observes a new nurse preparing to lead guided imagery for a client with procedural anxiety before a dressing change. Which action by the new nurse requires correction?', '[{"id": "a", "text": "Helps the client into a comfortable seated position"}, {"id": "b", "text": "Dims the overhead lights in the client''s room"}, {"id": "c", "text": "Asks the client what calming place to picture"}, {"id": "d", "text": "Leaves the door open and the television on low"}]'::jsonb, '["d"]', 'Preparing the environment requires privacy, reduced noise, a closed door, and minimal interruptions, so leaving the door open with the television on needs correction. Dimming lights, positioning comfortably, and letting the client choose the scene are correct.', false),
  ('imagery', 24, 'During a guided imagery session for a client with insomnia, the nurse notices the client has been silent and breathing slowly for about a minute. Which nurse actions are appropriate at this point in the session? Select all that apply.', '[{"id": "a", "text": "Allow the silence to continue without rushing"}, {"id": "b", "text": "Speak more quickly so the session ends on time"}, {"id": "c", "text": "Turn up the lights to check the client''s alertness"}, {"id": "d", "text": "Keep using a calm, slow, gentle voice when speaking"}, {"id": "e", "text": "Ask the client to open both eyes and sit up right away"}]'::jsonb, '["a", "d"]', 'While maintaining the session, the nurse allows silences and avoids rushing (a) and uses a calm, slow, gentle voice (d). Speaking quickly (b) rushes the session, raising the lights (c) undoes the prepared environment, and the return step is gradual — "when you''re ready" — not abrupt (e).', true),
  ('imagery', 25, 'A nurse is about to begin the imagery portion of a session with a client who has hypertension and is anxious about a stress test. Which nurse statement is MOST appropriate when establishing the focus image?', '[{"id": "a", "text": "\"Choose a peaceful, pleasant place where you feel safe and calm.\""}, {"id": "b", "text": "\"We''ll picture a beach today, because that works for everyone.\""}, {"id": "c", "text": "\"Picture the stress test going perfectly from start to finish.\""}, {"id": "d", "text": "\"Imagine any scene that comes to mind, even if it is upsetting.\""}]'::jsonb, '["a"]', 'When establishing a focus image, the nurse asks the patient to choose or suggest a peaceful, pleasant scene — a place of safety and calm. Imposing a beach ignores client choice, and an upsetting scene defeats the purpose of the technique.', false),
  ('imagery', 26, 'A client with chronic neck pain is visibly tense, with clenched jaw and raised shoulders, and is having difficulty settling for a guided imagery session in a quiet, darkened room. Which sequence is BEST for the nurse to follow?', '[{"id": "a", "text": "Engage the senses in a scene, then teach diaphragmatic breathing"}, {"id": "b", "text": "Assess the pain level after the session only, then begin imagery"}, {"id": "c", "text": "Diaphragmatic breathing, muscle relaxation, then imagery"}, {"id": "d", "text": "Establish the focus image first, then progressive muscle relaxation"}]'::jsonb, '["c"]', 'After preparing the environment, the nurse guides slow, deep diaphragmatic breathing, and progressive muscle relaxation may precede imagery before the focus image is established. Pain is assessed before and after the session, not only afterward.', false),
  ('imagery', 27, 'A nurse in an outpatient clinic is identifying clients who may benefit from guided imagery for a physical indication. Which clients are appropriate candidates? Select all that apply.', '[{"id": "a", "text": "A client with drowning trauma, using an ocean script"}, {"id": "b", "text": "A client with irritable bowel syndrome (IBS)"}, {"id": "c", "text": "A client receiving care for hypertension management"}, {"id": "d", "text": "A client in acute suicidal crisis, as the only intervention"}, {"id": "e", "text": "A client seeking headache and migraine relief"}]'::jsonb, '["b", "c", "e"]', 'Physical indications include irritable bowel syndrome (b), hypertension management (c), and headache and migraine relief (e). Water imagery may trigger trauma related to drowning (a), and imagery is not appropriate as the primary or sole intervention in an acute suicidal crisis (d).', true),
  ('imagery', 28, 'During relaxation breathing at the start of guided imagery, a client with pre-operative anxiety is taking rapid, shallow breaths through the mouth. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "\"Breathe quickly through your mouth to release the tension.\""}, {"id": "b", "text": "\"Breathe slowly and deeply, in through your nose, out your mouth.\""}, {"id": "c", "text": "\"Hold your breath as long as you can, then let it out all at once.\""}, {"id": "d", "text": "\"Breathe in and out through your mouth while you tighten your chest.\""}]'::jsonb, '["b"]', 'Relaxation breathing is slow, deep diaphragmatic breathing — in through the nose and out through the mouth. Rapid mouth breathing or breath-holding does not produce the relaxation response.', false),
  ('imagery', 29, 'A nurse has just completed guided imagery with a client who has cancer pain. Before the session the client rated pain 8/10 with HR 108/min; afterward the client rates pain 5/10 with HR 90/min. Which documentation entry is BEST?', '[{"id": "a", "text": "\"Guided imagery done. Client tolerated well.\""}, {"id": "b", "text": "\"Client relaxed after imagery; will repeat it daily.\""}, {"id": "c", "text": "\"Imagery offered for pain; client appeared to enjoy it.\""}, {"id": "d", "text": "\"Imagery 15 min; pain 8/10 to 5/10, HR 108 to 90; client reports relief.\""}]'::jsonb, '["d"]', 'The nurse assesses pain level, anxiety, HR, and patient report before and after the session and documents the intervention and response. The other entries omit the before-and-after measures needed to show effectiveness.', false),
  ('imagery', 30, 'During a staff in-service on guided imagery, several nurses describe their role. Which statements about the nurse''s role with a client are accurate? Select all that apply.', '[{"id": "a", "text": "\"Only a licensed therapist may lead guided imagery.\""}, {"id": "b", "text": "\"We teach it so patients can use it independently.\""}, {"id": "c", "text": "\"It can take the place of therapy for most patients.\""}, {"id": "d", "text": "\"We document effectiveness and patient response.\""}, {"id": "e", "text": "\"A provider''s order is required before each session.\""}]'::jsonb, '["b", "d"]', 'Nurses teach the technique so patients can use it independently (b) and document effectiveness and patient response (d). Guided imagery is within nursing scope (a), may be initiated as an independent nursing action (e), and is complementary, not a replacement for therapy (c).', true),
  ('imagery', 31, 'A 16-year-old with a history of needle fear is about to have an IV inserted and is crying and pulling her arm away. The procedure is not urgent. Which nursing intervention is MOST appropriate to reduce her anxiety?', '[{"id": "a", "text": "Have staff hold her arm still and insert the IV quickly"}, {"id": "b", "text": "Guide her through imagery of a calm place she chooses"}, {"id": "c", "text": "Explain that she is too old to be afraid of needles"}, {"id": "d", "text": "Delay the IV until she says she is no longer afraid"}]'::jsonb, '["b"]', 'Procedural anxiety, including anxiety about IVs, is an indication for guided imagery, using a peaceful scene the patient chooses. Restraining her or dismissing her fear does not address the anxiety.', false),
  ('imagery', 32, 'A nurse has guided a client with generalized anxiety disorder through a 15-minute imagery session at the beach the client chose. Which statement is BEST for the nurse to use to end the session?', '[{"id": "a", "text": "\"Okay, time''s up. Open your eyes and get back to group right now.\""}, {"id": "b", "text": "\"Stay at the beach as long as you like; I''ll leave you alone.\""}, {"id": "c", "text": "\"When you''re ready, take a deep breath and slowly open your eyes.\""}, {"id": "d", "text": "\"Now picture the problems that made you anxious this morning.\""}]'::jsonb, '["c"]', 'In the return-and-reorient step, the nurse gently guides the client back — "When you''re ready, take a deep breath and slowly open your eyes" — and allows time before resuming activity. An abrupt ending rushes the client and skips reorientation.', false),
  ('imagery', 33, 'A client with chronic pain has chosen a garden as a peaceful scene. Which questions should the nurse ask to engage the client''s senses during guided imagery? Select all that apply.', '[{"id": "a", "text": "\"What can you hear in the garden?\""}, {"id": "b", "text": "\"Why did you choose a garden?\""}, {"id": "c", "text": "\"What can you smell in the garden?\""}, {"id": "d", "text": "\"What can you see in the garden?\""}, {"id": "e", "text": "\"What can you feel under your feet?\""}]'::jsonb, '["a", "c", "d", "e"]', 'The nurse asks what the client can see, hear, smell, and feel (a, c, d, e) because multisensory engagement deepens the response. Asking why the client chose the garden (b) is analytical and does not engage the senses.', true),
  ('imagery', 34, 'A client with migraines who has just learned guided imagery asks, "What is this ''relaxation response'' you keep mentioning?" Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "\"It is a state of high alert that helps your body fight pain.\""}, {"id": "b", "text": "\"It is the stress response that occurs when you feel anxious.\""}, {"id": "c", "text": "\"It is the sympathetic system speeding up your heart rate.\""}, {"id": "d", "text": "\"It is a state of deep rest, the opposite of fight-or-flight.\""}]'::jsonb, '["d"]', 'The relaxation response is a physiological state of deep rest — the opposite of the stress/fight-or-flight response — with decreased heart rate, respiratory rate, and blood pressure. Increased heart rate from sympathetic activity is the opposite of the relaxation response.', false),
  ('imagery', 35, 'A combat veteran with PTSD who is stable and not in crisis asks the nurse to help him use guided imagery for his frequent anxiety. Which imagery approach is MOST appropriate?', '[{"id": "a", "text": "Safe-place imagery of a scene he chooses"}, {"id": "b", "text": "Positive future imagery of his next goals"}, {"id": "c", "text": "Imagery of the combat scene to process it"}, {"id": "d", "text": "Imagery combined with exposure for phobias"}]'::jsonb, '["a"]', 'Safe-place imagery is the approach listed for PTSD, and the patient chooses a place of safety and calm. Positive future imagery is the approach for depression, and imagery combined with exposure therapy is used for phobias.', false),
  ('imagery', 36, 'A nursing student explains guided imagery to a client during a clinical day. Which statements by the student require correction? Select all that apply.', '[{"id": "a", "text": "\"Imagery activates your sympathetic nervous system.\""}, {"id": "b", "text": "\"Visualization is the core mechanism of imagery.\""}, {"id": "c", "text": "\"The relaxation response is like fight-or-flight.\""}, {"id": "d", "text": "\"Imagery can help reduce cortisol, a stress hormone.\""}, {"id": "e", "text": "\"Imagery decreases the release of your endorphins.\""}]'::jsonb, '["a", "c", "e"]', 'Imagery activates the parasympathetic branch and reduces sympathetic activity (a), the relaxation response is the opposite of fight-or-flight (c), and imagery increases, not decreases, endorphin release (e). Visualization as the core mechanism (b) and reduced cortisol (d) are accurate.', true),
  ('imagery', 37, 'A client with depression who is not suicidal tells the nurse, "I can''t see anything good ahead of me." The nurse plans guided imagery as part of the care plan. Which imagery approach is MOST appropriate for this client?', '[{"id": "a", "text": "Safe-place imagery of a past refuge"}, {"id": "b", "text": "Imagery combined with exposure therapy"}, {"id": "c", "text": "Positive future imagery"}, {"id": "d", "text": "Imagery of a stressful upcoming event"}]'::jsonb, '["c"]', 'Positive future imagery is the approach listed for depression. Safe-place imagery is the approach for PTSD, and imagery combined with exposure therapy is used for phobias.', false),
  ('imagery', 38, 'A client with a severe fear of elevators is beginning treatment with a therapist. The client asks the nurse whether guided imagery alone can treat the phobia. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Yes, imagery alone is the standard treatment for phobias.\""}, {"id": "b", "text": "\"For phobias, imagery is combined with exposure therapy.\""}, {"id": "c", "text": "\"No, imagery is contraindicated for anyone with a phobia.\""}, {"id": "d", "text": "\"Imagery only helps physical problems, not phobias.\""}]'::jsonb, '["b"]', 'Guided imagery is a mental health intervention for phobias when combined with exposure therapy. It is not contraindicated for phobias, and it is not limited to physical problems.', false),
  ('imagery', 39, 'A client with a history of sexual assault and ongoing anxiety is scheduled for guided imagery to manage chronic pelvic pain. Which nursing actions reflect trauma-informed precautions? Select all that apply.', '[{"id": "a", "text": "Use the unit''s standard script without asking about it"}, {"id": "b", "text": "Ask the client to choose a scene of safety and calm"}, {"id": "c", "text": "Have the client picture the assault to process the pain"}, {"id": "d", "text": "Avoid imagery entirely because of the trauma history"}, {"id": "e", "text": "Watch for images that may trigger traumatic memories"}]'::jsonb, '["b", "e"]', 'With a significant trauma history, the nurse uses trauma-informed precautions: letting the client choose a place of safety and calm (b) and being alert that some images may trigger traumatic memories (e). A standard script (a) or picturing the assault (c) risks triggering trauma, and trauma history calls for precautions, not automatic avoidance (d).', true),
  ('imagery', 40, 'A client with insomnia has completed three nurse-led guided imagery sessions on the unit and will be discharged tomorrow. Which outcome BEST reflects the nursing goal of teaching guided imagery?', '[{"id": "a", "text": "The client asks the nurse to lead a session each night"}, {"id": "b", "text": "The client asks for a sleeping pill to replace imagery"}, {"id": "c", "text": "The client states imagery needs a nurse to be present"}, {"id": "d", "text": "The client uses guided imagery independently at home"}]'::jsonb, '["d"]', 'Nurses teach the technique so patients can use it independently for self-management. Depending on the nurse for every session shows the teaching goal has not been met.', false),
  ('imagery', 41, 'A nursing student writes in a care plan that guided imagery will reduce a client''s anxiety. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"Imagery activates the sympathetic branch of the nervous system.\""}, {"id": "b", "text": "\"Imagery can lower heart rate, blood pressure, and muscle tension.\""}, {"id": "c", "text": "\"Imagery activates the relaxation response, the opposite of stress.\""}, {"id": "d", "text": "\"Imagery activates the parasympathetic ''rest and digest'' branch.\""}]'::jsonb, '["a"]', 'Guided imagery activates the parasympathetic branch (rest and digest) and reduces the sympathetic (fight-or-flight) response. The other statements accurately describe its effects.', false),
  ('imagery', 42, 'A nurse teaches a client scheduled for surgery tomorrow how to use guided imagery for pre-operative anxiety. Which client statements indicate understanding of the expected effects? Select all that apply.', '[{"id": "a", "text": "\"My heart rate may slow down as I relax.\""}, {"id": "b", "text": "\"My respiratory rate should decrease.\""}, {"id": "c", "text": "\"My muscle tension may decrease.\""}, {"id": "d", "text": "\"My blood pressure may go up as I focus.\""}, {"id": "e", "text": "\"It may reduce my pre-operative anxiety.\""}]'::jsonb, '["a", "b", "c", "e"]', 'Guided imagery activates the parasympathetic nervous system, decreasing heart rate (a), respiratory rate (b), and muscle tension (c), and is used to reduce pre-operative anxiety (e). Blood pressure decreases rather than rises (d).', true),
  ('imagery', 43, 'A client receiving chemotherapy says, "My oncologist mentioned guided imagery, but isn''t that just a new-age fad?" Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"It''s a fad, but some people like it, so it can''t hurt.\""}, {"id": "b", "text": "\"It''s experimental, so it''s only used in research studies.\""}, {"id": "c", "text": "\"The NIH supports it as a complementary health practice.\""}, {"id": "d", "text": "\"It replaces medication for chemotherapy-related nausea.\""}]'::jsonb, '["c"]', 'Guided imagery is supported by the NIH as a complementary health practice, with evidence for cancer pain and chemotherapy nausea. It is complementary, so it does not replace other treatment.', false),
  ('imagery', 44, 'A nurse is about to start guided imagery with a client who has post-operative pain and anxiety. Which data should the nurse collect right before beginning so that effectiveness can be evaluated?', '[{"id": "a", "text": "The client''s preferred music and favorite vacation spot"}, {"id": "b", "text": "The client''s pain level, anxiety, and heart rate"}, {"id": "c", "text": "The client''s height, weight, and allergy history"}, {"id": "d", "text": "The client''s opinion of complementary therapies"}]'::jsonb, '["b"]', 'Evaluation requires assessing pain level, anxiety, HR, and patient report before and after the session. The client''s preferred scene is chosen during the session, but baseline measures are needed to judge effectiveness.', false),
  ('imagery', 45, 'A nurse evaluates a guided imagery session for a client with procedural anxiety before a dressing change. Which post-session findings indicate the intervention was effective? Select all that apply.', '[{"id": "a", "text": "Heart rate fell from 112/min to 88/min"}, {"id": "b", "text": "The client reports anxiety is unchanged"}, {"id": "c", "text": "Respiratory rate rose from 18/min to 24/min"}, {"id": "d", "text": "Pain level fell from 7/10 to 4/10"}, {"id": "e", "text": "Blood pressure rose from 128/80 to 144/92"}]'::jsonb, '["a", "d"]', 'A falling heart rate (a) reflects the relaxation response, and a lower pain level (d) shows the intended effect on pain. Unchanged anxiety (b) does not show effectiveness, and rising respiratory rate (c) and blood pressure (e) are the opposite of the expected decreases.', true),
  ('imagery', 46, 'A client receiving the first cycle of chemotherapy becomes anxious and tearful as the infusion is about to start and has an antiemetic already given as ordered. Which additional nursing action is MOST appropriate?', '[{"id": "a", "text": "Ask the provider to delay chemotherapy until the anxiety resolves"}, {"id": "b", "text": "Tell the client that most people feel fine during chemotherapy"}, {"id": "c", "text": "Leave the client alone so the infusion can run without stress"}, {"id": "d", "text": "Offer guided imagery to reduce the client''s procedural anxiety"}]'::jsonb, '["d"]', 'Procedural anxiety, including anxiety about chemotherapy, is an indication for guided imagery, which is complementary to ordered medications. Leaving the client alone or offering false reassurance does not address the anxiety.', false),
  ('imagery', 47, 'A client being followed in the clinic for hypertension management asks the nurse for a non-drug strategy to use at home when feeling stressed. Which nursing action is MOST appropriate?', '[{"id": "a", "text": "Teach the client guided imagery for self-management"}, {"id": "b", "text": "Advise the client to stop the prescribed medication"}, {"id": "c", "text": "Tell the client stress has no effect on blood pressure"}, {"id": "d", "text": "Recommend imagery only when a nurse can lead it"}]'::jsonb, '["a"]', 'Hypertension management is a physical indication for guided imagery, and nurses teach the technique so patients can use it independently. Imagery is complementary, so it does not replace prescribed treatment.', false),
  ('imagery', 48, 'A college music student reports a racing heart and shaking hands before every recital and asks the nurse for help. The student prefers to avoid medication. Which nursing action is BEST?', '[{"id": "a", "text": "Recommend that the student avoid performing for now"}, {"id": "b", "text": "Reassure the student that the anxiety will pass on its own"}, {"id": "c", "text": "Teach a quick 2-minute version to use backstage"}, {"id": "d", "text": "Teach guided imagery for the student''s performance anxiety"}]'::jsonb, '["d"]', 'Performance anxiety is a mental health indication for guided imagery, a non-pharmacological, evidence-based intervention. A rushed 2-minute version conflicts with the typical 10–20 minute session and the guidance to avoid rushing.', false),
  ('imagery', 49, 'A client with a history of near-drowning and chronic pain is scheduled for guided imagery. The nurse''s standard script describes a lakeside scene. What should the nurse do FIRST?', '[{"id": "a", "text": "Begin the lakeside script and stop if the client seems upset"}, {"id": "b", "text": "Cancel imagery because trauma is an absolute contraindication"}, {"id": "c", "text": "Ask the client to choose a scene that feels safe and calm"}, {"id": "d", "text": "Ask the client to describe the drowning in detail before imagery"}]'::jsonb, '["c"]', 'Without trauma-informed precautions, some images — such as water for someone with drowning trauma — may trigger traumatic memories, so the nurse first lets the client choose a place of safety and calm. Trauma history calls for caution, not automatic cancellation.', false),
  ('imagery', 50, 'After a 15-minute guided imagery session, a client with chronic pain reports no change in pain (6/10 before and after), and heart rate remains 96/min. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Record the session as effective since it was completed"}, {"id": "b", "text": "Document the intervention and the client''s response"}, {"id": "c", "text": "Omit the session from the record since it did not work"}, {"id": "d", "text": "Document only the pain rating taken before the session"}]'::jsonb, '["b"]', 'The nurse documents the intervention and the patient''s response, including effectiveness, as part of nursing assessment — even when there is no improvement. Recording it as effective or omitting it misrepresents the before-and-after findings.', false),
  ('ethics', 1, 'A 45-year-old competent patient who is bleeding after surgery refuses a blood transfusion for religious reasons. The patient''s adult son insists, "Give it anyway; she''ll thank you later." Which action by the nurse is BEST?', '[{"id": "a", "text": "Give the transfusion, because the son''s request reflects beneficence"}, {"id": "b", "text": "Respect the patient''s decision and inform the provider"}, {"id": "c", "text": "Ask the son to sign consent so the transfusion can be given legally"}, {"id": "d", "text": "Consult the ethics committee before honoring the patient''s refusal"}]'::jsonb, '["b"]', 'Autonomy means a competent adult may refuse a blood transfusion for religious reasons, and the nurse must respect this decision even if others disagree. A family member cannot override a competent patient, and an ethics committee is a resource for complex dilemmas, not for a clear refusal by a competent adult.', false),
  ('ethics', 2, 'A nurse educator asks new graduates to identify care that applies the principle of autonomy, using examples from each patient assignment on a psychiatric unit. Which nursing actions reflect autonomy? Select all that apply.', '[{"id": "a", "text": "Giving a patient full information before ECT consent"}, {"id": "b", "text": "Initiating suicide precautions for a patient at risk"}, {"id": "c", "text": "Following a patient''s advance directive while unconscious"}, {"id": "d", "text": "Triaging the most critical patient first"}, {"id": "e", "text": "Honoring a competent patient''s refusal of medication"}]'::jsonb, '["a", "c", "e"]', 'Autonomy includes informed consent with full information before treatment such as ECT (a), advance directives that guide care even when the patient is unconscious (c), and the right to refuse medication (e). Initiating suicide precautions (b) is a mental health application of beneficence, and triaging the most critical patient first (d) reflects justice.', true),
  ('ethics', 3, 'A competent patient with bipolar disorder tells the nurse she will stop taking her mood stabilizer because it makes her feel "flat," although the treatment team believes it is preventing relapse. Which ethical principles are MOST directly in conflict?', '[{"id": "a", "text": "Justice vs. beneficence"}, {"id": "b", "text": "Autonomy vs. beneficence"}, {"id": "c", "text": "Veracity vs. fidelity"}, {"id": "d", "text": "Confidentiality vs. nonmaleficence"}]'::jsonb, '["b"]', 'When a patient refuses psychiatric medication, the patient''s right to decide (autonomy) is in tension with the team''s duty to act in the patient''s best interest (beneficence). Confidentiality vs. nonmaleficence is the conflict raised when a patient discloses a plan to harm someone.', false),
  ('ethics', 4, 'A competent adult patient with schizophrenia refuses his scheduled antipsychotic, saying, "I don''t want it anymore." He is calm and is not a danger to anyone. Which actions are appropriate for the nurse? Select all that apply.', '[{"id": "a", "text": "Explore the patient''s reasons for refusal"}, {"id": "b", "text": "Ensure the patient has full information"}, {"id": "c", "text": "Mix the medication into food without telling him"}, {"id": "d", "text": "Document the refusal"}, {"id": "e", "text": "Respect the competent patient''s refusal"}]'::jsonb, '["a", "b", "d", "e"]', 'For a competent patient who refuses psychiatric medication, the nurse respects the refusal (e), documents it (d), ensures the patient has full information (b), and explores the reasons for refusal (a). Hiding medication in food (c) overrides autonomy and is a form of withholding truth, which destroys trust.', true),
  ('ethics', 5, 'An 80-year-old patient with dementia pushes the nurse away and refuses to let staff change her soiled clothing. Her daughter says, "Just do it; she doesn''t know what she''s saying." Which action should the nurse take FIRST?', '[{"id": "a", "text": "Change the clothing now, because beneficence outweighs autonomy here"}, {"id": "b", "text": "Leave her in the soiled clothing to respect her right to autonomy"}, {"id": "c", "text": "Determine whether the patient has decisional capacity"}, {"id": "d", "text": "Ask the daughter to make the decision as the surrogate"}]'::jsonb, '["c"]', 'When a patient with dementia refuses care, the nurse first determines decisional capacity; only if capacity is lacking are advance directives or a surrogate decision-maker used. Overriding the refusal, simply accepting it, or turning to the daughter all skip this first step.', false),
  ('ethics', 6, 'A patient with advanced dementia who lacks decisional capacity is admitted with pneumonia. Her advance directive, written while she was competent, declines a feeding tube. Her son asks the team to place one anyway. Which action by the nurse BEST reflects the patient''s autonomy?', '[{"id": "a", "text": "Follow the son''s wishes, since he is now the decision-maker"}, {"id": "b", "text": "Place the tube, since beneficence takes priority in dementia"}, {"id": "c", "text": "Delay all decisions until the patient regains her capacity"}, {"id": "d", "text": "Advocate for care guided by the advance directive"}]'::jsonb, '["d"]', 'Advance directives express the patient''s pre-stated wishes and guide care even when the patient cannot decide, so they reflect her autonomy. When capacity is lacking, advance directives are used, and a surrogate''s wishes should not replace the patient''s own documented choice.', false),
  ('ethics', 7, 'At 1300 the nurse tells a patient with severe back pain, "I will check on your pain medication in 30 minutes." At 1325 the nurse is asked to help with a routine new admission. Which action BEST demonstrates fidelity?', '[{"id": "a", "text": "Follow through and check on the pain medication as promised"}, {"id": "b", "text": "Assume the patient will use the call light if pain gets worse"}, {"id": "c", "text": "Check on the patient at the end of the shift when time allows"}, {"id": "d", "text": "Ask the patient to wait, since admissions come before pain"}]'::jsonb, '["a"]', 'Fidelity is the duty to keep promises, such as "I will check on your pain medication in 30 minutes." Relying on the call light or checking later breaks the commitment made to the patient.', false),
  ('ethics', 8, 'During an annual review, a manager examines how a nurse cared for each patient on her mental health caseload. Which actions demonstrate the principle of fidelity? Select all that apply.', '[{"id": "a", "text": "Following through on a promise made to a patient"}, {"id": "b", "text": "Maintaining confidentiality of a patient''s disclosures"}, {"id": "c", "text": "Telling a patient the truth about a terminal diagnosis"}, {"id": "d", "text": "Advocating for a patient even when it is unpopular"}, {"id": "e", "text": "Following through on a delegated task as committed"}]'::jsonb, '["a", "b", "d", "e"]', 'Fidelity includes following through on promises (a), maintaining confidentiality as a commitment of privacy (b), advocating for patients even when it is inconvenient or unpopular (d), and following through on delegation and professional commitments (e). Telling the truth about a terminal diagnosis (c) is veracity.', true),
  ('ethics', 9, 'A patient with borderline personality disorder becomes tearful when her assigned nurse arrives 20 minutes late for their scheduled talk, saying, "Everyone always lets me down." Which plan for future sessions BEST reflects fidelity?', '[{"id": "a", "text": "Rotate staff so she does not come to depend on one nurse"}, {"id": "b", "text": "Be consistent and reliable at each session"}, {"id": "c", "text": "End sessions early to limit how much she relies on staff"}, {"id": "d", "text": "Tell her the lateness is not important enough to discuss"}]'::jsonb, '["b"]', 'Fidelity in mental health means being consistent and reliable, and patients with borderline personality disorder particularly rely on it. Rotating staff, ending sessions early, or dismissing the lateness undermines that consistency.', false),
  ('ethics', 10, 'A nurse realizes she gave a patient twice the ordered dose of a sedative. The patient is drowsy but stable, and no one else noticed the error. Which action BEST reflects veracity?', '[{"id": "a", "text": "Accurately report the medication error rather than conceal it"}, {"id": "b", "text": "Chart the dose as the ordered dose to avoid confusing the team"}, {"id": "c", "text": "Watch the patient closely and report it only if harm develops"}, {"id": "d", "text": "Tell the patient the drowsiness is a normal medication effect"}]'::jsonb, '["a"]', 'Veracity includes accurately reporting medication errors rather than concealing them. Waiting for harm, charting a false dose, or giving the patient a false explanation all conceal the truth.', false),
  ('ethics', 11, 'A patient with long-standing depression that has not responded to several medications asks the nurse, "Just tell me this new medication will finally fix everything." Which response by the nurse BEST reflects veracity?', '[{"id": "a", "text": "\"Everything will be fine; this one is definitely going to work for you.\""}, {"id": "b", "text": "\"Let''s not focus on that; tell me about your family instead.\""}, {"id": "c", "text": "\"The provider would not order it unless it was sure to work.\""}, {"id": "d", "text": "\"I won''t give false hope, but I''ll share honest information.\""}]'::jsonb, '["d"]', 'Veracity means providing honest, accurate information and not giving false hope such as "everything will be fine" when it may not be. Changing the subject withholds the truth, and claiming the drug is sure to work is false hope.', false),
  ('ethics', 12, 'A charge nurse evaluates how staff on a psychiatric unit communicate with each patient and with colleagues. Which staff actions demonstrate veracity? Select all that apply.', '[{"id": "a", "text": "Giving honest information about medication side effects"}, {"id": "b", "text": "Accurately reporting a medication error to the team"}, {"id": "c", "text": "Telling a patient with a poor prognosis \"everything will be fine\""}, {"id": "d", "text": "Keeping a promise to return to a patient in 30 minutes"}, {"id": "e", "text": "Telling a patient the truth about the diagnosis"}]'::jsonb, '["a", "b", "e"]', 'Veracity includes honest information about side effects (a), accurately reporting medication errors (b), and telling patients the truth about their diagnosis (e). Saying "everything will be fine" when it may not be (c) is false hope, and keeping a promise (d) is fidelity.', true),
  ('ethics', 13, 'A patient starting a new antipsychotic asks, "Will this make me gain weight? My last one did." The nurse knows weight gain is a common side effect, but a colleague whispers, "Don''t mention it or she won''t take it." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"I''ll give you honest information about its side effects.\""}, {"id": "b", "text": "\"Most people have no problems with it, so there''s no need to worry.\""}, {"id": "c", "text": "\"It''s best not to focus on side effects so you can give it a fair try.\""}, {"id": "d", "text": "\"You should ask the provider, since nurses cannot discuss side effects.\""}]'::jsonb, '["a"]', 'Veracity requires providing honest information about side effects of medications; lying or withholding the truth destroys trust. Minimizing the side effect or deflecting the question withholds the truth the patient asked for.', false),
  ('ethics', 14, 'A patient admitted after an overdose angrily says, "Taking my belt and checking on me every 15 minutes is a violation of my rights." The nurse explains the precautions. Which ethical principle MOST directly supports initiating these suicide precautions?', '[{"id": "a", "text": "Autonomy"}, {"id": "b", "text": "Justice"}, {"id": "c", "text": "Veracity"}, {"id": "d", "text": "Beneficence"}]'::jsonb, '["d"]', 'Initiating suicide precautions to protect a patient at risk is the mental health application of beneficence, acting in the patient''s best interest. Autonomy would favor the patient''s wishes, justice concerns fair treatment, and veracity concerns honesty.', false),
  ('ethics', 15, 'A staff member wants to place a patient in restraints because he keeps pacing the hallway and asking the same questions. The nurse objects, stating that restraints should be a last resort. Which ethical principle is the nurse MOST directly applying?', '[{"id": "a", "text": "Nonmaleficence"}, {"id": "b", "text": "Fidelity"}, {"id": "c", "text": "Veracity"}, {"id": "d", "text": "Justice"}]'::jsonb, '["a"]', 'Using restraints as a last resort is the mental health application of nonmaleficence, because restraints cause harm such as psychological trauma and physical injury. Fidelity, veracity, and justice concern promises, honesty, and fairness.', false),
  ('ethics', 16, 'A nurse manager is reviewing actions taken by nurses on a mental health unit during the past month. Which actions involving patients BEST demonstrate nonmaleficence? Select all that apply.', '[{"id": "a", "text": "Verifying the six rights before giving a medication"}, {"id": "b", "text": "Administering pain medication to relieve suffering"}, {"id": "c", "text": "Reporting a colleague who is practicing unsafely"}, {"id": "d", "text": "Providing education so a patient can make decisions"}, {"id": "e", "text": "Avoiding overmedication of an agitated patient"}]'::jsonb, '["a", "c", "e"]', 'Nonmaleficence, the duty to avoid harm, includes verifying the six rights of medication administration (a), reporting a colleague who is practicing unsafely (c), and avoiding overmedication (e). Administering pain medication (b) and providing education (d) are examples of beneficence, actively doing good.', true),
  ('ethics', 17, 'A nurse notices that a colleague smells of alcohol, is slurring her words, and is about to prepare medications for a patient on the unit. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Report the colleague who is practicing unsafely"}, {"id": "b", "text": "Wait until the end of the shift to talk with her privately"}, {"id": "c", "text": "Ask another nurse to double-check her medications today"}, {"id": "d", "text": "Cover the colleague''s patients quietly to protect her job"}]'::jsonb, '["a"]', 'Reporting a colleague who is practicing unsafely is part of nonmaleficence, the duty to avoid causing harm. Covering for her, waiting, or adding a double-check still leaves an impaired nurse caring for patients.', false),
  ('ethics', 18, 'A patient with schizophrenia in the emergency department reports chest pain. A staff member says, "He''s psych; it''s probably anxiety," and moves him to the end of the queue without an assessment. Which response by the nurse BEST reflects justice?', '[{"id": "a", "text": "\"His psychiatric history makes anxiety the most likely cause.\""}, {"id": "b", "text": "\"We should respect his autonomy and wait until he asks again.\""}, {"id": "c", "text": "\"He deserves the same quality of care as other patients.\""}, {"id": "d", "text": "\"Let''s ask his psychiatrist before we assess the chest pain.\""}]'::jsonb, '["c"]', 'Justice in mental health means ensuring patients with mental illness receive the same quality of care as those with physical illness. Attributing the pain to his diagnosis or delaying assessment treats him unequally.', false),
  ('ethics', 19, 'A nurse is preparing an in-service on justice in mental health nursing and wants examples that involve patients on the unit. Which examples should the nurse include? Select all that apply.', '[{"id": "a", "text": "Providing equal care regardless of race or religion"}, {"id": "b", "text": "Keeping a promise to meet a patient at 1400"}, {"id": "c", "text": "Fighting stigma in healthcare settings"}, {"id": "d", "text": "Telling a patient the truth about side effects"}, {"id": "e", "text": "Advocating for underserved populations"}]'::jsonb, '["a", "c", "e"]', 'Justice includes providing equal care regardless of race, religion, and other characteristics (a), fighting stigma in healthcare settings (c), and advocating for underserved and marginalized populations (e). Keeping a promise (b) is fidelity, and telling the truth about side effects (d) is veracity.', true),
  ('ethics', 20, 'Two patients arrive in the emergency department at the same time: a well-known local politician with a sprained wrist and a homeless man with severe shortness of breath and chest pain. Which patient should the nurse see FIRST, and why?', '[{"id": "a", "text": "The homeless man, because the most critical is first"}, {"id": "b", "text": "The politician, because he arrived with full insurance"}, {"id": "c", "text": "The politician, because of his standing in the community"}, {"id": "d", "text": "Both at once, because justice requires equal time"}]'::jsonb, '["a"]', 'Justice in triage means the most critical patient is seen first, regardless of identity. Social standing or insurance status should not determine priority, and justice does not mean identical time for unequal needs.', false),
  ('ethics', 21, 'An inpatient psychiatric unit has one open bed, and a patient with acute psychosis is one of three people waiting in the emergency department. Which actions by the nurse manager reflect the recommended approach to this ethical conflict? Select all that apply.', '[{"id": "a", "text": "Triage based on clinical need"}, {"id": "b", "text": "Give the bed to the first patient who arrived"}, {"id": "c", "text": "Advocate for resource expansion"}, {"id": "d", "text": "Document the decisions made"}, {"id": "e", "text": "Give the bed to the patient with the best insurance"}]'::jsonb, '["a", "c", "d"]', 'For allocation of limited psychiatric beds, the approach is to triage based on clinical need (a), advocate for resource expansion (c), and document decisions (d). Arrival order (b) and insurance (e) do not reflect clinical need or fair, equal treatment.', true),
  ('ethics', 22, 'During a bed shortage, a nurse manager must decide which patient with acute psychosis, among several waiting, will be admitted to the last available psychiatric bed. Which ethical principles are MOST directly in tension?', '[{"id": "a", "text": "Veracity vs. Fidelity"}, {"id": "b", "text": "Autonomy vs. Veracity"}, {"id": "c", "text": "Fidelity vs. Nonmaleficence"}, {"id": "d", "text": "Justice vs. Beneficence"}]'::jsonb, '["d"]', 'Allocation of limited psychiatric beds places justice (fair distribution of resources) in tension with beneficence (acting in each patient''s best interest). The other pairs do not describe this resource conflict.', false),
  ('ethics', 23, 'A patient tells the nurse he plans to stab his roommate, whom he names, after discharge tomorrow. The team decides to break confidentiality. Which principles support breaking confidentiality in this situation? Select all that apply.', '[{"id": "a", "text": "Autonomy"}, {"id": "b", "text": "Justice"}, {"id": "c", "text": "Fidelity"}, {"id": "d", "text": "Nonmaleficence"}, {"id": "e", "text": "Veracity"}]'::jsonb, '["b", "d"]', 'When a patient discloses a plan to harm someone, confidentiality is in tension with justice (b) and nonmaleficence (d), which support the Tarasoff duty to warn. Fidelity (c) includes maintaining confidentiality and argues against disclosure, while autonomy (a) and veracity (e) are not the principles in tension here.', true),
  ('ethics', 24, 'A nursing student asks, "How can it be ethical to hospitalize someone against her will when we''re supposed to respect autonomy?" The patient being discussed is threatening to kill herself. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Autonomy does not apply to patients who have a psychiatric diagnosis.\""}, {"id": "b", "text": "\"It''s legal and ethical when she is a danger to self or others.\""}, {"id": "c", "text": "\"Beneficence always outweighs autonomy in mental health settings.\""}, {"id": "d", "text": "\"It is ethical whenever the family agrees that admission is needed.\""}]'::jsonb, '["b"]', 'Involuntary hospitalization is legal and ethical if the patient is a danger to self or others. Patients with mental illness keep their autonomy, beneficence does not automatically override it, and family agreement is not the standard.', false),
  ('ethics', 25, 'A patient with mania who has not slept in 4 days and is threatening others is being hospitalized against his will. Which ethical principles are in tension in this decision? Select all that apply.', '[{"id": "a", "text": "Autonomy"}, {"id": "b", "text": "Veracity"}, {"id": "c", "text": "Beneficence"}, {"id": "d", "text": "Fidelity"}, {"id": "e", "text": "Nonmaleficence"}]'::jsonb, '["a", "c", "e"]', 'Involuntary hospitalization places autonomy (a) in tension with beneficence (c) and nonmaleficence (e). Veracity (b) and fidelity (d) concern honesty and keeping promises and are not the principles in this conflict.', true),
  ('ethics', 26, 'A nurse is troubled because a competent patient with anorexia is refusing a feeding plan that the team believes is lifesaving. The nurse decides to use a structured ethical decision-making process. Which step should the nurse take FIRST?', '[{"id": "a", "text": "Gather the patient''s values and the clinical facts"}, {"id": "b", "text": "Consult the ethics committee for a recommendation"}, {"id": "c", "text": "Make a decision guided by the patient''s best interest"}, {"id": "d", "text": "Identify the dilemma and the principles in conflict"}]'::jsonb, '["d"]', 'The first step of the ethical decision-making process is to identify the ethical dilemma and which principles are in conflict. Gathering information comes second, and consulting resources and making a decision come later.', false),
  ('ethics', 27, 'A nurse working through an ethical dilemma has identified the principles in conflict, gathered the clinical facts and the patient''s values, and listed the patient, family, team, and society as stakeholders. Which step should the nurse take NEXT?', '[{"id": "a", "text": "Consider all the possible courses of action"}, {"id": "b", "text": "Evaluate whether the outcome matched the principles"}, {"id": "c", "text": "Make and implement a decision for the patient"}, {"id": "d", "text": "Identify the ethical dilemma that is involved"}]'::jsonb, '["a"]', 'After identifying the dilemma, gathering information, and identifying stakeholders, the next step is to consider all options, the possible courses of action. Making a decision and evaluating the outcome come later, and identifying the dilemma is already done.', false),
  ('ethics', 28, 'A nurse has listed the possible courses of action for a patient whose family disagrees with his treatment choice. Which steps of the ethical decision-making process remain to be completed? Select all that apply.', '[{"id": "a", "text": "Identify the stakeholders involved"}, {"id": "b", "text": "Apply ethical principles to each option"}, {"id": "c", "text": "Gather information on legal requirements"}, {"id": "d", "text": "Consult resources such as a chaplain"}, {"id": "e", "text": "Evaluate the outcome"}]'::jsonb, '["b", "d", "e"]', 'After considering all options, the nurse applies ethical principles to each option (b), consults resources such as an ethics committee or chaplain (d), makes and implements a decision, and evaluates the outcome (e). Identifying stakeholders (a) and gathering information such as legal requirements (c) happen before options are considered.', true),
  ('ethics', 29, 'Two weeks after the team honored a competent patient''s refusal of ECT, the nurse meets with colleagues to review whether the action aligned with ethical principles and what can be learned. Which step of the ethical decision-making process BEST describes this meeting?', '[{"id": "a", "text": "Evaluate the outcome"}, {"id": "b", "text": "Gather information"}, {"id": "c", "text": "Apply ethical principles"}, {"id": "d", "text": "Consult resources"}]'::jsonb, '["a"]', 'Evaluating the outcome asks whether the action aligned with ethical principles and what can be learned; it is the final step. Gathering information and applying principles occur before a decision is made.', false),
  ('ethics', 30, 'A nurse cannot resolve an ethical dilemma involving a dying patient''s spiritual beliefs, a family conflict, and questions about the law. Which resources should the nurse consult? Select all that apply.', '[{"id": "a", "text": "Ethics committee"}, {"id": "b", "text": "Chaplain"}, {"id": "c", "text": "The patient''s employer"}, {"id": "d", "text": "Social worker"}, {"id": "e", "text": "Legal counsel"}]'::jsonb, '["a", "b", "d", "e"]', 'Resources for an ethical dilemma include the ethics committee (a), chaplain (b), social worker (d), and legal counsel (e). The patient''s employer (c) is not an ethical resource and is not a stakeholder listed in the process.', true),
  ('ethics', 31, 'A nurse on a geropsychiatric unit is considering requesting an ethics committee consultation. Which patient situation is the MOST appropriate reason for this request?', '[{"id": "a", "text": "A patient refuses to attend the morning group session"}, {"id": "b", "text": "A patient asks to change the time of a daily shower"}, {"id": "c", "text": "A patient declines one dose of a PRN sleep medication"}, {"id": "d", "text": "Family members disagree about a surrogate''s decision"}]'::jsonb, '["d"]', 'The ethics committee is a resource for complex dilemmas, not everyday decisions; a family dispute over a surrogate decision-maker''s choice is a complex dilemma. Skipping a group, rescheduling a shower, or declining one PRN dose are everyday decisions.', false),
  ('ethics', 32, 'During report, a nurse says about a newly admitted patient who has been living on the street, "I''m not wasting my time on him; he''ll just be back next month." Which response by the charge nurse BEST reflects the ANA Code of Ethics Provision 1?', '[{"id": "a", "text": "\"Every patient gets compassion and respect, whatever his background.\""}, {"id": "b", "text": "\"You''re right; let''s focus our time on patients who will benefit more.\""}, {"id": "c", "text": "\"Let''s assign him to the newest nurse so the rest of us can manage.\""}, {"id": "d", "text": "\"His autonomy means we should wait until he asks us for our help.\""}]'::jsonb, '["a"]', 'ANA Code of Ethics Provision 1 states that the nurse practices with compassion and respect for every individual regardless of background. Rationing care by expected benefit or passing him to a new nurse contradicts this provision.', false),
  ('ethics', 33, 'A patient with severe depression is scheduled for ECT. When the nurse brings the consent form, the patient says, "The doctor said it''s just a quick shock; I don''t know anything else about it." Which action by the nurse is BEST?', '[{"id": "a", "text": "Witness the signature, since the provider has already explained the procedure"}, {"id": "b", "text": "Notify the provider that the patient needs full information first"}, {"id": "c", "text": "Explain that ECT is completely safe so the patient can go ahead and sign"}, {"id": "d", "text": "Have the family co-sign the form, since the patient seems unsure about it"}]'::jsonb, '["b"]', 'Informed consent for ECT requires that the patient receive full information before agreeing to treatment, which is part of autonomy. Witnessing a signature without understanding, offering false assurance, or using a family co-signature does not meet this standard.', false),
  ('ethics', 34, 'A competent patient with alcohol use disorder chooses weekly outpatient counseling instead of the 28-day residential program the nurse believes would work better. Which action by the nurse BEST reflects ethical practice?', '[{"id": "a", "text": "Delay discharge until the patient agrees to the residential program"}, {"id": "b", "text": "Ask the family to persuade the patient to choose residential care"}, {"id": "c", "text": "Respect the patient''s choice, even though the nurse disagrees"}, {"id": "d", "text": "Tell the patient that outpatient counseling will not be effective"}]'::jsonb, '["c"]', 'Autonomy is the patient''s right to make health care decisions even if the nurse or provider disagrees, and when autonomy conflicts with beneficence in a competent patient, informed autonomy is supported. Delaying discharge, pressuring through family, or discouraging the choice overrides it.', false),
  ('ethics', 35, 'A nurse is mentoring a student who confuses beneficence with nonmaleficence while they care for a patient with major depression. Which nurse action is the BEST example of nonmaleficence rather than beneficence?', '[{"id": "a", "text": "Administering pain medication to relieve a patient''s suffering"}, {"id": "b", "text": "Recommending a therapist for a patient who needs support"}, {"id": "c", "text": "Weighing the risks vs. benefits of a treatment for a patient"}, {"id": "d", "text": "Providing education so a patient can make informed decisions"}]'::jsonb, '["c"]', 'Weighing the risks vs. benefits of a treatment is an example of nonmaleficence, the duty to avoid harm. Administering pain medication, recommending a therapist, and providing education are examples of beneficence, actively doing good.', false),
  ('ethics', 36, 'A nurse is reviewing ethical principles with nursing students on a psychiatric unit. Which student statements about caring for patients indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "\"Advance directives guide care even when a patient is unconscious.\""}, {"id": "b", "text": "\"Beneficence and nonmaleficence are the same principle.\""}, {"id": "c", "text": "\"If a competent patient''s autonomy conflicts with beneficence, I support autonomy.\""}, {"id": "d", "text": "\"An ethics committee should handle everyday decisions.\""}, {"id": "e", "text": "\"Veracity means telling patients the truth.\""}]'::jsonb, '["b", "d"]', 'Beneficence (do good) and nonmaleficence (do no harm) are different principles (b), and the ethics committee is a resource for complex dilemmas, not everyday decisions (d). Advance directives guiding care when unconscious (a), supporting informed autonomy in a competent patient (c), and veracity as telling the truth (e) are correct.', true),
  ('ethics', 37, 'A patient with catatonic schizophrenia is mute and immobile and has not bathed in days. During rounds, the team overlooks reddened skin over his sacrum. Which nurse action BEST demonstrates beneficence?', '[{"id": "a", "text": "Waiting until the patient can request skin care for himself"}, {"id": "b", "text": "Advocating for a patient who cannot advocate for himself"}, {"id": "c", "text": "Documenting the finding and reporting it at the next rounds"}, {"id": "d", "text": "Respecting the patient''s silence as a refusal of all care"}]'::jsonb, '["b"]', 'Beneficence includes advocating for the patient when they cannot advocate for themselves. Waiting for a mute patient to ask, delaying until the next rounds, or treating silence as refusal does not actively promote his well-being.', false),
  ('ethics', 38, 'A 19-year-old patient newly diagnosed with schizophrenia asks the nurse, "Is this something that will go away?" The provider has already explained that it is a chronic illness. Which approach by the nurse BEST applies veracity?', '[{"id": "a", "text": "Avoid the question for now to protect the patient''s hope"}, {"id": "b", "text": "Say it will likely go away so he stays engaged in treatment"}, {"id": "c", "text": "Give the truth in a compassionate and thoughtful way"}, {"id": "d", "text": "State the facts quickly and move on to the next topic"}]'::jsonb, '["c"]', 'Honesty is foundational to the therapeutic relationship, and delivery of truth should be compassionate and thoughtful. Avoiding the question or giving false hope violates veracity, and a blunt delivery ignores how truth should be shared.', false),
  ('ethics', 39, 'A patient preparing for discharge from an inpatient unit tells the nurse she feels lost without the daily groups that helped her. Each option below is an appropriate nursing action. Which action BEST demonstrates beneficence?', '[{"id": "a", "text": "Telling her honestly that groups end at the time of discharge"}, {"id": "b", "text": "Ensuring her discharge plan matches the care others receive"}, {"id": "c", "text": "Keeping the promise to call her at home one week from today"}, {"id": "d", "text": "Recommending a therapist for ongoing support after discharge"}]'::jsonb, '["d"]', 'Recommending a therapist for a patient who needs support is the mental health application of beneficence. Honest information reflects veracity, equal care reflects justice, and keeping a promise reflects fidelity.', false),
  ('ethics', 40, 'A patient tells the nurse about a painful past event and asks, "This stays private, right?" The nurse explains it will be shared only with the treatment team. Later, a nurse from another unit asks what the patient talked about. Which response BEST demonstrates fidelity?', '[{"id": "a", "text": "Share a brief summary, since the other nurse is also staff"}, {"id": "b", "text": "Decline to share, honoring the commitment of privacy"}, {"id": "c", "text": "Share it, because veracity requires honest answers"}, {"id": "d", "text": "Ask the patient whether the story can be shared with her"}]'::jsonb, '["b"]', 'Fidelity includes maintaining confidentiality, honoring the commitment of privacy made to the patient. Sharing with staff outside the treatment team breaks that promise, and veracity does not require disclosing a patient''s private information.', false),
  ('ethics', 41, 'A patient with moderate dementia refuses all morning care, and the nurse determines that the patient lacks decisional capacity. Which sources should guide the care decision NEXT? Select all that apply.', '[{"id": "a", "text": "The nurse''s personal preference"}, {"id": "b", "text": "The patient''s advance directive"}, {"id": "c", "text": "The patient''s current refusal alone"}, {"id": "d", "text": "A surrogate decision-maker"}, {"id": "e", "text": "The unit''s staffing level that day"}]'::jsonb, '["b", "d"]', 'When a patient with dementia lacks decisional capacity, the nurse uses advance directives (b) or a surrogate decision-maker (d). The nurse''s preference (a) and staffing (e) are not valid bases, and a refusal alone (c) does not govern care once capacity is lacking.', true),
  ('ethics', 42, 'A nurse on an inpatient mental health unit is asked to give examples of beneficence from the past shift. Which actions involving patients should the nurse identify? Select all that apply.', '[{"id": "a", "text": "Verifying the six rights before giving medication"}, {"id": "b", "text": "Administering pain medication to relieve suffering"}, {"id": "c", "text": "Keeping a promise to return in 30 minutes"}, {"id": "d", "text": "Avoiding unnecessary or harmful interventions"}, {"id": "e", "text": "Providing education so a patient can make decisions"}]'::jsonb, '["b", "e"]', 'Beneficence, actively doing good, includes administering pain medication to relieve suffering (b) and providing education so the patient can make informed decisions (e). Verifying the six rights (a) and avoiding unnecessary or harmful interventions (d) are nonmaleficence, and keeping a promise (c) is fidelity.', true),
  ('ethics', 43, 'A nurse sitting with a patient on 1:1 suicide observation is told by a colleague, "Go chart; he''s asleep, and I''ll glance in now and then." The nurse stays with the patient. Which ethical principle is the nurse MOST directly upholding?', '[{"id": "a", "text": "Justice"}, {"id": "b", "text": "Veracity"}, {"id": "c", "text": "Autonomy"}, {"id": "d", "text": "Nonmaleficence"}]'::jsonb, '["d"]', 'Not leaving a suicidal patient alone is a mental health application of nonmaleficence, the duty to avoid harm. Justice, veracity, and autonomy concern fairness, honesty, and self-determination.', false),
  ('ethics', 44, 'A colleague suggests telling a patient who has refused his new antidepressant that the pill is "just a vitamin" so that he will take it. Which response by the nurse BEST reflects veracity?', '[{"id": "a", "text": "\"That could work, since it is in his best interest to take it.\""}, {"id": "b", "text": "\"Let''s mix it in his juice instead, so we don''t have to lie to him.\""}, {"id": "c", "text": "\"Lying destroys trust; he needs accurate information.\""}, {"id": "d", "text": "\"We can tell him the truth after he has taken it for a week.\""}]'::jsonb, '["c"]', 'Veracity requires honest, complete, and accurate information, and lying or withholding truth destroys trust. Hiding the drug in juice is still deception, and delaying the truth is withholding it.', false),
  ('ethics', 45, 'A patient with depression who is considering ECT tells the nurse he is struggling because he fears the treatment conflicts with his religious beliefs. The team has already given him full information. Which resource is MOST appropriate for the nurse to consult?', '[{"id": "a", "text": "Legal counsel"}, {"id": "b", "text": "The chaplain"}, {"id": "c", "text": "The ethics committee"}, {"id": "d", "text": "A social worker"}]'::jsonb, '["b"]', 'The chaplain is one of the resources listed for ethical decision-making and is the best match for a patient''s religious concerns. Legal counsel addresses legal questions, and the ethics committee is reserved for complex dilemmas rather than an individual spiritual concern.', false),
  ('ethics', 46, 'The charge nurse observes how staff interact with each patient on a psychiatric unit during the evening shift. Which staff actions require follow-up because they conflict with an ethical principle? Select all that apply.', '[{"id": "a", "text": "Respecting a competent patient''s refusal of medication"}, {"id": "b", "text": "Telling a patient with a poor prognosis \"everything will be fine\""}, {"id": "c", "text": "Following through on a promise to return at 1500"}, {"id": "d", "text": "Providing the same quality of care to a patient with psychosis"}, {"id": "e", "text": "Using restraints first for a patient who is pacing"}]'::jsonb, '["b", "e"]', 'Saying "everything will be fine" when it may not be gives false hope and violates veracity (b), and restraints should be a last resort because they cause harm, so using them first violates nonmaleficence (e). Respecting a competent refusal (a), keeping a promise (c), and equal quality of care (d) uphold autonomy, fidelity, and justice.', true),
  ('ethics', 47, 'A 78-year-old patient with mild dementia refuses an influenza vaccine. The provider documents that the patient has decisional capacity for this decision. The patient''s daughter asks the nurse to give the vaccine anyway. Which action by the nurse is BEST?', '[{"id": "a", "text": "Give the vaccine, since the daughter is the surrogate decision-maker"}, {"id": "b", "text": "Give the vaccine, since beneficence outweighs autonomy in dementia"}, {"id": "c", "text": "Respect the refusal, since the patient has decisional capacity"}, {"id": "d", "text": "Ask the ethics committee to decide whether the vaccine can be given"}]'::jsonb, '["c"]', 'A surrogate decision-maker or advance directive is used only if decisional capacity is lacking; this patient has capacity, so her refusal is respected. A diagnosis of dementia alone does not let beneficence override a competent choice.', false),
  ('ethics', 48, 'In the staff break room, a nurse jokes that a patient with bipolar disorder who is often readmitted is a "frequent flyer" who does not deserve a private room like the medical patients. Which response BEST reflects the principle of justice?', '[{"id": "a", "text": "\"It''s just a joke, and the patient will never hear about it.\""}, {"id": "b", "text": "\"Room assignments are based on whoever arrives first each day.\""}, {"id": "c", "text": "\"Comments like that add to the stigma we should be fighting.\""}, {"id": "d", "text": "\"You''re right that repeat patients should get fewer resources.\""}]'::jsonb, '["c"]', 'Justice in mental health includes fighting stigma in healthcare settings and giving patients with mental illness the same quality of care as those with physical illness. Dismissing the comment or agreeing with fewer resources accepts unequal treatment.', false),
  ('ethics', 49, 'A nurse has identified the ethical dilemma for a competent patient with schizophrenia who refuses a recommended change in medication; the principles in conflict are autonomy and beneficence. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Make and implement a decision guided by the patient''s best interest"}, {"id": "b", "text": "Collect the patient''s values, clinical facts, and legal requirements"}, {"id": "c", "text": "Evaluate whether the action aligned with the ethical principles"}, {"id": "d", "text": "Consult the ethics committee about what the final decision should be"}]'::jsonb, '["b"]', 'After identifying the dilemma, the next step is to gather information: patient values, clinical facts, legal requirements, and institutional policies. Consulting resources, deciding, and evaluating the outcome come later in the process.', false),
  ('ethics', 50, 'A nurse promised a patient she would raise his request for a medication change at team rounds. At rounds, the team is short on time and visibly annoyed, but the nurse presents the request anyway. Which principle is the nurse MOST directly demonstrating?', '[{"id": "a", "text": "Veracity, by giving honest information"}, {"id": "b", "text": "Justice, by treating all patients equally"}, {"id": "c", "text": "Fidelity, by keeping a commitment"}, {"id": "d", "text": "Autonomy, by letting the patient decide"}]'::jsonb, '["c"]', 'Fidelity is keeping promises and advocating for patients even when it is inconvenient or unpopular. The nurse is following through on a commitment, not mainly giving information, distributing care, or deferring a decision to the patient.', false),
  ('defense', 1, 'A client who learned yesterday that a biopsy confirmed cancer tells the nurse, "I don''t believe the test results — the lab must have made a mistake," and changes the subject whenever treatment is mentioned. Which nursing action is BEST at this time?', '[{"id": "a", "text": "Show the client the written pathology report so the diagnosis is faced today"}, {"id": "b", "text": "Tell the client that refusing to believe the results is an unhealthy defense"}, {"id": "c", "text": "Acknowledge what the client is expressing and gently provide reality over time"}, {"id": "d", "text": "Ask the provider to repeat the biopsy so the client has a second set of results"}]'::jsonb, '["c"]', 'The client is using denial, and the nurse should not directly confront it; instead the nurse acknowledges what the client is expressing and gently provides reality over time. Showing the report or labeling the defense as unhealthy are forms of direct confrontation.', false),
  ('defense', 2, 'During morning rounds the physician cancels a client''s discharge, and the client says nothing to the physician. An hour later the client shouts at the nurse that the breakfast tray was cold and the nurse is useless. This behavior MOST likely reflects which defense mechanism?', '[{"id": "a", "text": "Projection"}, {"id": "b", "text": "Displacement"}, {"id": "c", "text": "Rationalization"}, {"id": "d", "text": "Regression"}]'::jsonb, '["b"]', 'Displacement is redirecting emotional reactions from the real source (the physician) to a safer, substitute target (the nurse). Projection would involve attributing the client''s own feelings to the nurse, such as claiming the nurse is angry at the client.', false),
  ('defense', 3, 'A nurse on a consultation service documents statements made by several clients with substance use or newly diagnosed cancer. Which client statements indicate the use of denial? Select all that apply.', '[{"id": "a", "text": "\"I can stop whenever I want — I don''t have a problem.\""}, {"id": "b", "text": "\"I drink because it helps me sleep — it''s medicinal.\""}, {"id": "c", "text": "\"Those scan results must belong to someone else.\""}, {"id": "d", "text": "\"I can tell you don''t like me and are trying to hurt me.\""}, {"id": "e", "text": "\"I don''t believe the results, so I won''t need treatment.\""}]'::jsonb, '["a", "c", "e"]', 'Denial is refusing to acknowledge an unpleasant reality: insisting the client can stop whenever wanted (a), claiming the results belong to someone else (c), and not believing the results (e) all refuse the reality. Option b is rationalization — a logical-sounding excuse for drinking. Option d is projection — attributing the client''s own feelings to the nurse.', true),
  ('defense', 4, 'A client with borderline personality disorder tells the day nurse, "You''re the best nurse ever — the evening nurse is terrible and hates me," and asks the day nurse to tell the evening nurse to stop picking on her. Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "Maintain a consistent, unified team approach and do not take sides"}, {"id": "b", "text": "Agree to speak with the evening nurse about how the client is treated"}, {"id": "c", "text": "Request to be assigned to this client every shift to protect rapport"}, {"id": "d", "text": "Tell the client that the evening nurse is experienced and she is wrong"}]'::jsonb, '["a"]', 'This is splitting; the nurse should use a consistent, unified team approach and not take sides. Agreeing to speak to the evening nurse or becoming the client''s only nurse validates the splitting behavior, which the nurse must avoid.', false),
  ('defense', 5, 'A client admitted for alcohol use disorder acknowledges drinking every night and says, "Anyone with my boss would need a few drinks after work — it''s the only way to unwind." Which interpretation of the client''s statement is MOST accurate?', '[{"id": "a", "text": "Denial, because the client refuses to acknowledge the drinking"}, {"id": "b", "text": "Projection, because the client attributes own feelings to the boss"}, {"id": "c", "text": "Displacement, because the client redirects anger from the boss"}, {"id": "d", "text": "Rationalization, because these are excuses for the behavior"}]'::jsonb, '["d"]', 'The client admits the drinking but offers a logical-sounding, socially acceptable explanation for it, which is rationalization (making excuses). Denial would mean refusing to acknowledge the drinking at all, which this client does not do.', false),
  ('defense', 6, 'A client with borderline personality disorder has been telling some staff they are "wonderful" and others they are "terrible," and staff members have begun arguing with each other about the client''s privileges. Which actions should the nurse include in the plan of care? Select all that apply.', '[{"id": "a", "text": "Use a consistent, unified team approach on every shift"}, {"id": "b", "text": "Do not take sides when the client criticizes a staff member"}, {"id": "c", "text": "Allow the client to choose which staff members provide care"}, {"id": "d", "text": "Hold firm, non-punitive limits on the client''s requests"}, {"id": "e", "text": "Avoid validating splitting behavior by being consistent"}]'::jsonb, '["a", "b", "d", "e"]', 'Splitting calls for a consistent, unified team approach (a), not taking sides (b), firm, non-punitive limits (d), and avoiding validation of splitting by being consistent (e). Letting the client choose staff (c) rewards the all-good/all-bad view of staff and validates the splitting.', true),
  ('defense', 7, 'A client who has repeatedly made hostile remarks about her roommate tells the nurse, "My roommate can''t stand me — she''s just waiting for a chance to hurt me." Staff have observed the roommate being friendly toward the client. Which defense mechanism is the client MOST likely using?', '[{"id": "a", "text": "Displacement"}, {"id": "b", "text": "Reaction formation"}, {"id": "c", "text": "Projection"}, {"id": "d", "text": "Splitting"}]'::jsonb, '["c"]', 'The client attributes her own hostile feelings toward the roommate to the roommate, which is projection. Displacement would redirect feelings from the real source to a safer target, but here the client''s own feeling is placed onto another person.', false),
  ('defense', 8, 'After a difficult code on a patient, a nurse tells a colleague, "I''m going to set this aside and not think about it until I''m off shift, and then I''ll talk it through with my manager." Which interpretation of the nurse''s coping is MOST accurate?', '[{"id": "a", "text": "Suppression, a mature mechanism that is used consciously"}, {"id": "b", "text": "Repression, an intermediate mechanism that is involuntary"}, {"id": "c", "text": "Denial, an immature mechanism refusing to accept reality"}, {"id": "d", "text": "Dissociation, a disconnection from feelings to escape distress"}]'::jsonb, '["a"]', 'Consciously choosing to delay thinking about a distressing event — "I''ll deal with it later" — is suppression, a mature mechanism and the only one used consciously. Repression is involuntary, so the nurse''s deliberate decision rules it out.', false),
  ('defense', 9, 'The nurse is evaluating coping in clients on a mental health unit. Which client behaviors reflect a mature (healthy) defense mechanism? Select all that apply.', '[{"id": "a", "text": "A grieving client becomes demanding and child-like"}, {"id": "b", "text": "A client consciously decides to deal with a worry later"}, {"id": "c", "text": "A client accuses her spouse of feelings she herself has"}, {"id": "d", "text": "A widow channels her grief into writing and art"}, {"id": "e", "text": "A client sees one nurse as all good and another as all bad"}]'::jsonb, '["b", "d"]', 'Suppression (b) and sublimation (d) are mature mechanisms that manage stress without significantly distorting reality. Becoming demanding and child-like (a) is regression, attributing one''s own feelings to a spouse (c) is projection, and all-good/all-bad views (e) are splitting — all immature.', true),
  ('defense', 10, 'A client being treated for PTSD after a sexual assault several months ago reports intrusive anxiety but no memory of the assault itself, stating, "I''ve tried to remember, but there''s just nothing there." Which defense mechanism BEST explains the absent memory?', '[{"id": "a", "text": "Suppression"}, {"id": "b", "text": "Repression"}, {"id": "c", "text": "Denial"}, {"id": "d", "text": "Intellectualization"}]'::jsonb, '["b"]', 'Repression involuntarily pushes threatening memories out of conscious awareness, as in PTSD with amnesia about the incident. Suppression is a conscious choice to delay thinking about something, which does not fit a client who is trying but unable to remember.', false),
  ('defense', 11, 'The parent of a 5-year-old who has been toilet-trained for over a year reports that the child began wetting the bed shortly after a new baby sibling came home. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "The child is using undoing to cancel out angry thoughts about the baby"}, {"id": "b", "text": "The child is using projection by attributing feelings to the sibling"}, {"id": "c", "text": "The child is using repression to push memories of training away"}, {"id": "d", "text": "The child is reverting to earlier behavior under stress (regression)"}]'::jsonb, '["d"]', 'Regression is reverting to behaviors of an earlier developmental stage under stress, such as a toilet-trained 5-year-old bedwetting after a sibling''s birth. Undoing involves an action or ritual to cancel out a thought, not a return to earlier behavior.', false),
  ('defense', 12, 'A nursing student describes clients observed during a clinical day and names the defense mechanism each one used. Which of the student''s identifications are accurate? Select all that apply.', '[{"id": "a", "text": "Performs a ritual to cancel out an angry thought: undoing"}, {"id": "b", "text": "Has no memory of a traumatic assault: repression"}, {"id": "c", "text": "Acts excessively loving toward a resented sibling: projection"}, {"id": "d", "text": "Channels violent urges into a career as a surgeon: sublimation"}, {"id": "e", "text": "Excels academically after being poor at sports: rationalization"}]'::jsonb, '["a", "b", "d"]', 'A ritual to cancel out a thought is undoing (a), no memory of a trauma is repression (b), and channeling violent urges into surgery is sublimation (d). Acting excessively loving toward a resented sibling is reaction formation, not projection (c). Excelling academically to make up for poor sports ability is compensation, not rationalization (e).', true),
  ('defense', 13, 'A client tells the nurse, "Every time I have an angry thought about my sister, I feel so guilty that I go out and buy her something expensive." The nurse recognizes the gift-buying as MOST consistent with which defense mechanism?', '[{"id": "a", "text": "Reaction formation"}, {"id": "b", "text": "Sublimation"}, {"id": "c", "text": "Undoing"}, {"id": "d", "text": "Compensation"}]'::jsonb, '["c"]', 'Undoing is performing an action to cancel out an unacceptable thought, such as buying an expensive gift after an angry thought. Reaction formation would be a persistent expression of the opposite feeling (acting excessively loving), not an act triggered to cancel a specific thought.', false),
  ('defense', 14, 'A client newly diagnosed with a terminal illness spends each visit discussing survival statistics, treatment protocols, and research papers but has never expressed any emotion about the diagnosis. Which nursing action is BEST?', '[{"id": "a", "text": "Explore the underlying anxiety driving the client''s focus on data"}, {"id": "b", "text": "Provide additional research articles to support the client''s coping"}, {"id": "c", "text": "Point out to the client that discussing data is a way to avoid feelings"}, {"id": "d", "text": "Insist that the client express feelings before treatment is discussed"}]'::jsonb, '["a"]', 'The client is intellectualizing; the nurse should explore the underlying anxiety driving the defense to address the root cause. Supplying more research articles reinforces an unhealthy mechanism, and pointing out or forcing feelings does not address the underlying anxiety.', false),
  ('defense', 15, 'A nurse is mentoring a new graduate who is frustrated with a client who keeps making excuses for missing group therapy. Which principles should the nurse reinforce about responding to a client''s defense mechanisms? Select all that apply.', '[{"id": "a", "text": "Point out each excuse so the client stops the behavior quickly"}, {"id": "b", "text": "Be non-judgmental, because all people use defense mechanisms"}, {"id": "c", "text": "Explore the underlying anxiety that is driving the defense"}, {"id": "d", "text": "Directly confront denial so the client accepts reality sooner"}, {"id": "e", "text": "Recognize when a mechanism protects the client temporarily"}]'::jsonb, '["b", "c", "e"]', 'The nurse should be non-judgmental because all people use defense mechanisms (b), explore the underlying anxiety driving the defense (c), and recognize when a mechanism is protecting the client temporarily versus preventing treatment (e). Pointing out each excuse (a) is judgmental and does not address the root cause, and denial should NOT be directly confronted (d).', true),
  ('defense', 16, 'An adolescent client with a physical disability who could not join school sports tells the nurse about training intensively to become a Paralympic swimmer, adding, "I want to be the best at something." Which defense mechanism is the client MOST likely demonstrating?', '[{"id": "a", "text": "Sublimation"}, {"id": "b", "text": "Compensation"}, {"id": "c", "text": "Identification"}, {"id": "d", "text": "Reaction formation"}]'::jsonb, '["b"]', 'Compensation is overachieving in one area to make up for a real or perceived deficit, such as a person with a physical disability becoming a Paralympic champion. Sublimation channels unacceptable impulses into acceptable activities; this adolescent is making up for a limitation, not redirecting an unacceptable impulse.', false),
  ('defense', 17, 'During a panic attack, a client with a history of trauma tells the nurse, "This doesn''t feel real — it''s like I''m watching myself from outside my body." Which defense mechanism does this statement MOST likely represent?', '[{"id": "a", "text": "Repression"}, {"id": "b", "text": "Denial"}, {"id": "c", "text": "Intellectualization"}, {"id": "d", "text": "Dissociation"}]'::jsonb, '["d"]', 'Dissociation is disconnecting from thoughts, feelings, identity, or surroundings to escape distress, such as a trauma survivor feeling detached from the body during a panic attack. Repression removes memories from awareness; the client here is aware but feels detached.', false),
  ('defense', 18, 'The nurse reviews the coping of several clients. Which client situations indicate that a defense mechanism is preventing necessary treatment and requires follow-up? Select all that apply.', '[{"id": "a", "text": "A client uses humor with visitors while awaiting surgery"}, {"id": "b", "text": "A client who says, \"I can stop whenever I want,\" refuses detox"}, {"id": "c", "text": "A client with aggressive tendencies has taken up boxing"}, {"id": "d", "text": "A client cancels cancer treatment, insisting the lab made a mistake"}, {"id": "e", "text": "A widow channels her grief into writing poetry each evening"}]'::jsonb, '["b", "d"]', 'Denial in substance abuse (b) and denial of a cancer diagnosis (d) are keeping these clients from necessary treatment, so they require follow-up. Humor (a) and sublimation through boxing (c) or writing (e) are mature mechanisms that help manage stress without distorting reality.', true),
  ('defense', 19, 'An adult client with depression tells the nurse, "When I make even a small mistake, I hear my father''s critical voice telling me I''m useless — and now I say it to myself." Which defense mechanism does the nurse MOST likely identify?', '[{"id": "a", "text": "Identification"}, {"id": "b", "text": "Projection"}, {"id": "c", "text": "Introjection"}, {"id": "d", "text": "Displacement"}]'::jsonb, '["c"]', 'Introjection is internalizing another person''s values or attitudes as part of the self, as when a child internalizes a parent''s critical voice and becomes self-critical as an adult. Projection moves one''s own feelings outward onto someone else, the opposite direction.', false),
  ('defense', 20, 'A client who was held hostage for several weeks now dresses and speaks like the captor and defends the captor to police investigators. The nurse recognizes this response as MOST consistent with which defense mechanism?', '[{"id": "a", "text": "Identification"}, {"id": "b", "text": "Displacement"}, {"id": "c", "text": "Reaction formation"}, {"id": "d", "text": "Rationalization"}]'::jsonb, '["a"]', 'Identification is modeling oneself after another person, including someone who caused harm, as in Stockholm syndrome, where a hostage identifies with the captor. Reaction formation expresses the opposite of one''s feelings; modeling oneself on the captor is identification.', false),
  ('defense', 21, 'The nurse reviews documented statements from a client who has been openly angry and resentful toward the staff for several days. Which statements by the client indicate projection? Select all that apply.', '[{"id": "a", "text": "\"You''re the best nurse ever, but the others are terrible.\""}, {"id": "b", "text": "\"I''ll deal with how I feel about my diagnosis later.\""}, {"id": "c", "text": "\"I can tell you don''t like me and are trying to hurt me.\""}, {"id": "d", "text": "\"I yelled at you because the doctor made me so angry.\""}, {"id": "e", "text": "\"Everyone on this unit hates me — I see it in their faces.\""}]'::jsonb, '["c", "e"]', 'A client who feels anger and resentment toward staff but says the nurse dislikes them (c) or that everyone hates them (e) is attributing their own feelings to others — projection. Option a is all-good/all-bad splitting, b is suppression (consciously delaying), and d describes displacement of anger from the doctor to the nurse.', true),
  ('defense', 22, 'A client with borderline personality disorder tells the evening nurse, "The day nurse said I could skip group and stay in my room — you''re the worst nurse here." The team has agreed that the client attends every group. Which response is BEST?', '[{"id": "a", "text": "Allow the client to skip group this once to avoid escalating the conflict"}, {"id": "b", "text": "Remove the client''s phone privileges for speaking disrespectfully to staff"}, {"id": "c", "text": "Call the day nurse in front of the client to determine who is correct"}, {"id": "d", "text": "Hold firm, non-punitive limits with a unified team approach"}]'::jsonb, '["d"]', 'For splitting, the nurse holds firm, non-punitive limits within a consistent, unified team approach. Removing privileges is punitive, and letting the client skip group or calling the day nurse to settle who is right validates the splitting.', false),
  ('defense', 23, 'A client tells a new nurse, "I''m not going to think about my divorce until after I''m discharged — right now I need to focus on getting well." Which statement by the new nurse about this client indicates a need for further teaching?', '[{"id": "a", "text": "\"The client is consciously choosing to delay a distressing thought.\""}, {"id": "b", "text": "\"The client is repressing the divorce into the unconscious.\""}, {"id": "c", "text": "\"This is suppression, which is considered a mature defense mechanism.\""}, {"id": "d", "text": "\"Unlike most defense mechanisms, this one is used with awareness.\""}]'::jsonb, '["b"]', 'The client is deliberately postponing a distressing thought, which is suppression — the only conscious defense mechanism. Repression is involuntary, so calling this repression shows the new nurse needs further teaching; the other statements are accurate.', false),
  ('defense', 24, 'The nurse is reviewing the coping of four clients on a medical-psychiatric unit. Which client''s use of a defense mechanism requires the nurse''s IMMEDIATE follow-up?', '[{"id": "a", "text": "A hospitalized adult who has become demanding and wants to be fed"}, {"id": "b", "text": "A client who makes jokes to ease tension while waiting for visiting hours"}, {"id": "c", "text": "A client with new cancer who says the lab made a mistake and refuses treatment"}, {"id": "d", "text": "A client who decides to put off thinking about a work problem until later"}]'::jsonb, '["c"]', 'Denial is preventing this client from receiving necessary treatment, so this client requires follow-up first. Regression during hospitalization is an immature mechanism but is not keeping the client from treatment, and humor and putting off a worry (suppression) are mature mechanisms that manage stress without distorting reality.', false),
  ('defense', 25, 'During a family session, a client says, "After my supervisor criticized me in front of everyone, I came home and started an argument with my wife over the dishes." Which defense mechanism does the nurse MOST likely identify?', '[{"id": "a", "text": "Displacement"}, {"id": "b", "text": "Projection"}, {"id": "c", "text": "Rationalization"}, {"id": "d", "text": "Passive aggression"}]'::jsonb, '["a"]', 'Displacement redirects emotional reactions from the real source (the supervisor) to a safer substitute target (the family), as when a person frustrated at work comes home and argues with family. Projection would attribute the client''s own feelings to the wife.', false),
  ('defense', 26, 'A client who has been angry at the nurse all morning says, "I can tell you don''t like me and you''re trying to hurt me." Which nursing response is MOST appropriate?', '[{"id": "a", "text": "Assure the client that the nurse likes the client and change the topic"}, {"id": "b", "text": "Remain non-judgmental and explore the anxiety behind the client''s feelings"}, {"id": "c", "text": "Ask the charge nurse to reassign the client to avoid further conflict"}, {"id": "d", "text": "Tell the client that these feelings are really the client''s own anger"}]'::jsonb, '["b"]', 'The client is projecting; the nurse should be non-judgmental and explore the underlying anxiety driving the defense mechanism. Telling the client the feelings are really their own confronts the defense without addressing the root cause, and reassurance or reassignment avoids it.', false),
  ('defense', 27, 'The nurse is caring for a client with a personality disorder who is under significant distress. Which observed behaviors reflect immature or primitive defense mechanisms? Select all that apply.', '[{"id": "a", "text": "Sees staff as either entirely good or entirely bad"}, {"id": "b", "text": "Consciously delays thinking about a stressful event"}, {"id": "c", "text": "Refuses to acknowledge an obvious unpleasant reality"}, {"id": "d", "text": "Attributes own hostile feelings to the nurse"}, {"id": "e", "text": "Becomes demanding and child-like when stressed"}]'::jsonb, '["a", "c", "d", "e"]', 'Splitting (a), denial (c), projection (d), and regression (e) are immature/primitive mechanisms associated with mental illness, personality disorders, and significant distress. Consciously delaying a stressful thought (b) is suppression, a mature mechanism.', true),
  ('defense', 28, 'A client who was fired for repeated lateness acknowledges being late often but tells the nurse, "They let me go because my manager was biased against me — it had nothing to do with my attendance." Which defense mechanism is MOST evident?', '[{"id": "a", "text": "Denial"}, {"id": "b", "text": "Projection"}, {"id": "c", "text": "Reaction formation"}, {"id": "d", "text": "Rationalization"}]'::jsonb, '["d"]', 'The client offers a logical-sounding excuse for the outcome while acknowledging the behavior, which is rationalization (like blaming a biased boss for a missed promotion). Denial would mean refusing to acknowledge the lateness, which the client does not do.', false),
  ('defense', 29, 'Two days after her husband''s sudden death, a client tells the nurse, "He''s just away on a business trip — he''ll be home on Sunday." Which nursing action is MOST therapeutic?', '[{"id": "a", "text": "State clearly that her husband has died so that grieving can begin"}, {"id": "b", "text": "Acknowledge her feelings and gently provide reality over coming days"}, {"id": "c", "text": "Agree that he will be home on Sunday to avoid upsetting her further"}, {"id": "d", "text": "Ask her why she is unable to accept that her husband has died"}]'::jsonb, '["b"]', 'The client is in denial during grief, which should not be directly confronted; the nurse acknowledges what she is expressing and gently provides reality over time. Stating the death bluntly is direct confrontation, and agreeing reinforces an unhealthy mechanism.', false),
  ('defense', 30, 'The nurse is assessing a client with borderline personality disorder who was admitted after a crisis at home. Which client behaviors are consistent with splitting? Select all that apply.', '[{"id": "a", "text": "Performs a ritual to cancel out an anxiety-provoking thought"}, {"id": "b", "text": "Calls the nurse the best ever one day and terrible the next"}, {"id": "c", "text": "Tries to pit staff members against each other over privileges"}, {"id": "d", "text": "Discusses treatment research while showing no emotion"}, {"id": "e", "text": "Views the day staff as entirely good and night staff as entirely bad"}]'::jsonb, '["b", "c", "e"]', 'Splitting is all-good or all-bad thinking: calling the nurse the best ever and then terrible (b), pitting staff against each other (c), and seeing one shift as entirely good and another as entirely bad (e). A ritual to cancel a thought (a) is undoing, and discussing research without emotion (d) is intellectualization.', true),
  ('defense', 31, 'A client with a history of violent urges, who previously punched walls when frustrated, tells the nurse he has started training at a boxing gym three evenings a week. Which interpretation of this change is BEST?', '[{"id": "a", "text": "Displacement of anger onto a safer target, which should be stopped"}, {"id": "b", "text": "Reaction formation, converting aggression into its opposite feeling"}, {"id": "c", "text": "Sublimation, channeling impulses into an acceptable activity"}, {"id": "d", "text": "Regression to an earlier developmental stage when under stress"}]'::jsonb, '["c"]', 'Channeling unacceptable impulses into socially acceptable or productive activities, such as taking up boxing, is sublimation, a mature mechanism. Displacement redirects emotion onto a substitute target such as a person; boxing is a socially acceptable channel for the impulse.', false),
  ('defense', 32, 'A staff nurse says about a client, "He''s just playing games — he blames everyone else for his problems, and I''m tired of it." Which response by the charge nurse is MOST appropriate?', '[{"id": "a", "text": "\"All people use defense mechanisms; let''s explore the anxiety behind his.\""}, {"id": "b", "text": "\"You''re right; let''s tell him we won''t tolerate him blaming the staff.\""}, {"id": "c", "text": "\"Ignore him when he blames others so the behavior is not reinforced.\""}, {"id": "d", "text": "\"He has a personality disorder, so there''s little we can do to change it.\""}]'::jsonb, '["a"]', 'Nurses should be non-judgmental because all people use defense mechanisms as normal responses to anxiety, and should explore the underlying anxiety to address the root cause. Threatening the client or ignoring him does not address the anxiety driving the defense.', false),
  ('defense', 33, 'A client with a history of trauma is being assessed after an episode of severe anxiety in the dayroom. Which findings suggest the client is using dissociation? Select all that apply.', '[{"id": "a", "text": "Reports feeling detached from her body during panic attacks"}, {"id": "b", "text": "Consciously chooses not to discuss the trauma until next session"}, {"id": "c", "text": "Says the trauma \"was no big deal\" and refuses all therapy"}, {"id": "d", "text": "States, \"This doesn''t feel real,\" when she becomes anxious"}, {"id": "e", "text": "Begins thumb-sucking and asking staff to feed her"}]'::jsonb, '["a", "d"]', 'Feeling detached from the body (a) and saying "this doesn''t feel real" (d) show disconnection from feelings or surroundings to escape distress — dissociation. Consciously delaying discussion (b) is suppression, refusing to accept the trauma''s reality (c) is denial, and reverting to child-like behaviors (e) is regression.', true),
  ('defense', 34, 'A client who privately told the nurse she resents her younger brother for "ruining my childhood" is observed being excessively affectionate toward him during visits and praising him to staff at every opportunity. Which defense mechanism is MOST likely?', '[{"id": "a", "text": "Undoing"}, {"id": "b", "text": "Sublimation"}, {"id": "c", "text": "Intellectualization"}, {"id": "d", "text": "Reaction formation"}]'::jsonb, '["d"]', 'Reaction formation is expressing the opposite of one''s true feelings, such as a person with deep hostility toward a sibling acting excessively loving and caring. Undoing is a single act to cancel out a specific thought, not an ongoing display of the opposite feeling.', false),
  ('defense', 35, 'An adult client admitted with pneumonia, who lives independently, now refuses to wash his own face, calls for the nurse every few minutes, and asks to be fed. Which interpretation and action by the nurse is BEST?', '[{"id": "a", "text": "Projection; reassure the client that staff do not resent his requests"}, {"id": "b", "text": "Regression; explore the underlying anxiety about being hospitalized"}, {"id": "c", "text": "Reaction formation; set punitive limits on the client''s call light use"}, {"id": "d", "text": "Displacement; refer the client''s anger back to the admitting provider"}]'::jsonb, '["b"]', 'An adult who becomes demanding and dependent (child-like) when hospitalized is regressing, and the nurse should explore the underlying anxiety driving the defense. Limits for clients should be non-punitive, and nothing suggests the client is attributing feelings to staff.', false),
  ('defense', 36, 'A client in an outpatient substance use program discusses drinking during group therapy. Which client statements indicate rationalization? Select all that apply.', '[{"id": "a", "text": "\"I don''t have a problem; I can stop whenever I want.\""}, {"id": "b", "text": "\"Wine at night is basically my sleep medicine.\""}, {"id": "c", "text": "\"I''ve earned a few drinks on weekends with how hard I work.\""}, {"id": "d", "text": "\"My sponsor is the one who''s angry at me, not the other way.\""}, {"id": "e", "text": "\"Everyone at my job drinks this much — it''s how you fit in.\""}]'::jsonb, '["b", "c", "e"]', 'Rationalization is making logical-sounding, socially acceptable excuses for unacceptable behavior: wine as sleep medicine (b), as an earned reward (c), or to fit in (e). Saying there is no problem (a) refuses reality and is denial, and claiming the sponsor is the angry one (d) is projection.', true),
  ('defense', 37, 'A school-age child who struggles in sports and is often picked last for teams tells the school nurse, "I can''t kick a ball, but I''m going to have the best grades in the whole class." Which interpretation is BEST?', '[{"id": "a", "text": "Rationalization; the child is making excuses for poor sports skills"}, {"id": "b", "text": "Sublimation; the child is channeling unacceptable impulses into study"}, {"id": "c", "text": "Compensation; the child is making up for a perceived weakness"}, {"id": "d", "text": "Displacement; the child is redirecting frustration onto schoolwork"}]'::jsonb, '["c"]', 'Overachieving in one area (academics) to make up for a real or perceived deficit in another (sports) is compensation. Sublimation involves unacceptable impulses, such as violent or aggressive urges, which are not present here.', false),
  ('defense', 38, 'A 7-year-old child who has been fully independent with dressing and feeding begins using baby talk and insists that a parent spoon-feed every meal on the second day of a stressful hospitalization. The nurse identifies this behavior as which defense mechanism MOST likely?', '[{"id": "a", "text": "Regression"}, {"id": "b", "text": "Introjection"}, {"id": "c", "text": "Reaction formation"}, {"id": "d", "text": "Identification"}]'::jsonb, '["a"]', 'Regression is reverting to behaviors characteristic of an earlier developmental stage when under stress, such as a previously independent child acting younger during hospitalization. Introjection internalizes another person''s values or attitudes, which does not explain a return to younger behavior.', false),
  ('defense', 39, 'A nurse explains that most defense mechanisms operate below conscious awareness. Which client statements reflect a defense mechanism that operates unconsciously? Select all that apply.', '[{"id": "a", "text": "\"I''ll think about the hospital bill after I''m discharged.\""}, {"id": "b", "text": "\"This doesn''t feel real — I feel outside my own body.\""}, {"id": "c", "text": "\"The lab must have made a mistake with my results.\""}, {"id": "d", "text": "\"I smoke because it helps my back pain — it''s practically medicinal.\""}, {"id": "e", "text": "\"I bought her a gift because I felt bad about my angry thought.\""}]'::jsonb, '["b", "c", "d", "e"]', 'Dissociation (b), denial (c), rationalization (d), and undoing (e) are unconscious defense mechanisms. Deliberately deciding to think about the bill later (a) is suppression, the one defense mechanism that is conscious.', true),
  ('defense', 40, 'A client whose child died last month speaks to the nurse at length about the medical causes of the child''s illness and the hospital''s research protocols, but changes the subject whenever the nurse asks how she is feeling. Which defense mechanism is MOST likely?', '[{"id": "a", "text": "Denial"}, {"id": "b", "text": "Dissociation"}, {"id": "c", "text": "Suppression"}, {"id": "d", "text": "Intellectualization"}]'::jsonb, '["d"]', 'Intellectualization is using abstract thinking, data, or reasoning to avoid the emotional aspects of an issue. The client is not denying the death (denial) or consciously choosing to set it aside for later (suppression); she is focusing on data to avoid feelings.', false),
  ('defense', 41, 'A client with obsessive-compulsive disorder tells the nurse, "Whenever the thought pops into my head that something bad will happen to my mother, I have to tap the door frame ten times or I can''t calm down." The tapping is MOST consistent with which defense mechanism?', '[{"id": "a", "text": "Undoing"}, {"id": "b", "text": "Regression"}, {"id": "c", "text": "Reaction formation"}, {"id": "d", "text": "Displacement"}]'::jsonb, '["a"]', 'Undoing is performing an action or ritual to cancel out an unacceptable thought, and it is common in OCD as repetitive rituals to undo anxiety-provoking thoughts. Reaction formation expresses the opposite feeling rather than performing a ritual to cancel a thought.', false),
  ('defense', 42, 'The charge nurse observes staff members interacting with clients who are using defense mechanisms. Which staff actions with a client require correction? Select all that apply.', '[{"id": "a", "text": "Explores the anxiety underlying a client''s intellectualizing"}, {"id": "b", "text": "Takes sides when a client says another nurse is terrible"}, {"id": "c", "text": "Remains non-judgmental when a client makes excuses for drinking"}, {"id": "d", "text": "Holds the same limits as other staff for a client who is splitting"}, {"id": "e", "text": "Tells a grieving widow in denial, \"He''s gone; you must accept it.\""}]'::jsonb, '["b", "e"]', 'Taking sides when the client calls another nurse terrible (b) validates splitting, and bluntly telling a grieving widow to accept the death (e) directly confronts denial — both need correction. Exploring underlying anxiety (a), being non-judgmental (c), and holding the same limits as the team (d) are correct responses.', true),
  ('defense', 43, 'A newly hired graduate nurse begins to dress, speak, and approach patients exactly the way a highly respected preceptor does, and tells a client, "I want to be just like her." Which defense mechanism is the graduate nurse MOST likely using?', '[{"id": "a", "text": "Projection"}, {"id": "b", "text": "Identification"}, {"id": "c", "text": "Reaction formation"}, {"id": "d", "text": "Compensation"}]'::jsonb, '["b"]', 'Identification is modeling oneself after another person, especially someone admired, such as a young nurse modeling behavior after a respected mentor. Compensation is overachieving to make up for a deficit, which is not described here.', false),
  ('defense', 44, 'A client who has expressed deep hostility toward his stepfather in therapy insists to staff that he "loves him more than anything" and fusses over the stepfather excessively at every visit. Which defense mechanism is MOST likely?', '[{"id": "a", "text": "Undoing"}, {"id": "b", "text": "Displacement"}, {"id": "c", "text": "Reaction formation"}, {"id": "d", "text": "Intellectualization"}]'::jsonb, '["c"]', 'Reaction formation is expressing the opposite of one''s true feelings — converting hostility into excessive loving and caring. Displacement would redirect the hostility toward a safer target, not convert it into affection.', false),
  ('defense', 45, 'After caring for a client who used several defense mechanisms, a nursing student makes statements during post-conference. Which statements by the student indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"These are normal responses to anxiety that all people use.\""}, {"id": "b", "text": "\"Denial should be confronted directly so grief can progress.\""}, {"id": "c", "text": "\"A mechanism can protect a client but may block treatment.\""}, {"id": "d", "text": "\"Suppression is the defense mechanism used consciously.\""}, {"id": "e", "text": "\"Exploring the underlying anxiety addresses the root cause.\""}]'::jsonb, '["a", "c", "d", "e"]', 'Defense mechanisms are normal responses to anxiety (a); a mechanism may protect the client temporarily or prevent necessary treatment (c); suppression is the only conscious mechanism (d); and exploring underlying anxiety addresses the root cause (e). Denial should NOT be directly confronted, especially in grief (b).', true),
  ('defense', 46, 'A client with severe childhood trauma has distinct identities that take control at different times and reports gaps in memory for those periods. The nurse understands that this disorder is the extreme form of which defense mechanism MOST directly?', '[{"id": "a", "text": "Repression"}, {"id": "b", "text": "Reaction formation"}, {"id": "c", "text": "Regression"}, {"id": "d", "text": "Dissociation"}]'::jsonb, '["d"]', 'Dissociative identity disorder is the extreme form of dissociation, disconnecting from thoughts, feelings, identity, or surroundings to escape distress. Repression pushes specific threatening memories out of awareness but is not described as producing separate identities.', false),
  ('defense', 47, 'A combat veteran in therapy cannot recall the ambush in which members of his unit were killed, even though he wants to remember and fellow soldiers have described it to him. Which defense mechanism BEST explains this finding?', '[{"id": "a", "text": "Repression"}, {"id": "b", "text": "Suppression"}, {"id": "c", "text": "Denial"}, {"id": "d", "text": "Intellectualization"}]'::jsonb, '["a"]', 'Repression involuntarily pushes threatening memories out of conscious awareness into the unconscious. Suppression is a conscious decision to delay thinking about something, which does not fit a client who wants to remember and cannot.', false),
  ('defense', 48, 'A client whose infant died yesterday tells the nurse that the baby is "just in the nursery" and asks when she can feed him. Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Acknowledge what the client is expressing about her baby"}, {"id": "b", "text": "Gently provide reality about the loss over time"}, {"id": "c", "text": "Insist that the client view the death certificate today"}, {"id": "d", "text": "Remain non-judgmental about the client''s response"}, {"id": "e", "text": "Explore the underlying anxiety driving the client''s denial"}]'::jsonb, '["a", "b", "d", "e"]', 'In grief, the nurse acknowledges what the client is expressing (a) and gently provides reality over time (b), remains non-judgmental (d), and explores the underlying anxiety driving the defense (e). Insisting she view the death certificate today (c) directly confronts denial, which the nurse should not do.', true),
  ('defense', 49, 'A client who learned from the physician that discharge will be delayed two more days waits until the physician leaves, then shouts at the nurse for being slow with medications. Which nursing response is BEST?', '[{"id": "a", "text": "Tell the client that yelling at staff will lead to loss of privileges"}, {"id": "b", "text": "Recognize the redirected anger and explore the underlying anxiety"}, {"id": "c", "text": "Explain that the nurse is not responsible for the physician''s decision"}, {"id": "d", "text": "Ask the physician to return so the client can direct the anger at him"}]'::jsonb, '["b"]', 'The client is displacing anger from the physician onto the nurse, a safer target; the nurse should explore the underlying anxiety driving the defense mechanism. Threatening loss of privileges is punitive and judgmental, and defending oneself does not address the root cause.', false),
  ('defense', 50, 'The nurse is reviewing how four bereaved clients are coping several months after a loss. Which client is using the MOST mature, adaptive defense mechanism?', '[{"id": "a", "text": "A widower who insists the death certificate must be someone else''s"}, {"id": "b", "text": "A mother who accuses the nurses of the guilt she herself feels"}, {"id": "c", "text": "A father who channels his grief into writing or art"}, {"id": "d", "text": "A widow who becomes demanding and dependent on her children"}]'::jsonb, '["c"]', 'Channeling grief into writing or art is sublimation, the most adaptive/mature mechanism. Insisting the certificate is wrong is denial, accusing others of one''s own feelings is projection, and becoming demanding and dependent is regression — all immature mechanisms.', false),
  ('family', 1, 'During a family assessment, the nurse learns that the parents of a 14-year-old have argued bitterly for years, but whenever their son gets in trouble at school they stop fighting and work together to discipline him. The parents describe the son as "the problem in this family." Which concept BEST explains this pattern?', '[{"id": "a", "text": "Emotional cutoff"}, {"id": "b", "text": "Multigenerational transmission"}, {"id": "c", "text": "Triangulation"}, {"id": "d", "text": "Disengaged boundaries"}]'::jsonb, '["c"]', 'When tension between two people becomes too great, a third person is pulled in to reduce anxiety and stabilize the dyad; the child becomes "the problem" and the parents temporarily unite against him. Emotional cutoff involves distancing from family, which is not occurring here.', false),
  ('family', 2, 'The wife of a client with alcohol use disorder tells the nurse she calls his employer to say he has the flu when he is hungover, pays his overdue bills, and tells the children their father is "just tired." Which family role is the wife MOST likely filling?', '[{"id": "a", "text": "The Hero"}, {"id": "b", "text": "The Enabler"}, {"id": "c", "text": "The Mascot"}, {"id": "d", "text": "The Scapegoat"}]'::jsonb, '["b"]', 'The Enabler/Caretaker makes excuses for the dysfunctional member, covers up problems, and takes over their responsibilities, which enables the behavior to continue. The Hero is usually the eldest child who achieves to bring the family a sense of worth.', false),
  ('family', 3, 'A nurse is assessing a 32-year-old client who lives near her parents and is admitted for anxiety. Which client statements suggest LOW differentiation of self? Select all that apply.', '[{"id": "a", "text": "\"When my family gets anxious, I get swept along and can''t think.\""}, {"id": "b", "text": "\"I love my family, and I can still disagree with them calmly.\""}, {"id": "c", "text": "\"I have difficulty separating my own needs from others'' needs.\""}, {"id": "d", "text": "\"I can stay calm when everyone else at home is panicking.\""}, {"id": "e", "text": "\"Whatever my family is anxious about, I end up anxious about too.\""}]'::jsonb, '["a", "c", "e"]', 'Low differentiation means emotional fusion: being easily swept along by family anxiety (a, e) and having difficulty separating one''s own needs from others'' (c). Disagreeing calmly while staying connected (b) and remaining calm under pressure (d) show HIGH differentiation.', true),
  ('family', 4, 'A 26-year-old client tells the nurse she cannot choose which job offer to accept, what to wear to the interview, or whether to move out until her mother approves, adding, "When she''s sad, I''m sad — we''re basically the same person." Which family boundary pattern is MOST evident?', '[{"id": "a", "text": "Healthy boundaries"}, {"id": "b", "text": "Disengaged boundaries"}, {"id": "c", "text": "Emotional cutoff"}, {"id": "d", "text": "Enmeshment"}]'::jsonb, '["d"]', 'In enmeshment, boundaries are overly blurred and individual autonomy and identity are lost, as when a daughter cannot make any decision without her mother''s approval and their emotions are merged. Disengaged boundaries are the opposite — family members are too emotionally distant.', false),
  ('family', 5, 'A 45-year-old client in marital therapy says, "I haven''t spoken to my parents in 20 years, so their drama doesn''t affect me anymore." His wife reports he reacts to their arguments exactly the way his father did. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The distance has resolved his attachment, so the issue lies elsewhere"}, {"id": "b", "text": "This is emotional cutoff, which relocates the problem rather than resolving it"}, {"id": "c", "text": "This is healthy differentiation, because he has kept his own identity"}, {"id": "d", "text": "This is triangulation, because a third person absorbs the couple''s conflict"}]'::jsonb, '["b"]', 'Emotional cutoff manages unresolved attachment by distancing but does NOT resolve the underlying emotional problem; the person carries the same emotional patterns into new relationships such as a marriage. Differentiation means keeping one''s identity while staying connected, not cutting off.', false),
  ('family', 6, 'A nurse in a community mental health clinic reviews a client''s genogram with a student. Which of the student''s interpretations of the genogram symbols are correct? Select all that apply.', '[{"id": "a", "text": "A jagged line between two people shows a close relationship"}, {"id": "b", "text": "A circle with an X through it is a deceased female"}, {"id": "c", "text": "A vertical line connects parents to their children"}, {"id": "d", "text": "A dotted line between two people shows a marriage"}, {"id": "e", "text": "A double line between two people shows conflict"}]'::jsonb, '["b", "c"]', 'Circles are females and an X through the shape means deceased (b), and vertical lines show children (c). Jagged lines indicate conflict, not closeness (a); dotted lines show a distant relationship, while horizontal lines show marriages (d); double lines indicate a close relationship, not conflict (e).', true),
  ('family', 7, 'In a family where the father has a long history of alcohol use, the 17-year-old eldest daughter has straight A''s, captains two teams, and manages her siblings'' schedules. She tells the nurse privately, "If I mess up even once, everything falls apart." Which role is the daughter MOST likely filling?', '[{"id": "a", "text": "The Hero / Super Achiever"}, {"id": "b", "text": "The Lost Child / Invisible Child"}, {"id": "c", "text": "The Enabler / Caretaker"}, {"id": "d", "text": "The Mascot / Clown"}]'::jsonb, '["a"]', 'The Hero is often the eldest child — high-achieving and responsible — who internally feels pressure, inadequacy, and a heavy family burden. The Enabler covers up and makes excuses for the dysfunctional member rather than achieving to give the family a sense of worth.', false),
  ('family', 8, 'During a home visit to a family with a parent who has a chronic mental illness, the nurse notices that the 10-year-old middle child stays in her room reading, never causes problems, and is rarely mentioned by either parent. Which adult outcome is this child MOST at risk for?', '[{"id": "a", "text": "Becoming a perfectionist or workaholic"}, {"id": "b", "text": "Using humor to avoid serious topics or any intimacy"}, {"id": "c", "text": "Developing codependency in close relationships"}, {"id": "d", "text": "Difficulty forming relationships and loneliness"}]'::jsonb, '["d"]', 'This child fits the Lost Child, who withdraws, stays out of the way, and receives no attention, and who may struggle with identity, loneliness, and difficulty forming relationships in adulthood. Perfectionism or workaholism is the adult risk for the Hero.', false),
  ('family', 9, 'A nurse observes a family session for a client with a substance use disorder. Which observations correctly match the family member''s behavior to a dysfunctional family role? Select all that apply.', '[{"id": "a", "text": "Son who uses humor and comic behavior to relieve tension: Mascot"}, {"id": "b", "text": "Daughter who quietly withdraws and is rarely noticed: Hero"}, {"id": "c", "text": "Teen who is suspended and blamed for family stress: Scapegoat"}, {"id": "d", "text": "Spouse who covers up and makes excuses for the client: Enabler"}, {"id": "e", "text": "Eldest who earns top grades as the family''s pride: Lost Child"}]'::jsonb, '["a", "c", "d"]', 'The Mascot uses humor to relieve family tension (a), the Scapegoat is blamed and gets in trouble (c), and the Enabler makes excuses and covers up (d). A quietly withdrawn, unnoticed child is the Lost Child, not the Hero (b), and the high-achieving eldest is the Hero, not the Lost Child (e).', true),
  ('family', 10, 'During a tense family meeting about their mother''s relapse, the 12-year-old youngest son repeatedly makes silly faces and jokes until everyone laughs. Later he tells the nurse, "I''m scared all the time that something bad will happen." Which interpretation is MOST accurate?', '[{"id": "a", "text": "He is the Lost Child, coping through isolation and fantasy"}, {"id": "b", "text": "He is the Scapegoat, acting out so the family can blame him"}, {"id": "c", "text": "He is the Mascot, relieving tension while internally anxious"}, {"id": "d", "text": "He is the Hero, providing the family a sense of worth and hope"}]'::jsonb, '["c"]', 'The Mascot/Clown uses humor and comic behavior to relieve family tension and distract from dysfunction, while internally often being anxious, fearful, and emotionally fragile. The Scapegoat acts out, rebels, and gets in trouble rather than relieving tension with humor.', false),
  ('family', 11, 'Parents bring their 15-year-old son for evaluation of fighting and school suspensions, saying, "Everything at home would be fine if it weren''t for him." The nurse learns the parents have had serious marital conflict for years. Which nursing action is BEST?', '[{"id": "a", "text": "Help the family understand how the system maintains the problem"}, {"id": "b", "text": "Focus the plan of care on correcting the son''s behavior problems"}, {"id": "c", "text": "Advise the parents to set stricter consequences for the son at home"}, {"id": "d", "text": "Recommend that the son spend time living away from the family"}]'::jsonb, '["a"]', 'The son is being scapegoated — blamed for family stress although the real dysfunction is the parents'' marital conflict — so the nurse helps the family understand how the system maintains the problem, not just one individual. Focusing only on the son treats the individual, which may be insufficient because the family system reinforces the problem.', false),
  ('family', 12, 'A family is referred to therapy after the nurse identifies that the parents routinely pull their daughter into their conflicts and that similar patterns appear in the grandparents'' generation. Which goals are appropriate for this family''s therapy? Select all that apply.', '[{"id": "a", "text": "Increase differentiation of self for each family member"}, {"id": "b", "text": "Identify and reduce triangulation patterns"}, {"id": "c", "text": "Encourage the daughter to keep her distance from the family"}, {"id": "d", "text": "Interrupt multigenerational transmission of dysfunction"}, {"id": "e", "text": "Help the family understand how the system maintains the problem"}]'::jsonb, '["a", "b", "d", "e"]', 'Family therapy goals include increasing differentiation (a), identifying and reducing triangulation (b), interrupting multigenerational transmission (d), and helping the family understand how the system maintains the problem (e). Encouraging distance (c) resembles emotional cutoff; the goal is to resolve cutoffs through reconnection, not just distance.', true),
  ('family', 13, 'While completing a genogram with a client admitted for alcohol use disorder, the nurse finds that the client''s father and paternal grandfather both had alcohol use disorder and that the client''s teenage son was recently arrested for intoxication. Which concept BEST explains this finding?', '[{"id": "a", "text": "Nuclear family emotional process"}, {"id": "b", "text": "Multigenerational transmission process"}, {"id": "c", "text": "Triangulation through a scapegoated child"}, {"id": "d", "text": "Sibling position"}]'::jsonb, '["b"]', 'In the multigenerational transmission process, patterns of emotional functioning and behavior, such as substance abuse, are transmitted across multiple generations. The nuclear family emotional process describes patterns within the immediate family unit only, not across three generations.', false),
  ('family', 14, 'A couple tells the nurse they "never fight," but over the years the mother has focused all of her worry on their 9-year-old son, who now has frequent stomachaches and school refusal. Which pattern of the nuclear family emotional process is this family MOST likely using to manage anxiety?', '[{"id": "a", "text": "Impairment of one or more children"}, {"id": "b", "text": "Dysfunction in one spouse"}, {"id": "c", "text": "Marital conflict"}, {"id": "d", "text": "Emotional distance"}]'::jsonb, '["a"]', 'One of the four patterns families use to manage anxiety is impairment of one or more children, in which the family''s anxiety is focused on a child who becomes symptomatic. The couple denies marital conflict, and nothing indicates one spouse is impaired.', false),
  ('family', 15, 'A nurse is developing the plan of care for a client with schizophrenia who lives with his parents and has been rehospitalized three times this year. Which nursing actions reflect Family Systems Theory? Select all that apply.', '[{"id": "a", "text": "Treat only the client, because the illness belongs to the individual"}, {"id": "b", "text": "Include family education in the plan of care"}, {"id": "c", "text": "Use a genogram to assess the family''s patterns and supports"}, {"id": "d", "text": "Encourage the client to cut off contact with his parents"}, {"id": "e", "text": "Refer to family therapy if family dysfunction contributes"}]'::jsonb, '["b", "c", "e"]', 'Nurses include family education, especially for chronic mental illness such as schizophrenia (b), use genograms to assess family structure and support systems (c), and refer to family therapy when dysfunction contributes to illness (e). Treating only the individual may be insufficient (a), and emotional cutoff does not resolve the underlying problem (d).', true),
  ('family', 16, 'The nurse is evaluating several family members during a session in which the father announces he is leaving his job and the mother begins to cry. Which family member''s statement indicates the HIGHEST level of differentiation of self?', '[{"id": "a", "text": "\"When Mom cries, I start crying too — I can''t help it.\""}, {"id": "b", "text": "\"I''ll do whatever Dad decides; I don''t really have an opinion.\""}, {"id": "c", "text": "\"I''m worried too, but I can think this through and stay calm.\""}, {"id": "d", "text": "\"I''m moving out so I never have to deal with their problems.\""}]'::jsonb, '["c"]', 'High differentiation means being able to think independently, not being emotionally reactive, and remaining calm under pressure while staying connected. Crying because Mom cries shows emotional fusion, and moving out to avoid problems is emotional cutoff.', false),
  ('family', 17, 'The nurse is planning family involvement for a client in treatment for alcohol use disorder. The wife covers up his drinking, the eldest daughter is a high achiever, the middle son is often in trouble at school, and the youngest child jokes constantly. Which family member''s role is MOST important to address FIRST in addiction treatment?', '[{"id": "a", "text": "The eldest daughter, who achieves to provide worth"}, {"id": "b", "text": "The middle son, who absorbs blame for family stress"}, {"id": "c", "text": "The youngest child, who relieves tension with humor"}, {"id": "d", "text": "The wife, who covers up problems and enables the behavior"}]'::jsonb, '["d"]', 'The wife is the Enabler, often the most important role to address in addiction treatment because covering up enables the behavior to continue. The other roles are adaptations to the dysfunction but do not directly sustain the drinking.', false),
  ('family', 18, 'A 16-year-old client is admitted after a third arrest. His parents describe him as "the problem child," and the nurse suspects he is filling the scapegoat role in a family with chronic dysfunction. Which additional findings are consistent with this role? Select all that apply.', '[{"id": "a", "text": "Acts out, rebels, and has school problems"}, {"id": "b", "text": "Withdraws and never receives attention at home"}, {"id": "c", "text": "Is described as the pride of the family"}, {"id": "d", "text": "Uses comic behavior to distract from conflict"}, {"id": "e", "text": "Is the most sensitive and honest family member"}]'::jsonb, '["a", "e"]', 'The Scapegoat acts out, rebels, gets in trouble, and often has school problems (a), and ironically is often the most sensitive and honest family member (e). Withdrawing without attention is the Lost Child (b), being the pride of the family is the Hero (c), and comic distraction is the Mascot (d).', true),
  ('family', 19, 'During a well-child visit, the nurse learns that the parents of a 13-year-old did not know she had failed two classes for an entire semester, rarely eat meals together, and say, "We each do our own thing — we don''t really talk." Which boundary pattern is MOST evident?', '[{"id": "a", "text": "Enmeshment"}, {"id": "b", "text": "Disengaged boundaries"}, {"id": "c", "text": "Healthy boundaries"}, {"id": "d", "text": "Emotional cutoff from family"}]'::jsonb, '["b"]', 'Disengaged boundaries occur when family members are too emotionally distant, with a lack of support or connection. Enmeshment and fusion are the opposite — boundaries so blurred that individual autonomy and identity are lost.', false),
  ('family', 20, 'A mother of a 12-year-old tells the nurse she sends her son to tell his father when she is angry, complains to the boy about his father''s faults, and asks him to choose whose side he is on. Which family therapy goal is MOST directly indicated?', '[{"id": "a", "text": "Identify and reduce triangulation patterns"}, {"id": "b", "text": "Resolve emotional cutoffs through reconnection"}, {"id": "c", "text": "Interrupt multigenerational transmission"}, {"id": "d", "text": "Increase the son''s academic achievement"}]'::jsonb, '["a"]', 'The mother is pulling a third person — the son — into tension between the parents, which is triangulation, so the goal is to identify and reduce triangulation patterns. No family member is distancing, so resolving emotional cutoffs is not the focus.', false),
  ('family', 21, 'A 34-year-old client who was the eldest child in a family with parental alcohol use is admitted for exhaustion. The nurse recognizes the client filled the Hero role. Which findings are consistent with this role? Select all that apply.', '[{"id": "a", "text": "Withdrew and was rarely noticed as a child"}, {"id": "b", "text": "Internally feels pressure and inadequacy despite success"}, {"id": "c", "text": "Was blamed for the family''s problems as a teen"}, {"id": "d", "text": "Has become a perfectionist and workaholic in adulthood"}, {"id": "e", "text": "Was seen as the \"pride of the family\" growing up"}]'::jsonb, '["b", "d", "e"]', 'The Hero is the "pride of the family" (e) who internally feels pressure and inadequacy (b) and may become a perfectionist or workaholic in adulthood (d). Withdrawing unnoticed is the Lost Child (a), and being blamed for family problems is the Scapegoat (c).', true),
  ('family', 22, 'A client in outpatient therapy says, "I moved across the country so I don''t have to deal with my family anymore — problem solved." The client also reports repeating the same angry arguments with a new partner that she had with her mother. Which nursing action is BEST?', '[{"id": "a", "text": "Agree that the distance has resolved the conflict with her family"}, {"id": "b", "text": "Advise the client to move back home so the conflict can be resolved"}, {"id": "c", "text": "Explore how the family pattern appears in her new relationship"}, {"id": "d", "text": "Recommend she stay cut off from family to protect her emotional health"}]'::jsonb, '["c"]', 'Emotional cutoff does NOT resolve the underlying problem — it relocates it, and the person carries the unresolved emotional process into new relationships, so the nurse explores that pattern. Agreeing that distance solved the problem or recommending continued cutoff reinforces the cutoff.', false),
  ('family', 23, 'A nurse reviewing a client''s genogram sees that the client''s father is drawn as a square with an X through it and that a jagged line connects the client to the client''s mother. Which interpretation is MOST accurate?', '[{"id": "a", "text": "The mother is deceased and was close to the client"}, {"id": "b", "text": "The father is still living but has a distant relationship with the client"}, {"id": "c", "text": "The father is deceased, and the client and mother are close"}, {"id": "d", "text": "The father is deceased, and the client and mother have conflict"}]'::jsonb, '["d"]', 'A square is a male and an X through the shape means deceased, so the father has died; a jagged line indicates conflict. A close relationship would be drawn with double lines, not a jagged line.', false),
  ('family', 24, 'A nurse is assessing the boundaries in the family of a 19-year-old client admitted with anxiety. Which findings indicate enmeshment? Select all that apply.', '[{"id": "a", "text": "The parents did not notice the client was failing college classes"}, {"id": "b", "text": "The client cannot make any decision without her mother''s approval"}, {"id": "c", "text": "The mother says their emotions and identities are merged"}, {"id": "d", "text": "The client has not spoken to her parents in several years"}, {"id": "e", "text": "The family balances closeness with each person''s independence"}]'::jsonb, '["b", "c"]', 'Enmeshment means boundaries are overly blurred, so autonomy and identity are lost: the client cannot decide without her mother''s approval (b) and their emotions and identities are merged (c). Parents not noticing failure (a) suggests disengaged boundaries, years without contact (d) suggests emotional cutoff, and balance of closeness with independence (e) is healthy.', true),
  ('family', 25, 'After eight months of family therapy, a young adult client who previously could not separate her own needs from her parents'' makes several statements. Which statement BEST indicates that the central goal of Family Systems Theory is being met?', '[{"id": "a", "text": "\"I stopped visiting my parents so I won''t get pulled into their fights.\""}, {"id": "b", "text": "\"I can stay close to my parents and still make my own decisions.\""}, {"id": "c", "text": "\"My parents finally agree with every decision I make about my life.\""}, {"id": "d", "text": "\"I check with my mother before each decision so that we don''t argue.\""}]'::jsonb, '["b"]', 'Differentiation of self — maintaining one''s identity while remaining connected — is the central goal. Stopping visits is emotional cutoff, and checking with her mother before each decision reflects continued fusion.', false),
  ('family', 26, 'A father enters recovery for alcohol use disorder. Within weeks, his wife becomes withdrawn and their 15-year-old daughter begins skipping school. The wife asks the nurse, "Why is everyone else falling apart now that he''s finally sober?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Your daughter is probably acting out to get the attention he used to get.\""}, {"id": "b", "text": "\"This means your husband''s recovery is not truly working yet.\""}, {"id": "c", "text": "\"A change in one family member creates change throughout the family.\""}, {"id": "d", "text": "\"These problems are unrelated to his drinking and need separate care.\""}]'::jsonb, '["c"]', 'The key premise of Family Systems Theory is that a change in one part of the system creates change throughout the entire system. Saying the problems are unrelated ignores that problems in one member affect the whole system.', false),
  ('family', 27, 'A family has attended therapy for six months to address triangulation, emotional cutoff, and blaming of the youngest son. Which statements by family members indicate progress toward therapy goals? Select all that apply.', '[{"id": "a", "text": "\"We see that our son''s behavior is part of how our family works.\""}, {"id": "b", "text": "\"I''m working to resolve the cutoff with my sister through reconnection.\""}, {"id": "c", "text": "\"We no longer involve our daughter when tension between us is high.\""}, {"id": "d", "text": "\"I can think independently and still stay connected to Mom.\""}, {"id": "e", "text": "\"We agreed our son is the one who needs to be fixed first.\""}]'::jsonb, '["a", "b", "c", "d"]', 'Progress includes understanding how the system maintains the problem (a), resolving cutoffs through reconnection (b), reducing triangulation (c), and increased differentiation of self (d). Agreeing the son must be fixed (e) continues to focus on one individual, which is scapegoating.', true),
  ('family', 28, 'A 38-year-old client tells the nurse that his partner is leaving because "every time she wants to talk about something serious, I make a joke." He grew up with a mother who had a chronic mental illness. Which childhood family role did the client MOST likely fill?', '[{"id": "a", "text": "The Mascot / Clown"}, {"id": "b", "text": "The Hero / Super Achiever"}, {"id": "c", "text": "The Lost Child / Invisible Child"}, {"id": "d", "text": "The Enabler / Caretaker"}]'::jsonb, '["a"]', 'As an adult, the Mascot may use humor to avoid serious topics or intimacy. The Lost Child copes through isolation and struggles with loneliness and relationships, but humor is the Mascot''s coping style.', false),
  ('family', 29, 'A nursing student reviews a family in which parents with marital conflict blame their 14-year-old daughter for all of the family''s stress. Which statement by the student indicates a need for further teaching?', '[{"id": "a", "text": "\"She is the third party absorbing the family''s conflict.\""}, {"id": "b", "text": "\"Blaming her lets the rest of the family temporarily unite.\""}, {"id": "c", "text": "\"She is often the most emotionally vulnerable person.\""}, {"id": "d", "text": "\"Blaming her resolves the parents'' underlying conflict.\""}]'::jsonb, '["d"]', 'Scapegoating deflects attention from broader systemic issues and only temporarily reduces internal tension; it does not resolve the marital conflict. The other statements are accurate: the scapegoat is the third party absorbing conflict and is often the most emotionally vulnerable member.', false),
  ('family', 30, 'A client asks the nurse why a genogram is being completed during her admission to the mental health unit instead of a simple family tree. Which information will the genogram include that a family tree typically does not? Select all that apply.', '[{"id": "a", "text": "Emotional relationships between family members"}, {"id": "b", "text": "Only the names and birth dates of relatives"}, {"id": "c", "text": "Significant events such as deaths and divorces"}, {"id": "d", "text": "Only the client''s own generation and siblings"}, {"id": "e", "text": "Diagnoses and health patterns across generations"}]'::jsonb, '["a", "c", "e"]', 'A genogram is more detailed than a family tree and includes emotional relationships (a), significant events (c), and diagnoses and patterns across multiple generations (e). It is not limited to names and dates (b), and it spans multiple generations rather than one (d).', true),
  ('family', 31, 'The mother of a 24-year-old with opioid use disorder tells the nurse she pays his rent, lies to relatives about where he is, and does his laundry "so the family doesn''t look bad." Which outcome of her behavior is MOST likely?', '[{"id": "a", "text": "Her son''s family role will shift to the Hero"}, {"id": "b", "text": "Her son''s substance use is likely to continue"}, {"id": "c", "text": "The family''s shame will be permanently resolved"}, {"id": "d", "text": "She will become emotionally cut off from her son"}]'::jsonb, '["b"]', 'The Enabler''s goal is to reduce family shame and maintain stability, but the effect is to enable the problematic behavior to continue. Reducing shame is the goal of enabling, not a lasting outcome.', false),
  ('family', 32, 'During a family assessment, a 16-year-old says she spends weekends with her own friends and disagrees with her parents about politics, yet the family eats dinner together most nights and her parents attend her events. Which description of this family''s boundaries is MOST accurate?', '[{"id": "a", "text": "Enmeshed, because the family is emotionally close"}, {"id": "b", "text": "Disengaged, because the teen has separate activities"}, {"id": "c", "text": "Healthy, balancing closeness with independence"}, {"id": "d", "text": "Cut off, because the teen disagrees with her parents"}]'::jsonb, '["c"]', 'Healthy boundaries balance closeness and independence, with individuals maintaining their own identity while staying connected. Enmeshment would involve loss of individual autonomy, which is not present in this teen who keeps her own opinions.', false),
  ('family', 33, 'The nurse is assessing clients in a marital therapy group. Which client findings are consistent with emotional cutoff? Select all that apply.', '[{"id": "a", "text": "Cannot make any decision without first getting his mother''s approval"}, {"id": "b", "text": "Has not spoken to his parents in 20 years but repeats their patterns in his marriage"}, {"id": "c", "text": "Moved far away from family but carries the same patterns into new relationships"}, {"id": "d", "text": "Is pulled in to carry messages whenever his parents are in conflict"}, {"id": "e", "text": "Keeps her own values while staying in regular, close contact with family"}]'::jsonb, '["b", "c"]', 'Emotional cutoff is physical or emotional distancing from family that relocates the problem, so the person carries the same patterns into new relationships (b, c). Needing a mother''s approval (a) is enmeshment, carrying messages between parents (d) is triangulation, and keeping one''s values while staying connected (e) is differentiation.', true),
  ('family', 34, 'A genogram for a client with severe depression shows that each generation of the family has had somewhat more anxiety and impairment than the one before. The client''s mother asks why her daughter seems more affected than she was. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Your daughter is being triangulated into conflict between you and her father.\""}, {"id": "b", "text": "\"Your daughter is enmeshed with you, so her feelings merge with yours.\""}, {"id": "c", "text": "\"Your daughter has cut herself off from the family''s emotional problems.\""}, {"id": "d", "text": "\"A child with slightly lower differentiation than parents may be more vulnerable.\""}]'::jsonb, '["d"]', 'In multigenerational transmission, a child with slightly lower differentiation than the parents may be more vulnerable, and over many generations this can result in significantly impaired functioning. Nothing in the genogram suggests triangulation, enmeshment, or cutoff in this family.', false),
  ('family', 35, 'A community mental health nurse is admitting a new client whose relatives have a history of suicide, substance abuse, and divorce. The nurse wants to assess multigenerational health patterns, family structure, and support systems. Which action is BEST?', '[{"id": "a", "text": "Use a genogram as an assessment tool"}, {"id": "b", "text": "Draw a basic family tree of names and dates"}, {"id": "c", "text": "Ask the client to rank siblings by birth order"}, {"id": "d", "text": "Interview the client only about current symptoms"}]'::jsonb, '["a"]', 'A genogram is used by nurses to assess multigenerational health patterns, family structure, and support systems and is more detailed than a family tree. A basic family tree omits emotional relationships, significant events, and patterns.', false),
  ('family', 36, 'A married couple in their 50s reports a long, quiet marriage. The nurse learns that the wife has steadily taken over all decisions, finances, and household tasks while the husband has become increasingly depressed, dependent, and unable to function at work. Which nuclear family emotional process pattern is MOST evident?', '[{"id": "a", "text": "Marital conflict"}, {"id": "b", "text": "Emotional distance"}, {"id": "c", "text": "Impairment of one or more children"}, {"id": "d", "text": "Dysfunction in one spouse"}]'::jsonb, '["d"]', 'Dysfunction in one spouse is one of the four patterns families use to manage anxiety, and each pattern creates symptomatic problems — here, the husband''s impairment. The couple does not describe open fighting (marital conflict), and no child is the focus of the anxiety.', false),
  ('family', 37, 'A nurse is teaching a family about the nuclear family emotional process after their son was hospitalized for depression. Which patterns does the nurse describe as ways families manage anxiety? Select all that apply.', '[{"id": "a", "text": "Marital conflict"}, {"id": "b", "text": "Increased differentiation of self"}, {"id": "c", "text": "Dysfunction in one spouse"}, {"id": "d", "text": "Impairment of one or more children"}, {"id": "e", "text": "Emotional distance"}]'::jsonb, '["a", "c", "d", "e"]', 'The four patterns families use to manage anxiety are marital conflict (a), dysfunction in one spouse (c), impairment of one or more children (d), and emotional distance (e), and each creates symptomatic problems. Increased differentiation of self (b) is a therapy goal, not an anxiety-management pattern.', true),
  ('family', 38, 'A 15-year-old with an eating disorder gains weight steadily during an inpatient stay but relapses within two weeks of returning home, where her parents argue nightly and focus all attention on what she eats. Which nursing action is BEST?', '[{"id": "a", "text": "Extend the inpatient stay until the client maintains her weight"}, {"id": "b", "text": "Refer the family to family therapy as part of the plan of care"}, {"id": "c", "text": "Teach the client to ignore her parents'' comments about food"}, {"id": "d", "text": "Recommend that the client live with a relative for a while"}]'::jsonb, '["b"]', 'Treating only the individual may be insufficient because the family system may reinforce the problem, so the nurse refers to family therapy when family dysfunction is contributing to the illness. Extending the stay or moving her treats only the individual and leaves the system unchanged.', false),
  ('family', 39, 'A couple whose son is being treated for anxiety reports that they rarely argue, live largely separate lives in the same house, sleep in different rooms, and seldom share feelings. The son says, "It''s like they''re roommates." Which nuclear family emotional process pattern is MOST evident?', '[{"id": "a", "text": "Marital conflict"}, {"id": "b", "text": "Dysfunction in one spouse"}, {"id": "c", "text": "Emotional distance"}, {"id": "d", "text": "Multigenerational transmission"}]'::jsonb, '["c"]', 'Emotional distance is one of the four nuclear family patterns used to manage anxiety. There is no open fighting (marital conflict) and neither spouse is described as impaired; multigenerational transmission refers to patterns across generations, not within the couple.', false),
  ('family', 40, 'A nurse is working with the family of a client who has alcohol use disorder. Which husband''s statements suggest enabling or codependency that the nurse should address? Select all that apply.', '[{"id": "a", "text": "\"I''ve started going to a support group to understand my part in this.\""}, {"id": "b", "text": "\"I make excuses to her boss when she''s hungover.\""}, {"id": "c", "text": "\"I took over her responsibilities so she doesn''t have to worry.\""}, {"id": "d", "text": "\"I told her I won''t cover for her with her family anymore.\""}, {"id": "e", "text": "\"We each need to look at how our family keeps this going.\""}]'::jsonb, '["b", "c"]', 'Making excuses (b) and taking over the client''s responsibilities (c) are Enabler behaviors that enable the drinking to continue and may lead to codependency. Seeking to understand his part (a), refusing to cover up (d), and looking at how the system maintains the problem (e) are healthy changes.', true),
  ('family', 41, 'A school nurse meets with a family in which the father has an addiction. The eldest daughter is class president, the 13-year-old son is frequently suspended, and the 10-year-old daughter spends recess alone daydreaming and never causes problems. Which child is the nurse MOST likely to overlook without a deliberate assessment?', '[{"id": "a", "text": "The 10-year-old daughter who never causes problems"}, {"id": "b", "text": "The 13-year-old son who is frequently suspended"}, {"id": "c", "text": "The eldest daughter who is class president"}, {"id": "d", "text": "All three children are equally likely to be missed"}]'::jsonb, '["a"]', 'The Lost Child withdraws, stays out of the way, copes through isolation or fantasy, and never receives attention, positive or negative, so she is easily overlooked. The Scapegoat son draws negative attention, and the Hero draws positive attention.', false),
  ('family', 42, 'A nurse is preparing a client with bipolar disorder for discharge to the home he shares with his parents and sister. The family has had little involvement in his care during two previous admissions. Which action is the PRIORITY when applying Family Systems Theory?', '[{"id": "a", "text": "Give the client written materials to share with his family later"}, {"id": "b", "text": "Include family education in the client''s plan of care"}, {"id": "c", "text": "Limit the family''s involvement to protect the client''s privacy"}, {"id": "d", "text": "Focus discharge teaching on the client''s medication schedule only"}]'::jsonb, '["b"]', 'Family Systems Theory directs nurses to include family education in the plan of care, especially for chronic mental illness such as bipolar disorder. Focusing only on the client treats the individual alone, which may be insufficient because the family system may reinforce the problem.', false),
  ('family', 43, 'A new mother whose own father was physically abusive tells the nurse, "My dad was raised the same way by his father. I''m terrified I''ll do the same thing to my baby." Which family therapy goal BEST addresses her concern?', '[{"id": "a", "text": "Interrupt multigenerational transmission of dysfunction"}, {"id": "b", "text": "Resolve emotional cutoffs through reconnection"}, {"id": "c", "text": "Identify and reduce triangulation patterns"}, {"id": "d", "text": "Clarify each child''s sibling position"}]'::jsonb, '["a"]', 'The mother describes trauma patterns repeating across generations, so the goal is to interrupt multigenerational transmission of dysfunction. Triangulation involves pulling a third person into a conflicted dyad, which she does not describe.', false),
  ('family', 44, 'A nurse is admitting a client with alcohol use disorder whose spouse, children, and parents are involved in his life. Which nursing actions reflect Family Systems Theory in caring for this client? Select all that apply.', '[{"id": "a", "text": "Focus care only on the client''s withdrawal and relapse plan"}, {"id": "b", "text": "Assess the family system as part of the client''s care"}, {"id": "c", "text": "Recognize family roles such as the enabler and scapegoat"}, {"id": "d", "text": "Understand codependency often seen in families with addiction"}, {"id": "e", "text": "Use a genogram as an assessment tool in the mental health setting"}]'::jsonb, '["b", "c", "d", "e"]', 'Nurses assess the family system in substance abuse (b), recognize roles such as enabler and scapegoat (c), understand codependency in families with addiction (d), and use genograms as an assessment tool in mental health settings (e). Focusing only on the client (a) may be insufficient because the family system may reinforce the problem.', true),
  ('family', 45, 'A grandmother caring for her grandchildren tells the nurse that her daughter and son-in-law each call her to complain about the other, and that the couple''s fighting calms down only after she gets involved. Which concept BEST describes the grandmother''s position?', '[{"id": "a", "text": "Enmeshment"}, {"id": "b", "text": "Emotional cutoff"}, {"id": "c", "text": "Triangulation"}, {"id": "d", "text": "Disengaged boundaries"}]'::jsonb, '["c"]', 'In triangulation, when tension between two people becomes too great, a third person is pulled in to reduce anxiety and stabilize the dyad — here, the grandmother. Emotional cutoff would involve distancing, which is the opposite of her involvement.', false),
  ('family', 46, 'During a family session, a nurse makes several statements about the roles family members have taken on. Which statement by the nurse requires correction?', '[{"id": "a", "text": "\"Each of you chose these roles on purpose to control the family.\""}, {"id": "b", "text": "\"These roles help keep the family stable and reduce anxiety.\""}, {"id": "c", "text": "\"Families with chronic dysfunction often develop predictable roles.\""}, {"id": "d", "text": "\"The roles develop as adaptations to substance abuse or trauma.\""}]'::jsonb, '["a"]', 'Dysfunctional family roles are unconscious adaptations that stabilize the system and reduce anxiety, not deliberate choices. The other statements accurately describe roles in families with chronic dysfunction.', false),
  ('family', 47, 'The husband of a client with alcohol use disorder tells the nurse, "I would never help her drink — I just handle everything so she doesn''t have to worry about anything." Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "\"You are the reason your wife continues to drink every day.\""}, {"id": "b", "text": "\"Taking over may unwittingly support the addiction to continue.\""}, {"id": "c", "text": "\"You are doing the right thing by protecting her from stress.\""}, {"id": "d", "text": "\"Your role in the family is unrelated to your wife''s drinking.\""}]'::jsonb, '["b"]', 'The enabler supports the addiction unwittingly; taking over responsibilities enables the problematic behavior to continue. Blaming the husband for the drinking is inaccurate, and praising his caretaking reinforces enabling.', false),
  ('family', 48, 'A 14-year-old boy whose mother has alcohol use disorder calls the school to excuse her absences from meetings, cooks dinner for his siblings, and hides her empty bottles before relatives visit. Which family role is the boy MOST likely filling?', '[{"id": "a", "text": "The Hero / Super Achiever"}, {"id": "b", "text": "The Scapegoat"}, {"id": "c", "text": "The Enabler / Caretaker"}, {"id": "d", "text": "The Mascot / Clown"}]'::jsonb, '["c"]', 'The Enabler/Caretaker is often a spouse or older child who makes excuses, covers up problems, and takes over the dysfunctional member''s responsibilities. The Hero is defined by high achievement as the "pride of the family," not by covering up.', false),
  ('family', 49, 'A family who attended a teaching session on Family Systems Theory makes several statements before their son''s discharge from the adolescent unit. Which statements indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"Problems in one of us can affect the whole family.\""}, {"id": "b", "text": "\"Our family works as an emotional unit, like a system.\""}, {"id": "c", "text": "\"Our son is best understood in the context of our family.\""}, {"id": "d", "text": "\"Patterns like drinking can repeat across generations.\""}, {"id": "e", "text": "\"If our son gets better, the rest of us won''t need to change.\""}]'::jsonb, '["a", "b", "c", "d"]', 'The family is an emotional unit, a system (b); individuals can only be understood in the context of family relationships (c); problems in one member affect the whole system (a); and patterns can be transmitted across generations (d). Expecting only the son to change (e) ignores that the system may maintain the problem.', true),
  ('family', 50, 'A 16-year-old admitted with depression asks the nurse, "Why do you keep asking about my parents and my brother? I''m the one who''s sick." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"It''s routine paperwork that every new client has to complete.\""}, {"id": "b", "text": "\"Your parents asked us to find out what goes on at home.\""}, {"id": "c", "text": "\"Your family may be the cause of your depression, so we need to know.\""}, {"id": "d", "text": "\"You can be understood best in the context of your family relationships.\""}]'::jsonb, '["d"]', 'Family Systems Theory holds that individuals can only be understood in the context of their family relationships, and the system affects each individual. Telling the client the family caused the depression blames one part of the system rather than viewing the family as a whole.', false),
  ('suicide', 1, 'A patient admitted with major depression says, "Lately I don''t see the point of anything." Earlier, the patient''s spouse asked staff not to mention suicide because it might "put the idea in his head." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"You have a wonderful family, so things will get better soon.\""}, {"id": "b", "text": "\"Are you having thoughts of suicide?\""}, {"id": "c", "text": "\"Why would you say there is no point to anything right now?\""}, {"id": "d", "text": "\"Your spouse is worried about you; let''s talk about that first.\""}]'::jsonb, '["b"]', 'Asking a patient directly about suicidal ideation does NOT plant the idea; direct questioning reduces risk by allowing the patient to express thoughts, so the spouse''s request should not stop the nurse from asking. The other responses reassure, question the reason, or shift the focus without directly assessing for suicidal ideation.', false),
  ('suicide', 2, 'A 45-year-old man in the emergency department says he plans to shoot himself tonight with the loaded handgun in his truck and that he intends to go through with it. Which actions should the nurse include in the IMMEDIATE plan of care? Select all that apply.', '[{"id": "a", "text": "Initiate 1:1 continuous observation"}, {"id": "b", "text": "Notify the provider immediately"}, {"id": "c", "text": "Obtain a signed no-suicide contract"}, {"id": "d", "text": "Complete an environmental safety sweep"}, {"id": "e", "text": "Plan check-ins every 30 minutes"}]'::jsonb, '["a", "b", "d"]', 'Plan + intent + access to means is an imminent emergency. 1:1 continuous observation (a), notifying the provider immediately because it is a medical emergency (b), and a complete environmental safety sweep to remove potential means (d) are priority actions. A no-suicide contract (c) is not evidence-based and should never be the sole or primary safety intervention. Check-ins every 30 minutes (e) fall short of the every-15-minutes minimum used even for ongoing care and do not replace 1:1 observation for active risk.', true),
  ('suicide', 3, 'The nurse on an inpatient psychiatric unit receives report on four patients with depression. Based on the data in the report, which patient should the nurse assess FIRST?', '[{"id": "a", "text": "Said, \"I wish I were dead,\" and denies any plan or intent to act"}, {"id": "b", "text": "Has thought about killing herself daily but has no method in mind"}, {"id": "c", "text": "Says she sees no hope for her future after losing her job last week"}, {"id": "d", "text": "Plans to take the pills she has hidden in her room tonight, and intends to"}]'::jsonb, '["d"]', 'Planning to take hidden (stockpiled) pills tonight with intent is plan + intent + access to means, the imminent-emergency level, so this patient is seen first. Hopelessness is a strong predictor, and passive ideation or active ideation without a method still needs assessment, but these do not reach plan + intent + means.', false),
  ('suicide', 4, 'During an admission interview, a 40-year-old patient going through a divorce says, "Sometimes I think I wouldn''t mind if I didn''t wake up." The patient denies any intent or plan to act. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Continue assessing, since passive ideation still requires assessment"}, {"id": "b", "text": "Initiate 1:1 continuous observation and notify the provider immediately"}, {"id": "c", "text": "Document the statement as an expected reaction to divorce and move on"}, {"id": "d", "text": "Arrange immediate psychiatric hospitalization for imminent suicide risk"}]'::jsonb, '["a"]', '"I wouldn''t mind if I didn''t wake up" with no intent or plan is passive ideation, which is lower risk but still requires assessment. 1:1 observation and immediate hospitalization are reserved for active risk and for plan + intent + access to means; dismissing the statement skips the required assessment.', false),
  ('suicide', 5, 'A nurse reviews the history of a 34-year-old woman admitted with depression: a cousin who died by suicide, an overdose 2 years ago, chronic migraine pain, and a breakup last month. Which finding places this patient at the HIGHEST risk for a future suicide attempt?', '[{"id": "a", "text": "Family history of suicide in a cousin"}, {"id": "b", "text": "Recent significant loss of a relationship"}, {"id": "c", "text": "Previous suicide attempt by overdose"}, {"id": "d", "text": "Chronic pain from frequent migraines"}]'::jsonb, '["c"]', 'A previous suicide attempt is the strongest single predictor of a future attempt. Family history, chronic pain, and a recent significant loss are all risk factors, but none is as strong a predictor as a prior attempt.', false),
  ('suicide', 6, 'A 70-year-old retired man is seen in a primary care clinic 2 months after his wife''s death. He lives alone, drinks several glasses of whiskey every night, has chronic pain from terminal cancer, and says his faith teaches that suicide is wrong. Which findings increase this patient''s suicide risk? Select all that apply.', '[{"id": "a", "text": "Elderly age of 70"}, {"id": "b", "text": "Substance abuse with alcohol"}, {"id": "c", "text": "Religious beliefs that discourage suicide"}, {"id": "d", "text": "Terminal illness with chronic pain"}, {"id": "e", "text": "Recent significant loss"}]'::jsonb, '["a", "b", "d", "e"]', 'Elderly age (65 or older) (a), substance abuse with alcohol, a major risk factor (b), chronic pain or terminal illness (d), and a recent significant loss such as the death of a spouse (e) all raise risk. Religious or spiritual beliefs that discourage suicide (c) are a protective factor, not a risk factor.', true),
  ('suicide', 7, 'A patient on a medical unit who was admitted after a car crash tells the nurse, "I have a belt in my bag, and I''m going to hang myself tonight." Which action should the nurse take FIRST?', '[{"id": "a", "text": "Leave the room to notify the provider immediately of the plan"}, {"id": "b", "text": "Ask the patient to sign a no-suicide contract before the end of the shift"}, {"id": "c", "text": "Stay with the patient and call for help to remove potential means"}, {"id": "d", "text": "Document the patient''s statements thoroughly in the medical record"}]'::jsonb, '["c"]', 'The first priority action for active suicidal risk is to stay with the patient and not leave the patient alone under any circumstances, while getting the means removed. Leaving the room to call the provider breaks this rule, a no-suicide contract is not evidence-based, and documentation follows safety actions.', false),
  ('suicide', 8, 'A patient with severe depression started an antidepressant 2 weeks ago. Today the patient is smiling, has more energy, and tells the nurse, "I finally know what I need to do." Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The medication is working, so suicide precautions can be reduced"}, {"id": "b", "text": "The patient is showing a new sense of purpose, a protective factor"}, {"id": "c", "text": "Risk is now at its lowest because the depression has started to lift"}, {"id": "d", "text": "Energy returns before mood fully lifts, so suicide risk increases"}]'::jsonb, '["d"]', 'Risk increases when antidepressants start working because energy returns before mood fully lifts, especially in the first 1–4 weeks; new energy plus a statement of having decided what to do calls for more vigilance, not less. Reading this as a sense of purpose or lower risk misses this high-risk period.', false),
  ('suicide', 9, 'A nurse is completing a suicide risk assessment for a 30-year-old patient with bipolar disorder who reported passive ideation last week. Which findings should the nurse document as protective factors? Select all that apply.', '[{"id": "a", "text": "Discharged from a psychiatric facility 1 week ago"}, {"id": "b", "text": "Identifies her two children as reasons for living"}, {"id": "c", "text": "Describes acting on impulse whenever she is upset"}, {"id": "d", "text": "Has a positive therapeutic relationship with her provider"}, {"id": "e", "text": "Has no firearms in the home"}]'::jsonb, '["b", "d", "e"]', 'Reasons for living such as children (b), a positive therapeutic relationship (d), and means restriction with no firearms in the home (e) reduce suicide risk. Recent discharge from a psychiatric facility (a) and impulsivity (c) are modifiable/situational risk factors, not protective factors.', true),
  ('suicide', 10, 'A nurse in an outpatient mental health clinic has four voicemails to return after a holiday weekend. Which patient should the nurse call FIRST?', '[{"id": "a", "text": "A patient discharged from an inpatient unit 8 months ago who needs a refill"}, {"id": "b", "text": "A patient who left inpatient psychiatric care 3 weeks ago and missed a visit"}, {"id": "c", "text": "A patient with depression who wants information about a local support group"}, {"id": "d", "text": "A patient stable on the same antidepressant for 2 years who reports poor sleep"}]'::jsonb, '["b"]', 'Suicide risk is highest within the first 30–90 days after discharge from inpatient psychiatric care, so the patient discharged 3 weeks ago who missed a visit is called first. The patient discharged 8 months ago is outside that window, and the other two calls do not describe a high-risk period.', false),
  ('suicide', 11, 'A nursing student caring for a patient on suicide precautions tells the nurse, "She signed a no-suicide contract with me, so I think we can stop watching her so closely." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Contracts are not evidence-based; we use structured safety planning instead.\""}, {"id": "b", "text": "\"Good work; a signed contract shows that she is now committed to staying safe.\""}, {"id": "c", "text": "\"Have the provider sign it too, so that the contract becomes legally binding.\""}, {"id": "d", "text": "\"Since she signed it, we can reduce her checks to once every hour tonight.\""}]'::jsonb, '["a"]', 'No-suicide contracts are NOT evidence-based, may give false reassurance, and should never be the sole or primary safety intervention; structured safety planning is used instead. Reducing observation or relying on a co-signed contract acts on that false reassurance.', false),
  ('suicide', 12, 'A patient admitted for suicidal ideation is preparing for discharge and says, "Just give me something to sign so I can go home." The nurse works with the patient to develop a safety plan. Which components should the nurse include? Select all that apply.', '[{"id": "a", "text": "Warning signs that a crisis is developing"}, {"id": "b", "text": "Internal coping strategies the patient can do alone"}, {"id": "c", "text": "People the patient can ask for support"}, {"id": "d", "text": "A no-suicide contract signed by the patient"}, {"id": "e", "text": "Making the environment safe by removing access to means"}]'::jsonb, '["a", "b", "c", "e"]', 'The Stanley-Brown safety plan includes warning signs that a crisis is developing (a), internal coping strategies (b), people the patient can ask for support (c), and making the environment safe by removing access to means (e). A signed no-suicide contract (d) is not evidence-based and may provide false reassurance; structured safety planning replaces it.', true),
  ('suicide', 13, 'The father of a 16-year-old who is being discharged after a suicide attempt says, "We keep a hunting rifle in the garage, but it''s locked and she doesn''t know the code." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Keeping it locked is enough as long as the code stays private.\""}, {"id": "b", "text": "\"Ask her to promise that she will stay out of the garage alone.\""}, {"id": "c", "text": "\"Removing firearms from the home is one of the most effective steps.\""}, {"id": "d", "text": "\"Focus on her moods for now; the rifle matters far less than her therapy.\""}]'::jsonb, '["c"]', 'Means restriction, removing firearms from the home, is one of the most effective suicide prevention strategies, and means restriction counseling is extremely effective. A locked rifle that remains in the home is still access to lethal means, and a promise is not a safety measure.', false),
  ('suicide', 14, 'A patient with schizophrenia is pacing in the hallway and tells the nurse, "The voices keep saying I have to die tonight." The patient has no history of suicide attempts. Which interpretation and action by the nurse is BEST?', '[{"id": "a", "text": "Organized plan; ask the patient to agree to a written safety contract now"}, {"id": "b", "text": "Rational thinking lost; stay with the patient and notify the provider"}, {"id": "c", "text": "Social support lacking; arrange a family meeting for tomorrow morning"}, {"id": "d", "text": "No previous attempt; reassess the patient at the next routine check"}]'::jsonb, '["b"]', 'Command hallucinations represent "Rational thinking lost" on the SAD PERSONS scale and signal active risk, so the nurse stays with the patient and notifies the provider. Lack of a previous attempt does not make this safe to defer, and the statement describes command hallucinations rather than an organized plan.', false),
  ('suicide', 15, 'The nurse is reinforcing discharge teaching with the family of a 19-year-old patient who was hospitalized after a suicide attempt and started an antidepressant 1 week ago. Which statements by family members indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "\"His risk will drop as soon as the antidepressant starts working.\""}, {"id": "b", "text": "\"We can call 988 if he is ever in crisis.\""}, {"id": "c", "text": "\"Once he has been home for 30 days, his risk is over.\""}, {"id": "d", "text": "\"His no-suicide contract means his medications can stay at home.\""}, {"id": "e", "text": "\"Removing the firearms from our home will help keep him safe.\""}]'::jsonb, '["a", "c", "d"]', 'Risk increases, not drops, when antidepressants start working because energy returns before mood lifts (a). Post-discharge risk remains highest for 30–90 days, not just 30 (c). A no-suicide contract is not evidence-based, and means restriction includes removing medications from home (d). Calling 988 (b) and removing firearms (e) are correct.', true),
  ('suicide', 16, 'An intoxicated patient is brought to the emergency department after losing his job that day and says, "Maybe I''ll just end it all." His friend tells the nurse, "He''s just drunk; he''ll be fine once he sobers up." Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Alcohol lowers inhibition and increases impulsivity, so his risk is higher.\""}, {"id": "b", "text": "\"Statements made while drunk are unreliable, so we will ask him again tomorrow.\""}, {"id": "c", "text": "\"His risk is low right now because he has not described a specific plan.\""}, {"id": "d", "text": "\"Alcohol use is a non-modifiable factor, so it does not change his risk.\""}]'::jsonb, '["a"]', 'On the SAD PERSONS scale, ethanol/substance use lowers inhibition and increases impulsivity, and alcohol is a major risk factor, added here to a recent significant loss. Dismissing the statement until he is sober, or calling the risk low because no plan was stated, ignores these factors.', false),
  ('suicide', 17, 'The charge nurse listens to a nurse give an SBAR handoff for a patient admitted yesterday after an intentional overdose who remains on 1:1 observation. Which action by the reporting nurse requires follow-up?', '[{"id": "a", "text": "Repeating the patient''s exact statements about wanting to die"}, {"id": "b", "text": "Describing the interventions used and the patient''s response"}, {"id": "c", "text": "Stating the current observation level and when it was started"}, {"id": "d", "text": "Leaving suicide risk out of the SBAR handoff"}]'::jsonb, '["d"]', 'Suicide risk must always be included in SBAR/handoff reports, even when it is documented elsewhere. Sharing the patient''s statements, interventions, response, and observation level is appropriate handoff content.', false),
  ('suicide', 18, 'A community mental health nurse is reviewing a caseload of patients with depression to plan home visits this week. Which patients are currently in a period of HIGHEST suicide risk? Select all that apply.', '[{"id": "a", "text": "A patient stable on the same antidepressant dose for 3 years"}, {"id": "b", "text": "A patient following a significant loss of a loved one 2 weeks ago"}, {"id": "c", "text": "A patient facing anniversaries of traumatic events this week"}, {"id": "d", "text": "A patient discharged from inpatient care 2 years ago and working"}, {"id": "e", "text": "A patient discharged from inpatient psychiatric care 6 weeks ago"}]'::jsonb, '["b", "c", "e"]', 'Highest-risk periods include following a significant loss (b), anniversaries of traumatic events (c), and the first 30–90 days after inpatient psychiatric discharge, which includes 6 weeks (e). A patient stable on the same antidepressant for years (a) is past the early treatment window, and discharge 2 years ago (d) is well beyond 90 days.', true),
  ('suicide', 19, 'A patient assessed at moderate suicide risk is on routine precautions. The UAP reports, "I''ve been checking on him every 30 minutes, and he seems fine." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"That''s fine; every 30 minutes is enough when there is no plan.\""}, {"id": "b", "text": "\"Check-ins are needed every 15 minutes minimum.\""}, {"id": "c", "text": "\"You can check hourly now, since he seems to be fine to you today.\""}, {"id": "d", "text": "\"Ask him to sign a no-suicide contract so that checks can be hourly.\""}]'::jsonb, '["b"]', 'Ongoing nursing interventions include frequent check-ins every 15 minutes minimum, and more often if risk is high. Checks every 30 minutes or hourly are too infrequent, and a no-suicide contract is not evidence-based and cannot justify less observation.', false),
  ('suicide', 20, 'A patient tells the nurse, "I''ve been thinking about killing myself a lot this week, but I haven''t figured out how I''d do it." The patient has no access to firearms. Which risk level is the MOST accurate classification of this ideation?', '[{"id": "a", "text": "Lower, because there is no active intent"}, {"id": "b", "text": "High, because a method has been considered"}, {"id": "c", "text": "Moderate, because there is no specific plan"}, {"id": "d", "text": "Imminent, because the thoughts are so frequent"}]'::jsonb, '["c"]', 'Active thoughts of killing self with no specific plan or method identified is active ideation without a plan, classified as moderate risk. High risk requires a specific method and plan, and imminent risk requires plan, intent, and access to means; "lower" applies to passive ideation.', false),
  ('suicide', 21, 'A 28-year-old man admitted after a suicide attempt has a family history of suicide, drinks heavily, has had few friends since moving to a new city, has a history of childhood abuse, and keeps a firearm at home. Which risk factors can be directly targeted by nursing interventions before discharge? Select all that apply.', '[{"id": "a", "text": "Substance abuse with alcohol"}, {"id": "b", "text": "Family history of suicide"}, {"id": "c", "text": "History of trauma or abuse"}, {"id": "d", "text": "Social isolation and lack of support"}, {"id": "e", "text": "Access to lethal means"}]'::jsonb, '["a", "d", "e"]', 'Substance abuse (a), social isolation and lack of support (d), and access to lethal means (e) are modifiable/situational risk factors that interventions such as means restriction counseling and involving support people can change. Family history of suicide (b) and a history of trauma or abuse (c) are non-modifiable risk factors.', true),
  ('suicide', 22, 'A patient says, "I''ve thought about overdosing on Friday night," and states that she intends to do it. She has never been hospitalized. Which additional finding would MOST clearly indicate that her risk is imminent?', '[{"id": "a", "text": "She has stockpiled medications at home"}, {"id": "b", "text": "She says she sees no hope for her future"}, {"id": "c", "text": "She has a family history of suicide"}, {"id": "d", "text": "She made a suicide attempt 5 years ago"}]'::jsonb, '["a"]', 'A plan and intent combined with access to the means, such as stockpiled medications, is the imminent-emergency level. Hopelessness and a previous attempt are strong predictors and family history is a risk factor, but the imminent level is defined by plan + intent + means.', false),
  ('suicide', 23, 'A nurse is reviewing crisis resources with a patient who is being discharged after 10 days of inpatient care for suicidal ideation. Which statement by the patient indicates understanding of the teaching?', '[{"id": "a", "text": "\"If I have those thoughts again, I''ll wait until my next appointment.\""}, {"id": "b", "text": "\"I''m safe now, so I won''t need any crisis numbers once I get home.\""}, {"id": "c", "text": "\"Once I''m home my risk is gone, so I can stop using my safety plan.\""}, {"id": "d", "text": "\"I can call the National Suicide Prevention Lifeline at 988.\""}]'::jsonb, '["d"]', 'Nurses provide crisis line numbers, including the National Suicide Prevention Lifeline at 988. The other statements ignore that risk is highest shortly after discharge and that crisis resources are part of the safety plan.', false),
  ('suicide', 24, 'An adult patient on suicide precautions is creating a safety plan with the nurse. The patient''s sister arrives and asks to help write the plan. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Invite the sister in, because family involvement lowers suicide risk"}, {"id": "b", "text": "Ask the sister to leave, because family may not take part in planning"}, {"id": "c", "text": "Ask for patient consent before involving family in safety planning"}, {"id": "d", "text": "Give the sister a copy of the plan once the patient has finished it"}]'::jsonb, '["c"]', 'Family and support systems are involved in safety planning with the patient''s consent, so consent is obtained first. Inviting the sister in or sharing the plan without consent skips this step, and excluding family ignores that support people are part of the plan.', false),
  ('suicide', 25, 'Using the Columbia Suicide Severity Rating Scale, the nurse interviews a patient who currently denies suicidal thoughts. Which reported findings should the nurse document as suicidal behavior rather than ideation? Select all that apply.', '[{"id": "a", "text": "Actual attempt with pills last year"}, {"id": "b", "text": "Aborted attempt before tying a cord"}, {"id": "c", "text": "Wish to be dead, reported last month"}, {"id": "d", "text": "Preparatory actions such as stockpiling pills"}, {"id": "e", "text": "Active ideation with no specific plan"}]'::jsonb, '["a", "b", "d"]', 'The C-SSRS assesses suicidal behavior: actual attempts (a), aborted attempts (b), and preparatory actions (d), plus lethality of past attempts. A wish to be dead (c) is passive ideation and active ideation with no plan (e) is ideation, not behavior.', true),
  ('suicide', 26, 'A 52-year-old patient with depression and chronic pain says she is managing, but her husband reports that she has stopped making any plans. Which question by the nurse BEST assesses the factor that MOST strongly predicts suicide?', '[{"id": "a", "text": "\"How many hours are you sleeping each night?\""}, {"id": "b", "text": "\"How long have you been feeling depressed?\""}, {"id": "c", "text": "\"Do you see any hope for your future?\""}, {"id": "d", "text": "\"How would you rate your pain right now?\""}]'::jsonb, '["c"]', 'Hopelessness is a stronger predictor of suicide than depression, and it is assessed by asking, "Do you see any hope for your future?" Asking about the length of depression or pain addresses risk factors that predict suicide less strongly.', false),
  ('suicide', 27, 'A patient on suicide precautions tells the nurse, "Every nurse here is different, and none of you will stick around anyway." Which approach by the nursing staff will BEST build a therapeutic relationship with this patient?', '[{"id": "a", "text": "Being non-judgmental, consistent, and hopeful"}, {"id": "b", "text": "Rotating nurses daily so the patient does not become dependent"}, {"id": "c", "text": "Avoiding talk about suicide to keep each conversation upbeat"}, {"id": "d", "text": "Agreeing to keep any suicidal thoughts private from the team"}]'::jsonb, '["a"]', 'A therapeutic relationship is built by being non-judgmental, consistent, and hopeful. Rotating staff undermines consistency, avoiding talk of suicide contradicts asking directly, and suicide risk must be communicated in handoff rather than kept private.', false),
  ('suicide', 28, 'A patient admitted after voicing suicidal ideation has been on ongoing suicide precautions for 3 days and is starting to plan for discharge. Which ongoing nursing interventions are appropriate? Select all that apply.', '[{"id": "a", "text": "Avoid mentioning suicide so the patient can focus on recovery"}, {"id": "b", "text": "Monitor for changes in mood, behavior, and statements"}, {"id": "c", "text": "Provide crisis line numbers for use after discharge"}, {"id": "d", "text": "Discuss removing firearms and medications from home"}, {"id": "e", "text": "Reduce checks as soon as the patient''s energy improves"}]'::jsonb, '["b", "c", "d"]', 'Ongoing interventions include monitoring for changes in mood, behavior, and statements (b), providing crisis line numbers such as 988 (c), and means restriction counseling about removing firearms and medications from home (d). Avoiding the topic (a) contradicts asking directly, and returning energy (e) calls for more vigilance because the patient may now have energy to act.', true),
  ('suicide', 29, 'In an outpatient clinic, a patient says he keeps a rope in his car, plans to hang himself from a beam in his garage this weekend, and intends to do it. Which disposition is MOST appropriate for this patient?', '[{"id": "a", "text": "Outpatient follow-up in 1 week with a written safety plan"}, {"id": "b", "text": "Immediate psychiatric hospitalization for imminent risk"}, {"id": "c", "text": "A no-suicide contract and a phone check-in tomorrow"}, {"id": "d", "text": "Means restriction counseling, then discharge home with family"}]'::jsonb, '["b"]', 'Ideation with a specific plan, intent, and access to means is the highest risk and requires immediate psychiatric hospitalization. Safety planning and means restriction counseling are ongoing interventions that do not replace hospitalization at this level, and no-suicide contracts are not evidence-based.', false),
  ('suicide', 30, 'A patient is being discharged 10 days after starting an antidepressant for major depression with suicidal ideation. Which instruction to the family is the PRIORITY?', '[{"id": "a", "text": "\"Expect the medication to fully improve his mood within a few days.\""}, {"id": "b", "text": "\"Watch closely for weeks; energy returns before mood lifts.\""}, {"id": "c", "text": "\"His suicide risk falls as soon as the antidepressant begins working.\""}, {"id": "d", "text": "\"Remove firearms only; medications at home do not need to be secured.\""}]'::jsonb, '["b"]', 'The first few weeks of antidepressant treatment are a highest-risk period because energy returns before mood fully lifts, giving the patient energy to act. Risk does not fall when the drug begins working, and means restriction includes medications as well as firearms.', false),
  ('suicide', 31, 'The mother of a 15-year-old who has been withdrawn since a breakup asks the school nurse, "Should I ask her if she''s thinking about suicide, or will that make her more likely to do it?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Asking directly does not plant the idea; it can reduce risk.\""}, {"id": "b", "text": "\"It is better to wait until she brings up the topic on her own.\""}, {"id": "c", "text": "\"Teenagers rarely act on these thoughts, so asking isn''t needed.\""}, {"id": "d", "text": "\"Ask her friends instead, so that she does not feel singled out.\""}]'::jsonb, '["a"]', 'Asking directly about suicidal ideation does NOT plant the idea; direct questioning reduces risk by allowing the person to express thoughts. Adolescents are a higher-risk age group, and a recent relationship loss adds risk, so waiting or minimizing is unsafe.', false),
  ('suicide', 32, 'The nurse reviews C-SSRS results for five patients on a crisis stabilization unit. Which patients require IMMEDIATE intervention? Select all that apply.', '[{"id": "a", "text": "Wish to be dead, with no active thoughts of acting"}, {"id": "b", "text": "Active ideation with plan and intent to act"}, {"id": "c", "text": "Active ideation with no plan identified yet"}, {"id": "d", "text": "Plan, intent, and access to a loaded firearm"}, {"id": "e", "text": "Passive ideation that began after a recent loss"}]'::jsonb, '["b", "d"]', 'Active ideation with plan and intent to act is high risk and requires immediate intervention (b), and plan + intent + means such as a loaded firearm is an imminent emergency (d). A wish to be dead (a) and passive ideation (e) are lower risk, and active ideation with no plan (c) is moderate; all still need assessment but not immediate intervention.', true),
  ('suicide', 33, 'A 66-year-old patient with terminal cancer and chronic pain tells the nurse during a dressing change, "I''d rather not wake up than go through more of this." Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Reassure the patient that hospice will keep the pain controlled"}, {"id": "b", "text": "Treat the statement as expected near the end of life and chart it"}, {"id": "c", "text": "Ask directly about suicidal thoughts; age and illness raise risk"}, {"id": "d", "text": "Ask the family to visit more often so the patient feels less alone"}]'::jsonb, '["c"]', 'Elderly age (65 or older) and chronic pain or terminal illness are risk factors, and the statement suggests passive ideation, which still requires assessment, so the nurse asks directly. Reassurance or charting the comment as expected skips the assessment.', false),
  ('suicide', 34, 'Four patients on a mood disorders unit are being evaluated before a change in observation level. Which patient''s finding should the nurse report to the provider as the MOST concerning?', '[{"id": "a", "text": "Severe depression ratings, but she says her grandchildren keep her going"}, {"id": "b", "text": "Moderate depression ratings, and he is looking forward to a new job"}, {"id": "c", "text": "Severe depression ratings, and she is attending every group session"}, {"id": "d", "text": "Mild depression ratings, but he says things will never get better"}]'::jsonb, '["d"]', 'Hopelessness, the belief that things will never get better, is a stronger predictor of suicide than depression and is the highest risk indicator, even when depression is mild. The patients with more severe depression describe reasons for living or engagement, which are protective.', false),
  ('suicide', 35, 'A husband and wife are both being treated for major depression after the death of their son. The wife asks why her husband was rated at higher suicide risk than she was, even though her symptoms are more severe. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Men tend to use more lethal methods, so male gender raises risk.\""}, {"id": "b", "text": "\"Men usually have fewer protective factors, such as faith or family.\""}, {"id": "c", "text": "\"Your symptoms are more severe, so your own risk is actually higher.\""}, {"id": "d", "text": "\"His risk is higher because grief always affects men more deeply.\""}]'::jsonb, '["a"]', 'Male gender is a non-modifiable risk factor because men use more lethal methods. Symptom severity alone does not outweigh this factor, and the other explanations are not reasons given for gender-related risk.', false),
  ('suicide', 36, 'A patient on 1:1 observation told the nurse earlier in the shift, "I''ll find a way to do it, even here." The nurse completed a room sweep and notified the provider. Which documentation entry is MOST complete?', '[{"id": "a", "text": "Calm behavior noted; suicide precautions continued per protocol"}, {"id": "b", "text": "Nurse''s opinion that the patient is seeking attention from staff"}, {"id": "c", "text": "A concerning remark noted; staff will continue to monitor closely"}, {"id": "d", "text": "All observations, interventions, and patient statements"}]'::jsonb, '["d"]', 'The nurse documents all observations, interventions, and patient statements thoroughly. A vague note about a "concerning remark" or calm behavior omits the patient''s statement and the actions taken, and personal opinions are not a substitute for observations.', false),
  ('suicide', 37, 'A patient in the emergency department reports active thoughts of killing himself. Which questions should the nurse ask to determine how high the patient''s suicide risk is? Select all that apply.', '[{"id": "a", "text": "\"Do you have a specific method and plan?\""}, {"id": "b", "text": "\"Do you intend to carry out the plan?\""}, {"id": "c", "text": "\"Will you promise me you won''t hurt yourself?\""}, {"id": "d", "text": "\"Do you have access to the means, like firearms?\""}, {"id": "e", "text": "\"Do you see any hope for your future?\""}]'::jsonb, '["a", "b", "d", "e"]', 'Risk level rises with a specific method and plan (a), intent to carry it out (b), and access to the means (d); hopelessness, assessed by asking about hope for the future (e), is the strongest psychological predictor. Asking for a promise (c) is a no-suicide contract, which is not evidence-based and may give false reassurance.', true),
  ('suicide', 38, 'The nurse reviews the admission assessments of five patients on a psychiatric unit. Which patient statements should the nurse classify as passive suicidal ideation? Select all that apply.', '[{"id": "a", "text": "\"I''ll use the pills in my medicine cabinet Friday night.\""}, {"id": "b", "text": "\"I wouldn''t mind if I didn''t wake up tomorrow.\""}, {"id": "c", "text": "\"I keep thinking about killing myself, but I don''t know how.\""}, {"id": "d", "text": "\"I wish I were dead.\""}, {"id": "e", "text": "\"I''ve decided to do it, and I have the gun ready.\""}]'::jsonb, '["b", "d"]', '"I wish I were dead" (d) and "I wouldn''t mind if I didn''t wake up" (b) are passive ideation with no active intent or plan. A specific method and timing (a) is active ideation with a plan, thoughts of killing self without a method (c) is active ideation with no plan, and a decision plus a ready gun (e) is plan + intent + means.', true),
  ('suicide', 39, 'A patient admitted this morning has a plan to overdose and says she intends to act on it as soon as she can. The charge nurse is assigning staff for the shift. Which observation level is MOST appropriate for this patient?', '[{"id": "a", "text": "Checks every 15 minutes with the door left open"}, {"id": "b", "text": "1:1 continuous observation by an assigned sitter"}, {"id": "c", "text": "Checks every 30 minutes with a room near the station"}, {"id": "d", "text": "Hourly checks once all sharps are removed from the room"}]'::jsonb, '["b"]', 'A plan plus intent is active suicidal risk, which calls for 1:1 continuous observation (a 1:1 sitter or constant monitoring). Checks every 15 minutes are the minimum for ongoing care, not for a patient with plan and intent, and 30-minute or hourly checks are unsafe.', false),
  ('suicide', 40, 'A UAP is assigned to provide 1:1 continuous observation for a patient who stated a plan to hang himself. Which actions by the UAP require follow-up? Select all that apply.', '[{"id": "a", "text": "Leaves the patient alone briefly while the patient naps"}, {"id": "b", "text": "Reports the patient''s statements to the nurse"}, {"id": "c", "text": "Allows the patient to keep cords and belts in the room"}, {"id": "d", "text": "Stays with the patient during visiting hours"}, {"id": "e", "text": "Removes a plastic bag from the patient''s room"}]'::jsonb, '["a", "c"]', 'A patient at active risk must not be left alone under any circumstances (a), and cords and belts are potential means that must be removed (c). Reporting statements (b), staying with the patient (d), and removing plastic bags (e) are correct actions.', true),
  ('suicide', 41, 'After a long conversation, a patient tells the nurse about a plan to overdose and then says, "Please promise you won''t tell anyone. You''re the only one I trust." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"I promise to keep this between us, since trust matters so much to you.\""}, {"id": "b", "text": "\"I can''t keep this secret; I must notify the provider to keep you safe.\""}, {"id": "c", "text": "\"I''ll keep it secret if you agree to sign a no-suicide contract with me.\""}, {"id": "d", "text": "\"Why would you want to keep something this serious from your care team?\""}]'::jsonb, '["b"]', 'Active suicidal risk is a medical emergency that requires notifying the provider immediately, and suicide risk is always communicated in handoff, so the nurse cannot keep it secret. Making a secret promise or trading secrecy for a no-suicide contract leaves the patient unsafe.', false),
  ('suicide', 42, 'A patient reports, "I''ve thought about using the pills in my medicine cabinet on Friday night," but says she has no intention of acting on it. Her husband has since removed all medications from the home. Which risk level BEST describes this patient''s current ideation?', '[{"id": "a", "text": "Lower, because she has no intent"}, {"id": "b", "text": "Moderate, because the means are gone"}, {"id": "c", "text": "High, due to a specific plan"}, {"id": "d", "text": "Very high, because a date is chosen"}]'::jsonb, '["c"]', 'A specific method and plan (pills, Friday night) is active ideation with a plan, which is high risk even without intent. Very high requires a plan AND intent, and moderate applies to active ideation with no specific plan; removing means lowers imminence but does not erase the plan.', false),
  ('suicide', 43, 'A 17-year-old boy is admitted after cutting his wrists. He uses cannabis daily, hears voices telling him he is worthless, and has a supportive older sister and a youth pastor he trusts. Using the SAD PERSONS scale, which findings increase his risk? Select all that apply.', '[{"id": "a", "text": "Very young age of 17"}, {"id": "b", "text": "Daily substance use"}, {"id": "c", "text": "Command hallucinations"}, {"id": "d", "text": "Supportive older sister"}, {"id": "e", "text": "Trusted youth pastor"}]'::jsonb, '["a", "b", "c"]', 'SAD PERSONS counts very young age (teens) (a), ethanol/substance use, which lowers inhibition (b), and rational thinking lost, including command hallucinations (c). A supportive sister (d) and a trusted pastor (e) reflect social support and spiritual connection, which are protective rather than risk factors.', true),
  ('suicide', 44, 'A 50-year-old woman with depression who lives with her teenage daughter tells the nurse, "I''ve picked the bridge, the date, and the time." Which SAD PERSONS factor is MOST clearly shown by her statement?', '[{"id": "a", "text": "Rational thinking lost"}, {"id": "b", "text": "Organized plan"}, {"id": "c", "text": "Social support lacking"}, {"id": "d", "text": "No significant other"}]'::jsonb, '["b"]', 'A specific method, timeline, and place is an organized plan on the SAD PERSONS scale. Rational thinking lost refers to psychosis or command hallucinations, and she lives with her daughter, so the stem gives no evidence of absent support or relationships.', false),
  ('suicide', 45, 'Two weeks after starting a safety plan, a patient with recurrent suicidal ideation meets with the nurse. Which finding BEST indicates that the patient''s protective factors have been strengthened?', '[{"id": "a", "text": "Describes a renewed sense of purpose or meaning in life"}, {"id": "b", "text": "Was discharged from inpatient psychiatric care last month"}, {"id": "c", "text": "Has stopped contact with friends to get more rest at home"}, {"id": "d", "text": "Reports that energy has improved before mood has lifted"}]'::jsonb, '["a"]', 'A sense of purpose or meaning in life is a protective factor. Recent discharge and social isolation are risk factors, and energy returning before mood lifts signals a higher-risk period.', false),
  ('suicide', 46, 'A patient discharged from an inpatient psychiatric unit 2 weeks ago tells the clinic nurse, "I feel so much better that I''d like to cancel my follow-up visits for the next few months." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Let''s cut back to one visit every 6 months, since you are doing so well now.\""}, {"id": "b", "text": "\"Feeling better means your risk period has passed, so cancelling is reasonable.\""}, {"id": "c", "text": "\"You can cancel now and call the clinic if the thoughts come back in the future.\""}, {"id": "d", "text": "\"Risk is highest 30 to 90 days after discharge, so keep your visits.\""}]'::jsonb, '["d"]', 'Post-discharge risk is highest in the first 30–90 days after inpatient discharge, so this patient, 2 weeks out, is still in the highest-risk window. Feeling better does not end that period, and access to mental health care is a protective factor.', false),
  ('suicide', 47, 'At 0300, a patient on a medical-surgical unit tells the nurse he hid a razor blade and plans to cut his wrists before morning. The nurse has stayed with the patient, called for help, and the razor has been removed. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Wait to tell the provider at morning rounds, since the razor is gone"}, {"id": "b", "text": "Finish all charting first, then call the provider at shift change"}, {"id": "c", "text": "Notify the provider immediately; this is a medical emergency"}, {"id": "d", "text": "Reassure the patient that he will feel better after some sleep"}]'::jsonb, '["c"]', 'For active suicidal risk, the nurse notifies the provider immediately because it is a medical emergency; removing one item does not end the risk. Waiting for rounds or completing charting first delays a required priority action.', false),
  ('suicide', 48, 'A 58-year-old woman with depression has lived alone since her divorce, has no close relationships, and spends most days in her apartment. She denies a plan. Which nursing intervention BEST addresses her modifiable risk factor?', '[{"id": "a", "text": "Focus care on the divorce, since a past loss cannot be changed"}, {"id": "b", "text": "Explain that her age places her in the highest-risk age group"}, {"id": "c", "text": "Teach that her gender is the main reason her risk is elevated"}, {"id": "d", "text": "Identify support people and social settings for distraction"}]'::jsonb, '["d"]', 'Social isolation and lack of support is a modifiable risk factor, addressed by identifying people she can ask for support and social contacts and settings that provide distraction. She is not in the 65-or-older age group, and male (not female) gender is the higher-risk gender.', false),
  ('suicide', 49, 'A patient at imminent suicide risk is being transferred from the emergency department to the psychiatric unit. Which information must the nurse include in the handoff report? Select all that apply.', '[{"id": "a", "text": "The patient''s suicide risk and stated plan"}, {"id": "b", "text": "Patient statements and interventions done"}, {"id": "c", "text": "A signed contract, so 1:1 observation may stop"}, {"id": "d", "text": "Risk is low now that the means were removed"}, {"id": "e", "text": "No suicide details, to protect confidentiality"}]'::jsonb, '["a", "b"]', 'Suicide risk is always included in SBAR/handoff reports (a), and patient statements and interventions are documented and communicated (b). A no-suicide contract (c) is not evidence-based and cannot justify stopping 1:1, removing means (d) does not make imminent risk low, and omitting suicide details (e) violates the handoff rule.', true),
  ('suicide', 50, 'The nurse at a senior center screens four members for suicide risk. Which member should the nurse refer for further assessment FIRST?', '[{"id": "a", "text": "A 72-year-old woman with arthritis who walks with friends each morning"}, {"id": "b", "text": "A 66-year-old woman who volunteers weekly and lives with her daughter"}, {"id": "c", "text": "A 70-year-old man with strong religious beliefs and a large family"}, {"id": "d", "text": "A 68-year-old widowed man who drinks daily and owns firearms"}]'::jsonb, '["d"]', 'This man combines male gender, elderly age, alcohol use (a major risk factor), and access to lethal means such as firearms. The others are elderly but have protective factors such as a strong social support network, a sense of purpose, and religious beliefs that discourage suicide.', false),
  ('ddd', 1, 'An 82-year-old resident of a long-term care facility was oriented and conversing normally yesterday. Since last night the resident''s alertness fluctuates from hour to hour, attention drifts mid-sentence, and the resident points at ''bugs'' crawling on the wall. The urine is dark and foul-smelling. Which action is the nurse''s PRIORITY?', '[{"id": "a", "text": "Start the dementia safety plan, including door alarms and an identification bracelet for the resident"}, {"id": "b", "text": "Identify and treat the underlying cause, such as a possible UTI"}, {"id": "c", "text": "Reorient the resident frequently by stating name, date, place, and situation at every contact"}, {"id": "d", "text": "Apply restraints so the resident cannot pick at the sheets or climb out of bed overnight"}]'::jsonb, '["b"]', 'Sudden onset, fluctuating consciousness, and visual hallucinations indicate delirium, and identifying and treating the underlying cause (UTI is common in the elderly) is the top priority. Reorienting is a helpful delirium intervention but does not treat the cause; restraints increase agitation.', false),
  ('ddd', 2, 'A 79-year-old client admitted with pneumonia is confused. The daughter reports that her mother ''has been getting more forgetful for about three years'' and asks whether today''s confusion is just more of the same. Which assessment finding MOST strongly indicates a new delirium rather than progression of the dementia?', '[{"id": "a", "text": "Affect is flat, with occasional mood swings that the family has noticed recently"}, {"id": "b", "text": "The client gets lost in familiar places and has difficulty with complex tasks"}, {"id": "c", "text": "Memory is impaired for recent events, and long-term memory is now affected too"}, {"id": "d", "text": "Consciousness is fluctuating and confused, with a sudden onset"}]'::jsonb, '["d"]', 'Delirium has a sudden onset (hours to days) with fluctuating, confused consciousness, whereas dementia is gradual and consciousness is initially clear. Short-term then long-term memory loss, flat affect with late mood swings, and getting lost in familiar places all fit the existing dementia.', false),
  ('ddd', 3, 'A nurse on a medical unit assesses a 77-year-old client who was admitted 2 days ago and is now acutely confused. Which findings support delirium rather than dementia or depression? Select all that apply.', '[{"id": "a", "text": "Visual hallucinations of insects on the wall"}, {"id": "b", "text": "Memory decline that has progressed over years"}, {"id": "c", "text": "Selective memory gaps with a hopeless mood"}, {"id": "d", "text": "Sudden onset of confusion during the evening"}, {"id": "e", "text": "Fluctuating consciousness, drowsy then agitated"}]'::jsonb, '["a", "d", "e"]', 'Sudden onset (hours to days), visual hallucinations, and fluctuating consciousness are delirium findings. Memory decline progressing over years describes dementia, and selective gaps (''I can''t remember'') with hopelessness describe depression.', true),
  ('ddd', 4, 'A 74-year-old client is brought to the clinic by his son, who reports that over the past 2 months his father has stopped gardening, sleeps most of the day, and answers many questions with ''I can''t remember.'' The client is alert with clear consciousness and says he feels worthless. Which condition do these findings MOST likely reflect?', '[{"id": "a", "text": "Depression, with selective memory gaps and clear consciousness"}, {"id": "b", "text": "Middle-stage dementia, with increasing memory loss and repetitive behavior"}, {"id": "c", "text": "Early-stage dementia, with recent memory loss and personality changes"}, {"id": "d", "text": "Delirium, with short-term memory impairment and fluctuating consciousness"}]'::jsonb, '["a"]', 'Gradual onset over weeks to months, clear consciousness with low energy, selective memory gaps (''I can''t remember''), anhedonia, hypersomnia, and worthlessness describe depression. Delirium would be sudden with fluctuating consciousness, and dementia develops over months to years.', false),
  ('ddd', 5, 'A 76-year-old client is on postoperative day 2 after hip surgery. The client receives an opioid narcotic every 3 hours for pain and a benzodiazepine at bedtime, and since this morning has been disoriented and frightened. Which action by the nurse is the BEST initial step toward resolving the confusion?', '[{"id": "a", "text": "Tell the family that confusion like this is likely permanent at the client''s age"}, {"id": "b", "text": "Request an anticholinergic sleep aid so the client rests better tonight and tomorrow"}, {"id": "c", "text": "Begin dementia communication strategies and gentle redirection only"}, {"id": "d", "text": "Review the drugs, such as narcotics and benzodiazepines, as a cause"}]'::jsonb, '["d"]', 'Drugs such as narcotics and benzodiazepines are a common cause of delirium, and identifying and treating the cause is the top priority. Anticholinergic medications should be avoided in delirium, and delirium is reversible, not permanent.', false),
  ('ddd', 6, 'A 68-year-old client develops acute confusion on postoperative day 3. The nurse reviews the history and medication administration record. Which findings could be contributing to the client''s delirium? Select all that apply.', '[{"id": "a", "text": "Narcotics given every 4 hours for pain"}, {"id": "b", "text": "Receiving steroids as ordered"}, {"id": "c", "text": "Lack of home benzodiazepines (withdrawal)"}, {"id": "d", "text": "Hearing aids worn and in place"}, {"id": "e", "text": "Withdrawal from daily alcohol use"}]'::jsonb, '["a", "b", "c", "e"]', 'Alcohol withdrawal and benzodiazepine withdrawal (lack of drugs), narcotics, and steroids are all listed causes of delirium. Hearing aids that are in place reduce sensory deprivation; they do not contribute to delirium.', true),
  ('ddd', 7, 'A client with delirium is restless and pulling at the IV line. The client''s son asks the nurse, ''Shouldn''t you tie her hands down so she doesn''t hurt herself?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "''Restraints are the safest choice for her, and we will place them on her right away.''"}, {"id": "b", "text": "''Restraints are needed only at night, when the lights are off and she cannot see.''"}, {"id": "c", "text": "''She is confused only because of her age, so restraints will not change anything.''"}, {"id": "d", "text": "''We avoid restraints unless absolutely necessary because they increase agitation.''"}]'::jsonb, '["d"]', 'Restraints are avoided in delirium unless absolutely necessary because they increase agitation. Delirium is caused by a medical condition, medication, or substance, not simply age.', false),
  ('ddd', 8, 'A nurse observes an unlicensed assistive personnel (UAP) caring for an older client with delirium. Which action by the UAP requires the nurse to intervene and provide correction?', '[{"id": "a", "text": "Places the client''s glasses and hearing aids on before starting morning care"}, {"id": "b", "text": "States the date, the place, and the reason for admission at every interaction"}, {"id": "c", "text": "Keeps the room lights on at night to reduce confusion"}, {"id": "d", "text": "Opens the blinds during the day and turns the room lights off at bedtime"}]'::jsonb, '["c"]', 'Delirium care includes encouraging the sleep-wake cycle with lights off at night and on during the day, so lights left on all night must be corrected. Correcting glasses/hearing aids and frequent reorientation are appropriate.', false),
  ('ddd', 9, 'A nurse on a geropsychiatric unit receives a report on four clients taking antidepressants. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Duloxetine: reports that chronic back pain has improved this week"}, {"id": "b", "text": "Bupropion: asks whether the drug could cause sexual dysfunction"}, {"id": "c", "text": "Amitriptyline: a large supply found hidden at the bedside"}, {"id": "d", "text": "Sertraline: day 7 of therapy and reports no change in mood yet"}]'::jsonb, '["c"]', 'TCAs such as amitriptyline are lethal in overdose, so a client stockpiling pills is an immediate safety risk. Lack of mood change after 1 week of an SSRI is expected because these drugs take 2–4 weeks to work.', false),
  ('ddd', 10, 'A client with major depressive disorder started fluoxetine 5 days ago and says, ''This pill isn''t doing anything. I''m going to stop taking it.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "''Don''t worry. You will start feeling much better by tomorrow or the day after.''"}, {"id": "b", "text": "''It takes 2 to 4 weeks to work. How are you feeling meanwhile?''"}, {"id": "c", "text": "''You should ask your provider to switch you to a drug like bupropion instead.''"}, {"id": "d", "text": "''Why would you expect an antidepressant to start working after only a few days?''"}]'::jsonb, '["b"]', 'SSRIs such as fluoxetine take 2–4 weeks to work, so the nurse educates about delayed onset while encouraging expression of feelings. False reassurance, ''why'' questions, and giving advice are nontherapeutic.', false),
  ('ddd', 11, 'A client admitted for severe depression has stayed in bed, eating little, for most of the first 2 weeks of hospitalization. Today the client is up early, energetic, and tells the nurse, ''I finally have everything figured out.'' The client''s affect remains flat. Which action is the PRIORITY?', '[{"id": "a", "text": "Assess for suicidal ideation and increase monitoring"}, {"id": "b", "text": "Encourage the client to use the new energy in a group exercise class"}, {"id": "c", "text": "Document the improvement and begin planning for an early discharge"}, {"id": "d", "text": "Reduce the level of observation as a reward for the client''s progress"}]'::jsonb, '["a"]', 'Increased energy before mood improves marks the point of highest suicide risk because the client now has energy to act on a plan, so monitoring must increase. Encouraging activity is appropriate later, but safety comes first.', false),
  ('ddd', 12, 'A nurse completes an admission assessment of a 70-year-old client referred for possible major depressive disorder. Which findings count toward the diagnostic criteria for this disorder? Select all that apply.', '[{"id": "a", "text": "Visual hallucinations of small animals"}, {"id": "b", "text": "Hypersomnia and fatigue for 3 weeks"}, {"id": "c", "text": "Decreased appetite with weight changes"}, {"id": "d", "text": "Anhedonia: no pleasure in usual activities"}, {"id": "e", "text": "Fluctuating consciousness during the day"}]'::jsonb, '["b", "c", "d"]', 'Hypersomnia and fatigue (Sleep, Energy), anhedonia (Interest), and decreased appetite with weight change (Appetite) are SIG E CAPS criteria. Visual hallucinations and fluctuating consciousness are delirium findings; hallucinations are rare in depression.', true),
  ('ddd', 13, 'A client reports depressed mood, insomnia, fatigue, excessive guilt, and difficulty concentrating, all of which began 9 days ago after a job loss. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Criteria are not met, because suicidal ideation must be one of the symptoms"}, {"id": "b", "text": "Criteria are met, because five symptoms are present, including depressed mood"}, {"id": "c", "text": "Criteria are not met, because at least seven symptoms must be present together"}, {"id": "d", "text": "Criteria are not yet met; symptoms must last 2 weeks or more"}]'::jsonb, '["d"]', 'Major depressive disorder requires 5 or more symptoms lasting at least 2 weeks; this client has five symptoms but for only 9 days. Suicidal ideation is not required; depressed mood or anhedonia must be one of the five.', false),
  ('ddd', 14, 'A client has had insomnia, fatigue, poor concentration, decreased appetite, psychomotor agitation, and excessive guilt for 4 weeks. The client denies feeling sad and still enjoys weekend fishing trips. Which conclusion by the nurse is MOST accurate?', '[{"id": "a", "text": "Criteria are not met, because symptoms must be present for at least 6 months"}, {"id": "b", "text": "Criteria are met, because guilt and psychomotor agitation outweigh the other symptoms"}, {"id": "c", "text": "Criteria are met, because six symptoms have been present for longer than 2 weeks"}, {"id": "d", "text": "Criteria are not met, because depressed mood or anhedonia must be one of the 5"}]'::jsonb, '["d"]', 'Although six symptoms have lasted more than 2 weeks, the criteria must include either depressed mood or anhedonia, and this client has neither. Duration of 2 weeks, not 6 months, is required.', false),
  ('ddd', 15, 'A client who started sertraline 2 weeks ago is being taught about the medication. Which statements by the client indicate understanding of the teaching? Select all that apply.', '[{"id": "a", "text": "''I will be monitored for serotonin syndrome.''"}, {"id": "b", "text": "''A tyramine-free diet is needed with this drug.''"}, {"id": "c", "text": "''When I begin to feel better, my suicide risk is gone.''"}, {"id": "d", "text": "''Increased energy before mood improves means higher suicide risk.''"}, {"id": "e", "text": "''It takes 2 to 4 weeks to work.''"}]'::jsonb, '["a", "d", "e"]', 'SSRIs take 2–4 weeks and require monitoring for serotonin syndrome, and increased energy before mood improves signals the highest suicide risk, so reporting it is correct. A tyramine-free diet applies to MAOIs, and suicide risk is highest, not gone, when the client begins to feel better.', true),
  ('ddd', 16, 'A client with a recent history of suicidal ideation is being discharged with a prescription for a 90-day supply of amitriptyline. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Contact the provider about limiting the supply dispensed because of overdose risk"}, {"id": "b", "text": "Instruct the client that this drug lowers the seizure threshold and to report seizures"}, {"id": "c", "text": "Teach the client to follow a tyramine-free diet while taking this medication"}, {"id": "d", "text": "Reassure the client that this drug has no sexual dysfunction or other major risks"}]'::jsonb, '["a"]', 'TCAs such as amitriptyline are lethal in overdose, so a large supply should not be given, especially to a client at risk for suicide. A tyramine-free diet applies to MAOIs, and lowering the seizure threshold is a key point for bupropion.', false),
  ('ddd', 17, 'A client with major depressive disorder who also reports chronic low back pain and frequent worry is started on duloxetine. Which statement by the client indicates understanding of the teaching?', '[{"id": "a", "text": "''This medicine may also help my anxiety and chronic pain.''"}, {"id": "b", "text": "''This medicine works within a day or two of the first dose.''"}, {"id": "c", "text": "''My provider will dispense only a few pills because it is lethal.''"}, {"id": "d", "text": "''I must avoid all foods that contain tyramine while taking it.''"}]'::jsonb, '["a"]', 'Duloxetine is an SNRI, which also treats anxiety and chronic pain. Tyramine restriction applies to MAOIs, limited supply because of lethality applies to TCAs, and antidepressants take 2–4 weeks to work.', false),
  ('ddd', 18, 'A nurse reviews new antidepressant prescriptions for four clients. Which prescription should the nurse question FIRST before administering?', '[{"id": "a", "text": "Escitalopram for a client newly diagnosed with depression"}, {"id": "b", "text": "Duloxetine for a client with depression and chronic back pain"}, {"id": "c", "text": "Bupropion for a client with a seizure disorder"}, {"id": "d", "text": "Venlafaxine for a client with depression and anxiety"}]'::jsonb, '["c"]', 'Bupropion lowers the seizure threshold, so it is a concern in a client with a seizure disorder. SNRIs such as venlafaxine and duloxetine also treat anxiety and chronic pain, and SSRIs such as escitalopram are first-line.', false),
  ('ddd', 19, 'A client with depression is prescribed tranylcypromine. Which teaching points should the nurse include? Select all that apply.', '[{"id": "a", "text": "It also relieves chronic pain"}, {"id": "b", "text": "Dangerous interactions can occur"}, {"id": "c", "text": "A tyramine-free diet is required"}, {"id": "d", "text": "Full effect occurs within 2 days"}, {"id": "e", "text": "It causes no sexual dysfunction"}]'::jsonb, '["b", "c"]', 'Tranylcypromine is an MAOI, which requires a tyramine-free diet and has dangerous interactions, so new drugs must be checked first. Relief of chronic pain is a feature of SNRIs, lack of sexual dysfunction describes bupropion, and antidepressants take 2–4 weeks to work.', true),
  ('ddd', 20, 'A client taking sertraline for 3 weeks is also receiving other medications. When evaluating this client, which assessment is MOST important to the specific drug class prescribed?', '[{"id": "a", "text": "Monitor for a lowered seizure threshold"}, {"id": "b", "text": "Monitor adherence to a tyramine-free diet"}, {"id": "c", "text": "Monitor for signs of serotonin syndrome"}, {"id": "d", "text": "Monitor pill counts for a lethal overdose supply"}]'::jsonb, '["c"]', 'Sertraline is an SSRI, and the key monitoring point for SSRIs is serotonin syndrome. Tyramine restriction belongs to MAOIs, lowered seizure threshold to bupropion, and lethality in overdose to TCAs.', false),
  ('ddd', 21, 'The wife of a client diagnosed with dementia 5 years ago reports that he now needs help bathing and dressing, asks the same question repeatedly, has walked out of the house twice, and becomes more confused every evening. Which stage do these findings MOST likely represent?', '[{"id": "a", "text": "Acute delirium, which includes sudden onset and fluctuating consciousness"}, {"id": "b", "text": "Late stage, which includes total dependence and loss of recognition of family"}, {"id": "c", "text": "Middle stage, which includes needing help with ADLs and wandering"}, {"id": "d", "text": "Early stage, which includes forgetting recent events and personality changes"}]'::jsonb, '["c"]', 'Needing help with ADLs, wandering, sundowning, and repetitive behavior describe the middle stage of dementia. In the early stage the client is still independent in most ADLs, and the late stage involves total dependence.', false),
  ('ddd', 22, 'The daughter of a client with middle-stage dementia says, ''Every day around dinnertime Dad gets more confused and agitated.'' Which instruction by the nurse is MOST appropriate?', '[{"id": "a", "text": "''Give him coffee in the afternoon so he stays alert through dinner.''"}, {"id": "b", "text": "''Change his daily routine often so he stays interested in activities.''"}, {"id": "c", "text": "''Increase his activity during the day and ensure lighting at dusk.''"}, {"id": "d", "text": "''Dim the lights early in the evening so he settles down for bed.''"}]'::jsonb, '["c"]', 'Sundowning is managed by increasing activity during the day, avoiding stimulants in the afternoon, ensuring lighting at dusk, and maintaining routine. Afternoon coffee, dim evening lighting, and a changing routine all worsen it.', false),
  ('ddd', 23, 'A home health nurse visits a client whose dementia has progressed. Which findings indicate the client has reached the late stage of the disease? Select all that apply.', '[{"id": "a", "text": "Incontinence; bedridden"}, {"id": "b", "text": "Total dependence for all ADLs"}, {"id": "c", "text": "Loss of recognition of family"}, {"id": "d", "text": "Gets lost in familiar places"}, {"id": "e", "text": "Loss of speech and swallowing"}]'::jsonb, '["a", "b", "c", "e"]', 'Total dependence for all ADLs, loss of speech and swallowing, incontinence, being bedridden, and loss of recognition of family are late-stage findings. Getting lost in familiar places is an early-stage finding.', true),
  ('ddd', 24, 'An 88-year-old client with dementia becomes tearful at bedtime and says, ''I have to go home right now. My baby needs to be fed.'' Which response by the nurse is MOST therapeutic?', '[{"id": "a", "text": "Monitor for a lowered seizure threshold"}, {"id": "b", "text": "Monitor pill counts for a lethal overdose supply"}, {"id": "c", "text": "Monitor adherence to a tyramine-free diet"}, {"id": "d", "text": "Monitor for serotonin syndrome"}]'::jsonb, '["d"]', 'In validation therapy the nurse does not correct delusions or argue but validates the emotion. Correcting her age argues with the confused statement, a ''why'' question demands insight she lacks, and agreeing with the delusion offers false reassurance.', false),
  ('ddd', 25, 'A client with middle-stage dementia gets up from the table after a few bites at every meal and walks the hallway. The client has lost weight over the past month. Which intervention is MOST appropriate?', '[{"id": "a", "text": "Offer only thin liquid supplements between meals"}, {"id": "b", "text": "Keep the client seated until the tray is empty"}, {"id": "c", "text": "Serve three large meals at set times daily"}, {"id": "d", "text": "Offer finger foods in small, frequent meals"}]'::jsonb, '["d"]', 'Finger foods are easy to self-feed and small, frequent meals support nutrition in a client who will not stay at the table. Large meals and forcing the client to stay seated do not match the note''s nutrition interventions.', false),
  ('ddd', 26, 'A nurse caring for a client with late-stage dementia notes that the client coughs and clears the throat repeatedly while drinking water. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Monitor for dysphagia and use thickened liquids"}, {"id": "b", "text": "Encourage larger sips so the client finishes the water faster"}, {"id": "c", "text": "Document the coughing as an expected finding of the late stage"}, {"id": "d", "text": "Offer the client finger foods instead of the scheduled meal"}]'::jsonb, '["a"]', 'Late-stage dementia brings loss of swallowing, so the nurse monitors for dysphagia and uses thickened liquids if needed. Finger foods support self-feeding but do not address unsafe swallowing, and the cough requires action, not only documentation.', false),
  ('ddd', 27, 'The family of a client with middle-stage dementia who has wandered out of the house twice asks how to keep him safe at home. Which interventions should the nurse recommend? Select all that apply.', '[{"id": "a", "text": "Give stimulants in the afternoon"}, {"id": "b", "text": "Install door alarms"}, {"id": "c", "text": "Vary the daily routine often"}, {"id": "d", "text": "Wear an identification bracelet"}, {"id": "e", "text": "Provide safe enclosed areas"}]'::jsonb, '["b", "d", "e"]', 'Door alarms, an identification bracelet, and safe enclosed areas are the wandering interventions. Maintaining routine (not varying it) and avoiding stimulants in the afternoon are recommended for sundowning.', true),
  ('ddd', 28, 'A daughter caring for her mother with dementia tells the nurse, ''I haven''t slept a full night in months, I never leave the house, and yesterday I snapped at her.'' Which actions are appropriate for the nurse to take? Select all that apply.', '[{"id": "a", "text": "Teach her to correct each confused statement"}, {"id": "b", "text": "Advise her to avoid having anyone else help"}, {"id": "c", "text": "Discuss respite care with the daughter"}, {"id": "d", "text": "Assess the daughter as the caregiver"}, {"id": "e", "text": "Say donepezil will soon cure the disease"}]'::jsonb, '["c", "d"]', 'Caregiver burnout is managed by assessing the caregiver, referring to support groups, and discussing respite care. Donepezil slows progression but does not cure, confused statements should not be argued with, and refusing help works against respite.', true),
  ('ddd', 29, 'The son of a client with dementia says, ''The doctor started Dad on donepezil. Once it kicks in, his memory should come back to normal, right?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "''This medicine reverses the disease if it is started in the early stage.''"}, {"id": "b", "text": "''This medicine may slow the progression, but it does not cure dementia.''"}, {"id": "c", "text": "''Yes, his memory should improve after 2 to 4 weeks of treatment.''"}, {"id": "d", "text": "''Yes, his memory should return once the cause has been treated.''"}]'::jsonb, '["b"]', 'Dementia is chronic, progressive, and irreversible; donepezil and memantine slow progression but do not cure. Return of function once the cause is treated describes delirium, and the 2–4 week onset applies to antidepressants.', false),
  ('ddd', 30, 'An older client is evaluated for memory complaints. Which finding would MOST suggest depression rather than dementia as the cause?', '[{"id": "a", "text": "Selective memory gaps with clear consciousness, gradual over weeks"}, {"id": "b", "text": "Short-term memory lost first, then long-term memory, over several years"}, {"id": "c", "text": "Getting lost in familiar places and having difficulty with complex tasks"}, {"id": "d", "text": "Fluctuating consciousness with visual hallucinations that began yesterday"}]'::jsonb, '["a"]', 'Depression has a gradual onset over weeks to months, clear consciousness, and selective memory gaps. Short-term then long-term loss over years and getting lost in familiar places describe dementia; sudden fluctuating consciousness with visual hallucinations describes delirium.', false),
  ('ddd', 31, 'An 84-year-old client is being treated with antibiotics for a UTI that caused acute confusion. The client''s daughter tearfully asks, ''Is this Alzheimer''s? Will Mom be like this forever?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "''This is depression, which improves once an antidepressant starts to take effect.''"}, {"id": "b", "text": "''This is likely dementia, and medication can only slow down its progression.''"}, {"id": "c", "text": "''This is likely dementia, which progresses slowly and cannot be reversed.''"}, {"id": "d", "text": "''This is delirium, and it is reversible once we treat the cause.''"}]'::jsonb, '["d"]', 'Acute confusion from a UTI is delirium, which is short and reversible when the cause is treated. Dementia is progressive and irreversible, and its medications only slow progression.', false),
  ('ddd', 32, 'An 80-year-old client is admitted with new confusion that started this morning. Which actions should the nurse take to help identify the underlying cause? Select all that apply.', '[{"id": "a", "text": "Assess oxygenation for hypoxia"}, {"id": "b", "text": "Assess for hypoglycemia"}, {"id": "c", "text": "Begin validation therapy as the plan"}, {"id": "d", "text": "Review drugs for anticholinergics"}, {"id": "e", "text": "Assess for urinary retention and constipation"}]'::jsonb, '["a", "b", "d", "e"]', 'Urinary retention/constipation, drugs such as anticholinergics, reduced oxygenation, and metabolic causes such as hypoglycemia are all DELIRIUM causes to investigate. Validation therapy is a dementia approach; with acute confusion, identifying and treating the underlying cause is the top priority.', true),
  ('ddd', 33, 'A long-term care resident, age 88, has been drinking very little for 3 days and is newly confused. The resident is afebrile, has no urinary complaints, and has dry mucous membranes. Which cause of the confusion should the nurse suspect FIRST?', '[{"id": "a", "text": "Intracranial process"}, {"id": "b", "text": "Onset of depression"}, {"id": "c", "text": "Dehydration"}, {"id": "d", "text": "Progression of dementia"}]'::jsonb, '["c"]', 'In older adults, UTI and dehydration are the most common causes of delirium, and poor intake with dry mucous membranes points to dehydration. Dementia and depression have gradual onsets rather than a sudden change.', false),
  ('ddd', 34, 'A 90-year-old client is newly confused, but temperature and vital signs are within the client''s usual range. The client''s son says, ''She can''t have an infection. She doesn''t even have a fever.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "''Her confusion is most likely the start of dementia, not an infection.''"}, {"id": "b", "text": "''In older adults, confusion is often the only sign of an infection.''"}, {"id": "c", "text": "''You are right; without a fever, infection can be ruled out for now.''"}, {"id": "d", "text": "''Some confusion at her age is expected and should not be a concern.''"}]'::jsonb, '["b"]', 'Confusion is often the only sign of infection in elderly patients, so the absence of fever does not rule it out. Sudden confusion is not expected with age, and dementia develops gradually.', false),
  ('ddd', 35, 'A client with middle-stage dementia for 4 years has been calm and drowsy at times but, since breakfast today, keeps telling staff about children playing in the room and alternates between drowsiness and agitation. Which action is the PRIORITY?', '[{"id": "a", "text": "Use validation therapy and continue the routine observation only"}, {"id": "b", "text": "Identify and treat the cause of the acute delirium"}, {"id": "c", "text": "Increase daytime activity to reduce the client''s evening sundowning"}, {"id": "d", "text": "Document the behavior as the expected progression of the dementia"}]'::jsonb, '["b"]', 'Visual hallucinations are common in delirium but rare in dementia until late stages, and a sudden morning change with fluctuating alertness signals delirium, whose cause must be identified and treated. It is not sundowning, which occurs in the evening.', false),
  ('ddd', 36, 'A nurse reviews a care plan for a client in the early stage of dementia. Which findings should the nurse expect at this stage? Select all that apply.', '[{"id": "a", "text": "Is incontinent of urine"}, {"id": "b", "text": "Forgets recent events"}, {"id": "c", "text": "Shows personality changes"}, {"id": "d", "text": "Needs help with most ADLs"}, {"id": "e", "text": "Has trouble with complex tasks"}]'::jsonb, '["b", "c", "e"]', 'Forgetting recent events, personality changes, and difficulty with complex tasks occur in the early stage, while the client is still independent in most ADLs. Needing help with ADLs is middle stage, and incontinence is late stage.', true),
  ('ddd', 37, 'A client with depression tells the nurse, ''I''m worthless. Everyone would be better off without me.'' Which response by the nurse is the PRIORITY?', '[{"id": "a", "text": "''Why would you say that you are worthless?''"}, {"id": "b", "text": "''You have so much to live for, and people care.''"}, {"id": "c", "text": "''Are you having thoughts of death or suicide?''"}, {"id": "d", "text": "''Let''s set one small goal for you to do today.''"}]'::jsonb, '["c"]', 'The priority in depression is to assess for suicidal ideation, and this statement warrants a direct question. Setting simple goals is appropriate later; reassurance and ''why'' questions are nontherapeutic.', false),
  ('ddd', 38, 'A client with severe depression has stayed in bed for 3 days, saying, ''I can''t do anything right.'' Which goal should the nurse set FIRST with the client?', '[{"id": "a", "text": "Exercise for 1 hour each day for the rest of the stay"}, {"id": "b", "text": "Walk with the nurse for 10 minutes today"}, {"id": "c", "text": "Lead the evening community meeting on the unit this week"}, {"id": "d", "text": "Attend every scheduled group activity starting today"}]'::jsonb, '["b"]', 'Simple, achievable goals rebuild self-esteem, and activity is increased gradually. Leading meetings, attending every group, or exercising an hour daily are not gradual and set the client up to fail.', false),
  ('ddd', 39, 'A nurse is planning care for an older client with delirium. Which interventions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Keep lights on during the day and off at night"}, {"id": "b", "text": "Rotate different staff to provide new faces"}, {"id": "c", "text": "Put on the client''s glasses and hearing aids"}, {"id": "d", "text": "Apply restraints each night to prevent falls"}, {"id": "e", "text": "Give an anticholinergic to help the client sleep"}]'::jsonb, '["a", "c"]', 'Correcting glasses/hearing aids reduces sensory deprivation, and lights on during the day and off at night support the sleep-wake cycle. Restraints increase agitation, anticholinergic medications should be avoided, and the same staff should be kept if possible.', true),
  ('ddd', 40, 'A nurse receives report on four older clients. Which client should the nurse assess FIRST?', '[{"id": "a", "text": "Depression with a flat affect; ate half of breakfast today"}, {"id": "b", "text": "Alert yesterday, now confused with hypoxia"}, {"id": "c", "text": "Late-stage dementia; did not recognize his wife this morning"}, {"id": "d", "text": "Early-stage dementia; keeps asking where she left her glasses"}]'::jsonb, '["b"]', 'A sudden change in a previously alert client suggests delirium, possibly from reduced oxygenation, and needs immediate assessment. Loss of recognition of family in late-stage dementia and forgetting recent events in early-stage dementia are expected.', false),
  ('ddd', 41, 'A nurse on a memory-care unit observes a UAP during the afternoon. Which action by the UAP requires correction?', '[{"id": "a", "text": "Serves coffee with the afternoon snack"}, {"id": "b", "text": "Walks a resident outside in the late morning sun"}, {"id": "c", "text": "Turns the hallway lights on as it begins to get dark"}, {"id": "d", "text": "Follows the same bathing schedule each day of the week"}]'::jsonb, '["a"]', 'To prevent sundowning, stimulants are avoided in the afternoon, so afternoon coffee must be corrected. Daytime activity, lighting at dusk, and maintaining routine are recommended.', false),
  ('ddd', 42, 'On postoperative day 1, a client who was calm before surgery is suddenly agitated and fearful, accusing staff of trying to poison him. He has no psychiatric history. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Apply restraints until the client is no longer agitated"}, {"id": "b", "text": "Assess oxygenation and level of consciousness"}, {"id": "c", "text": "Initiate suicide precautions and remove all sharp objects"}, {"id": "d", "text": "Explain firmly that no one on the unit is poisoning him"}]'::jsonb, '["b"]', 'Sudden agitation, fear, and paranoia are the mood picture of delirium, and checking for a cause such as reduced oxygenation comes first. Restraints increase agitation, and arguing with the confused belief does not treat the cause.', false),
  ('ddd', 43, 'A nurse is planning care for a client admitted with severe major depressive disorder. Which interventions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Assess for suicidal ideation weekly"}, {"id": "b", "text": "Schedule all group activities on day 1"}, {"id": "c", "text": "Ensure adequate nutrition and sleep"}, {"id": "d", "text": "Encourage expression of feelings"}, {"id": "e", "text": "Set simple, achievable goals"}]'::jsonb, '["c", "d", "e"]', 'Encouraging expression of feelings, simple achievable goals, and adequate nutrition and sleep are depression interventions. Activity is increased gradually, not all at once, and suicidal ideation is assessed every shift, not weekly.', true),
  ('ddd', 44, 'A client with dementia stands at the nurses'' station shouting, ''This isn''t my room! Someone stole all my furniture!'' The client''s voice is getting louder. Which action by the nurse is BEST?', '[{"id": "a", "text": "Avoid arguing and use gentle redirection to a calm activity"}, {"id": "b", "text": "Ask the client to describe exactly who took the furniture and why"}, {"id": "c", "text": "Explain that the furniture was never stolen and is still at home"}, {"id": "d", "text": "Show the client the room number to prove it is the right room"}]'::jsonb, '["a"]', 'Communication in dementia means not arguing with confused statements and using gentle redirection. Proving or explaining the facts argues with the confusion, and probing for details reinforces it.', false),
  ('ddd', 45, 'A client with delirium is calmer when her daughter visits. The daughter asks whether she may bring family photos and stay overnight, but a staff member says visitors ''overstimulate'' patients. Which response by the nurse is BEST?', '[{"id": "a", "text": "''Yes, but you may stay only while she is asleep.''"}, {"id": "b", "text": "''No. Familiar items will only increase her confusion.''"}, {"id": "c", "text": "''No. Visitors cause sensory overload and must leave.''"}, {"id": "d", "text": "''Yes. Having family present can help keep her calm.''"}]'::jsonb, '["d"]', 'Keeping family present when possible calms the patient, and a familiar environment supports orientation. Minimizing sensory overload refers to excessive noise and stimuli, not a calming family member.', false),
  ('ddd', 46, 'A client with depression is prescribed phenelzine. Which teaching point is MOST important for the nurse to emphasize?', '[{"id": "a", "text": "It also treats anxiety and chronic pain"}, {"id": "b", "text": "It causes no sexual dysfunction at all"}, {"id": "c", "text": "A tyramine-free diet is required"}, {"id": "d", "text": "It lowers the seizure threshold markedly"}]'::jsonb, '["c"]', 'Phenelzine is an MAOI, which requires a tyramine-free diet because of dangerous interactions. Treating anxiety and chronic pain describes SNRIs, and lowering the seizure threshold and lack of sexual dysfunction describe bupropion.', false),
  ('ddd', 47, 'A 72-year-old client with diabetes is found sweating, confused, and unable to state where he is, although he was oriented 1 hour ago. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Reorient to name and place"}, {"id": "b", "text": "Request dementia screening"}, {"id": "c", "text": "Assess for hypoglycemia"}, {"id": "d", "text": "Assess for suicidal ideation"}]'::jsonb, '["c"]', 'Sudden confusion is delirium, and hypoglycemia is a metabolic cause that must be identified and treated first. Reorienting helps but does not treat the cause, and dementia develops gradually.', false),
  ('ddd', 48, 'A charge nurse reviews findings for residents on a long-term care unit. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Sudden onset of confusion today"}, {"id": "b", "text": "Reports thoughts of suicide"}, {"id": "c", "text": "More confusion at dusk in middle-stage dementia"}, {"id": "d", "text": "Visual hallucinations with fluctuating alertness"}, {"id": "e", "text": "Incontinence in late-stage dementia"}]'::jsonb, '["a", "b", "d"]', 'A sudden change in orientation and visual hallucinations with fluctuating alertness signal delirium, whose cause is the top priority, and suicidal ideation is the priority in depression. Sundowning in middle-stage dementia and incontinence in late-stage dementia are expected.', true),
  ('ddd', 49, 'A client with depression has been taking an antidepressant for 3 weeks. Which findings require IMMEDIATE follow-up by the nurse? Select all that apply.', '[{"id": "a", "text": "Says escitalopram is helping a bit"}, {"id": "b", "text": "Large supply of amitriptyline at home"}, {"id": "c", "text": "Reports thoughts of death"}, {"id": "d", "text": "Increased energy before mood improves"}, {"id": "e", "text": "Says duloxetine eased chronic pain"}]'::jsonb, '["b", "c", "d"]', 'TCAs are lethal in overdose, thoughts of death are suicidal ideation, and increased energy before mood improves is the point of highest suicide risk. Pain relief from an SNRI and early SSRI benefit are expected.', true),
  ('ddd', 50, 'A nurse teaches the family of a client with middle-stage dementia about communication and meals. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Use short, simple sentences"}, {"id": "b", "text": "Correct each confused statement"}, {"id": "c", "text": "Use face-to-face eye contact"}, {"id": "d", "text": "Offer small, frequent meals"}, {"id": "e", "text": "Provide finger foods to self-feed"}]'::jsonb, '["a", "c", "d", "e"]', 'Short, simple sentences and face-to-face eye contact support communication, and finger foods with small frequent meals support nutrition. Confused statements should not be argued with or corrected; gentle redirection is used instead.', true),
  ('overview', 1, 'A nurse is about to begin a medication pass when a patient with depression approaches and says quietly, "I just want it to end." Which action should the nurse take FIRST?', '[{"id": "a", "text": "Remove sharp objects, belts, and cords from the patient''s room"}, {"id": "b", "text": "Stay with the patient and notify the team immediately"}, {"id": "c", "text": "Reflect the feeling by saying, \"It sounds like you feel scared.\""}, {"id": "d", "text": "Finish the medication pass and then reassess the patient''s mood"}]'::jsonb, '["b"]', 'A statement such as "I want it to end" is never ignored: the nurse stays with the patient and notifies the team immediately, because safety is the first priority. Removing dangerous items is a correct safety intervention but requires leaving the patient, and reflecting feelings or delaying the response does not address the immediate risk.', false),
  ('overview', 2, 'A nurse is admitting a patient with major depression and reviews the history obtained from the patient and family. Which findings are red flags that increase this patient''s suicide risk? Select all that apply.', '[{"id": "a", "text": "A plan and the means to carry it out"}, {"id": "b", "text": "Repeated handwashing before each meal"}, {"id": "c", "text": "Hopelessness about the future"}, {"id": "d", "text": "Withdrawal from usual social support"}, {"id": "e", "text": "Startling easily when a door slams"}]'::jsonb, '["a", "c", "d"]', 'Red flags for suicide are plan and means (a), past attempts, hopelessness (c), and withdrawal (d). Repeated handwashing (b) is a compulsion seen in OCD, and startling easily (e) is a PTSD finding.', true),
  ('overview', 3, 'During a mental status exam, a patient smiles brightly and says, "I feel terrible, like nothing matters anymore." Which documentation by the nurse is MOST accurate?', '[{"id": "a", "text": "Mood: \"I feel terrible\"; affect: smiling"}, {"id": "b", "text": "Mood: smiling; affect: \"I feel terrible\""}, {"id": "c", "text": "Thought content: smiling; mood: terrible"}, {"id": "d", "text": "Perception: smiling; affect: \"terrible\""}]'::jsonb, '["a"]', 'Mood is how the patient says they feel ("I feel terrible"), while affect is what the nurse sees, here smiling. Reversing the two is the most common error, and perception refers to hallucinations, not expressions.', false),
  ('overview', 4, 'A patient admitted with hallucinations tells the nurse, "There''s nothing wrong with me. I don''t know why my family made me come here." This statement gives the nurse the MOST information about which area of the mental status exam?', '[{"id": "a", "text": "Perception"}, {"id": "b", "text": "Judgment"}, {"id": "c", "text": "Thought process"}, {"id": "d", "text": "Insight"}]'::jsonb, '["d"]', 'Insight asks whether the patient understands they are ill, and denying any problem shows poor insight. Perception refers to hallucinations, judgment to the ability to make safe choices, and thought process to whether thinking is clear or disorganized.', false),
  ('overview', 5, 'During a mental status exam, a patient with mania states she plans to leave the hospital tonight, withdraw all her savings, and hand it out to strangers at a bus station. Which area of the exam is MOST directly reflected by this plan?', '[{"id": "a", "text": "Appearance"}, {"id": "b", "text": "Judgment"}, {"id": "c", "text": "Mood"}, {"id": "d", "text": "Perception"}]'::jsonb, '["b"]', 'Judgment asks whether the patient can make safe choices, and giving away all savings to strangers is an unsafe choice. Mood is how the patient says they feel, appearance is grooming and dress, and perception refers to hallucinations.', false),
  ('overview', 6, 'A patient sitting alone in the dayroom suddenly swats at the wall and tells the nurse, "Get these spiders off the wall!" The nurse sees no spiders. Under which mental status exam area should the nurse document this finding?', '[{"id": "a", "text": "Thought content"}, {"id": "b", "text": "Behavior"}, {"id": "c", "text": "Perception"}, {"id": "d", "text": "Thought process"}]'::jsonb, '["c"]', 'Perception covers hallucinations, which are seeing or hearing unreal things, such as spiders that are not there. Thought content covers delusions, which are false beliefs, and thought process covers whether thinking is clear or disorganized.', false),
  ('overview', 7, 'A patient with schizophrenia refuses lunch and tells the nurse, "The staff are putting poison in my food." Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "\"No one here would poison you; that is not possible.\""}, {"id": "b", "text": "\"Which staff member do you think is doing this to you?\""}, {"id": "c", "text": "\"It sounds like you don''t feel safe. Let''s talk about how you feel.\""}, {"id": "d", "text": "\"Why do you believe we would want to put poison in it?\""}]'::jsonb, '["c"]', 'The nurse should not argue with delusions but acknowledge the patient''s experience without reinforcing it and redirect gently. Insisting it is impossible argues with the delusion, asking which staff member reinforces it, and a "why" question feels judgmental.', false),
  ('overview', 8, 'A patient with schizophrenia looks toward an empty corner and asks the nurse, "You hear them too, right? They keep saying I''m worthless." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Yes, I hear them, but try your best to ignore what they say.\""}, {"id": "b", "text": "\"Those voices aren''t real, so there''s no reason to listen to them.\""}, {"id": "c", "text": "\"Why do you think the voices are calling you worthless today?\""}, {"id": "d", "text": "\"I don''t hear them, but it sounds like you feel scared.\""}]'::jsonb, '["d"]', 'The nurse acknowledges the patient''s experience (reflecting the feeling) without reinforcing it, then redirects gently. Agreeing to hear the voices reinforces the hallucination, flatly saying they are not real argues with it, and "why" questions feel judgmental.', false),
  ('overview', 9, 'A nurse precepting a new graduate observes several interactions with a patient who is yelling, pacing, and clenching his fists. Which action by the new graduate requires follow-up?', '[{"id": "a", "text": "Speaks in a calm voice using clear, short statements"}, {"id": "b", "text": "Turns his back on the patient to get a PRN medication"}, {"id": "c", "text": "Stands at a distance that gives the patient extra space"}, {"id": "d", "text": "Tells the patient, \"Sit down. We can talk when you''re calm.\""}]'::jsonb, '["b"]', 'The nurse must never turn their back on an aggressive patient, even briefly to retrieve medication. Staying calm, giving space, and using clear, short statements are the correct responses to signs of violence.', false),
  ('overview', 10, 'A patient is admitted after a suicide attempt and continues to describe a plan. Which safety interventions should the nurse implement? Select all that apply.', '[{"id": "a", "text": "One-to-one supervision with someone with the patient at all times"}, {"id": "b", "text": "Avoid mentioning suicide so the patient is not given ideas"}, {"id": "c", "text": "Remove sharp objects from the patient''s room and belongings"}, {"id": "d", "text": "Remove belts and cords from the patient''s room"}, {"id": "e", "text": "Check on the patient once every hour during the night"}]'::jsonb, '["a", "c", "d"]', 'Safety interventions include one-to-one supervision with someone with the patient at all times (a) and removing sharp objects (c), belts, and cords (d). The nurse must never avoid the subject of suicide (b), and hourly checks (e) do not meet one-to-one supervision, which requires someone with the patient at all times.', true),
  ('overview', 11, 'A patient arrives at the emergency department hours after losing her home in a fire. She is sobbing, cannot answer simple questions, and says, "I can''t think. I don''t know what to do." Which nursing goal takes PRIORITY?', '[{"id": "a", "text": "Teach long-term coping skills before discharge from the department"}, {"id": "b", "text": "Stabilize the patient first, then help her regain control"}, {"id": "c", "text": "Encourage her to join a support group with others who had losses"}, {"id": "d", "text": "Complete all nine domains of the mental status exam right away"}]'::jsonb, '["b"]', 'This is a crisis, a moment of breakdown or loss of coping, and the goal is to stabilize first, then help the patient regain control. Teaching long-term coping skills or group participation comes later, after stabilization.', false),
  ('overview', 12, 'A patient started on sertraline for depression 6 days ago tells the nurse, "This pill isn''t doing anything. I''m going to stop taking it." Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "\"That''s reasonable; if it hasn''t helped by now, it probably won''t.\""}, {"id": "b", "text": "\"You should ask to switch to lorazepam, since it works faster.\""}, {"id": "c", "text": "\"Sertraline takes weeks to work; let''s talk about how you feel.\""}, {"id": "d", "text": "\"Doubling the dose for a few days may help it start working.\""}]'::jsonb, '["c"]', 'SSRIs such as sertraline take weeks to work, so lack of effect after 6 days is expected, and the nurse explores the patient''s feelings. Lorazepam is a benzodiazepine for anxiety that is sedating and habit-forming, and suggesting it is giving advice.', false),
  ('overview', 13, 'A nurse teaches a patient with an anxiety disorder who is newly prescribed lorazepam. Which statement by the patient indicates a need for further teaching?', '[{"id": "a", "text": "\"This medicine may make me feel sleepy during the day.\""}, {"id": "b", "text": "\"I should be careful because it can be sedating at first.\""}, {"id": "c", "text": "\"This medicine is being used to treat my anxiety symptoms.\""}, {"id": "d", "text": "\"This anxiety medicine isn''t habit-forming at all.\""}]'::jsonb, '["d"]', 'Benzodiazepines such as lorazepam are sedating and habit-forming, so believing it is not habit-forming shows a need for more teaching. Sleepiness and sedation are expected, and lorazepam is used for anxiety.', false),
  ('overview', 14, 'A nurse reviews morning serum lithium levels for four patients with bipolar disorder. Which result requires IMMEDIATE follow-up?', '[{"id": "a", "text": "0.6 mEq/L"}, {"id": "b", "text": "0.9 mEq/L"}, {"id": "c", "text": "1.2 mEq/L"}, {"id": "d", "text": "1.3 mEq/L"}]'::jsonb, '["d"]', 'Lithium levels are monitored with a target range of 0.6–1.2, so 1.3 is above the range and needs follow-up. Values of 0.6 and 1.2 sit at the edges of the range but are still within it.', false),
  ('overview', 15, 'A nurse is teaching a patient with bipolar disorder who takes lithium. Which statement by the patient indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll keep drinking fluids when I''m out working in the heat.\""}, {"id": "b", "text": "\"I''ll cut back on fluids so I don''t have to urinate so often.\""}, {"id": "c", "text": "\"I''ll have my lithium levels checked as my provider orders.\""}, {"id": "d", "text": "\"I''ll call if I have vomiting that keeps me from drinking.\""}]'::jsonb, '["b"]', 'Patients on lithium must avoid dehydration, so restricting fluids shows a need for further teaching. Drinking fluids in the heat, keeping level checks, and reporting fluid loss all support avoiding dehydration and monitoring levels.', false),
  ('overview', 16, 'A nurse is teaching a patient with depression who has been prescribed phenelzine. Which statement by the patient indicates understanding of the teaching?', '[{"id": "a", "text": "\"I need my blood level checked to keep it between 0.6 and 1.2.\""}, {"id": "b", "text": "\"I need to watch for EPS and NMS while I''m taking this drug.\""}, {"id": "c", "text": "\"I need to avoid tyramine foods to prevent a hypertensive crisis.\""}, {"id": "d", "text": "\"I need to be careful because this drug is habit-forming.\""}]'::jsonb, '["c"]', 'Phenelzine is an MAOI, and patients must avoid tyramine foods because of the risk of hypertensive crisis. Levels of 0.6–1.2 apply to lithium, EPS and NMS to antipsychotics, and habit-forming effects to benzodiazepines.', false),
  ('overview', 17, 'A patient with schizophrenia is started on haloperidol. Which complications is it MOST important for the nurse to monitor for with this medication?', '[{"id": "a", "text": "Dehydration that alters drug levels"}, {"id": "b", "text": "EPS and NMS"}, {"id": "c", "text": "Hypertensive crisis from tyramine foods"}, {"id": "d", "text": "Dependence because it is habit-forming"}]'::jsonb, '["b"]', 'Antipsychotics such as haloperidol and risperidone require watching for EPS and NMS. Dehydration and level changes relate to lithium, tyramine and hypertensive crisis to MAOIs, and habit-forming effects to benzodiazepines.', false),
  ('overview', 18, 'A nurse is preparing medication teaching for several patients on a psychiatric unit. Which teaching points are accurate? Select all that apply.', '[{"id": "a", "text": "Risperidone: watch for EPS and NMS"}, {"id": "b", "text": "Lithium: avoid tyramine foods"}, {"id": "c", "text": "Fluoxetine: takes weeks to work"}, {"id": "d", "text": "Phenelzine: monitor levels 0.6–1.2"}, {"id": "e", "text": "Diazepam: sedating and habit-forming"}]'::jsonb, '["a", "c", "e"]', 'Risperidone is an antipsychotic, so the nurse watches for EPS and NMS (a); fluoxetine is an SSRI that takes weeks to work (c); diazepam is a benzodiazepine that is sedating and habit-forming (e). Avoiding tyramine foods (b) applies to MAOIs such as phenelzine, and levels of 0.6–1.2 (d) apply to lithium.', true),
  ('overview', 19, 'A patient with bipolar disorder has not slept for 3 nights, talks rapidly about new business ideas, and was found trying to climb onto the roof of the unit''s courtyard shelter. Which nursing action is the PRIORITY?', '[{"id": "a", "text": "Protect the patient from harm during mania"}, {"id": "b", "text": "Encourage group participation to build skills"}, {"id": "c", "text": "Teach breathing techniques and coping skills"}, {"id": "d", "text": "Assess insight into the need for treatment"}]'::jsonb, '["a"]', 'These findings show mania with high energy, no sleep, and risky behavior, and the nurse must protect the patient during mania because safety comes first. Group participation, coping skills, and assessing insight are appropriate later but do not address immediate danger.', false),
  ('overview', 20, 'A patient with mania demands to use the phone for the fourth time in an hour and raises his voice when told phone time is over. Which response by the nurse is BEST?', '[{"id": "a", "text": "Debate the reasons for the phone policy until the patient agrees with it"}, {"id": "b", "text": "Allow unlimited phone use today so the patient does not become angry"}, {"id": "c", "text": "Set a firm, calm limit and avoid a power struggle"}, {"id": "d", "text": "Tell the patient he will lose all privileges for the rest of the week"}]'::jsonb, '["c"]', 'Limits for manic or aggressive patients are set clearly and kindly with firm, calm boundaries, avoiding power struggles. Debating the policy creates a power struggle, giving in removes the boundary, and threatening loss of all privileges is not a calm, kind limit.', false),
  ('overview', 21, 'A nurse is assessing a patient with schizophrenia. Which findings should the nurse document as positive symptoms? Select all that apply.', '[{"id": "a", "text": "Hearing unreal voices"}, {"id": "b", "text": "A blank facial expression"}, {"id": "c", "text": "False beliefs about being royalty"}, {"id": "d", "text": "Not showering for a week"}, {"id": "e", "text": "Speech that is disorganized"}]'::jsonb, '["a", "c", "e"]', 'Positive symptoms of schizophrenia are hallucinations such as hearing unreal voices (a), delusions or false beliefs (c), and disorganized speech (e). A blank facial expression is flat affect (b) and not showering is poor hygiene (d), which are negative symptoms.', true),
  ('overview', 22, 'A patient with OCD has been washing her hands for 45 minutes and will miss breakfast if she continues. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Turn off the water and escort her to breakfast now"}, {"id": "b", "text": "Ask her why she needs to wash for so long each time"}, {"id": "c", "text": "Lock the bathroom until breakfast time has ended"}, {"id": "d", "text": "Allow the ritual and plan to reduce it gradually"}]'::jsonb, '["d"]', 'Compulsions should not be stopped abruptly; rituals are reduced gradually. Turning off the water or locking the bathroom stops the ritual abruptly, and a "why" question feels judgmental.', false),
  ('overview', 23, 'A veteran with PTSD begins trembling and says, "I''m back there again," when fireworks appear on the dayroom television. Which nursing action is BEST?', '[{"id": "a", "text": "Encourage him to keep watching so he can face his fears"}, {"id": "b", "text": "Move him to a busier area of the unit to distract him"}, {"id": "c", "text": "Ask him why fireworks still bother him so much"}, {"id": "d", "text": "Use grounding techniques and turn off the trigger"}]'::jsonb, '["d"]', 'PTSD causes flashbacks and easy startling; care involves avoiding triggers and using grounding techniques. Continuing to watch keeps him exposed to the trigger, a "why" question feels judgmental, and a busier area adds stimulation rather than limiting it.', false),
  ('overview', 24, 'A patient with an anxiety disorder reports a racing heart and tense muscles and says, "I can''t stop worrying about everything." Which nursing action is MOST appropriate?', '[{"id": "a", "text": "Use a calm voice and guide her through breathing techniques"}, {"id": "b", "text": "Tell her she should stop thinking about the things that worry her"}, {"id": "c", "text": "Ask her why she worries so much when things are going well"}, {"id": "d", "text": "Encourage her to join a loud, active game in the dayroom"}]'::jsonb, '["a"]', 'Anxiety disorders cause excess worry, racing heart, and tense muscles, and the nurse uses a calm voice, breathing techniques, and coping skills. Telling her what she should do is giving advice, a "why" question feels judgmental, and a loud game increases rather than limits stimulation.', false),
  ('overview', 25, 'A nurse manager is evaluating whether an inpatient unit provides a therapeutic milieu. Which features should the manager expect to find? Select all that apply.', '[{"id": "a", "text": "Structure, safety, and social support"}, {"id": "b", "text": "Clear rules and roles for patients and staff"}, {"id": "c", "text": "Encouragement of group participation"}, {"id": "d", "text": "Unit rules that change daily based on patient requests"}, {"id": "e", "text": "Limits on stimulation when patients need them"}]'::jsonb, '["a", "b", "c", "e"]', 'A therapeutic milieu provides structure, safety, and social support (a), clear rules and roles (b), encouragement of group participation (c), and limited stimulation when needed (e). Rules that change daily (d) remove the structure and clear rules that help patients feel secure.', true),
  ('overview', 26, 'A patient with mania is becoming louder and more restless in a crowded dayroom where a television and a card game are both in progress. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Encourage the patient to lead the card game to use up energy"}, {"id": "b", "text": "Turn up the television so the patient can focus on a program"}, {"id": "c", "text": "Guide the patient to a quieter area to limit stimulation"}, {"id": "d", "text": "Explain all of the unit''s rules in detail to the patient"}]'::jsonb, '["c"]', 'A therapeutic milieu limits stimulation when needed, which helps the patient feel secure. Leading a game or turning up the television increases stimulation, and a detailed explanation is not a clear, short way to set limits.', false),
  ('overview', 27, 'A patient on an inpatient unit tells the nurse, "Nobody here listens to me, and I don''t feel safe at night." Which response by the nurse is MOST therapeutic?', '[{"id": "a", "text": "\"You''re saying you don''t feel safe?\""}, {"id": "b", "text": "\"Why don''t you feel safe here at night?\""}, {"id": "c", "text": "\"You should tell the night nurse right away.\""}, {"id": "d", "text": "\"I''ve felt unsafe on night shift here too.\""}]'::jsonb, '["a"]', 'Restating ("You''re saying you don''t feel safe?") shows listening and invites the patient to explore the concern. A "why" question feels judgmental, "You should" is giving advice, and sharing the nurse''s own feelings shifts focus away from the patient''s needs.', false),
  ('overview', 28, 'A patient says, "My husband says he''s leaving me. I don''t know what to do." Which responses by the nurse are therapeutic? Select all that apply.', '[{"id": "a", "text": "\"Can you tell me more about that?\""}, {"id": "b", "text": "\"You should move in with your sister.\""}, {"id": "c", "text": "\"It sounds like you feel scared.\""}, {"id": "d", "text": "\"Why did he decide to leave you?\""}, {"id": "e", "text": "\"You''re saying you feel lost?\""}]'::jsonb, '["a", "c", "e"]', 'Open-ended questions (a), reflecting feelings (c), and restating (e) let the patient explore feelings safely. "You should" (b) is giving advice, and asking "why" (d) feels judgmental.', true),
  ('overview', 29, 'A charge nurse observes a nurse spending most of a one-to-one session describing her own recent family vacation to a withdrawn patient "to build rapport." Which feedback by the charge nurse is MOST appropriate?', '[{"id": "a", "text": "\"Sharing stories is fine as long as the patient seems interested.\""}, {"id": "b", "text": "\"The focus should be on the patient''s needs, not the nurse''s.\""}, {"id": "c", "text": "\"Personal stories work best with patients who are not withdrawn.\""}, {"id": "d", "text": "\"Try asking the patient why he isn''t sharing more with you.\""}]'::jsonb, '["b"]', 'The goal of therapeutic communication is to build trust and let the patient explore feelings safely, and the focus is always on the patient''s needs, not the nurse''s. Asking "why" feels judgmental.', false),
  ('overview', 30, 'A patient with depression reports low mood, loss of interest in hobbies, and fatigue and asks the nurse for something to help her sleep. Which nursing action is the PRIORITY?', '[{"id": "a", "text": "Encourage participation in a group activity this afternoon"}, {"id": "b", "text": "Teach that her SSRI may take weeks to work"}, {"id": "c", "text": "Ask directly, \"Are you thinking of hurting yourself?\""}, {"id": "d", "text": "Assess her appearance and grooming for self-care"}]'::jsonb, '["c"]', 'With depression the nurse always assesses for suicide risk, asking directly. Group participation, SSRI teaching, and assessing appearance are appropriate but do not come before the safety assessment.', false),
  ('overview', 31, 'A nurse receives report on four patients. Which patient should the nurse see FIRST?', '[{"id": "a", "text": "A patient with schizophrenia who has a flat affect and poor hygiene"}, {"id": "b", "text": "A patient with OCD who checks the door lock repeatedly before bed"}, {"id": "c", "text": "A patient with depression who says she feels hopeless and has withdrawn from everyone"}, {"id": "d", "text": "A patient who started fluoxetine 5 days ago and reports no improvement yet"}]'::jsonb, '["c"]', 'Hopelessness and withdrawal are suicide red flags, and safety is the first priority, so this patient is seen first. Flat affect and poor hygiene are negative symptoms, checking is a compulsion, and SSRIs take weeks to work, so these are not immediate threats.', false),
  ('overview', 32, 'A nurse is making rounds on a psychiatric unit. Which patient is MOST likely to become violent toward staff?', '[{"id": "a", "text": "A patient pacing the hallway, yelling, with clenched fists"}, {"id": "b", "text": "A patient who startles easily and reports nightmares"}, {"id": "c", "text": "A patient with a blank affect who is sitting alone"}, {"id": "d", "text": "A patient repeatedly arranging items on a shelf"}]'::jsonb, '["a"]', 'Signs of assault or violence risk are clenched fists, pacing, and yelling. Startling easily and nightmares are PTSD findings, a blank affect is a negative schizophrenia symptom, and repeated actions are compulsions.', false),
  ('overview', 33, 'A patient is pacing in the hallway, yelling at staff, and clenching his fists. Which actions by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Stay calm when approaching the patient"}, {"id": "b", "text": "Give the patient space"}, {"id": "c", "text": "Use clear, short statements"}, {"id": "d", "text": "Touch his arm to reassure him"}, {"id": "e", "text": "Never turn the back on the patient"}]'::jsonb, '["a", "b", "c", "e"]', 'With signs of violence the nurse stays calm (a), gives space (b), uses clear, short statements (c), and never turns their back on an aggressive patient (e). Touching his arm (d) removes the space the nurse should give.', true),
  ('overview', 34, 'A nurse is evaluating outcomes for a patient being discharged after treatment for depression. Which outcome BEST reflects the core goal of mental health nursing?', '[{"id": "a", "text": "The patient''s symptoms are gone and no follow-up is needed"}, {"id": "b", "text": "The patient takes medication but stays home and avoids others"}, {"id": "c", "text": "The patient''s diagnosis is documented and fully explained"}, {"id": "d", "text": "The patient uses coping skills to return to work and daily life"}]'::jsonb, '["d"]', 'The core goal of mental health nursing is to help patients function, not just treat illness, through crisis intervention and coping support. Symptom control without return to function, or simply documenting the diagnosis, does not meet this goal.', false),
  ('overview', 35, 'A nursing student is asked how to approach a patient in crisis after a sudden loss. Which statement by the student indicates understanding?', '[{"id": "a", "text": "\"Stabilize the patient first, then help the patient regain control.\""}, {"id": "b", "text": "\"Begin teaching new long-term coping skills during the first contact.\""}, {"id": "c", "text": "\"Ask the patient why the event caused such a strong breakdown.\""}, {"id": "d", "text": "\"Leave the patient alone so the patient can regain control alone.\""}]'::jsonb, '["a"]', 'A crisis is a moment of breakdown or loss of coping, and the goal is to stabilize first, then help regain control. Long-term coping teaching comes after stabilization, "why" questions feel judgmental, and leaving the patient alone does not stabilize the patient.', false),
  ('overview', 36, 'A new nurse tells the preceptor, "I don''t bring up suicide with my depressed patients because I''m afraid it will give them the idea." Which response by the preceptor is BEST?', '[{"id": "a", "text": "\"That''s sensible; let the patient raise the topic first.\""}, {"id": "b", "text": "\"Wait until the patient''s SSRI has had time to work.\""}, {"id": "c", "text": "\"Ask only if the patient has made a past attempt.\""}, {"id": "d", "text": "\"Always assess risk directly; never avoid the subject.\""}]'::jsonb, '["d"]', 'Suicide risk is always assessed directly, and the nurse never avoids the subject. Waiting for the patient to raise it, limiting questions to those with past attempts, or waiting for an SSRI to work all avoid direct assessment.', false),
  ('overview', 37, 'A nursing assistant is assigned to one-to-one supervision of a patient who described a plan to hang himself. Which action by the nursing assistant requires IMMEDIATE intervention by the nurse?', '[{"id": "a", "text": "Removes the drawstring cord from the patient''s sweatpants"}, {"id": "b", "text": "Steps away, so no one is with the patient at all times"}, {"id": "c", "text": "Stays with the patient while the patient uses the phone"}, {"id": "d", "text": "Places the patient''s belt in a locked area at the station"}]'::jsonb, '["b"]', 'One-to-one supervision means someone is with the patient at all times, so stepping away while the patient showers is unsafe. Removing cords and belts is a correct safety intervention, and staying with the patient during phone use maintains supervision.', false),
  ('overview', 38, 'A nurse is performing a mental status exam. Which findings should the nurse document as abnormal thought process or thought content? Select all that apply.', '[{"id": "a", "text": "Hearing unreal voices at night"}, {"id": "b", "text": "Delusions (false beliefs) about neighbors"}, {"id": "c", "text": "Uncombed hair and stained clothing"}, {"id": "d", "text": "Speech that is disorganized and unclear"}, {"id": "e", "text": "States, \"I feel empty inside.\""}]'::jsonb, '["b", "d"]', 'Delusions, or false beliefs, are documented under thought content (b), and disorganized speech reflects a disorganized thought process (d). Hearing unreal voices (a) belongs under perception, uncombed hair and stained clothing (c) under appearance, and "I feel empty" (e) is mood.', true),
  ('overview', 39, 'A patient with bipolar disorder had been tearful and low in energy last week. Which new finding today indicates the patient may be entering mania?', '[{"id": "a", "text": "No sleep for 2 nights and high energy"}, {"id": "b", "text": "Stays in bed and says he feels sad"}, {"id": "c", "text": "Shows a flat affect and poor hygiene"}, {"id": "d", "text": "Reports excess worry and tense muscles"}]'::jsonb, '["a"]', 'Mania is high energy, no sleep, and risky behavior, while bipolar depression is low energy and sadness. Flat affect and poor hygiene are negative symptoms of schizophrenia, and excess worry with tense muscles describes anxiety.', false),
  ('overview', 40, 'A nurse reviews a patient''s lithium level of 0.4 mEq/L after the patient reports racing thoughts and sleeping only 2 hours a night. Which interpretation is MOST accurate?', '[{"id": "a", "text": "Levels should be 0.4–1.0, so this is acceptable"}, {"id": "b", "text": "Levels should be 0.6–1.2, so this is too low"}, {"id": "c", "text": "Levels should be 0.3–0.9, so this is acceptable"}, {"id": "d", "text": "Levels should be 1.0–1.5, so this is too low"}]'::jsonb, '["b"]', 'Lithium levels are monitored against a range of 0.6–1.2, so 0.4 is too low, which fits returning manic symptoms of no sleep and high energy. The other ranges are not the ones used to monitor lithium.', false),
  ('overview', 41, 'A nurse is evaluating medication teaching for several patients. Which statements by patients indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "\"Fluoxetine should lift my mood within a day or two.\""}, {"id": "b", "text": "\"Diazepam can make me sleepy, so I''ll be careful.\""}, {"id": "c", "text": "\"Lorazepam is not habit-forming, so extra is safe.\""}, {"id": "d", "text": "\"Phenelzine means I need to avoid tyramine foods.\""}, {"id": "e", "text": "\"Risperidone can cause EPS, so I''ll report changes.\""}]'::jsonb, '["a", "c"]', 'Fluoxetine is an SSRI that takes weeks to work, so expecting improvement in a day or two (a) needs correction, and lorazepam is habit-forming (c). Diazepam is sedating (b), phenelzine requires avoiding tyramine foods (d), and antipsychotics such as risperidone require watching for EPS (e), so those statements are correct.', true),
  ('overview', 42, 'A nurse is planning care for a patient with an anxiety disorder who reports constant worry and a racing heart. Which interventions are appropriate? Select all that apply.', '[{"id": "a", "text": "Use a calm voice when speaking with the patient"}, {"id": "b", "text": "Teach breathing techniques to use when worry rises"}, {"id": "c", "text": "Increase stimulation with loud group games"}, {"id": "d", "text": "Help the patient build coping skills"}, {"id": "e", "text": "Tell the patient, \"You should stop worrying.\""}]'::jsonb, '["a", "b", "d"]', 'For anxiety the nurse uses a calm voice (a), breathing techniques (b), and coping skills (d). Loud games (c) add stimulation instead of limiting it, and "You should..." (e) is giving advice, which therapeutic communication avoids.', true),
  ('overview', 43, 'A nurse is caring for a patient during an acute manic episode. Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Protect the patient from risky behavior"}, {"id": "b", "text": "Set limits clearly and kindly"}, {"id": "c", "text": "Use firm, calm boundaries"}, {"id": "d", "text": "Win arguments to establish control"}, {"id": "e", "text": "Limit stimulation when needed"}]'::jsonb, '["a", "b", "c", "e"]', 'The nurse protects the patient during mania (a), sets limits clearly and kindly (b), uses firm, calm boundaries (c), and limits stimulation when needed (e). Winning arguments (d) creates a power struggle, which should be avoided.', true),
  ('overview', 44, 'A nurse is assessing a patient with OCD. Which findings are compulsions? Select all that apply.', '[{"id": "a", "text": "Unwanted thoughts about germs"}, {"id": "b", "text": "Repeated actions like washing hands"}, {"id": "c", "text": "Flashbacks of a past event"}, {"id": "d", "text": "Repeated actions like checking locks"}, {"id": "e", "text": "Excess worry about safety"}]'::jsonb, '["b", "d"]', 'Compulsions are repeated actions, such as washing hands (b) and checking locks (d) again and again. Unwanted thoughts about germs (a) are obsessions, flashbacks (c) are a PTSD finding, and excess worry (e) describes anxiety disorders.', true),
  ('overview', 45, 'A patient with a car accident 3 months ago reports nightmares about the crash, startles easily at loud noises, and has sudden episodes of reliving the event. The nurse recognizes these findings are MOST consistent with which condition?', '[{"id": "a", "text": "OCD"}, {"id": "b", "text": "Anxiety disorder"}, {"id": "c", "text": "PTSD"}, {"id": "d", "text": "Schizophrenia"}]'::jsonb, '["c"]', 'Flashbacks, nightmares, and startling easily are the findings of PTSD. OCD involves obsessions and compulsions, anxiety disorders involve excess worry, and schizophrenia involves hallucinations and delusions.', false),
  ('overview', 46, 'A patient asks the nurse, "Do you think I should quit my job and move back home?" Which response by the nurse is MOST therapeutic?', '[{"id": "a", "text": "\"Can you tell me more about that?\""}, {"id": "b", "text": "\"Why would you want to move back home right now?\""}, {"id": "c", "text": "\"You should stay where you are until you feel better.\""}, {"id": "d", "text": "\"I moved back home once, and it helped me a lot.\""}]'::jsonb, '["a"]', 'An open-ended question lets the patient explore feelings safely, keeping the focus on the patient''s needs. "You should..." is giving advice, "why" feels judgmental, and sharing the nurse''s own experience shifts focus away from the patient.', false),
  ('overview', 47, 'A patient with schizophrenia tells the nurse, "The TV is sending me special messages about my mission." Which responses by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Explain that televisions cannot send messages to anyone"}, {"id": "b", "text": "Acknowledge that the experience seems real to the patient"}, {"id": "c", "text": "Ask the patient to describe today''s messages in detail"}, {"id": "d", "text": "Redirect gently to a reality-based unit activity"}, {"id": "e", "text": "Agree the messages are real to build the patient''s trust"}]'::jsonb, '["b", "d"]', 'The nurse acknowledges the patient''s experience without reinforcing it (b) and redirects gently (d). Explaining that TVs cannot send messages (a) argues with the delusion, while asking for details (c) or agreeing the messages are real (e) reinforces it.', true),
  ('overview', 48, 'A nurse is reviewing statements patients made to staff during the evening shift. Which statements require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "\"I keep checking the stove.\""}, {"id": "b", "text": "\"I just want it to end.\""}, {"id": "c", "text": "\"I have nightmares about the crash.\""}, {"id": "d", "text": "\"I have a plan and the means to do it.\""}, {"id": "e", "text": "\"My antidepressant hasn''t worked yet.\""}]'::jsonb, '["b", "d"]', '"I want it to end" (b) requires the nurse to stay with the patient and notify the team immediately, and a plan with means (d) are suicide red flags. Checking the stove (a) is a compulsion, nightmares (c) are a PTSD finding, and SSRIs take weeks to work (e).', true),
  ('overview', 49, 'A depressed patient states, "I''ll be fine. You don''t need to keep sitting with me," after describing a plan earlier in the shift. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"All right, I''ll check on you in an hour.\""}, {"id": "b", "text": "\"I''ll stay with you; your safety comes first.\""}, {"id": "c", "text": "\"Why don''t you want me to sit with you?\""}, {"id": "d", "text": "\"You should try to get some rest instead.\""}]'::jsonb, '["b"]', 'Safety is the first priority, above feelings, so the nurse stays with the patient who has a plan. Leaving and checking back later breaks one-to-one supervision, a "why" question feels judgmental, and "You should" is giving advice.', false),
  ('overview', 50, 'A nurse reviews a mental status exam documented by a new graduate for a patient with schizophrenia. Which entries are documented under the correct area? Select all that apply.', '[{"id": "a", "text": "Appearance: unkempt, with stained clothing"}, {"id": "b", "text": "Affect: patient states, \"I''m sad.\""}, {"id": "c", "text": "Perception: hearing unreal voices"}, {"id": "d", "text": "Thought content: delusions that he is followed"}, {"id": "e", "text": "Insight: says he is not ill and needs no help"}]'::jsonb, '["a", "c", "d", "e"]', 'Appearance covers whether the patient is clean, dressed, and groomed (a); perception covers hallucinations such as hearing unreal voices (c); thought content covers delusions (d); and insight is whether the patient understands they are ill (e). "I''m sad" (b) is how the patient says they feel, which is mood, not affect, because affect is what the nurse sees.', true),
  ('therapeutic', 1, 'A nurse is assigned to a newly admitted patient whose chart documents repeated violence toward a partner. While reading the history before the first meeting, the nurse notices feeling angry and judgmental toward the patient. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Introduce self to the patient and explain the nurse''s role on the unit"}, {"id": "b", "text": "Reflect on personal biases and feelings that could interfere with care"}, {"id": "c", "text": "Encourage the patient to express feelings about the violent incidents"}, {"id": "d", "text": "Set treatment goals with the patient before these feelings grow stronger"}]'::jsonb, '["b"]', 'Before first contact, the nurse is in the pre-interaction phase, and self-reflection on personal biases, feelings, or attitudes that could interfere with care is the key nursing activity. Introducing self and setting goals belong to the orientation phase, and encouraging expression of feelings belongs to the working phase.', false),
  ('therapeutic', 2, 'On the first day of admission, a patient with depression watches the nurse warily and says, "I don''t even know who you are or what you want from me." Which response by the nurse is MOST appropriate at this point in the relationship?', '[{"id": "a", "text": "\"Don''t worry, you can trust me. Everything we talk about will be fine.\""}, {"id": "b", "text": "\"Why are you so suspicious of the staff who are here to help you?\""}, {"id": "c", "text": "\"Tell me more about how you have coped with sadness in the past.\""}, {"id": "d", "text": "\"I''m your nurse. Let me explain my role so we can set goals together.\""}]'::jsonb, '["d"]', 'The first contact is the orientation phase: the nurse introduces themselves, explains their role, and sets goals collaboratively so the patient can begin to trust the nurse. Identifying coping patterns is working-phase work and is premature before trust exists; "Don''t worry" is false reassurance and a "why" question sounds judgmental.', false),
  ('therapeutic', 3, 'A nurse is holding the final scheduled one-to-one session with a patient who will be discharged tomorrow after a 3-week stay. Which nursing actions are appropriate for this session? Select all that apply.', '[{"id": "a", "text": "Summarize the patient''s progress"}, {"id": "b", "text": "Avoid discussing the ending so the patient does not feel sad"}, {"id": "c", "text": "Introduce self and establish the boundaries of the relationship"}, {"id": "d", "text": "Review the goals achieved"}, {"id": "e", "text": "Prepare the patient for discharge or transition"}]'::jsonb, '["a", "d", "e"]', 'This is the termination phase. Summarizing progress (a), reviewing goals achieved (d), and preparing the patient for discharge or transition (e) are the nurse''s termination tasks. Avoiding the ending (b) is wrong because the nurse must not avoid the topic or minimize the patient''s feelings. Introducing self and establishing boundaries (c) are orientation-phase actions.', true),
  ('therapeutic', 4, 'A patient who had attended every group and practiced new coping skills begins skipping groups and becomes tearful and irritable 2 days before a planned discharge. The patient tells the nurse, "I guess you''re done with me now." Which nursing action is BEST?', '[{"id": "a", "text": "Encourage the patient to talk about feelings about the relationship ending"}, {"id": "b", "text": "Avoid mentioning the discharge until the patient''s mood has improved"}, {"id": "c", "text": "Remind the patient that everyone feels sad when leaving the hospital"}, {"id": "d", "text": "Refocus the session on identifying new coping patterns to work on"}]'::jsonb, '["a"]', 'Regression, sadness, and feeling abandoned are expected in the termination phase, and the nurse must allow the patient to express feelings about the relationship ending and normalize them. Avoiding the topic and minimizing ("everyone feels sad") are specifically what the nurse should not do.', false),
  ('therapeutic', 5, 'A nurse has met with a patient with an anxiety disorder several times. The patient now openly admits to drinking alcohol whenever stressed, and the patient and nurse are examining what happens before each episode. Which nursing action is MOST consistent with this phase of the relationship?', '[{"id": "a", "text": "Reviews the chart and reflects on personal attitudes"}, {"id": "b", "text": "Summarizes progress and prepares the patient for transition"}, {"id": "c", "text": "Provides education and supports healthy coping skills"}, {"id": "d", "text": "Introduces themselves and explains their role to the patient"}]'::jsonb, '["c"]', 'The patient is exploring thoughts and behaviors and the pair is examining coping patterns, which places them in the working phase, where the nurse provides education and supports development of healthy coping skills. Chart review is pre-interaction, introductions are orientation, and summarizing progress is termination.', false),
  ('therapeutic', 6, 'During the working phase, a patient tells the nurse, "My partner keeps putting me down in front of our friends. Just tell me what I should do." Which response by the nurse is MOST therapeutic?', '[{"id": "a", "text": "\"You should just leave that relationship and focus on yourself.\""}, {"id": "b", "text": "\"Tell me more about what happened with your partner.\""}, {"id": "c", "text": "\"Why do you stay with someone who treats you that way?\""}, {"id": "d", "text": "\"Everyone has disagreements with their partner sometimes.\""}]'::jsonb, '["b"]', 'In the working phase the patient explores thoughts, behaviors, and feelings while the nurse guides but does not lead, so exploring ("Tell me more about what happened") is most therapeutic. Advising takes away the patient''s autonomy, the "why" question sounds judgmental, and "everyone has disagreements" minimizes the patient''s emotions.', false),
  ('therapeutic', 7, 'A charge nurse is observing staff interactions on an inpatient psychiatric unit. Which staff behaviors require the charge nurse to intervene? Select all that apply.', '[{"id": "a", "text": "A nurse tells a grieving patient, \"I went through a divorce too.\""}, {"id": "b", "text": "A nurse tells a shouting patient, \"I need you to lower your voice so we can talk calmly.\""}, {"id": "c", "text": "A nurse hugs a patient with a trauma history to comfort her."}, {"id": "d", "text": "A nurse tells a patient with romantic feelings, \"This is a professional relationship.\""}, {"id": "e", "text": "A nurse accepts an expensive necklace from a patient at discharge."}]'::jsonb, '["a", "c", "e"]', 'Sharing personal problems (a) shifts focus from the patient to the nurse; hugging a patient who has not been asked (c) is touching without consent and may trigger trauma; accepting an expensive gift (e) creates favoritism and ethical issues. Asking a shouting patient to lower the voice (b) is correct limit setting, and stating that the relationship is professional (d) is the correct response to romantic feelings.', true),
  ('therapeutic', 8, 'On the day of discharge, a patient hands the nurse a gold bracelet and says, "You''re the only one who really helped me here. Please take this." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Thank you, I''ll accept it so your feelings aren''t hurt, but just this once.\""}, {"id": "b", "text": "\"Why do you feel you need to give me something to thank me?\""}, {"id": "c", "text": "\"I can''t accept gifts; this is a professional relationship.\""}, {"id": "d", "text": "\"I''ll accept it and share it with all the staff who cared for you.\""}]'::jsonb, '["c"]', 'The nurse must never accept gifts from patients because it blurs professional boundaries and creates favoritism or ethical issues; stating this keeps the relationship professional. Accepting "just this once" or on behalf of the staff is still accepting the gift, and a "why" question sounds judgmental.', false),
  ('therapeutic', 9, 'A patient pulls the nurse aside and whispers, "I''ll tell you something important, but only if you promise not to tell anyone. It''s about hurting myself." Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "\"I promise. Whatever you tell me will stay between the two of us.\""}, {"id": "b", "text": "\"Why would you want to hurt yourself when you''re doing so well?\""}, {"id": "c", "text": "\"Let''s talk about it later, after you''ve had a chance to rest.\""}, {"id": "d", "text": "\"I can''t promise to keep secrets; nurses must report harm.\""}]'::jsonb, '["d"]', 'Keeping secrets about self-harm is a boundary violation and a safety risk because nurses must report harm, so the nurse cannot promise confidentiality. A "why" question sounds judgmental, and postponing the conversation changes the subject and avoids the patient''s concern.', false),
  ('therapeutic', 10, 'A patient with major depression tells the nurse, "There''s no point anymore. I''ve been saving my pills in my drawer." When asked, the patient confirms a plan to take them tonight. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Leave to remove the saved pills from the patient''s drawer right away"}, {"id": "b", "text": "Tell the patient that things will get better once treatment starts"}, {"id": "c", "text": "Stay with the patient and notify the provider immediately"}, {"id": "d", "text": "Go to the nurses'' station to call the provider about the plan"}]'::jsonb, '["c"]', 'The patient has a plan, means, and intent, so the nurse must stay with the patient and notify the provider immediately. Leaving to remove the pills or to phone the provider leaves the patient alone, and saying things will get better is false reassurance.', false),
  ('therapeutic', 11, 'While helping a patient with a puzzle in the dayroom, the nurse hears the patient mutter, "My family would be better off without me around." Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "\"Are you thinking of harming yourself?\""}, {"id": "b", "text": "\"Everyone feels like a burden sometimes.\""}, {"id": "c", "text": "\"You shouldn''t say that; they love you.\""}, {"id": "d", "text": "\"Why would your family feel that way?\""}]'::jsonb, '["a"]', 'A statement suggesting suicidal thoughts requires the nurse to ask directly about self-harm and then assess for plan, means, and intent. Saying everyone feels like a burden minimizes, telling the patient what not to say dismisses the feeling, and a "why" question sounds judgmental.', false),
  ('therapeutic', 12, 'A patient admitted for depression tells the nurse, "I''ve decided tonight is the night I end it all." Which actions should the nurse take? Select all that apply.', '[{"id": "a", "text": "Ask directly, \"Are you thinking of harming yourself?\""}, {"id": "b", "text": "Assess for a plan, means, and intent"}, {"id": "c", "text": "Leave briefly to call the provider from the station"}, {"id": "d", "text": "Stay with the patient"}, {"id": "e", "text": "Notify the provider immediately"}]'::jsonb, '["a", "b", "d", "e"]', 'For suicidal statements the nurse asks directly (a), assesses for plan, means, and intent (b), stays with the patient (d), and notifies the provider immediately (e). Leaving to call the provider (c) is wrong even though notification is needed, because the nurse must not leave the patient alone.', true),
  ('therapeutic', 13, 'A patient shouts at the nurse in the dayroom about a cancelled weekend pass, waving both arms while other patients watch. The patient has not approached or touched anyone. Which statement by the nurse is MOST appropriate?', '[{"id": "a", "text": "\"If you keep yelling, you will lose your privileges for the week.\""}, {"id": "b", "text": "\"Why are you yelling at me when I didn''t cancel your pass?\""}, {"id": "c", "text": "\"You have no reason to be this upset over a single pass.\""}, {"id": "d", "text": "\"I need you to lower your voice so we can talk calmly.\""}]'::jsonb, '["d"]', 'With an angry patient the nurse remains calm and sets limits, such as asking the patient to lower the voice so they can talk calmly. Threatening loss of privileges and arguing that the anger is unjustified are specifically to be avoided, and a "why" question makes the patient defensive.', false),
  ('therapeutic', 14, 'A patient who has been yelling in the hallway ignores the nurse''s request to lower the voice, picks up a chair, and moves toward another patient. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Offer the patient a choice between returning to the room or a quiet area"}, {"id": "b", "text": "Restate the limit to the patient using a firm but calm tone of voice"}, {"id": "c", "text": "Explore with the patient what triggered the anger about the situation"}, {"id": "d", "text": "Call for help to ensure the safety of the other patients and staff"}]'::jsonb, '["d"]', 'Once the patient threatens another person, safety comes first and the nurse calls for help. Offering choices and restating limits are appropriate for an angry patient who is not posing an immediate danger, and exploring triggers can wait until everyone is safe.', false),
  ('therapeutic', 15, 'A patient who has worked with the same nurse for 2 weeks says, "I think I''m falling for you. Could we meet for coffee after I''m discharged?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"I''m flattered, but I''m married, so that just wouldn''t be possible.\""}, {"id": "b", "text": "\"I am here to support your health — this is a professional relationship.\""}, {"id": "c", "text": "\"Why would you want to see your nurse outside of the hospital?\""}, {"id": "d", "text": "\"Let''s not get into that right now. How was your group today?\""}]'::jsonb, '["b"]', 'When a patient develops romantic feelings the nurse sets firm, professional boundaries immediately and then redirects to treatment goals. Mentioning the nurse''s marriage shares personal information and shifts focus to the nurse, a "why" question is judgmental, and simply changing the subject avoids the issue without setting a boundary.', false),
  ('therapeutic', 16, 'A nurse has twice set firm boundaries and redirected a patient to treatment goals, but the patient continues to leave love notes on the nurse''s medication cart. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Keep the notes private to avoid embarrassing the patient"}, {"id": "b", "text": "Tell the patient about the nurse''s own relationship status"}, {"id": "c", "text": "Document the behavior and report it to the supervisor"}, {"id": "d", "text": "Ask the patient why the notes keep being left on the cart"}]'::jsonb, '["c"]', 'When romantic behavior continues after boundaries are set and focus is redirected, the nurse documents and reports to the supervisor. Keeping the notes private is keeping secrets, sharing relationship status shifts focus to the nurse, and a "why" question sounds judgmental.', false),
  ('therapeutic', 17, 'A patient whose chart documents years of abuse by her father becomes hostile and sarcastic toward an older male nurse during their first conversation, although the nurse has done nothing to provoke her. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Countertransference, because the nurse''s past is affecting judgment"}, {"id": "b", "text": "Transference, because the patient projects feelings about her father"}, {"id": "c", "text": "A boundary violation, because focus has shifted from patient to nurse"}, {"id": "d", "text": "Termination-phase regression, because the patient feels abandoned"}]'::jsonb, '["b"]', 'In transference the patient projects feelings about someone from the past onto the nurse, such as treating the nurse like an abusive parent and becoming hostile for no apparent reason. Countertransference is the nurse''s feelings toward the patient, and regression with abandonment belongs to the termination phase, not a first conversation.', false),
  ('therapeutic', 18, 'A nurse caring for a 17-year-old patient tells a coworker, "She reminds me so much of my daughter. I''ve been staying late to sit with her, and I don''t want anyone else assigned to her." Which conclusion by the coworker is MOST accurate?', '[{"id": "a", "text": "The patient is demonstrating transference toward the nurse"}, {"id": "b", "text": "The nurse is in the working phase and is building rapport"}, {"id": "c", "text": "The nurse is showing empathy, which strengthens the relationship"}, {"id": "d", "text": "The nurse is demonstrating countertransference toward the patient"}]'::jsonb, '["d"]', 'Countertransference is the nurse projecting personal feelings onto the patient, such as a patient reminding the nurse of their own child and the nurse becoming overly protective with difficulty maintaining boundaries. Transference describes the patient''s feelings toward the nurse, and empathy is understanding feelings without judgment, not overprotection.', false),
  ('therapeutic', 19, 'A nurse educator presents situations observed on a psychiatric unit. Which situations are examples of transference? Select all that apply.', '[{"id": "a", "text": "A nurse feels irritated by a patient who reminds her of a former partner"}, {"id": "b", "text": "A patient shows dependency on a nurse who reminds her of a sibling"}, {"id": "c", "text": "A patient says she feels abandoned now that her nurse is ending their sessions"}, {"id": "d", "text": "A nurse becomes overly protective of a patient who resembles her own son"}, {"id": "e", "text": "A patient becomes hostile toward a nurse who reminds him of an abusive parent"}]'::jsonb, '["b", "e"]', 'Transference is the patient responding to the nurse with old feelings about someone from the past, often anger, dependency, or affection, so dependency on a nurse who resembles a sister (b) and hostility toward a nurse who resembles an abusive parent (e) are transference. The nurse''s irritation (a) and overprotectiveness (d) are the nurse''s feelings toward the patient, which is countertransference. Feeling abandoned when sessions end (c) is an expected termination-phase response.', true),
  ('therapeutic', 20, 'A patient sobs while describing the recent death of a dog that had been her only companion since her divorce. Which response by the nurse BEST demonstrates empathy?', '[{"id": "a", "text": "\"I''m so heartbroken for you that I''m about to cry myself.\""}, {"id": "b", "text": "\"It sounds like you''re feeling very alone without her.\""}, {"id": "c", "text": "\"Don''t worry, you can always adopt another dog later.\""}, {"id": "d", "text": "\"Everyone feels sad when they lose a pet at some point.\""}]'::jsonb, '["b"]', 'Empathy is understanding the patient''s feelings without judgment, shown here by reflecting the feeling back. Becoming heartbroken and tearful along with the patient is sympathy, which merges feelings; "don''t worry" is false reassurance and "everyone feels sad" minimizes.', false),
  ('therapeutic', 21, 'After describing a traumatic memory for the first time, a patient stops talking, looks at the floor, and appears to be searching for words. The pause has lasted about 20 seconds. Which action by the nurse is BEST?', '[{"id": "a", "text": "Remain quiet and give the patient time to think"}, {"id": "b", "text": "Change the subject to something less upsetting"}, {"id": "c", "text": "Tell the patient that everything will be fine now"}, {"id": "d", "text": "Ask the patient why the memory is still so upsetting"}]'::jsonb, '["a"]', 'Silence is a therapeutic technique that allows quiet and gives the patient time to think. Changing the subject avoids the patient''s concerns, saying everything will be fine is false reassurance, and a "why" question makes the patient defensive.', false),
  ('therapeutic', 22, 'A nursing student is caring for a patient who says, "I just can''t handle my job anymore." Which responses by the student are therapeutic? Select all that apply.', '[{"id": "a", "text": "\"You should just start looking for a different job.\""}, {"id": "b", "text": "\"Tell me more about what''s going on at work.\""}, {"id": "c", "text": "\"Why do you feel that way about your job?\""}, {"id": "d", "text": "\"It sounds like you''re feeling frustrated.\""}, {"id": "e", "text": "\"Everyone feels overwhelmed at work sometimes.\""}]'::jsonb, '["b", "d"]', 'Active listening ("Tell me more about what''s going on") (b) and reflection ("It sounds like you''re feeling frustrated") (d) are therapeutic. Advising (a) takes away the patient''s autonomy, a "why" question (c) sounds judgmental and makes the patient defensive, and "everyone feels overwhelmed" (e) is minimizing, which dismisses emotions.', true),
  ('therapeutic', 23, 'A patient with depression says, "Things at home are just... off. You know how it is." Which response by the nurse is MOST therapeutic?', '[{"id": "a", "text": "\"Yes, I know exactly how family life can be.\""}, {"id": "b", "text": "\"Do you get along with the people at home?\""}, {"id": "c", "text": "\"Can you explain what you mean by that?\""}, {"id": "d", "text": "\"Why are things at home off for you lately?\""}]'::jsonb, '["c"]', 'The patient''s statement is vague, so clarification ("Can you explain what you mean by that?") is the most therapeutic technique. The yes/no question limits expression, agreeing that the nurse knows how it is shifts focus to the nurse, and a "why" question makes the patient defensive.', false),
  ('therapeutic', 24, 'A nurse precepting a new graduate on a psychiatric unit hears the graduate ask four different patients the following questions during morning rounds. Which question requires follow-up by the preceptor?', '[{"id": "a", "text": "\"How are you feeling about your discharge plans today?\""}, {"id": "b", "text": "\"Are you feeling okay today?\""}, {"id": "c", "text": "\"Can you explain what you mean by feeling on edge?\""}, {"id": "d", "text": "\"What would you like to talk about during our time today?\""}]'::jsonb, '["b"]', 'The nurse should always use open-ended questions to encourage the patient to express themselves and avoid yes/no questions; asking whether the patient is feeling okay invites only a yes or no. The other questions are open-ended or seek clarification.', false),
  ('therapeutic', 25, 'A patient says, "My psychiatrist keeps changing my medications. I don''t think he knows what he''s doing." Which response by a nurse requires follow-up by the charge nurse?', '[{"id": "a", "text": "\"I think your doctor is wrong to keep changing them.\""}, {"id": "b", "text": "\"It sounds like you''re frustrated with all these changes.\""}, {"id": "c", "text": "\"Tell me more about what''s been happening with them.\""}, {"id": "d", "text": "\"Can you explain what concerns you most about the changes?\""}]'::jsonb, '["a"]', 'Agreeing or disagreeing, such as saying the doctor is wrong, creates division and is unprofessional. Reflection, exploring, and clarification are therapeutic techniques that keep the focus on the patient''s concerns.', false),
  ('therapeutic', 26, 'A patient with a history of sexual assault begins crying during a one-to-one session. The nurse feels the urge to comfort the patient physically. Which action by the nurse is BEST?', '[{"id": "a", "text": "Hug the patient right away to show genuine caring"}, {"id": "b", "text": "Leave the patient alone until the crying has stopped"}, {"id": "c", "text": "Tell the patient not to worry because she is safe here"}, {"id": "d", "text": "Ask for consent before touching, such as hugging"}]'::jsonb, '["d"]', 'Touching without consent, such as hugging without asking, may trigger trauma and is a boundary violation, especially for a patient with an assault history. Leaving the patient alone abandons the patient''s concern, and "don''t worry" is false reassurance.', false),
  ('therapeutic', 27, 'During a one-to-one session, a patient asks the nurse, "Enough about me. Are you married? Do you ever get depressed too?" Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "\"I''ve had some hard times too, so I understand how you feel.\""}, {"id": "b", "text": "\"Yes, I''m married, and I get down sometimes like everyone.\""}, {"id": "c", "text": "\"Why do you want to know so much about my personal life?\""}, {"id": "d", "text": "\"This time is for you. Tell me more about what''s going on.\""}]'::jsonb, '["d"]', 'A therapeutic relationship is patient-centered; the nurse focuses on helping the patient, not forming a personal friendship, so the nurse redirects to the patient and uses active listening. Sharing personal problems shifts focus from patient to nurse, and a "why" question sounds judgmental.', false),
  ('therapeutic', 28, 'A nurse is reviewing a care plan with a patient and must address several behaviors observed during the last few days. Which patient situations require the nurse to share information beyond the one-to-one relationship? Select all that apply.', '[{"id": "a", "text": "The patient asks the nurse to promise not to tell anyone about plans to self-harm"}, {"id": "b", "text": "The patient expresses sadness that the sessions with the nurse are ending soon"}, {"id": "c", "text": "The patient expresses suicidal thoughts and describes a plan and the means"}, {"id": "d", "text": "The patient continues to express romantic feelings after firm boundaries are set"}, {"id": "e", "text": "The patient becomes hostile toward a nurse who resembles an abusive parent"}]'::jsonb, '["a", "c", "d"]', 'Keeping secrets about self-harm (a) is a safety risk because nurses must report harm; suicidal thoughts with a plan (c) require notifying the provider immediately; ongoing romantic behavior after boundaries are set (d) is documented and reported to the supervisor if needed. Sadness about ending (b) is an expected termination response the nurse lets the patient express, and hostility toward a nurse resembling a parent (e) is transference.', true),
  ('therapeutic', 29, 'A nurse is meeting a newly admitted patient for the first time on an inpatient unit. Which nursing actions are appropriate during this meeting? Select all that apply.', '[{"id": "a", "text": "Summarize the patient''s progress toward goals"}, {"id": "b", "text": "Explain the nurse''s role and begin building rapport"}, {"id": "c", "text": "Encourage the patient to describe coping patterns in depth"}, {"id": "d", "text": "Set goals and boundaries collaboratively with the patient"}, {"id": "e", "text": "Review the chart and reflect on personal biases"}]'::jsonb, '["b", "d"]', 'The first meeting is the orientation phase, in which the nurse introduces themselves and explains their role (b) and sets goals and boundaries collaboratively (d). Summarizing progress (a) is termination, identifying coping patterns in depth (c) is working-phase work, and chart review with self-reflection (e) happens before the first contact in pre-interaction.', true),
  ('therapeutic', 30, 'After several days of meeting with the nurse, a previously guarded patient says, "You''ve shown up every time you said you would. I feel safe telling you things now." Which conclusion by the nurse is MOST accurate?', '[{"id": "a", "text": "The patient is projecting feelings about a past figure onto the nurse"}, {"id": "b", "text": "The patient is beginning to trust the nurse as a safe, consistent presence"}, {"id": "c", "text": "The patient is ready to summarize progress and prepare for discharge"}, {"id": "d", "text": "The nurse has developed countertransference toward the patient"}]'::jsonb, '["b"]', 'An orientation-phase goal is that the patient begins to trust the nurse as a safe, consistent presence, which this statement shows. Transference involves old feelings about someone from the past, summarizing progress belongs to termination, and countertransference is the nurse''s feelings toward the patient.', false),
  ('therapeutic', 31, 'A nurse reviews a nursing student''s responses to a patient who said, "I''m so scared about my court date tomorrow." Which student responses require follow-up? Select all that apply.', '[{"id": "a", "text": "\"Don''t worry, everything will be fine.\""}, {"id": "b", "text": "\"It sounds like you feel really scared.\""}, {"id": "c", "text": "\"Everyone feels nervous sometimes.\""}, {"id": "d", "text": "\"Why do you feel that way about it?\""}, {"id": "e", "text": "\"Let''s not talk about that right now.\""}]'::jsonb, '["a", "c", "d", "e"]', '"Don''t worry" (a) is false reassurance that dismisses feelings and may be untrue; "everyone gets nervous" (c) is minimizing, which dismisses emotions; a "why" question (d) sounds judgmental and makes the patient defensive; switching to lunch (e) is changing the subject, which avoids the patient''s concerns. Reflecting the feeling (b) is therapeutic.', true),
  ('therapeutic', 32, 'A nurse caring for a patient who repeatedly describes the same fishing trip feels impatient but says with a wide smile, "I just love hearing this story every time!" Which quality of a therapeutic relationship is the nurse MOST clearly failing to show?', '[{"id": "a", "text": "Genuineness"}, {"id": "b", "text": "Empathy"}, {"id": "c", "text": "Respect"}, {"id": "d", "text": "Boundaries"}]'::jsonb, '["a"]', 'Genuineness means being honest and authentic, not pretending to care; claiming to love the story while feeling impatient is pretending. Empathy is understanding feelings without judgment, respect is acknowledging dignity and autonomy, and boundaries keep the relationship professional, none of which is the main problem here.', false),
  ('therapeutic', 33, 'A nurse returns from a meeting to four patient concerns relayed by staff. Which patient should the nurse see FIRST?', '[{"id": "a", "text": "A patient in the final session who says, \"I feel like you''re abandoning me.\""}, {"id": "b", "text": "A patient at discharge who wants to give the nurse a homemade thank-you card"}, {"id": "c", "text": "A patient who said, \"Promise you won''t tell if I hurt myself tonight.\""}, {"id": "d", "text": "A patient who snapped at a male nurse who reminds her of her father"}]'::jsonb, '["c"]', 'A request to keep self-harm secret signals possible harm, and keeping such secrets is a safety risk because nurses must report harm, so this patient is seen first. Feelings of abandonment at termination are expected, a gift issue and a transference reaction without danger can be addressed after safety is ensured.', false),
  ('therapeutic', 34, 'A patient pacing and raising his voice about having to attend group lowers his voice after the nurse sets a limit, but he still refuses to go. Which action by the nurse is MOST appropriate NEXT?', '[{"id": "a", "text": "Tell him he will be restrained if he raises his voice again"}, {"id": "b", "text": "Offer choices about when to attend while maintaining his dignity"}, {"id": "c", "text": "Point out that his anger about group is not reasonable"}, {"id": "d", "text": "Ask him why attending group upsets him so much today"}]'::jsonb, '["b"]', 'After setting limits with an angry patient, the nurse offers choices and maintains the patient''s dignity. Threatening and arguing are to be avoided, and a "why" question makes the patient defensive.', false),
  ('therapeutic', 35, 'A patient is yelling and pacing in the hallway after an upsetting phone call but has not threatened anyone. Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Remain calm while speaking with the patient"}, {"id": "b", "text": "Point out the flaws in the patient''s version of the call"}, {"id": "c", "text": "Warn the patient that privileges will be lost if this continues"}, {"id": "d", "text": "Offer the patient choices that maintain dignity"}, {"id": "e", "text": "Call for help if needed to ensure safety"}]'::jsonb, '["a", "d", "e"]', 'With an angry patient the nurse remains calm (a), offers choices and maintains dignity (d), and ensures safety by calling for help if needed (e). Arguing about the facts (b) and threatening loss of privileges (c) are specifically to be avoided.', true),
  ('therapeutic', 36, 'A patient tells the nurse, "I''ve fallen in love with you, and I know you feel the same way." Which actions by the nurse are appropriate at this time? Select all that apply.', '[{"id": "a", "text": "Share that the nurse is already in a relationship"}, {"id": "b", "text": "Set firm, professional boundaries immediately"}, {"id": "c", "text": "Agree to keep the patient''s statement between them"}, {"id": "d", "text": "Ask the patient why he believes the nurse feels the same"}, {"id": "e", "text": "Redirect the focus to the patient''s treatment goals"}]'::jsonb, '["b", "e"]', 'When a patient develops romantic feelings the nurse sets firm, professional boundaries immediately (b) and redirects focus to treatment goals (e). Sharing the nurse''s relationship status (a) shifts focus to the nurse, keeping secrets (c) is a boundary violation, and a "why" question (d) sounds judgmental.', true),
  ('therapeutic', 37, 'A colleague asks a patient who returned from a pass intoxicated, "Why did you drink when you knew it was against the rules?" The nurse plans to give the colleague feedback. Which explanation is MOST accurate?', '[{"id": "a", "text": "The question can be answered only with a yes or a no"}, {"id": "b", "text": "The question offers false reassurance about the outcome"}, {"id": "c", "text": "The question sounds judgmental and makes the patient defensive"}, {"id": "d", "text": "The question shifts the focus from the patient to the colleague"}]'::jsonb, '["c"]', '"Why" questions sound judgmental and make the patient defensive. The question is not a yes/no question, does not reassure, and does not involve the colleague sharing personal problems.', false),
  ('therapeutic', 38, 'A nurse will meet a newly admitted patient for the first time tomorrow morning. Which activities should the nurse complete before meeting the patient? Select all that apply.', '[{"id": "a", "text": "Explain the nurse''s role to the patient by phone"}, {"id": "b", "text": "Review the patient''s history and chart"}, {"id": "c", "text": "Plan to share a similar personal story to build trust"}, {"id": "d", "text": "Establish treatment goals with the patient"}, {"id": "e", "text": "Reflect on personal biases and attitudes"}]'::jsonb, '["b", "e"]', 'Before meeting the patient (pre-interaction), the nurse reviews the history and chart (b) and reflects on personal biases, feelings, or attitudes that could interfere with care (e). Explaining the role (a) and setting goals (d) occur in orientation, and sharing personal stories (c) shifts focus from the patient to the nurse.', true),
  ('therapeutic', 39, 'A nurse supervisor is evaluating a new nurse''s interactions with patients. Which behaviors by the new nurse demonstrate the core qualities of a therapeutic relationship? Select all that apply.', '[{"id": "a", "text": "Being honest and authentic with the patient"}, {"id": "b", "text": "Understanding the patient''s feelings without judgment"}, {"id": "c", "text": "Sharing in the patient''s feelings so they feel less alone"}, {"id": "d", "text": "Acknowledging the patient''s dignity, worth, and autonomy"}, {"id": "e", "text": "Keeping the relationship professional, not personal"}]'::jsonb, '["a", "b", "d", "e"]', 'Genuineness is being honest and authentic (a), empathy is understanding feelings without judgment (b), respect acknowledges dignity, worth, and autonomy (d), and boundaries keep the relationship professional, not personal (e). Sharing in the patient''s feelings (c) is sympathy, which merges feelings, rather than empathy.', true),
  ('therapeutic', 40, 'A nurse is evaluating a patient during the last week of a planned 4-week admission as the nurse begins summarizing goals achieved. Which patient responses are expected findings at this stage of the relationship? Select all that apply.', '[{"id": "a", "text": "Feeling abandoned by the nurse"}, {"id": "b", "text": "Feeling sad about the discharge"}, {"id": "c", "text": "Asking the nurse to explain the nurse''s role"}, {"id": "d", "text": "Becoming regressive in coping"}, {"id": "e", "text": "Treating the nurse like an abusive parent"}]'::jsonb, '["a", "b", "d"]', 'In the termination phase patients may feel abandoned (a), sad (b), or regressive (d), and the nurse normalizes these responses. Asking about the nurse''s role (c) fits orientation, and treating the nurse like an abusive parent (e) is transference.', true),
  ('therapeutic', 41, 'A nurse and patient have been meeting for 3 weeks, and the patient now openly explores thoughts and behaviors. Which nursing actions are appropriate during this phase? Select all that apply.', '[{"id": "a", "text": "Encourages expression of feelings"}, {"id": "b", "text": "Identifies coping patterns"}, {"id": "c", "text": "Tells the patient which solution to choose"}, {"id": "d", "text": "Provides education"}, {"id": "e", "text": "Supports development of healthy coping skills"}]'::jsonb, '["a", "b", "d", "e"]', 'In the working phase the nurse encourages expression of feelings (a), identifies coping patterns (b), provides education (d), and supports healthy coping skills (e). Telling the patient which solution to choose (c) is wrong because the nurse guides but does not lead, and advising takes away autonomy.', true),
  ('therapeutic', 42, 'A patient says, "I''m going to stop my medications; they don''t do anything." Which nurse responses require follow-up because they are non-therapeutic? Select all that apply.', '[{"id": "a", "text": "\"Tell me more about what''s going on with them.\""}, {"id": "b", "text": "\"You should just do what your doctor says.\""}, {"id": "c", "text": "\"Why do you feel that way about them?\""}, {"id": "d", "text": "\"It sounds like you''re feeling frustrated.\""}, {"id": "e", "text": "\"I think your doctor is wrong to order them.\""}]'::jsonb, '["b", "c", "e"]', 'Advising ("You should...") (b) takes away the patient''s autonomy, a "why" question (c) sounds judgmental, and saying the doctor is wrong (e) is agreeing/disagreeing, which creates division and is unprofessional. Active listening (a) and reflection (d) are therapeutic.', true),
  ('therapeutic', 43, 'A patient says, "I''m worried my kids will be taken away from me while I''m in here." Which response by the nurse is MOST therapeutic?', '[{"id": "a", "text": "\"Don''t worry, I''m sure your children will be just fine.\""}, {"id": "b", "text": "\"Why do you think someone would take your children?\""}, {"id": "c", "text": "\"You should call a lawyer about it as soon as you can.\""}, {"id": "d", "text": "\"It sounds like you''re worried; tell me more about that.\""}]'::jsonb, '["d"]', 'The nurse should never say "Don''t worry" but should acknowledge the emotion and encourage discussion, as reflection plus exploring does. A "why" question sounds judgmental, and telling the patient to call a lawyer is advising, which takes away autonomy.', false),
  ('therapeutic', 44, 'On the day before discharge, a patient says, "Can we stay friends after I leave? I''d love to call you sometimes." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Our relationship is professional and time-limited; let''s focus on your goals.\""}, {"id": "b", "text": "\"Sure, I''d like that. I''ll give you my number before you go home.\""}, {"id": "c", "text": "\"Why would you want to stay in touch with a nurse after discharge?\""}, {"id": "d", "text": "\"Don''t worry about that now; we can figure it out after discharge.\""}]'::jsonb, '["a"]', 'A therapeutic relationship is professional, goal-oriented, and time-limited, and it is not a personal friendship, so the nurse restates this and refocuses on goals. Sharing a number forms a personal friendship, the "why" question is judgmental, and "don''t worry" postpones the issue with false reassurance.', false),
  ('therapeutic', 45, 'A patient returns from the visiting area, sits down heavily, and tells the nurse, "I had a terrible visit with my brother today." Which INITIAL response by the nurse is BEST?', '[{"id": "a", "text": "\"Did the two of you argue about money again?\""}, {"id": "b", "text": "\"Tell me more about what happened during it.\""}, {"id": "c", "text": "\"Don''t worry, family visits get easier with time.\""}, {"id": "d", "text": "\"You should limit his visits for the time being.\""}]'::jsonb, '["b"]', 'Exploring ("Tell me more about what happened") encourages the patient to express themselves. A question that can be answered yes or no limits expression, "don''t worry" is false reassurance, and advising takes away autonomy.', false),
  ('therapeutic', 46, 'A nurse observes a nursing assistant interacting with patients on the unit. Which action by the nursing assistant requires IMMEDIATE intervention by the nurse?', '[{"id": "a", "text": "Putting an arm around a crying patient with a trauma history"}, {"id": "b", "text": "Sitting quietly beside a tearful patient who is gathering thoughts"}, {"id": "c", "text": "Asking a patient, \"How are you feeling today?\" during rounds"}, {"id": "d", "text": "Telling a shouting patient, \"I need you to lower your voice.\""}]'::jsonb, '["a"]', 'Putting an arm around the patient without asking is touching without consent, which may trigger trauma and is a boundary violation. Silence, open-ended questions, and setting limits on an angry patient''s volume are appropriate.', false),
  ('therapeutic', 47, 'A nurse who grew up with a father who drank heavily finds herself avoiding a patient admitted for alcohol use and speaking curtly to him, although he has been polite. Which statement BEST describes what is occurring?', '[{"id": "a", "text": "The patient is projecting feelings about his past onto the nurse"}, {"id": "b", "text": "The nurse''s unresolved emotions are affecting professional judgment"}, {"id": "c", "text": "The patient is regressing because the relationship is ending"}, {"id": "d", "text": "The nurse is demonstrating empathy by limiting her involvement"}]'::jsonb, '["b"]', 'In countertransference the nurse''s past experiences or unresolved emotions affect professional judgment and reactions. Transference would be the patient''s feelings toward the nurse, regression belongs to termination, and empathy is understanding feelings without judgment.', false),
  ('therapeutic', 48, 'A nurse and patient agreed on goals and boundaries last week. Today the patient describes feelings about her mother''s criticism, and the nurse helps her identify how she has coped in the past. The relationship has MOST likely entered which phase?', '[{"id": "a", "text": "Pre-interaction"}, {"id": "b", "text": "Orientation"}, {"id": "c", "text": "Termination"}, {"id": "d", "text": "Working"}]'::jsonb, '["d"]', 'Goals and boundaries are set in orientation; once the patient explores feelings and the nurse identifies coping patterns, the pair is in the working phase, the longest and most productive phase. Pre-interaction occurs before meeting the patient, and termination involves summarizing progress and preparing for discharge.', false),
  ('therapeutic', 49, 'During a scheduled session, a patient says, "I don''t want to talk about my family today." Which response by the nurse BEST demonstrates respect for the patient?', '[{"id": "a", "text": "\"You should talk about it; it''s the only way you''ll get better.\""}, {"id": "b", "text": "\"Why don''t you want to talk about your family today?\""}, {"id": "c", "text": "\"I respect that. What would you like to talk about today?\""}, {"id": "d", "text": "\"Don''t worry, it gets much easier once you start talking.\""}]'::jsonb, '["c"]', 'Respect means acknowledging the patient''s dignity, worth, and autonomy, so the nurse accepts the choice and uses an open-ended question. Advising takes away autonomy, a "why" question sounds judgmental, and "don''t worry" is false reassurance.', false),
  ('therapeutic', 50, 'A patient begins describing a recent miscarriage, and the nurse, feeling uncomfortable, says, "Let''s go over your discharge paperwork instead." Which statement BEST explains why the nurse''s response is non-therapeutic?', '[{"id": "a", "text": "It avoids the patient''s concerns"}, {"id": "b", "text": "It takes away the patient''s autonomy"}, {"id": "c", "text": "It creates division and is unprofessional"}, {"id": "d", "text": "It makes the patient feel judged and defensive"}]'::jsonb, '["a"]', 'Changing the subject avoids the patient''s concerns. Taking away autonomy describes advising, creating division describes agreeing/disagreeing, and feeling judged and defensive describes "why" questions.', false),
  ('personality', 1, 'A client with a personality disorder distrusts staff, believes his roommate is stealing from him despite no evidence, and has held a grudge against his brother for 10 years. Which action by a newly hired nurse requires IMMEDIATE correction?', '[{"id": "a", "text": "Challenging his paranoid beliefs directly about the roommate"}, {"id": "b", "text": "Using the same calm, non-threatening approach at each contact"}, {"id": "c", "text": "Keeping a comfortable distance when talking with the patient"}, {"id": "d", "text": "Accepting that trust with this patient will build slowly over time"}]'::jsonb, '["a"]', 'Pervasive distrust, suspicion, and grudges suggest paranoid PD, and the nurse should not challenge paranoid beliefs directly. Being consistent and non-threatening, respecting personal space, and building trust slowly are the correct Cluster A approach.', false),
  ('personality', 2, 'A 34-year-old client says, "I don''t want close friends. I''d rather work alone at night and spend weekends by myself." The client shows restricted emotional expression and is not distressed by having few relationships. Which disorder is MOST consistent with these findings?', '[{"id": "a", "text": "Avoidant PD (Cluster C)"}, {"id": "b", "text": "Schizoid PD (Cluster A)"}, {"id": "c", "text": "Schizotypal PD (Cluster A)"}, {"id": "d", "text": "Dependent PD (Cluster C)"}]'::jsonb, '["b"]', 'Detachment from social relationships, restricted emotional expression, and a preference for solitary activities describe schizoid PD in Cluster A. A client with avoidant PD avoids others because of fear of rejection and feelings of inadequacy rather than lack of interest.', false),
  ('personality', 3, 'A client dresses in mismatched layers with a cape, believes the license plates on passing cars carry messages meant only for him, and says he can make it rain by thinking about it. Which personality disorder do these findings MOST suggest?', '[{"id": "a", "text": "Paranoid PD"}, {"id": "b", "text": "Narcissistic PD"}, {"id": "c", "text": "Schizotypal PD"}, {"id": "d", "text": "Schizoid PD"}]'::jsonb, '["c"]', 'Odd beliefs and magical thinking, ideas of reference, and peculiar speech and appearance describe schizotypal PD. Paranoid PD centers on distrust and suspicion, schizoid PD on detachment, and narcissistic PD on grandiosity, without the magical thinking.', false),
  ('personality', 4, 'A client says she would love to have friends but turned down a promotion because she was sure coworkers would criticize her, and she believes she is inferior to everyone on the unit. Which nursing approach is BEST?', '[{"id": "a", "text": "Foster independence and avoid over-helping"}, {"id": "b", "text": "Allow some control and help identify priorities"}, {"id": "c", "text": "Respect personal space and build trust slowly over time"}, {"id": "d", "text": "Encourage small social steps; validate accomplishments"}]'::jsonb, '["d"]', 'Feelings of inadequacy, hypersensitivity to criticism, avoiding occupational activities from fear of rejection, and viewing self as inferior describe avoidant PD; the approach is to encourage small social steps and validate accomplishments. Fostering independence is for dependent PD, and allowing some control is for OCPD.', false),
  ('personality', 5, 'A client asks the nurse to choose her clothes and her meals, says she cannot decide anything without her husband, and agrees with whatever staff suggest. Since her last relationship ended, she urgently began a new one within a week. Which personality disorder is MOST consistent with these findings?', '[{"id": "a", "text": "Dependent PD"}, {"id": "b", "text": "Borderline PD"}, {"id": "c", "text": "Histrionic PD"}, {"id": "d", "text": "Avoidant PD"}]'::jsonb, '["a"]', 'An excessive need to be taken care of, submissive and clinging behavior, difficulty making decisions alone, and urgently seeking a new relationship when one ends describe dependent PD. Borderline PD instead involves unstable relationships, self-harm, identity disturbance, and mood swings.', false),
  ('personality', 6, 'A client is preoccupied with perfection, refuses to let coworkers help with any task, and says, "There''s nothing wrong with me; I just do things the right way." Which statement by a nursing student requires follow-up?', '[{"id": "a", "text": "\"His perfectionism and need for control fit OCPD.\""}, {"id": "b", "text": "\"His difficulty delegating is a feature of OCPD.\""}, {"id": "c", "text": "\"Like OCD, he sees his behavior as a problem.\""}, {"id": "d", "text": "\"OCPD is part of Cluster C, the anxious group.\""}]'::jsonb, '["c"]', 'OCPD is ego-syntonic — consistent with self-image — so the client does not see it as a problem, which distinguishes it from OCD. Perfectionism, control, and difficulty delegating are OCPD features, and OCPD is in Cluster C.', false),
  ('personality', 7, 'A client with obsessive-compulsive personality disorder becomes tense and argumentative when the unit''s activity schedule changes and insists every task be completed his way. Which nursing approach is BEST?', '[{"id": "a", "text": "Allow some control; help identify priorities"}, {"id": "b", "text": "Encourage small social steps in group therapy"}, {"id": "c", "text": "Remove all choices until he accepts the change"}, {"id": "d", "text": "Insist that he follow the new schedule exactly"}]'::jsonb, '["a"]', 'For OCPD, the nurse allows some control and helps the client identify priorities. Removing all choices or insisting on exact compliance creates a power struggle, and small social steps are the approach for avoidant PD.', false),
  ('personality', 8, 'A client with antisocial personality disorder asks the nurse for extra phone time after hours and says, "The night nurse always lets me, so you should too." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"If the night nurse allows it, I suppose it is fine this once.\""}, {"id": "b", "text": "\"Phone time ends at 2100 for everyone, and that limit is firm.\""}, {"id": "c", "text": "\"Why do you think you deserve special treatment on this unit?\""}, {"id": "d", "text": "\"I''ll check with the night nurse before I make a decision on it.\""}]'::jsonb, '["b"]', 'With ASPD, the nurse sets firm, consistent limits, does not let the client manipulate staff, and confronts manipulative behavior calmly. Making an exception or deferring to another nurse allows the manipulation to work.', false),
  ('personality', 9, 'The parents of a 16-year-old who lies, steals, and shows no remorse after hurting others ask whether their son has antisocial personality disorder. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Yes, deceitfulness and no remorse confirm ASPD at any age.\""}, {"id": "b", "text": "\"ASPD is diagnosed only after a child shows Cluster C traits.\""}, {"id": "c", "text": "\"Under 18, this pattern is called conduct disorder, not ASPD.\""}, {"id": "d", "text": "\"These behaviors suggest borderline PD rather than antisocial PD.\""}]'::jsonb, '["c"]', 'ASPD is diagnosed at ≥18 years old; under 18 the pattern is called conduct disorder. The behaviors match ASPD features (deceitfulness, no remorse), but the client''s age rules out the diagnosis for now.', false),
  ('personality', 10, 'A client with borderline personality disorder has new superficial cuts on her forearm and says, "I wasn''t trying to die. I just needed to relieve the tension." Which action should the nurse take FIRST?', '[{"id": "a", "text": "Accept her statement, since cutting in BPD is usually tension relief"}, {"id": "b", "text": "Ignore the cuts to avoid reinforcing the self-harm behavior"}, {"id": "c", "text": "Tell her that cutting again will lead to a loss of privileges"}, {"id": "d", "text": "Assess the self-harm for suicidal intent"}]'::jsonb, '["d"]', 'Self-harm in BPD must be taken seriously, and the nurse assesses for suicidal intent every time, even though cutting is often tension relief. Ignoring the self-harm or accepting her explanation without assessment minimizes it.', false),
  ('personality', 11, 'A client with borderline personality disorder tells the nurse, "You''re the only one here who understands me. The evening nurse is cruel, and I won''t talk to her." Which action by the nurse is BEST?', '[{"id": "a", "text": "Accept the role of her one trusted nurse to build trust"}, {"id": "b", "text": "Present a unified treatment approach with all staff"}, {"id": "c", "text": "Validate her feelings by agreeing the evening nurse is unkind"}, {"id": "d", "text": "Defend the evening nurse as one of the unit''s very best"}]'::jsonb, '["b"]', 'Splitting divides staff into "good" and "bad" nurses, so the nurse presents a unified treatment approach and does not accept the role of the "good" nurse. Becoming her one trusted nurse or agreeing that a colleague is unkind reinforces the splitting, and defending the colleague argues with the client.', false),
  ('personality', 12, 'A client with borderline personality disorder learns her assigned nurse''s shift is ending and cries, "You''re leaving me like everyone does. Maybe I should just cut myself." Which response by the nurse is MOST therapeutic?', '[{"id": "a", "text": "\"I''ll stay late tonight so you won''t have to be alone after my shift.\""}, {"id": "b", "text": "\"You''re being dramatic; another nurse will be here in a few minutes.\""}, {"id": "c", "text": "\"I hear how scared you are of being left. Are you thinking of suicide?\""}, {"id": "d", "text": "\"If you cut yourself, you''ll lose your privileges for the whole week.\""}]'::jsonb, '["c"]', 'Fear of abandonment is a core BPD feature; the nurse validates the emotion while discouraging self-harm and assesses for suicidal intent every time self-harm comes up. Staying late abandons the limits of the plan, and calling her dramatic dismisses her feelings.', false),
  ('personality', 13, 'The family of a client with borderline personality disorder asks which treatment is most likely to help their daughter with self-harm and mood swings. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Treatment focuses mainly on having one favorite nurse.\""}, {"id": "b", "text": "\"Dialectical Behavior Therapy is the treatment of choice.\""}, {"id": "c", "text": "\"Staff will ignore her self-harm so it won''t be reinforced.\""}, {"id": "d", "text": "\"She will be treated as needed with changing staff each day.\""}]'::jsonb, '["b"]', 'Dialectical Behavior Therapy (DBT) is the evidence-based treatment of choice for BPD. Self-harm must never be ignored, and BPD care relies on consistent staff assignments rather than changing staff.', false),
  ('personality', 14, 'A client wears flamboyant outfits, speaks in an exaggerated, theatrical way, changes her opinions to match whoever she last talked to, and becomes visibly upset whenever another client becomes the focus of the group. Which personality disorder do these findings MOST suggest?', '[{"id": "a", "text": "Narcissistic PD"}, {"id": "b", "text": "Borderline PD"}, {"id": "c", "text": "Dependent PD"}, {"id": "d", "text": "Histrionic PD"}]'::jsonb, '["d"]', 'Excessive emotionality, attention-seeking, being uncomfortable when not the center of attention, being theatrical, and being easily influenced describe histrionic PD. Narcissistic PD centers on grandiosity and a need for admiration with a lack of empathy.', false),
  ('personality', 15, 'A client demands a private room because he is "far more important than the other patients," expects constant praise, and shows no concern when his comments upset a peer. Which personality disorder is MOST consistent with these findings?', '[{"id": "a", "text": "Narcissistic PD"}, {"id": "b", "text": "Antisocial PD"}, {"id": "c", "text": "Histrionic PD"}, {"id": "d", "text": "Obsessive-compulsive PD"}]'::jsonb, '["a"]', 'Grandiosity, need for admiration, lack of empathy, and believing he is "special" describe narcissistic PD. Antisocial PD centers on disregard for rules and the rights of others, deceitfulness, and no remorse rather than a need for admiration.', false),
  ('personality', 16, 'A client with narcissistic personality disorder tells the nurse, "I should be treated by the chief of psychiatry, not by ordinary staff like you." Which action by the nurse is BEST?', '[{"id": "a", "text": "Arrange for the chief of psychiatry to see him today"}, {"id": "b", "text": "Confront his grandiosity directly to set a firm limit"}, {"id": "c", "text": "Acknowledge his feelings and maintain therapeutic limits"}, {"id": "d", "text": "Use flattery to build trust before setting any limits"}]'::jsonb, '["c"]', 'With narcissistic PD, the nurse does not argue, maintains therapeutic limits, avoids flattery, and acknowledges feelings without reinforcing grandiosity. Arranging the chief reinforces grandiosity, confronting the grandiosity becomes an argument, and flattery is to be avoided.', false),
  ('personality', 17, 'The charge nurse is making assignments for the week. A client with borderline personality disorder has been praising some nurses and criticizing others. Which assignment plan is BEST?', '[{"id": "a", "text": "Rotate a different nurse each shift to prevent attachment"}, {"id": "b", "text": "Let the patient choose a preferred nurse at each shift"}, {"id": "c", "text": "Assign the nurses the patient praises to keep her calm"}, {"id": "d", "text": "Use consistent staff assignments throughout the week"}]'::jsonb, '["d"]', 'Consistent assignments reduce manipulation, build trust, and prevent splitting. Letting the client choose or assigning only the nurses she praises reinforces splitting, and rotating staff removes the consistency the client needs.', false),
  ('personality', 18, 'A client with a personality disorder refuses to attend a required group, folds his arms, and says, "Make me. I dare you to try." Which action by the nurse is BEST?', '[{"id": "a", "text": "Calmly restate the clear, firm limits and avoid power struggles"}, {"id": "b", "text": "Enforce the limit by calling security to escort him"}, {"id": "c", "text": "Let him skip group to avoid a power struggle"}, {"id": "d", "text": "Ask him why he always turns every request into a fight with staff"}]'::jsonb, '["a"]', 'The nurse states a clear, firm limit calmly and avoids a power struggle, which escalates conflict and undermines the therapeutic alliance. Calling security creates a power struggle, and letting him skip group abandons the clear, firm limit.', false),
  ('personality', 19, 'A client with borderline personality disorder whose wounds have just been dressed says quietly, "You must think I''m disgusting for doing this to myself." Which approach by the nurse is MOST therapeutic?', '[{"id": "a", "text": "Change the subject to avoid reinforcing the self-harm"}, {"id": "b", "text": "Tell her the cutting worries and disappoints the nursing staff"}, {"id": "c", "text": "Use a non-judgmental attitude and validate her emotions"}, {"id": "d", "text": "Advise her to call the nurse before cutting the next time"}]'::jsonb, '["c"]', 'Patients with personality disorders often feel shame, and a non-judgmental attitude with acceptance supports the therapeutic relationship and validates emotions. Changing the subject dismisses her feelings, expressing disappointment is judgmental, and advice skips past the feeling.', false),
  ('personality', 20, 'The nurse receives report on four clients with personality disorders. Which client should the nurse see FIRST?', '[{"id": "a", "text": "A patient with OCPD who is upset that group started 5 minutes late"}, {"id": "b", "text": "A patient with BPD who has urges for self-harm and a razor"}, {"id": "c", "text": "A patient with histrionic PD who is crying loudly in the dayroom"}, {"id": "d", "text": "A patient with dependent PD who wants help choosing her lunch"}]'::jsonb, '["b"]', 'Self-harm behavior in BPD must be taken seriously, and a client with urges to cut and access to a razor is a safety priority requiring assessment for suicidal intent. The other clients'' needs are real but not safety risks.', false),
  ('personality', 21, 'The nurse reviews four new clients'' histories. Which history is MOST consistent with a personality disorder?', '[{"id": "a", "text": "Suspiciousness that began 2 weeks ago, after a job loss at age 52"}, {"id": "b", "text": "Irritability that occurs only with one supervisor at work"}, {"id": "c", "text": "A pervasive, inflexible pattern since adolescence, with impairment"}, {"id": "d", "text": "Behavior that matches the cultural expectations of the patient''s family"}]'::jsonb, '["c"]', 'A personality disorder is an enduring pattern that deviates markedly from cultural expectations, is pervasive and inflexible, causes significant impairment, and begins in adolescence or early adulthood. A recent change, behavior limited to one setting, or behavior matching cultural expectations does not fit.', false),
  ('personality', 22, 'A client with dependent personality disorder can bathe and dress independently. Which action by a nursing assistant (UAP) requires intervention by the nurse?', '[{"id": "a", "text": "Encouraging the patient to choose her own outfit"}, {"id": "b", "text": "Doing the patient''s bathing and dressing for her"}, {"id": "c", "text": "Praising the patient for making her bed by herself"}, {"id": "d", "text": "Asking the patient which snack she would prefer"}]'::jsonb, '["b"]', 'For dependent PD, staff foster independence and avoid over-helping, so doing care the client can do herself reinforces dependence. Encouraging choices and praising independent actions foster independence.', false),
  ('personality', 23, 'A client with avoidant personality disorder attended group for the first time and said one sentence before leaving early. Which action by the nurse is MOST therapeutic?', '[{"id": "a", "text": "Validate her accomplishments in group"}, {"id": "b", "text": "Foster independence by letting her skip group"}, {"id": "c", "text": "Note that peers may think she didn''t care"}, {"id": "d", "text": "Ask her why she left before group ended"}]'::jsonb, '["a"]', 'For avoidant PD, the nurse encourages small social steps and validates accomplishments. Fostering independence is the dependent PD approach, and because the client is hypersensitive to criticism, comments about how others viewed her are likely to discourage her.', false),
  ('personality', 24, 'A client with histrionic personality disorder collapses dramatically to the floor in the dayroom each time visitors begin talking to other clients, then sits up smiling when staff gather around. Vital signs are stable. Which action is BEST?', '[{"id": "a", "text": "Gather the whole staff around her each time so she feels safe and cared for"}, {"id": "b", "text": "Avoid reinforcing the dramatic behavior and redirect to her goals"}, {"id": "c", "text": "Ask the other patients to give her more attention during visits"}, {"id": "d", "text": "Tell her in front of the group that the fainting is not real"}]'::jsonb, '["b"]', 'The approach to histrionic PD is to avoid reinforcing dramatic behaviors and redirect focus to therapeutic goals. Gathering staff or encouraging peers to give attention reinforces the behavior, and public confrontation is judgmental.', false),
  ('personality', 25, 'A client with paranoid personality disorder refuses to give the nurse his medication history, saying, "You''ll just use it against me." Which action by the nurse is BEST?', '[{"id": "a", "text": "Tell him that his information will not be shared and press for it"}, {"id": "b", "text": "Point out that he is being unreasonable about a routine question"}, {"id": "c", "text": "Ask a different nurse to try each shift until one gets an answer"}, {"id": "d", "text": "Stay consistent and non-threatening, building trust slowly"}]'::jsonb, '["d"]', 'Paranoid PD includes being reluctant to confide; the Cluster A approach is to be consistent and non-threatening and build trust slowly over time. Pressing for information or challenging the belief directly increases distrust, and changing nurses removes consistency.', false),
  ('personality', 26, 'A client with borderline personality disorder screams, "Nobody here cares about me!" after the nurse enforces the unit''s limit on phone calls. Which action by the nurse is MOST therapeutic?', '[{"id": "a", "text": "Avoid a power struggle by allowing extra phone time"}, {"id": "b", "text": "Tell her that she is overreacting to a phone rule"}, {"id": "c", "text": "Ask her why she is so angry about such a small rule"}, {"id": "d", "text": "Validate her emotions; keep clear limits on calls"}]'::jsonb, '["d"]', 'Validating emotions acknowledges feelings without reinforcing maladaptive behavior, and BPD care requires clear limits and avoiding power struggles. Allowing extra time drops the limit rather than avoiding a power struggle, and calling her reaction overreacting dismisses her feelings.', false),
  ('personality', 27, 'A client praises the day-shift nurses as "perfect angels" and calls all evening-shift nurses "evil," and two staff members have begun to argue over how to handle her. Which feature do these behaviors MOST clearly demonstrate?', '[{"id": "a", "text": "Identity disturbance"}, {"id": "b", "text": "Splitting"}, {"id": "c", "text": "Grandiosity"}, {"id": "d", "text": "Fear of abandonment"}]'::jsonb, '["b"]', 'Seeing people as all good or all bad and dividing staff ("staff splitting") is splitting, a core feature of BPD. Identity disturbance is an unstable self-image, and fear of abandonment involves frantic efforts to avoid abandonment.', false),
  ('personality', 28, 'A client with schizotypal personality disorder becomes visibly anxious when the nurse sits close to him to review his care plan. Which action by the nurse is BEST?', '[{"id": "a", "text": "Respect his need for personal space while continuing calmly"}, {"id": "b", "text": "Move closer and touch his shoulder to show that she is caring"}, {"id": "c", "text": "Tell him that his anxiety about the nurse is not reasonable"}, {"id": "d", "text": "Build trust by staying close until he relaxes"}]'::jsonb, '["a"]', 'The Cluster A approach is to be consistent and non-threatening and respect the need for personal space. Moving closer, touching, or staying close increases threat, and trust is built slowly over time.', false),
  ('personality', 29, 'A client with antisocial personality disorder compliments the nurse at length, then quietly asks her to mail a letter for him without the unit''s usual check. Which action by the nurse is BEST?', '[{"id": "a", "text": "Set firm, consistent limits on the mail request"}, {"id": "b", "text": "Mail it this one time, since he asked so politely"}, {"id": "c", "text": "Ask him why he thinks she would break the rules"}, {"id": "d", "text": "Validate his feelings by granting the request once"}]'::jsonb, '["a"]', 'With ASPD, the nurse sets firm, consistent limits and does NOT let the client manipulate staff. Mailing the letter rewards the manipulation, and asking why argues rather than calmly holding the limit.', false),
  ('personality', 30, 'A client with antisocial personality disorder threatened another client and then tried to persuade staff that the other client started it. Which action by the nurse is MOST important after the situation is under control?', '[{"id": "a", "text": "Document the interactions carefully"}, {"id": "b", "text": "Validate his account to avoid a power struggle"}, {"id": "c", "text": "Discuss the incident with the patient''s peers"}, {"id": "d", "text": "Ask the patient to write an apology letter"}]'::jsonb, '["a"]', 'Documenting all interactions carefully protects staff and tracks behavior patterns in ASPD. Accepting his account lets the manipulation work, and discussing it with peers or requesting an apology does not protect staff or track patterns.', false),
  ('personality', 31, 'A 23-year-old client tells the nurse, "I don''t really know who I am. Every few months I change my career plans and my whole style, and inside I just feel empty all the time." These statements MOST strongly suggest which disorder?', '[{"id": "a", "text": "Histrionic PD"}, {"id": "b", "text": "Narcissistic PD"}, {"id": "c", "text": "Dependent PD"}, {"id": "d", "text": "Borderline PD"}]'::jsonb, '["d"]', 'Identity disturbance (an unstable self-image) and chronic emptiness are features of borderline PD. Histrionic PD centers on attention-seeking and theatrical emotion, and dependent PD on the need to be taken care of.', false),
  ('personality', 32, 'The nurse is reviewing behaviors documented for four clients. Which client''s behavior is MOST consistent with a Cluster B personality disorder?', '[{"id": "a", "text": "Holds magical beliefs about controlling the weather"}, {"id": "b", "text": "Hypersensitive to criticism; avoids new activities"}, {"id": "c", "text": "Theatrical; uncomfortable when not center of attention"}, {"id": "d", "text": "Detached from relationships; prefers solitary activities"}]'::jsonb, '["c"]', 'Cluster B is "Dramatic, Emotional, or Erratic," and theatrical behavior with discomfort when not the center of attention describes histrionic PD. Magical thinking and detachment are Cluster A, and hypersensitivity to criticism is Cluster C (avoidant).', false),
  ('personality', 33, 'A client with borderline personality disorder says, "If you won''t let me call my boyfriend right now, I''ll cut myself tonight." Which action is the PRIORITY for the nurse?', '[{"id": "a", "text": "Allow the phone call to prevent the self-harm from occurring"}, {"id": "b", "text": "Ignore the statement because it is a manipulative threat"}, {"id": "c", "text": "Assess for suicidal intent while keeping the limit"}, {"id": "d", "text": "Restrict her privileges as a consequence for making a threat"}]'::jsonb, '["c"]', 'Self-harm statements in BPD are taken seriously and suicidal intent is assessed every time, while clear limits are maintained. Ignoring the threat minimizes it, giving in drops the limit, and punishment invites a power struggle.', false),
  ('personality', 34, 'A client with histrionic personality disorder approaches the nurse calmly before group and asks whether she may share a poem she wrote about her progress. Which action by the nurse is BEST?', '[{"id": "a", "text": "Refuse, to avoid reinforcing any attention-seeking"}, {"id": "b", "text": "Acknowledge appropriate attention-seeking; plan it for group"}, {"id": "c", "text": "Have her read it right away to the whole dayroom"}, {"id": "d", "text": "Tell her to save it for another week''s group"}]'::jsonb, '["b"]', 'For histrionic PD, the nurse acknowledges appropriate attention-seeking and redirects focus to therapeutic goals; a calm request to share progress in group is appropriate. Refusing all attention ignores appropriate behavior, and an unscheduled reading to the dayroom reinforces drama.', false),
  ('personality', 35, 'A client with schizoid personality disorder declines to join the unit''s social hour and asks to sit alone with a book. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Encourage small social steps by requiring social hour"}, {"id": "b", "text": "Warn that he will never make friends this way"}, {"id": "c", "text": "Ask him why he avoids the other patients"}, {"id": "d", "text": "Respect his need for personal space; check in later"}]'::jsonb, '["d"]', 'Schizoid PD involves a preference for solitary activities; the Cluster A approach is to respect the need for personal space and build trust slowly with consistent, non-threatening contact. Small social steps are the approach for avoidant PD, and forcing participation or criticizing the choice threatens trust.', false),
  ('personality', 36, 'The nurse reviews admission notes for several clients. Which documented behaviors are consistent with a Cluster A ("odd or eccentric") personality disorder? Select all that apply.', '[{"id": "a", "text": "Interprets motives as malevolent"}, {"id": "b", "text": "Frantic efforts to avoid abandonment"}, {"id": "c", "text": "Magical thinking; ideas of reference"}, {"id": "d", "text": "Hypersensitive to criticism"}, {"id": "e", "text": "Prefers solitary activities"}]'::jsonb, '["a", "c", "e"]', 'Interpreting motives as malevolent (paranoid), magical thinking and ideas of reference (schizotypal), and preferring solitary activities (schizoid) are Cluster A. Fear of abandonment is borderline PD (Cluster B), and hypersensitivity to criticism is avoidant PD (Cluster C).', true),
  ('personality', 37, 'A 25-year-old client is admitted after an impulsive overdose. Which findings would support a diagnosis of borderline personality disorder? Select all that apply.', '[{"id": "a", "text": "Sees people as all good or all bad"}, {"id": "b", "text": "Unstable self-image"}, {"id": "c", "text": "Chronic emptiness"}, {"id": "d", "text": "Ego-syntonic perfectionism"}, {"id": "e", "text": "Frantic efforts to avoid abandonment"}]'::jsonb, '["a", "b", "c", "e"]', 'Splitting (seeing people as all good or all bad), identity disturbance (unstable self-image), chronic emptiness, and frantic efforts to avoid abandonment are BPD features. Ego-syntonic perfectionism describes OCPD.', true),
  ('personality', 38, 'The nurse is planning care for a client with borderline personality disorder who has a history of cutting. Which interventions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Consistent staff assignments"}, {"id": "b", "text": "Ignore self-harm to avoid reinforcing it"}, {"id": "c", "text": "Validate emotions while discouraging self-harm"}, {"id": "d", "text": "Let the patient choose a new favorite nurse daily"}, {"id": "e", "text": "Assess for suicidal intent EVERY time"}]'::jsonb, '["a", "c", "e"]', 'BPD care includes consistent staff assignments, validating emotions while discouraging self-harm, and assessing for suicidal intent every time self-harm occurs. Self-harm must never be ignored, and letting the client choose a favorite nurse invites splitting.', true),
  ('personality', 39, 'A client with antisocial personality disorder repeatedly tries to talk staff into bending unit rules. Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Make small exceptions to build rapport"}, {"id": "b", "text": "Set firm, consistent limits"}, {"id": "c", "text": "Argue loudly to show who is in charge"}, {"id": "d", "text": "Grant requests made with flattery"}, {"id": "e", "text": "Document carefully"}]'::jsonb, '["b", "e"]', 'With ASPD, the nurse sets firm, consistent limits, does not get manipulated, confronts manipulation calmly, and documents carefully. Making exceptions or granting flattering requests lets the manipulation work, and arguing loudly is not a calm confrontation and creates a power struggle.', true),
  ('personality', 40, 'The nurse reviews behaviors of several clients. Which behaviors are consistent with a Cluster C ("anxious or fearful") personality disorder? Select all that apply.', '[{"id": "a", "text": "Peculiar speech and appearance"}, {"id": "b", "text": "Urgently seeks new relationship when one ends"}, {"id": "c", "text": "Disregard for rules/rights of others"}, {"id": "d", "text": "Avoids occupational activities due to fear of rejection"}, {"id": "e", "text": "Need for admiration; lack of empathy"}]'::jsonb, '["b", "d"]', 'Urgently seeking a new relationship (dependent PD) and avoiding occupational activities from fear of rejection (avoidant PD) are Cluster C. Peculiar speech and appearance is schizotypal (Cluster A), and disregard for rules and need for admiration are antisocial and narcissistic (Cluster B).', true),
  ('personality', 41, 'Staff on a unit are divided because a client with borderline personality disorder praises some nurses and criticizes others. Which actions should the nurse manager implement? Select all that apply.', '[{"id": "a", "text": "Staff meet regularly to maintain consistency"}, {"id": "b", "text": "Allow the patient to pick her nurse each shift"}, {"id": "c", "text": "Present a unified treatment approach"}, {"id": "d", "text": "Use consistent assignments"}, {"id": "e", "text": "Let the \"good\" nurse grant extra privileges"}]'::jsonb, '["a", "c", "d"]', 'To handle splitting, staff meet regularly to maintain consistency, present a unified treatment approach, and use consistent assignments, which prevent splitting. Letting the client pick nurses or letting a "good" nurse grant privileges allows the client to divide staff.', true),
  ('personality', 42, 'A client with histrionic personality disorder frequently makes loud, tearful scenes in the dayroom. Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Give extra attention during each outburst"}, {"id": "b", "text": "Redirect focus to therapeutic goals"}, {"id": "c", "text": "Compliment her appearance to build rapport"}, {"id": "d", "text": "Avoid reinforcing dramatic behaviors"}, {"id": "e", "text": "Ask peers to praise her during scenes"}]'::jsonb, '["b", "d"]', 'For histrionic PD, the nurse redirects focus to therapeutic goals and avoids reinforcing dramatic behaviors. Attention, compliments, or peer praise during scenes reinforces the dramatic behavior.', true),
  ('personality', 43, 'A client with narcissistic personality disorder insists on special treatment and belittles staff. Which nursing approaches are appropriate? Select all that apply.', '[{"id": "a", "text": "Acknowledge feelings without reinforcing grandiosity"}, {"id": "b", "text": "Argue that he is no more special than others"}, {"id": "c", "text": "Praise his talents often to build trust"}, {"id": "d", "text": "Grant special requests to prevent conflict"}, {"id": "e", "text": "Maintain therapeutic limits"}]'::jsonb, '["a", "e"]', 'With narcissistic PD, the nurse acknowledges feelings without reinforcing grandiosity and maintains therapeutic limits. Arguing is to be avoided, praise is flattery, and granting special requests reinforces grandiosity.', true),
  ('personality', 44, 'The nurse educator reviews general interventions for clients with personality disorders. Which intervention–rationale pairs are accurate? Select all that apply.', '[{"id": "a", "text": "Consistent assignments — prevents splitting"}, {"id": "b", "text": "Clear, firm limits — reduces testing behaviors"}, {"id": "c", "text": "Validate emotions — reinforces maladaptive behavior"}, {"id": "d", "text": "Document all interactions — protects staff"}, {"id": "e", "text": "Non-judgmental attitude — patients often feel shame"}]'::jsonb, '["a", "b", "d", "e"]', 'Consistent assignments prevent splitting, clear firm limits reduce testing behaviors, documenting all interactions protects staff, and a non-judgmental attitude matters because patients often feel shame. Validating emotions acknowledges feelings without reinforcing maladaptive behavior.', true),
  ('personality', 45, 'A client''s spouse says, "Everything at home has to be done his way, he redoes my work because it''s never perfect, and he thinks he''s completely fine." Which findings in this client are consistent with obsessive-compulsive personality disorder (OCPD)? Select all that apply.', '[{"id": "a", "text": "Preoccupation with orderliness and perfectionism"}, {"id": "b", "text": "Sees the behavior as a problem he wants to fix"}, {"id": "c", "text": "Difficulty delegating"}, {"id": "d", "text": "Frantic efforts to avoid abandonment"}, {"id": "e", "text": "Ego-syntonic; patient does not see it as a problem"}]'::jsonb, '["a", "c", "e"]', 'Preoccupation with orderliness and perfectionism, difficulty delegating, and being ego-syntonic (the patient does not see it as a problem) are OCPD features. Seeing the behavior as an unwanted problem is what distinguishes OCD, and fear of abandonment is BPD.', true),
  ('personality', 46, 'A client with dependent personality disorder asks the nurse to make every decision for her, from meals to discharge plans. Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Make the decisions for her to lower anxiety"}, {"id": "b", "text": "Foster independence"}, {"id": "c", "text": "Assign one nurse to do all of her care"}, {"id": "d", "text": "Avoid over-helping"}, {"id": "e", "text": "Tell her she is too old to need help"}]'::jsonb, '["b", "d"]', 'For dependent PD, the nurse fosters independence and avoids over-helping. Making her decisions or having one nurse do all of her care reinforces the excessive need to be taken care of, and telling her she is too old is judgmental.', true),
  ('personality', 47, 'A client with borderline personality disorder is preparing for discharge. Which findings in her history reflect the impulsivity seen in this disorder? Select all that apply.', '[{"id": "a", "text": "Substance use"}, {"id": "b", "text": "Spending"}, {"id": "c", "text": "Restricted emotional expression"}, {"id": "d", "text": "Sexual behavior"}, {"id": "e", "text": "Reckless driving"}]'::jsonb, '["a", "b", "d", "e"]', 'Impulsivity in BPD includes substance use, spending, sexual behavior, and reckless driving. Restricted emotional expression is a schizoid PD feature.', true),
  ('personality', 48, 'A nurse is caring for a client with paranoid personality disorder who believes staff are plotting against him. Which approaches are appropriate? Select all that apply.', '[{"id": "a", "text": "Be consistent and non-threatening"}, {"id": "b", "text": "Challenge paranoid beliefs directly"}, {"id": "c", "text": "Respect need for personal space"}, {"id": "d", "text": "Build trust slowly over time"}, {"id": "e", "text": "Rotate staff so he trusts no one nurse"}]'::jsonb, '["a", "c", "d"]', 'The Cluster A approach is to be consistent and non-threatening, respect the need for personal space, and build trust slowly over time. Paranoid beliefs should not be challenged directly, and rotating staff undermines consistency.', true),
  ('personality', 49, 'The nurse reviews care plans for clients with Cluster C personality disorders. Which disorder–approach pairs are correct? Select all that apply.', '[{"id": "a", "text": "Avoidant — encourage small social steps"}, {"id": "b", "text": "Dependent — make decisions on her behalf"}, {"id": "c", "text": "OCPD — allow some control"}, {"id": "d", "text": "Avoidant — point out every social mistake"}, {"id": "e", "text": "Dependent — foster independence"}]'::jsonb, '["a", "c", "e"]', 'For avoidant PD the nurse encourages small social steps, for OCPD the nurse allows some control and helps identify priorities, and for dependent PD the nurse fosters independence. Making decisions for a dependent client is over-helping, and pointing out mistakes harms an avoidant client who is hypersensitive to criticism.', true),
  ('personality', 50, 'A 30-year-old client is being evaluated for antisocial personality disorder. Which findings support this diagnosis? Select all that apply.', '[{"id": "a", "text": "Deceitfulness"}, {"id": "b", "text": "No remorse"}, {"id": "c", "text": "Impulsivity"}, {"id": "d", "text": "Hypersensitive to criticism"}, {"id": "e", "text": "Disregard for rules/rights of others"}]'::jsonb, '["a", "b", "c", "e"]', 'Disregard for the rules and rights of others, deceitfulness, impulsivity, and no remorse in a client 18 or older describe ASPD. Hypersensitivity to criticism is a feature of avoidant PD (Cluster C).', true),
  ('anxiety', 1, 'A client scheduled for discharge tomorrow is pacing, trembling, and says, ''My heart is pounding and I can''t focus on anything you''re saying.'' The client cannot follow a two-step instruction. The nurse had planned to teach relaxation techniques this shift. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Begin the relaxation teaching now, since anxiety increases motivation to learn"}, {"id": "b", "text": "Address anxiety first and provide direction for every action"}, {"id": "c", "text": "Ask the client to describe in detail what is causing the anxiety"}, {"id": "d", "text": "Leave written handouts for the client to review independently later"}]'::jsonb, '["b"]', 'Greatly reduced perception, inability to learn, physical symptoms, and needing direction for every action indicate severe anxiety, which impairs learning; the nurse addresses anxiety first and does not teach at this level. Starting the teaching now is wrong because only mild anxiety enhances learning and performance.', false),
  ('anxiety', 2, 'A client in the day room suddenly grips a chair and reports palpitations, shortness of breath, trembling, and tingling hands, saying, ''I''m going to die.'' A cardiac cause was ruled out earlier today. Which actions should the nurse take? Select all that apply.', '[{"id": "a", "text": "Teach progressive muscle relaxation steps during the attack"}, {"id": "b", "text": "Remain with the patient and speak in short, simple sentences"}, {"id": "c", "text": "Guide slow, deep breathing by breathing with the patient"}, {"id": "d", "text": "Leave the patient alone briefly to lower the stimulation"}, {"id": "e", "text": "Move the patient to a quiet, low-stimulation area"}]'::jsonb, '["b", "c", "e"]', 'These findings are a panic attack. Remaining with the patient and speaking in short, simple sentences is correct because the patient must not be left alone. Guiding slow, deep breathing by breathing with the patient is correct. Moving to a quiet, low-stimulation area is correct. Teaching relaxation steps during the attack is wrong because panic impairs learning — do not teach at this level. Leaving the patient alone is wrong because the nurse must remain with the patient.', true),
  ('anxiety', 3, 'A client preparing for a licensing exam tomorrow tells the nurse, ''I feel a little tense and restless, but I''m unusually alert and I''m remembering everything I study tonight.'' Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Moderate anxiety with narrowed perception that needs direction"}, {"id": "b", "text": "Severe anxiety, so studying and teaching should be postponed"}, {"id": "c", "text": "Mild anxiety, which enhances learning and performance"}, {"id": "d", "text": "Early panic, which places the client at risk of danger to self"}]'::jsonb, '["c"]', 'Heightened awareness, increased learning, restlessness, and tension describe mild anxiety, which enhances learning and performance. Moderate anxiety would show narrowed perception and a need for direction, which this client does not display.', false),
  ('anxiety', 4, 'A client awaiting biopsy results talks only about the pending results and misses other parts of the admission interview, but completes each form correctly when the nurse points to where to write. Which nursing approach is BEST for this level of anxiety?', '[{"id": "a", "text": "Provide direction and help focus, as perception is narrowed"}, {"id": "b", "text": "Give direction for every action, as the client cannot learn"}, {"id": "c", "text": "Stay continuously at the bedside, as the client is a danger to self"}, {"id": "d", "text": "Teach complex self-care now, while awareness is heightened"}]'::jsonb, '["a"]', 'Narrowed perception, focus on the immediate concern, and the ability to function when given direction indicate moderate anxiety, so the nurse provides direction. Needing direction for every action and being unable to learn describe severe anxiety, which this client does not show.', false),
  ('anxiety', 5, 'A client is crouched in a corner, screaming, and unable to move when staff approach. The client cannot answer simple questions and says shadows on the wall are ''coming to get me.'' Which nursing concern is the PRIORITY?', '[{"id": "a", "text": "Knowledge deficit, as the client cannot learn at this level"}, {"id": "b", "text": "Ineffective coping that needs realistic, achievable goals"}, {"id": "c", "text": "Social isolation from avoiding the crowded dayroom"}, {"id": "d", "text": "Danger to self from loss of rational thought"}]'::jsonb, '["d"]', 'Terror, immobilization, loss of rational thought, and possible hallucinations indicate panic-level anxiety, which carries danger to self, so safety is the priority. Impaired learning is true at this level but does not take priority over safety.', false),
  ('anxiety', 6, 'A client reports 9 months of excessive, uncontrollable worry about work, health, finances, and family that is not tied to any single object, situation, or past event. Which findings does the nurse expect during the assessment? Select all that apply.', '[{"id": "a", "text": "Muscle tension"}, {"id": "b", "text": "Poor concentration"}, {"id": "c", "text": "Exaggerated startle response"}, {"id": "d", "text": "Sleep disturbance"}, {"id": "e", "text": "Fatigue"}]'::jsonb, '["a", "b", "d", "e"]', 'Excessive, uncontrollable worry about multiple areas of life for 6 months or more indicates generalized anxiety disorder. Muscle tension, poor concentration, sleep disturbance, and fatigue are each listed GAD symptoms, so all four are expected. An exaggerated startle response is wrong because it is a hyperarousal symptom of PTSD, which develops after a traumatic event, and this client''s worry is not tied to any past event.', true),
  ('anxiety', 7, 'A client describes episodes that ''come out of nowhere'' several times a month, each reaching full intensity within 10 minutes, with sweating, dizziness, paresthesias, and a feeling of unreality. The client now worries constantly about having another episode and avoids crowded trains where escape would be difficult. Which condition is the MOST likely cause?', '[{"id": "a", "text": "Panic disorder with agoraphobia"}, {"id": "b", "text": "Generalized anxiety disorder with sleep disturbance"}, {"id": "c", "text": "Specific phobia with avoidance behavior"}, {"id": "d", "text": "Social anxiety disorder with fear of scrutiny"}]'::jsonb, '["a"]', 'Recurrent, unexpected attacks that peak within 10 minutes plus persistent worry about future attacks indicate panic disorder, and avoiding places where escape is difficult is agoraphobia. A specific phobia produces anxiety on exposure to a specific object or situation rather than unexpected attacks.', false),
  ('anxiety', 8, 'A client reports excessive worry about finances, the children''s safety, and job performance, along with fatigue, muscle tension, and irritability. Which additional assessment finding MOST strongly supports generalized anxiety disorder?', '[{"id": "a", "text": "Worry that began 3 weeks ago after a sudden layoff"}, {"id": "b", "text": "Discrete attacks that peak within 10 minutes"}, {"id": "c", "text": "Difficulty controlling worry for 6 months or more"}, {"id": "d", "text": "Intense fear that occurs only when speaking in public"}]'::jsonb, '["c"]', 'GAD requires excessive worry that is difficult to control, with symptoms lasting 6 months or more. Worry that began 3 weeks ago does not meet the duration, and attacks that peak within 10 minutes describe panic attacks.', false),
  ('anxiety', 9, 'A client with chronic generalized anxiety disorder is switched from PRN lorazepam to scheduled buspirone. Which statement by the client indicates understanding of the new medication?', '[{"id": "a", "text": "\"I''ll take a dose whenever I feel a wave of anxiety coming on.\""}, {"id": "b", "text": "\"I should feel the full calming effect within the first hour.\""}, {"id": "c", "text": "\"I''ll have to taper this slowly because it is habit-forming.\""}, {"id": "d", "text": "\"It takes 2–4 weeks to work and is not effective PRN.\""}]'::jsonb, '["d"]', 'Buspirone is non-habit forming, is used for chronic GAD, takes 2–4 weeks, and is not effective PRN. Taking a dose whenever anxiety strikes is PRN use, which does not work for buspirone.', false),
  ('anxiety', 10, 'A client with panic disorder is prescribed alprazolam PRN for attacks while sertraline takes effect. Which statements by the client indicate understanding of the alprazolam teaching? Select all that apply.', '[{"id": "a", "text": "\"When I want to quit it, I''ll just stop it all at once.\""}, {"id": "b", "text": "\"It takes 2–4 weeks before it can relieve a panic attack.\""}, {"id": "c", "text": "\"Alcohol adds CNS depression, so I will avoid alcohol.\""}, {"id": "d", "text": "\"There is a risk of dependence, so it''s for short-term relief.\""}, {"id": "e", "text": "\"It is non-habit forming, so I can use it indefinitely.\""}]'::jsonb, '["c", "d"]', 'Avoiding alcohol is correct because benzodiazepines cause additive CNS depression with alcohol. Recognizing the risk of dependence and short-term use is correct. Stopping it all at once is wrong because benzodiazepines must not be stopped abruptly (risk of seizures). A 2–4 week delay describes SSRIs and buspirone, not a PRN benzodiazepine used for panic attacks. Non-habit forming describes buspirone, not alprazolam.', true),
  ('anxiety', 11, 'A client who has taken diazepam daily for 8 months tells the clinic nurse, ''I ran out three days ago and figured I''d just quit cold turkey.'' The client appears tremulous and anxious. Which risk is the nurse''s PRIORITY concern?', '[{"id": "a", "text": "Seizures from stopping a benzodiazepine abruptly"}, {"id": "b", "text": "Additive CNS depression from combined sedative use"}, {"id": "c", "text": "Return of anxiety because SSRIs take 2–4 weeks"}, {"id": "d", "text": "Increased fall risk from excessive daytime sedation"}]'::jsonb, '["a"]', 'Benzodiazepines such as diazepam must never be stopped abruptly because of the risk of seizures, a physiologic threat that takes priority. Additive CNS depression occurs when a benzodiazepine is combined with alcohol, not when it is stopped.', false),
  ('anxiety', 12, 'An 80-year-old client receiving lorazepam for anxiety turns on the call light at 0200 and says, ''I need the bathroom, but I can manage on my own.'' Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Encourage walking alone to rebuild the client''s confidence"}, {"id": "b", "text": "Stay and assist, as elderly patients have increased fall risk"}, {"id": "c", "text": "Hold the morning lorazepam dose to prevent dependence"}, {"id": "d", "text": "Teach guided imagery so the client can fall back asleep afterward"}]'::jsonb, '["b"]', 'Benzodiazepines such as lorazepam increase fall risk in the elderly, so the nurse stays and assists. Setting goals to rebuild confidence is a valid anxiety intervention but not at the expense of safety.', false),
  ('anxiety', 13, 'A client with panic disorder who started sertraline 5 days ago says, ''This pill isn''t doing anything. I''m going to stop taking it.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "\"You should ask your provider to switch you to a benzodiazepine.\""}, {"id": "b", "text": "\"Don''t worry, I''m sure you''ll feel much better by tomorrow.\""}, {"id": "c", "text": "\"Sertraline takes 2–4 weeks; tell me how you''re feeling now.\""}, {"id": "d", "text": "\"Why would you stop a medication without talking to us?\""}]'::jsonb, '["c"]', 'SSRIs such as sertraline are first-line for panic but take 2–4 weeks, so the nurse explains the delay and invites the client to talk. Promising improvement by tomorrow is excessive reassurance, which reinforces anxiety and is inaccurate for an SSRI.', false),
  ('anxiety', 14, 'A client who plays violin professionally reports a racing heart and trembling hands before concerts but no anxiety at other times, and propranolol is prescribed. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"This should calm my shaking hands and my fast, pounding heartbeat.\""}, {"id": "b", "text": "\"I''ll use it for the performance anxiety I get on stage.\""}, {"id": "c", "text": "\"It works on the physical symptoms of my stage fright.\""}, {"id": "d", "text": "\"It will reduce my worry as well as the physical symptoms.\""}]'::jsonb, '["d"]', 'Propranolol is used for performance anxiety and reduces physical symptoms only, so expecting it to reduce worry shows a need for further teaching. Calming shaking hands and a fast heartbeat is a correct expectation because those are physical symptoms.', false),
  ('anxiety', 15, 'The nurse on an inpatient anxiety disorders unit receives morning report on four clients. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Patient with OCD who has been handwashing for 20 minutes"}, {"id": "b", "text": "Patient who chose to abruptly stop daily diazepam, now restless"}, {"id": "c", "text": "Patient with social anxiety refusing to eat in the dining room"}, {"id": "d", "text": "Patient with PTSD who is irritable after a nightmare last night"}]'::jsonb, '["b"]', 'Benzodiazepines such as diazepam must never be abruptly discontinued because of the risk of seizures, so this client has a potential physiologic emergency. The other findings are expected features of OCD, social anxiety, and PTSD that are not immediately dangerous.', false),
  ('anxiety', 16, 'A client who survived a house fire 3 months ago reports nightmares, startles at loud noises, and refuses to drive past the burned neighborhood. Which additional findings does the nurse expect? Select all that apply.', '[{"id": "a", "text": "Emotional numbness and anhedonia"}, {"id": "b", "text": "Intrusive images relieved by repetitive rituals"}, {"id": "c", "text": "Distorted blame of self for the fire"}, {"id": "d", "text": "Hypervigilance and difficulty concentrating"}, {"id": "e", "text": "Fear of scrutiny when eating in front of others"}]'::jsonb, '["a", "c", "d"]', 'Trauma exposure with symptoms lasting at least 1 month indicates PTSD. Emotional numbness and anhedonia are negative alterations in cognition/mood, as is distorted blame, so both are expected. Hypervigilance and difficulty concentrating are hyperarousal findings, so they are expected. Intrusive thoughts relieved by repetitive rituals describe OCD compulsions performed to reduce anxiety. Fear of scrutiny when eating in front of others describes social anxiety disorder.', true),
  ('anxiety', 17, 'A client admitted 6 weeks after a sexual assault is withdrawn, hypervigilant, and insists on sitting facing the door. During the INITIAL interview, which nursing action is the PRIORITY?', '[{"id": "a", "text": "Establish safety and trust before exploring the trauma"}, {"id": "b", "text": "Ask the client to describe the assault step by step in detail"}, {"id": "c", "text": "Begin EMDR so the client can process the memory today"}, {"id": "d", "text": "Reassure the client repeatedly that the attacker is gone"}]'::jsonb, '["a"]', 'PTSD nursing priorities begin with establishing safety and trust. Asking for a step-by-step description forces recall of the traumatic event, which the nurse must not do.', false),
  ('anxiety', 18, 'A client with PTSD after military combat becomes tearful and silent when a student nurse asks about the day the client''s unit was attacked. Which action by the student requires immediate intervention by the nurse?', '[{"id": "a", "text": "Sitting with the client in a quiet area and allowing silence"}, {"id": "b", "text": "Asking what would help the client feel safe on the unit now"}, {"id": "c", "text": "Prompting recall of the traumatic event in full detail"}, {"id": "d", "text": "Offering the client a seat that faces the doorway"}]'::jsonb, '["c"]', 'The nurse must not force a client with PTSD to recall the traumatic event; trauma-informed care avoids re-traumatization. Asking what helps the client feel safe supports the priority of establishing safety and trust.', false),
  ('anxiety', 19, 'A newly admitted client with OCD performs a 90-minute checking ritual every morning and becomes highly anxious when it is disrupted, so the client misses morning group. Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Stop the ritual midway so the client can attend group"}, {"id": "b", "text": "Allow the ritual initially rather than interrupting it"}, {"id": "c", "text": "Lock the client''s door so checking cannot take place"}, {"id": "d", "text": "Gradually set limits on the time spent on the ritual"}, {"id": "e", "text": "Work with the therapy team on response prevention"}]'::jsonb, '["b", "d", "e"]', 'Allowing the ritual initially is correct because interrupting compulsions abruptly increases anxiety. Gradually setting limits on time spent on rituals is correct. Working with the therapy team on response prevention is correct. Stopping the ritual midway and locking the door both interrupt compulsions abruptly, which increases anxiety.', true),
  ('anxiety', 20, 'A client spends about 3 hours a day rearranging items and checking locks and tells the nurse, ''I know these thoughts make no sense, but if I don''t check, the anxiety is unbearable.'' Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Orderly personality traits the client views as reasonable"}, {"id": "b", "text": "Ego-dystonic obsessions with compulsions that reduce anxiety"}, {"id": "c", "text": "Excessive, uncontrollable worry about many areas of daily life"}, {"id": "d", "text": "Avoidance behavior from a specific phobia of intruders"}]'::jsonb, '["b"]', 'Recognizing the obsessions as irrational (ego-dystonic) and performing time-consuming compulsions to reduce anxiety indicates OCD. Viewing the behavior as reasonable is the contrast drawn with OCPD.', false),
  ('anxiety', 21, 'A client with OCD whose handwashing takes more than 2 hours a day is starting Exposure and Response Prevention. Which medication order does the nurse anticipate as part of the MOST effective combined treatment?', '[{"id": "a", "text": "Buspirone, since it is non-habit forming"}, {"id": "b", "text": "Propranolol, to reduce physical symptoms"}, {"id": "c", "text": "Alprazolam PRN before each exposure session"}, {"id": "d", "text": "Fluvoxamine, an SSRI, with continued ERP"}]'::jsonb, '["d"]', 'OCD treatment is CBT with ERP plus an SSRI such as fluoxetine or fluvoxamine. Propranolol reduces physical symptoms only and is used for performance anxiety.', false),
  ('anxiety', 22, 'A client who is a college student avoids the cafeteria, eats alone, and dropped a course that required a class presentation, saying, ''Everyone will watch me shake and I''ll be humiliated.'' Which interventions does the nurse anticipate in the plan of care? Select all that apply.', '[{"id": "a", "text": "Systematic desensitization through gradual exposure"}, {"id": "b", "text": "Immediate full exposure to a large lecture audience"}, {"id": "c", "text": "Allowing meals alone until the fear goes away"}, {"id": "d", "text": "Setting realistic, achievable goals to rebuild confidence"}, {"id": "e", "text": "Frequent reassurance that no one is watching the client"}]'::jsonb, '["a", "d"]', 'Fear of scrutiny and humiliation with avoidance of public speaking and eating in front of others indicates social anxiety disorder. Systematic desensitization (gradual exposure) is correct because it is a stated treatment. Setting realistic, achievable goals is correct because it rebuilds confidence. Immediate full exposure is wrong because desensitization is gradual. Allowing meals alone reinforces avoidance. Frequent reassurance is excessive reassurance, which reinforces anxiety.', true),
  ('anxiety', 23, 'A client who needs blood work turns pale and shaky the moment the needle kit is opened, calls the fear ''silly,'' and admits to skipping care for years to avoid needles. Which condition is the nurse MOST likely observing?', '[{"id": "a", "text": "Specific phobia"}, {"id": "b", "text": "Panic disorder"}, {"id": "c", "text": "Generalized anxiety disorder"}, {"id": "d", "text": "Social anxiety disorder"}]'::jsonb, '["a"]', 'An intense, irrational fear of a specific object such as needles, with marked, immediate anxiety on exposure and avoidance behavior, is a specific phobia. Panic disorder involves unexpected attacks rather than anxiety triggered by a specific object.', false),
  ('anxiety', 24, 'A client with generalized anxiety disorder asks the nurse for the fourth time this hour, ''Are you sure my heart is okay? What if the tests missed something?'' Which response by the nurse is MOST therapeutic?', '[{"id": "a", "text": "\"Your tests were normal, so there is nothing at all to worry about.\""}, {"id": "b", "text": "\"Let''s change the subject and talk about your weekend plans.\""}, {"id": "c", "text": "\"Your worry is real to you. Let''s try slow, deep breathing.\""}, {"id": "d", "text": "\"Why do you keep asking when I''ve already answered you?\""}]'::jsonb, '["c"]', 'The nurse acknowledges and validates the anxiety and teaches a relaxation technique such as deep breathing. Repeatedly assuring the client there is nothing to worry about is excessive reassurance, which reinforces anxiety.', false),
  ('anxiety', 25, 'The charge nurse observes staff caring for a client who is pacing, trembling, unable to focus, and needing direction for each action. Which staff actions require follow-up? Select all that apply.', '[{"id": "a", "text": "Speaking slowly and clearly in a calm voice"}, {"id": "b", "text": "Using touch to calm the client without consent"}, {"id": "c", "text": "Providing excessive reassurance that all will be fine"}, {"id": "d", "text": "Turning off the television to create a quiet area"}, {"id": "e", "text": "Teaching a new skill while perception is greatly reduced"}]'::jsonb, '["b", "c", "e"]', 'Using touch without consent requires follow-up because therapeutic touch is used only with consent. Excessive reassurance requires follow-up because it reinforces anxiety. Teaching now requires follow-up because these findings indicate severe anxiety, which impairs learning. Speaking slowly and clearly in a calm voice and providing a quiet, safe environment are appropriate interventions.', true),
  ('anxiety', 26, 'A client with generalized anxiety disorder, now calm and reporting only mild tension, asks for ways to manage anxiety at home between therapy sessions. Which teaching by the nurse is BEST?', '[{"id": "a", "text": "Take PRN lorazepam every time the tension starts to build up"}, {"id": "b", "text": "Stay home and away from places that bring on the worry"}, {"id": "c", "text": "Have family reassure the client whenever worry starts"}, {"id": "d", "text": "Practice progressive muscle relaxation and guided imagery"}]'::jsonb, '["d"]', 'Relaxation techniques such as deep breathing, progressive muscle relaxation, and guided imagery are taught when anxiety is mild and learning is possible. PRN benzodiazepines are for short-term relief and carry a risk of dependence, and staying home reinforces avoidance.', false),
  ('anxiety', 27, 'A client having a panic attack remains terrified and trembling after the nurse has moved the client to a quiet room and breathed slowly with the client for several minutes. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Begin teaching the client about common panic triggers"}, {"id": "b", "text": "Administer the PRN lorazepam as ordered"}, {"id": "c", "text": "Give the PRN buspirone ordered for anxiety"}, {"id": "d", "text": "Ask the client to explain what set off the attack"}]'::jsonb, '["b"]', 'After remaining with the client, guiding breathing, and moving to a quiet area, the nurse administers the PRN benzodiazepine as ordered. Buspirone is not effective PRN, and teaching is not done at the panic level.', false),
  ('anxiety', 28, 'A client who was held at gunpoint 2 months ago has flashbacks, avoids the bank where it happened, feels emotionally numb, and has an exaggerated startle response. Which treatments does the nurse anticipate in the plan of care? Select all that apply.', '[{"id": "a", "text": "Paroxetine"}, {"id": "b", "text": "Detailed retelling of the event at each visit"}, {"id": "c", "text": "EMDR"}, {"id": "d", "text": "Trauma-focused CBT"}, {"id": "e", "text": "Sertraline"}]'::jsonb, '["a", "c", "d", "e"]', 'The findings indicate PTSD. Paroxetine and sertraline are correct because they are the FDA-approved PTSD medications. EMDR is correct because it is effective for PTSD. Trauma-focused CBT is correct because it is a stated PTSD treatment. A detailed retelling at each visit is wrong because the nurse must not force the client to recall the traumatic event.', true),
  ('anxiety', 29, 'The nurse is screening four clients who report distressing symptoms after frightening experiences or ongoing stress. Which client''s findings MOST clearly meet the time criterion for PTSD?', '[{"id": "a", "text": "Nightmares and startle since an assault 2 weeks ago"}, {"id": "b", "text": "Worry about many areas of life over the past 7 months or more"}, {"id": "c", "text": "Flashbacks that began after a flood 5 days ago"}, {"id": "d", "text": "Flashbacks and avoidance 6 weeks after a serious crash"}]'::jsonb, '["d"]', 'PTSD symptoms must be present at least 1 month after the event; 6 weeks meets this. Symptoms 2 weeks or 5 days after an event do not yet meet the duration, and months of worry about many areas of life describes GAD.', false),
  ('anxiety', 30, 'A client with generalized anxiety disorder also reports low mood, loss of interest, and early waking, and the provider diagnoses coexisting depression. Which medication does the nurse anticipate as the BEST choice to treat both conditions?', '[{"id": "a", "text": "Propranolol, a beta-blocker"}, {"id": "b", "text": "Buspirone (BuSpar)"}, {"id": "c", "text": "Venlafaxine, an SNRI"}, {"id": "d", "text": "Alprazolam, a benzodiazepine"}]'::jsonb, '["c"]', 'SNRIs such as venlafaxine are good for GAD and also treat depression. Propranolol reduces only the physical symptoms of performance anxiety, and buspirone is listed only for chronic GAD.', false),
  ('anxiety', 31, 'The nurse is assessing a client brought to the crisis unit by family after a heated argument. Which findings indicate the client''s anxiety has reached the level that is dangerous and requires IMMEDIATE intervention? Select all that apply.', '[{"id": "a", "text": "Heightened awareness"}, {"id": "b", "text": "Immobilized"}, {"id": "c", "text": "Loss of rational thought"}, {"id": "d", "text": "Narrowed perception"}, {"id": "e", "text": "Terror"}]'::jsonb, '["b", "c", "e"]', 'Panic is the dangerous level of anxiety and carries danger to self. Being immobilized is a panic finding. Loss of rational thought is a panic finding. Terror is a panic finding. Heightened awareness describes mild anxiety, which is helpful. Narrowed perception describes moderate anxiety.', true),
  ('anxiety', 32, 'A newly admitted client with OCD is in the middle of a counting ritual when breakfast trays arrive. A UAP tells the client to stop counting and eat now, and the client becomes agitated. Which response by the nurse to the UAP is BEST?', '[{"id": "a", "text": "Abrupt interruption increases anxiety; allow the ritual for now."}, {"id": "b", "text": "Remove the client from the tray area until the counting stops on its own."}, {"id": "c", "text": "Firmly repeat the request so the client learns to resist the urge to count."}, {"id": "d", "text": "Ignore the agitation, since response prevention requires stopping rituals."}]'::jsonb, '["a"]', 'With OCD, the nurse allows the ritual initially because interrupting compulsions abruptly increases anxiety, and limits are set gradually. Response prevention is worked on with the therapy team over time, not by abruptly stopping rituals.', false),
  ('anxiety', 33, 'A client taking lorazepam for short-term anxiety relief mentions, ''I have a glass or two of wine every night to unwind before bed.'' Which teaching point is the nurse''s PRIORITY?', '[{"id": "a", "text": "Wine is acceptable if it is taken 2 hours apart from the dose."}, {"id": "b", "text": "Alcohol causes additive CNS depression with lorazepam."}, {"id": "c", "text": "Switching from wine to beer lessens the effect on anxiety."}, {"id": "d", "text": "Stop lorazepam abruptly on nights when wine is consumed."}]'::jsonb, '["b"]', 'Benzodiazepines such as lorazepam cause additive CNS depression with alcohol, a safety risk the nurse must address. Stopping lorazepam abruptly is unsafe because of the risk of seizures.', false),
  ('anxiety', 34, 'A client being treated for panic disorder with agoraphobia says, ''I''ll just stay in my room today. The dayroom is too crowded, and I couldn''t get out fast enough.'' Which response by the nurse is MOST therapeutic?', '[{"id": "a", "text": "\"That''s fine; stay in your room for as long as you need.\""}, {"id": "b", "text": "\"The dayroom is perfectly safe, so there is really no reason to feel scared.\""}, {"id": "c", "text": "\"Your anxiety is real; a realistic, achievable goal is 5 minutes there.\""}, {"id": "d", "text": "\"Why are you afraid of a room full of people you know?\""}]'::jsonb, '["c"]', 'The nurse acknowledges and validates the anxiety without reinforcing avoidance and sets a realistic, achievable goal to rebuild confidence. Agreeing that the client can stay in the room reinforces avoidance.', false),
  ('anxiety', 35, 'A client describes recurring ''spells'' that started without warning and asks whether they could be panic attacks. Which reported features would the nurse expect if these are panic attacks? Select all that apply.', '[{"id": "a", "text": "Paresthesias and trembling"}, {"id": "b", "text": "Feeling of unreality"}, {"id": "c", "text": "Symptoms that build slowly over several hours"}, {"id": "d", "text": "Fear of dying or going crazy"}, {"id": "e", "text": "Intensity that peaks within 10 minutes"}]'::jsonb, '["a", "b", "d", "e"]', 'Paresthesias and trembling are listed panic attack symptoms. A feeling of unreality is a listed symptom. Fear of dying or ''going crazy'' is a listed symptom. A peak within 10 minutes is correct because panic attacks peak within 10 minutes. Symptoms that build slowly over several hours are wrong for the same reason.', true),
  ('anxiety', 36, 'A client newly diagnosed with panic disorder is receiving discharge teaching after an emergency visit for chest pain that was not cardiac. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"Sertraline can lower how often attacks happen, but it takes weeks.\""}, {"id": "b", "text": "\"Slow breathing techniques can help me get through an attack.\""}, {"id": "c", "text": "\"Cognitive behavioral therapy is part of my treatment plan.\""}, {"id": "d", "text": "\"An attack peaks after several hours, so I''ll leave the area.\""}]'::jsonb, '["d"]', 'A panic attack peaks within 10 minutes, so expecting it to build for several hours shows a need for further teaching. SSRIs, CBT, and breathing techniques are the stated treatments for panic disorder.', false),
  ('anxiety', 37, 'A client who was pacing, trembling, and unable to follow instructions this morning received PRN lorazepam and breathing coaching. Which finding this afternoon BEST indicates that the client''s anxiety has decreased to a mild level?', '[{"id": "a", "text": "Focuses only on the immediate concern but follows directions"}, {"id": "b", "text": "Shows heightened awareness and increased learning"}, {"id": "c", "text": "Needs step-by-step direction to complete each action"}, {"id": "d", "text": "Reports a feeling of unreality and fear of losing control"}]'::jsonb, '["b"]', 'Mild anxiety shows heightened awareness and increased learning. Focusing on the immediate concern while needing direction describes moderate anxiety.', false),
  ('anxiety', 38, 'A client newly diagnosed with generalized anxiety disorder has several new orders on the chart. Which order requires follow-up with the provider before the nurse implements the plan?', '[{"id": "a", "text": "Alprazolam as the only long-term treatment"}, {"id": "b", "text": "Escitalopram daily with weekly CBT sessions"}, {"id": "c", "text": "Teaching on progressive muscle relaxation"}, {"id": "d", "text": "Duloxetine daily for worry and low mood"}]'::jsonb, '["a"]', 'Benzodiazepines such as alprazolam are for short-term anxiety relief and carry a risk of dependence, so using one as the only long-term treatment needs clarification. SSRIs plus CBT are first-line for GAD, and SNRIs such as duloxetine are good for GAD.', false),
  ('anxiety', 39, 'A client reports intrusive thoughts about contamination and washes the hands until the skin cracks, arriving late to work most days because of it. Which additional findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "Recognizes the thoughts as irrational"}, {"id": "b", "text": "Views the washing as reasonable and desirable"}, {"id": "c", "text": "Washing performed to reduce anxiety"}, {"id": "d", "text": "Rituals taking more than 1 hour a day"}, {"id": "e", "text": "Worry spread across many areas of life"}]'::jsonb, '["a", "c", "d"]', 'These findings indicate OCD. Recognizing the thoughts as irrational is expected because OCD is ego-dystonic. Washing performed to reduce anxiety is expected because compulsions are performed to reduce anxiety. Rituals taking more than 1 hour a day are expected because compulsions are time-consuming and cause significant impairment. Viewing the behavior as reasonable is wrong because that contrasts OCD with OCPD. Worry spread across many areas of life describes GAD.', true),
  ('anxiety', 40, 'A client with PTSD after sexual violence needs a skin assessment and flinches each time staff enter the room. Which nursing action BEST reflects trauma-informed care?', '[{"id": "a", "text": "Complete the exam quickly without discussing each step"}, {"id": "b", "text": "Ask the client to describe the assault to guide the exam"}, {"id": "c", "text": "Get consent before touch to avoid re-traumatization"}, {"id": "d", "text": "Assign several staff to hold the client still if needed"}]'::jsonb, '["c"]', 'Trauma-informed care avoids re-traumatization, and touch is used only with consent. Asking the client to describe the assault forces recall of the traumatic event.', false),
  ('anxiety', 41, 'The nurse reviews intake screening notes for four clients at an outpatient clinic. Which client''s behavior is MOST consistent with obsessive-compulsive disorder requiring treatment?', '[{"id": "a", "text": "Checks the stove once before leaving for work each day"}, {"id": "b", "text": "Repetitive acts >1 hour/day to ease unwanted thoughts"}, {"id": "c", "text": "Rigid, orderly routines the person views as reasonable"}, {"id": "d", "text": "Excessive, uncontrollable worry about multiple areas of life"}]'::jsonb, '["b"]', 'OCD compulsions are repetitive behaviors performed to reduce anxiety from intrusive, unwanted thoughts and are time-consuming (more than 1 hour/day) with significant impairment. Routines the person views as reasonable lack the ego-dystonic recognition that distinguishes OCD from OCPD.', false),
  ('anxiety', 42, 'A client with OCD whose checking rituals take 3 hours a day is starting Exposure and Response Prevention, and the provider plans to add medication. Which medications would the nurse recognize as appropriate choices? Select all that apply.', '[{"id": "a", "text": "Propranolol"}, {"id": "b", "text": "Fluvoxamine"}, {"id": "c", "text": "Sertraline"}, {"id": "d", "text": "Fluoxetine"}, {"id": "e", "text": "Escitalopram"}]'::jsonb, '["b", "c", "d", "e"]', 'Fluvoxamine and fluoxetine are correct because they are the SSRIs named for OCD with ERP. Sertraline and escitalopram are correct because SSRIs are first-line for OCD. Propranolol is wrong because it is used for performance anxiety and reduces physical symptoms only.', true),
  ('anxiety', 43, 'A client is trembling, cannot follow the conversation, and keeps asking, ''What do I do? What do I do?'' while gripping the bed rail. Which statement by the nurse is MOST appropriate?', '[{"id": "a", "text": "\"Let me explain all the reasons your body reacts this way to stress.\""}, {"id": "b", "text": "\"Tell me about everything that has been bothering you this week.\""}, {"id": "c", "text": "\"Calm down; there is really nothing here to be anxious about.\""}, {"id": "d", "text": "\"Sit here with me, and breathe slowly with me.\""}]'::jsonb, '["d"]', 'These findings indicate severe anxiety: the client cannot learn and needs direction for every action, so the nurse gives a short, clear direction. Explaining reasons is teaching, which the client cannot process at this level.', false),
  ('anxiety', 44, 'A client who returned from combat 4 months ago reports irritability, sleep disturbance, and difficulty concentrating. Which additional finding MOST strongly suggests PTSD rather than generalized anxiety disorder?', '[{"id": "a", "text": "Hypervigilance and exaggerated startle response"}, {"id": "b", "text": "Fatigue and muscle tension on most days of the week"}, {"id": "c", "text": "Poor concentration while at work"}, {"id": "d", "text": "Excessive worry about many areas of life"}]'::jsonb, '["a"]', 'Irritability, sleep disturbance, and poor concentration occur in both GAD and PTSD hyperarousal, but hypervigilance and an exaggerated startle response are PTSD hyperarousal findings. Fatigue and muscle tension are GAD symptoms.', false),
  ('anxiety', 45, 'A client with a 1-year history of excessive, uncontrollable worry about many areas of life is starting treatment. Which statements by the client indicate understanding of the treatment plan? Select all that apply.', '[{"id": "a", "text": "\"I''ll take the buspirone only when I feel a worry attack.\""}, {"id": "b", "text": "\"CBT plus an SSRI is the usual first-line plan for me.\""}, {"id": "c", "text": "\"Alprazolam every day is the safest long-term choice.\""}, {"id": "d", "text": "\"Venlafaxine would be used only to treat depression.\""}, {"id": "e", "text": "\"Buspirone is non-habit forming but takes 2–4 weeks.\""}]'::jsonb, '["b", "e"]', 'The findings indicate GAD. CBT plus an SSRI is correct because it is first-line for GAD. Buspirone being non-habit forming but taking 2–4 weeks is correct. Taking buspirone only during worry is wrong because it is not effective PRN. Daily alprazolam long term is wrong because benzodiazepines are for short-term relief with a risk of dependence. Venlafaxine only for depression is wrong because SNRIs are good for GAD and also treat depression.', true),
  ('anxiety', 46, 'A client with panic disorder who was prescribed alprazolam PRN has requested early refills twice this month and says, ''I take it every few hours now just to feel normal.'' Which nursing action is the PRIORITY?', '[{"id": "a", "text": "Teach the client to stop the alprazolam today"}, {"id": "b", "text": "Advise a glass of wine in place of some doses"}, {"id": "c", "text": "Reassure the client that this pattern is expected"}, {"id": "d", "text": "Report possible dependence and monitor closely"}]'::jsonb, '["d"]', 'Escalating use and early refills suggest dependence, a known benzodiazepine risk that requires close monitoring and reporting. Stopping today is unsafe because benzodiazepines must not be stopped abruptly.', false),
  ('anxiety', 47, 'A client having a panic attack in the dayroom grips the nurse''s arm, breathes rapidly, and cries, ''I''m going crazy—don''t go!'' Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Tell me what triggered this so we can talk it all through.\""}, {"id": "b", "text": "\"I''m staying with you. Breathe slowly with me.\""}, {"id": "c", "text": "\"Nothing bad will happen; you will be completely fine.\""}, {"id": "d", "text": "\"I''ll go get your medicine and be right back to check.\""}]'::jsonb, '["b"]', 'During a panic attack the nurse remains with the patient and guides slow breathing by breathing with the patient. Leaving to get medication leaves the client alone during the attack.', false),
  ('anxiety', 48, 'A client admitted with PTSD after a violent home invasion startles at every sound and has not slept in days. Which actions should the nurse include in the INITIAL plan of care? Select all that apply.', '[{"id": "a", "text": "Establish safety and trust on the unit"}, {"id": "b", "text": "Encourage a detailed retelling of the invasion"}, {"id": "c", "text": "Use ERP to stop the client''s checking of the door"}, {"id": "d", "text": "Use trauma-informed care to avoid re-traumatization"}, {"id": "e", "text": "Give frequent reassurance that the danger is over"}]'::jsonb, '["a", "d"]', 'Establishing safety and trust is correct because it comes first in PTSD care. Trauma-informed care is correct because it avoids re-traumatization. A detailed retelling is wrong because the nurse must not force recall of the traumatic event. ERP is wrong because it is the treatment for OCD rituals, and checking the door here reflects hypervigilance. Frequent reassurance is wrong because excessive reassurance reinforces anxiety.', true),
  ('anxiety', 49, 'A client with an intense, irrational fear of spiders that keeps the client from gardening agrees to systematic desensitization. Which plan for the INITIAL session is BEST?', '[{"id": "a", "text": "Full exposure: holding a live spider for 10 minutes on day one"}, {"id": "b", "text": "Avoidance: removing every image of spiders until the fear fades"}, {"id": "c", "text": "Gradual exposure: a picture of spiders, with deep breathing"}, {"id": "d", "text": "Reassurance: repeating that the spiders here are not dangerous"}]'::jsonb, '["c"]', 'Systematic desensitization is gradual exposure, so the first session uses a low-intensity exposure paired with a relaxation technique such as deep breathing. Holding a live spider on day one is not gradual.', false),
  ('anxiety', 50, 'A client whose spouse is in emergency surgery paces the waiting area, can talk only about the surgery, and misses parts of the nurse''s explanation but completes the visitor form when guided. Which findings fit this client''s level of anxiety? Select all that apply.', '[{"id": "a", "text": "Narrowed perception"}, {"id": "b", "text": "Increased learning"}, {"id": "c", "text": "Focus on immediate concern"}, {"id": "d", "text": "Immobilized by terror"}, {"id": "e", "text": "Needs direction"}]'::jsonb, '["a", "c", "e"]', 'The findings indicate moderate anxiety. Narrowed perception is a moderate-level finding. Focus on the immediate concern is a moderate-level finding. Needing direction is a moderate-level finding. Increased learning describes mild anxiety. Being immobilized by terror describes panic.', true),
  ('eating', 1, 'A 17-year-old client is admitted with anorexia nervosa. Assessment findings include fine lanugo hair, dry skin, cold intolerance, amenorrhea for 6 months, and a prolonged QT interval on the cardiac monitor. Which finding requires IMMEDIATE follow-up?', '[{"id": "a", "text": "Fine lanugo hair on the arms and back"}, {"id": "b", "text": "Amenorrhea lasting 6 months"}, {"id": "c", "text": "Prolonged QT interval on the monitor"}, {"id": "d", "text": "Cold intolerance and dry skin"}]'::jsonb, '["c"]', 'Cardiac dysrhythmias from electrolyte imbalance are the biggest danger in anorexia, and QT prolongation signals that risk, so cardiac monitoring is the priority. Lanugo, amenorrhea, cold intolerance, and dry skin are expected physical signs that are not immediately life-threatening.', false),
  ('eating', 2, 'A 15-year-old client whose parents report months of fasting, excessive exercise, and an intense fear of weight gain is being admitted. The client insists, ''I still look fat.'' Which physical findings does the nurse expect? Select all that apply.', '[{"id": "a", "text": "Lanugo hair"}, {"id": "b", "text": "Amenorrhea"}, {"id": "c", "text": "Cold intolerance"}, {"id": "d", "text": "Parotid gland enlargement"}, {"id": "e", "text": "Dry skin"}]'::jsonb, '["a", "b", "c", "e"]', 'Restriction, fear of weight gain, and a distorted body image indicate anorexia nervosa. Lanugo hair, amenorrhea, cold intolerance, and dry skin are each listed physical signs of anorexia, so all four are expected. Parotid gland enlargement is wrong because it is a purging sign of bulimia caused by repeated vomiting, and this client restricts rather than vomits.', true),
  ('eating', 3, 'A severely malnourished client with anorexia nervosa is on day 3 of nutritional rehabilitation. This morning''s results show decreases in serum potassium, magnesium, and phosphorus from admission values. Which result is the PRIORITY for the nurse to report?', '[{"id": "a", "text": "Hypophosphatemia"}, {"id": "b", "text": "Hypokalemia"}, {"id": "c", "text": "Hypomagnesemia"}, {"id": "d", "text": "Daily weight change"}]'::jsonb, '["a"]', 'In refeeding syndrome, phosphorus, potassium, and magnesium all drop as insulin drives electrolytes into cells, but hypophosphatemia is the most dangerous because it can cause cardiac failure and respiratory failure. Potassium and magnesium also need replacement but are not the priority over phosphorus.', false),
  ('eating', 4, 'A 22-year-old client of normal weight comes to the clinic about ''swollen cheeks.'' The nurse notes eroded tooth enamel and calluses over the knuckles, and the client admits to ''feeling out of control around food.'' Which laboratory value is the PRIORITY for the nurse to review?', '[{"id": "a", "text": "Serum glucose"}, {"id": "b", "text": "Serum phosphorus"}, {"id": "c", "text": "Serum potassium"}, {"id": "d", "text": "Serum estrogen"}]'::jsonb, '["c"]', 'Parotid enlargement, dental erosion, and Russell''s sign indicate purging, and hypokalemia is the most dangerous purging finding because it leads to cardiac arrhythmias. Phosphorus is the priority electrolyte in refeeding syndrome, not in purging.', false),
  ('eating', 5, 'A client with anorexia nervosa pushes away a lunch tray and says, ''I''m so fat. I''m not eating any of this.'' Which response by the nurse is MOST therapeutic?', '[{"id": "a", "text": "\"You''re not fat at all; you''re dangerously underweight.\""}, {"id": "b", "text": "\"It sounds like this is about more than food. Tell me your feelings.\""}, {"id": "c", "text": "\"If you don''t eat this, the provider will have to order a feeding tube.\""}, {"id": "d", "text": "\"Just eat half of the sandwich and we''ll call it even.\""}]'::jsonb, '["b"]', 'Eating disorders are about control and distorted self-image, so the nurse avoids power struggles and focuses on feelings and emotions, not food or weight. Threatening a feeding tube creates a power struggle, and arguing that the client is not fat is confrontational.', false),
  ('eating', 6, 'A client of normal weight admits to binge episodes followed by self-induced vomiting several times a week for the past year. Which physical findings does the nurse expect on examination? Select all that apply.', '[{"id": "a", "text": "Dental enamel erosion"}, {"id": "b", "text": "Parotid gland enlargement"}, {"id": "c", "text": "Lanugo hair"}, {"id": "d", "text": "Cold intolerance"}, {"id": "e", "text": "Russell''s sign"}]'::jsonb, '["a", "b", "e"]', 'Binge episodes with vomiting in a normal-weight client indicate bulimia nervosa. Dental enamel erosion is expected from repeated exposure of teeth to stomach acid. Parotid gland enlargement (''chipmunk cheeks'') is expected from repeated vomiting. Russell''s sign (calluses on the dorsum of the hand) is expected from inducing vomiting. Lanugo hair and cold intolerance are wrong because they are physical signs of anorexia.', true),
  ('eating', 7, 'A client admitted at a very low weight after months of severe restriction is about to start nutritional rehabilitation. A family member urges, ''Feed her as much as she''ll take so she gains the weight back fast.'' Which plan is BEST?', '[{"id": "a", "text": "High-calorie feedings to restore weight as quickly as possible"}, {"id": "b", "text": "Slow, gradual refeeding with close electrolyte monitoring"}, {"id": "c", "text": "Withhold feedings until electrolyte levels are normal"}, {"id": "d", "text": "Offer only foods the client chooses, to avoid conflict"}]'::jsonb, '["b"]', 'Refeeding syndrome occurs when a severely malnourished patient is fed too quickly, so prevention is slow, gradual refeeding with close electrolyte monitoring. Weight restoration is the treatment priority, but rapid overfeeding is dangerous.', false),
  ('eating', 8, 'A client with bulimia nervosa finishes lunch at 1200 and at 1215 asks to use the bathroom alone, saying, ''I just need a few minutes of privacy.'' Which action by the nurse is BEST?', '[{"id": "a", "text": "Allow private bathroom use since the meal is finished"}, {"id": "b", "text": "Sit with the patient for at least 1 hour after meals"}, {"id": "c", "text": "Review the calories in the meal with the client before deciding"}, {"id": "d", "text": "Remove the client''s privileges for making the request"}]'::jsonb, '["b"]', 'Sitting with the patient during and after meals for at least 1 hour prevents purging immediately after eating. Allowing private bathroom use 15 minutes after the meal gives an opportunity to purge.', false),
  ('eating', 9, 'A client tells the nurse, ''I hate that I binge and then make myself throw up. It goes against everything I believe in, but I can''t seem to stop.'' The client''s weight is in the normal range. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Little insight, with behavior that is ego-syntonic"}, {"id": "b", "text": "Binge eating without compensatory purging"}, {"id": "c", "text": "Restricting-type behavior with distorted body image"}, {"id": "d", "text": "More insight, with behavior that is ego-dystonic"}]'::jsonb, '["d"]', 'Bingeing and vomiting at normal weight indicate bulimia, which shows more insight with ego-dystonic behavior (contrary to the client''s values). Little insight with ego-syntonic behavior describes anorexia.', false),
  ('eating', 10, 'A severely malnourished client with anorexia nervosa begins nutritional rehabilitation today. Which actions should the nurse include in the plan for the early days of refeeding? Select all that apply.', '[{"id": "a", "text": "Advance feedings rapidly to restore weight"}, {"id": "b", "text": "Monitor phosphorus, potassium, and magnesium"}, {"id": "c", "text": "Continuous cardiac monitoring"}, {"id": "d", "text": "Delay supplements until weight is restored"}, {"id": "e", "text": "Supplement electrolytes as needed"}]'::jsonb, '["b", "c", "e"]', 'Monitoring phosphorus, potassium, and magnesium closely is correct when beginning refeeding. Cardiac monitoring is correct because it is essential. Supplementing electrolytes as needed is correct as part of prevention. Advancing feedings rapidly is wrong because the nurse must not overfeed rapidly. Delaying supplements is wrong because electrolytes are supplemented as needed during refeeding.', true),
  ('eating', 11, 'A 19-year-old client with anorexia nervosa and comorbid depression is at a significantly low body weight. The provider''s new orders include bupropion. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Give the dose as ordered and monitor mood and appetite daily"}, {"id": "b", "text": "Question the order because of seizure risk at low weight"}, {"id": "c", "text": "Teach the client that bupropion will help promote weight gain"}, {"id": "d", "text": "Hold the dose until the client''s weight has been rechecked"}]'::jsonb, '["b"]', 'Bupropion is contraindicated in eating disorders because it increases seizure risk in low-weight patients, so the nurse questions the order before giving it. Giving the dose and monitoring mood ignores the contraindication.', false),
  ('eating', 12, 'A client with a BMI in the obese range reports eating very large amounts of food in a short time several times a week, feeling ashamed and guilty afterward, and denies vomiting, laxatives, or extra exercise. Which treatment plan does the nurse anticipate as MOST appropriate?', '[{"id": "a", "text": "Weight restoration with slow refeeding and cardiac monitoring"}, {"id": "b", "text": "Fluoxetine plus fluid restriction to prevent purging"}, {"id": "c", "text": "CBT, SSRIs, and behavioral weight management"}, {"id": "d", "text": "Removal of laxatives and supervision after every meal"}]'::jsonb, '["c"]', 'Recurrent binge eating without compensatory purging, with shame and guilt, indicates binge eating disorder, treated with CBT, SSRIs, and behavioral weight management. Removing laxatives and supervising after meals target purging, which this client denies.', false),
  ('eating', 13, 'The nurse reviews the histories of four clients who report binge eating followed by self-induced vomiting and who are not underweight. Which client''s history MOST clearly meets the frequency and duration criterion for bulimia nervosa?', '[{"id": "a", "text": "Binges about twice a month for the past 6 months"}, {"id": "b", "text": "Binges about once a week for the past 4 months"}, {"id": "c", "text": "Binges three times a week for the past 6 weeks"}, {"id": "d", "text": "Binges daily, but only for the past 2 weeks"}]'::jsonb, '["b"]', 'Bulimia requires binge episodes at least once a week for 3 months; once a week for 4 months meets both parts. Three times a week for 6 weeks meets the frequency but not the 3-month duration, and twice a month is too infrequent.', false),
  ('eating', 14, 'A client admitted with bulimia nervosa is suspected of purging after meals and of using laxatives at home. Which interventions should the nurse include in the plan of care? Select all that apply.', '[{"id": "a", "text": "Sit with the patient during and after meals"}, {"id": "b", "text": "Allow private bathroom use right after meals"}, {"id": "c", "text": "Remove laxatives and diet pills from the room"}, {"id": "d", "text": "Confront the client about each purging episode"}, {"id": "e", "text": "Monitor I&O"}]'::jsonb, '["a", "c", "e"]', 'Sitting with the patient during and after meals is correct because it prevents purging immediately after eating. Removing laxatives and diet pills is correct for safety because it prevents purging methods. Monitoring I&O is correct because it detects laxative abuse or vomiting patterns. Private bathroom use right after meals is wrong because it allows purging. Confronting the client is wrong because a non-confrontational approach is used.', true),
  ('eating', 15, 'A client with bulimia nervosa who has been vomiting several times a day for weeks has arterial blood gases drawn in the emergency department. Which acid-base imbalance is MOST likely?', '[{"id": "a", "text": "Metabolic alkalosis from HCl loss"}, {"id": "b", "text": "Metabolic acidosis from loss of stomach acid"}, {"id": "c", "text": "Respiratory acidosis from hypoventilation"}, {"id": "d", "text": "Respiratory alkalosis from hyperventilation"}]'::jsonb, '["a"]', 'Vomiting causes loss of hydrochloric acid, producing metabolic alkalosis. Metabolic acidosis is the opposite of what acid loss produces.', false),
  ('eating', 16, 'The nurse reviews the past 3 days of the weight log kept by a UAP for a client with anorexia nervosa. Which action by the UAP requires follow-up?', '[{"id": "a", "text": "Weighed the client at 0600 each morning before breakfast"}, {"id": "b", "text": "Used the same scale for each daily weigh-in"}, {"id": "c", "text": "Had the client wear a hospital gown for each weigh-in"}, {"id": "d", "text": "Varied the time of the daily weight from day to day"}]'::jsonb, '["d"]', 'Weight is monitored daily at the same time in the same clothes so that progress can be tracked and water-loading or weight manipulation detected. Weighing at 0600 before breakfast each day and using the same gown are correct practice.', false),
  ('eating', 17, 'A 16-year-old client with anorexia nervosa is medically stable after admission, and the team is setting treatment goals with the family. Which goal is the PRIORITY?', '[{"id": "a", "text": "Begin an SSRI to reduce depressive symptoms"}, {"id": "b", "text": "Weight restoration"}, {"id": "c", "text": "Weekly family therapy sessions"}, {"id": "d", "text": "Nutritional counseling on balanced meals"}]'::jsonb, '["b"]', 'Weight restoration is the priority in anorexia treatment; CBT, family therapy, and nutritional counseling support it. SSRIs are used only for comorbid depression and are not the priority goal.', false),
  ('eating', 18, 'A client who has used laxatives and self-induced vomiting daily for several months arrives at the emergency department feeling weak and dizzy. Which findings does the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Metabolic acidosis"}, {"id": "b", "text": "Hypokalemia"}, {"id": "c", "text": "Dehydration"}, {"id": "d", "text": "Risk of cardiac arrhythmias"}, {"id": "e", "text": "Metabolic alkalosis"}]'::jsonb, '["b", "c", "d", "e"]', 'Hypokalemia is expected from vomiting and laxative use. Dehydration is expected from purging behaviors. A risk of cardiac arrhythmias is expected because hypokalemia leads to arrhythmias. Metabolic alkalosis is expected from loss of hydrochloric acid with vomiting. Metabolic acidosis is wrong because acid loss from vomiting produces alkalosis.', true),
  ('eating', 19, 'During evening visiting hours, a parent brings several items to a client hospitalized for bulimia nervosa who has been purging. Which item requires IMMEDIATE action by the nurse?', '[{"id": "a", "text": "A bottle of diet pills in the gift bag"}, {"id": "b", "text": "A bag of the client''s favorite snacks"}, {"id": "c", "text": "A new journal for logging daily workouts"}, {"id": "d", "text": "A journal for writing about the day"}]'::jsonb, '["a"]', 'Laxatives and diet pills are removed from the room for safety because they are purging methods. Snacks, a magazine, and a journal do not pose the same immediate risk.', false),
  ('eating', 20, 'A client with bulimia nervosa is started on fluoxetine (Prozac) after several months of frequent binge–purge cycles. Which statement by the client indicates understanding of the medication''s purpose?', '[{"id": "a", "text": "\"This medicine will help me gain the weight I need.\""}, {"id": "b", "text": "\"If it doesn''t help, I can switch to bupropion instead.\""}, {"id": "c", "text": "\"It should reduce my binge-purge frequency.\""}, {"id": "d", "text": "\"I can stop the CBT sessions once this starts working.\""}]'::jsonb, '["c"]', 'Fluoxetine is FDA approved for bulimia nervosa and reduces binge-purge frequency. Switching to bupropion is unsafe because bupropion is contraindicated in eating disorders.', false),
  ('eating', 21, 'On day 3 of refeeding, a client with severe malnutrition from anorexia nervosa becomes short of breath, and the morning labs show that serum phosphorus has fallen sharply. Which complication is the nurse''s PRIORITY concern?', '[{"id": "a", "text": "Cardiac and respiratory failure"}, {"id": "b", "text": "Metabolic alkalosis from vomiting"}, {"id": "c", "text": "Osteoporosis from low estrogen"}, {"id": "d", "text": "Water-loading to manipulate weight"}]'::jsonb, '["a"]', 'A sharp drop in phosphorus during refeeding is hypophosphatemia, which can cause cardiac and respiratory failure. Metabolic alkalosis results from vomiting, which is not described here.', false),
  ('eating', 22, 'The nurse reviews new medication orders for a client with anorexia nervosa and for a client with bulimia nervosa on the eating disorders unit. Which orders require follow-up with the provider? Select all that apply.', '[{"id": "a", "text": "Bupropion for the client with anorexia and depression"}, {"id": "b", "text": "Fluoxetine for the client with bulimia nervosa"}, {"id": "c", "text": "Potassium replacement with cardiac monitoring"}, {"id": "d", "text": "An SSRI ordered to promote anorexia weight gain"}, {"id": "e", "text": "An SSRI for depression comorbid with bulimia"}]'::jsonb, '["a", "d"]', 'Bupropion requires follow-up because it is contraindicated in eating disorders and increases seizure risk in low-weight patients. An SSRI to promote weight gain requires follow-up because SSRIs are not approved for anorexia weight gain. Fluoxetine for bulimia is appropriate because it is FDA approved. Potassium replacement with cardiac monitoring is appropriate because replacement is essential with cardiac monitoring. An SSRI for comorbid depression is an appropriate use.', true),
  ('eating', 23, 'A client with anorexia nervosa weighed 41.0 kg yesterday and 42.6 kg this morning. The client looks unchanged, and the nurse finds several empty water bottles beside the bed just before the weigh-in. Which interpretation is MOST likely?', '[{"id": "a", "text": "Expected weight gain from the new meal plan"}, {"id": "b", "text": "Fluid retention from heart failure during refeeding"}, {"id": "c", "text": "Water-loading to manipulate the weight"}, {"id": "d", "text": "Dehydration from purging behaviors"}]'::jsonb, '["c"]', 'Daily weights track progress and detect water-loading or weight manipulation; empty bottles before weigh-in with a sudden overnight gain suggest water-loading. Dehydration from purging would lower weight, not raise it.', false),
  ('eating', 24, 'The parent of a 15-year-old with anorexia nervosa and comorbid depression says, ''Once the sertraline kicks in, she''ll finally start gaining weight.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "\"SSRIs treat her depression; they are not approved for weight gain.\""}, {"id": "b", "text": "\"Yes, weight gain usually starts within the first 2 weeks of therapy.\""}, {"id": "c", "text": "\"Bupropion would work faster for weight gain than sertraline.\""}, {"id": "d", "text": "\"Sertraline helps mainly by reducing her binge-purge frequency.\""}]'::jsonb, '["a"]', 'SSRIs are used for depression comorbid with eating disorders but are not approved for anorexia weight gain. Bupropion is contraindicated in eating disorders.', false),
  ('eating', 25, 'A 20-year-old client with amenorrhea and a significantly low body weight reports long periods of strict restriction along with episodes of eating large amounts and then vomiting. The client still feels fat. Which condition is MOST consistent with these findings?', '[{"id": "a", "text": "Bulimia nervosa"}, {"id": "b", "text": "Binge eating disorder"}, {"id": "c", "text": "Anorexia nervosa, restricting type"}, {"id": "d", "text": "Anorexia nervosa, binge-purge type"}]'::jsonb, '["d"]', 'Restriction plus episodes of bingeing and purging at a significantly low weight is anorexia, binge-purge type. Bulimia does not occur exclusively during anorexia episodes and is seen at normal or overweight body weight.', false),
  ('eating', 26, 'A client with obesity tells the nurse about eating large amounts of food in one sitting several times a week and denies vomiting, laxatives, fasting, or extra exercise. Which additional findings does the nurse expect? Select all that apply.', '[{"id": "a", "text": "Distress about bingeing"}, {"id": "b", "text": "Shame and guilt"}, {"id": "c", "text": "Russell''s sign"}, {"id": "d", "text": "Aware it is a problem"}, {"id": "e", "text": "Metabolic syndrome"}]'::jsonb, '["a", "b", "d", "e"]', 'Recurrent binge eating without compensatory purging indicates binge eating disorder. Distress about bingeing is expected. Shame and guilt are expected. Awareness that it is a problem is expected. Metabolic syndrome is an expected obesity complication. Russell''s sign is wrong because it is a purging sign from inducing vomiting, which this client denies.', true),
  ('eating', 27, 'A client starting nutritional rehabilitation asks why blood is being drawn every few hours: ''I''m finally eating. Why would my labs get worse?'' Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"Eating more food dilutes the electrolyte levels in your bloodstream.\""}, {"id": "b", "text": "\"Vomiting after meals causes a loss of hydrochloric acid from the stomach.\""}, {"id": "c", "text": "\"Eating again can cause hypoglycemia, so we check your labs often.\""}, {"id": "d", "text": "\"As carbohydrates are introduced, insulin drives electrolytes into cells.\""}]'::jsonb, '["d"]', 'In refeeding syndrome, insulin released as carbohydrates are introduced causes rapid cellular uptake of electrolytes and severe drops in serum levels. Loss of hydrochloric acid explains metabolic alkalosis from vomiting, not refeeding.', false),
  ('eating', 28, 'A client with anorexia nervosa refuses to discuss meal goals and says, ''Everyone keeps telling me what to do with my body.'' Which nursing approach BEST addresses the client''s need for involvement in recovery?', '[{"id": "a", "text": "Set a behavioral contract with agreed-upon weight gain goals"}, {"id": "b", "text": "Tell the client that meals must be finished or privileges end"}, {"id": "c", "text": "Let the client skip meals until ready to discuss goals"}, {"id": "d", "text": "Have the dietitian plan each meal without client input"}]'::jsonb, '["a"]', 'Behavioral contracts with agreed-upon weight gain goals provide structure and promote patient involvement in recovery. Threatening to remove privileges creates a power struggle over food.', false),
  ('eating', 29, 'A client with anorexia nervosa is admitted with bradycardia, orthostatic hypotension, and an irregular rhythm on the monitor. The nurse is planning care for the first shift. Which intervention is the HIGHEST priority?', '[{"id": "a", "text": "Establish a non-judgmental therapeutic relationship"}, {"id": "b", "text": "Set a behavioral contract for weight gain goals"}, {"id": "c", "text": "Monitor vital signs and electrolytes"}, {"id": "d", "text": "Weigh daily at the same time in the same clothes"}]'::jsonb, '["c"]', 'Monitoring vital signs and electrolytes is the first-priority intervention because cardiac dysrhythmias are the leading cause of death. A therapeutic relationship and behavioral contracts matter but come after physiologic safety.', false),
  ('eating', 30, 'A 24-year-old client has had anorexia nervosa, restricting type, for 6 years. The nurse is reviewing the client''s endocrine and metabolic status. Which findings does the nurse expect? Select all that apply.', '[{"id": "a", "text": "Amenorrhea"}, {"id": "b", "text": "Osteoporosis"}, {"id": "c", "text": "Hypoglycemia"}, {"id": "d", "text": "Type 2 diabetes"}, {"id": "e", "text": "Hypothermia"}]'::jsonb, '["a", "b", "c", "e"]', 'Amenorrhea, osteoporosis, hypoglycemia, and hypothermia are each listed metabolic/endocrine complications of anorexia, so all four are expected. Type 2 diabetes is wrong because it is a consequence of binge eating disorder, not anorexia.', true),
  ('eating', 31, 'A client with bulimia nervosa and a low serum potassium is receiving IV potassium replacement. The client is alert and asks to walk to the lounge. Which nursing action is MOST important during the replacement?', '[{"id": "a", "text": "Encourage the client to walk to promote appetite"}, {"id": "b", "text": "Weigh the client before and after the infusion"}, {"id": "c", "text": "Discuss the client''s food intake for the day"}, {"id": "d", "text": "Monitor cardiac status throughout replacement"}]'::jsonb, '["d"]', 'Electrolyte replacement for hypokalemia is essential, and cardiac status must be monitored during replacement because hypokalemia leads to cardiac arrhythmias. Discussing food intake focuses on food rather than feelings and does not address the cardiac risk.', false),
  ('eating', 32, 'A client with binge eating disorder has gained weight steadily over 2 years and reports eating large amounts several nights a week without purging. When planning screening, which complication should the nurse PRIORITIZE?', '[{"id": "a", "text": "Type 2 diabetes and metabolic syndrome"}, {"id": "b", "text": "Hypokalemia and cardiac arrhythmias"}, {"id": "c", "text": "Hypophosphatemia from rapid refeeding"}, {"id": "d", "text": "Bradycardia and a prolonged QT interval"}]'::jsonb, '["a"]', 'The biggest dangers in binge eating disorder are metabolic consequences, depression, and T2DM, with obesity complications such as metabolic syndrome. Hypokalemia with arrhythmias is the danger in bulimia, which involves purging.', false),
  ('eating', 33, 'A student nurse caring for a client with anorexia nervosa plans several statements to use during lunch. Which statement by the student requires follow-up by the nurse?', '[{"id": "a", "text": "\"How are you feeling about being on the unit today?\""}, {"id": "b", "text": "\"You ate all your food today, and your weight is up!\""}, {"id": "c", "text": "\"I''ll sit with you during the meal and afterward.\""}, {"id": "d", "text": "\"It''s okay to feel upset. I''m here to listen to you.\""}]'::jsonb, '["b"]', 'The nurse does not focus on food or weight during conversations because eating disorders are about control, and food talk feeds a power struggle. Sitting with the client during and after the meal and asking about feelings are appropriate.', false),
  ('eating', 34, 'A client of normal weight describes eating an entire large pizza and a carton of ice cream while feeling unable to stop, about twice a week for 5 months. Which behaviors would the nurse document as compensatory behaviors to prevent weight gain? Select all that apply.', '[{"id": "a", "text": "Taking diuretics after a binge"}, {"id": "b", "text": "Excessive exercise the following day"}, {"id": "c", "text": "Feeling a loss of control while eating"}, {"id": "d", "text": "Fasting for a day after a binge"}, {"id": "e", "text": "Eating a large amount in a short time"}]'::jsonb, '["a", "b", "d"]', 'Taking diuretics is a compensatory behavior. Excessive exercise is a compensatory behavior. Fasting is a compensatory behavior. A sense of loss of control and eating a large amount are wrong because they define the binge episode itself, not the compensation for it.', true),
  ('eating', 35, 'During lunch, the nurse notices that a client with anorexia nervosa has hidden most of a sandwich inside a napkin. The client smiles and says, ''All done!'' Which response by the nurse is BEST?', '[{"id": "a", "text": "\"I see the sandwich; let''s focus on your feelings, not food.\""}, {"id": "b", "text": "\"Hiding food is lying, and you will lose your weekend pass for it.\""}, {"id": "c", "text": "\"You need to eat that sandwich right now while I watch you.\""}, {"id": "d", "text": "\"Let''s count the calories you would have gotten from that.\""}]'::jsonb, '["a"]', 'Eating disorders are about control and distorted self-image, so the nurse uses a non-confrontational approach that focuses on feelings rather than food. Threatening to remove a pass or demanding the client eat now creates a power struggle over food.', false),
  ('eating', 36, 'A 19-year-old male client has had anorexia nervosa, restricting type, for 2 years and reports fatigue and cold intolerance. Which laboratory finding is the nurse MOST likely to see?', '[{"id": "a", "text": "Elevated serum glucose"}, {"id": "b", "text": "Elevated serum phosphorus"}, {"id": "c", "text": "Elevated serum potassium"}, {"id": "d", "text": "Low serum testosterone"}]'::jsonb, '["d"]', 'Low estrogen/testosterone is a listed endocrine complication of anorexia, so a male client is expected to have low testosterone. Anorexia causes hypoglycemia, not elevated glucose.', false),
  ('eating', 37, 'During report, a colleague says about a newly admitted client who vomits after most meals and has eroded tooth enamel, ''It can''t be an eating disorder — her weight is normal.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Bulimia often presents with normal or overweight body weight.\""}, {"id": "b", "text": "\"You''re right; eating disorders always cause a low body weight.\""}, {"id": "c", "text": "\"Normal weight rules out bulimia but not binge eating disorder.\""}, {"id": "d", "text": "\"She should be reassessed once her weight drops below normal.\""}]'::jsonb, '["a"]', 'In bulimia nervosa, body weight is normal or overweight, and vomiting with dental enamel erosion are purging signs. Significantly low body weight describes anorexia, not bulimia.', false),
  ('eating', 38, 'The parents of a 14-year-old with anorexia nervosa receive teaching before a weekend home pass. Which statements by the parents indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"We''ll keep laxatives and diet pills out of the house.\""}, {"id": "b", "text": "\"We''ll praise her each time she cleans her plate.\""}, {"id": "c", "text": "\"We''ll focus on her feelings rather than on food.\""}, {"id": "d", "text": "\"We''ll insist she eat until she gives in to us.\""}, {"id": "e", "text": "\"We''ll remind her how thin she looks if she refuses.\""}]'::jsonb, '["a", "c"]', 'Keeping laxatives and diet pills away is correct for safety because it prevents purging methods. Focusing on feelings rather than food is correct because eating disorders are about control. Praising a clean plate is wrong because it focuses on food. Insisting until she gives in is wrong because it is a power struggle over food. Commenting on how thin she looks is wrong because it focuses on weight and is confrontational.', true),
  ('eating', 39, 'A client with bulimia nervosa who binges and purges several times a week asks the clinic nurse for bupropion to help quit smoking, saying a friend had success with it. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Bupropion is a good choice because it also treats depression.\""}, {"id": "b", "text": "\"Bupropion is safe as long as your weight stays normal.\""}, {"id": "c", "text": "\"Bupropion is contraindicated in eating disorders.\""}, {"id": "d", "text": "\"Bupropion will also reduce your binge-purge frequency.\""}]'::jsonb, '["c"]', 'Bupropion is contraindicated in eating disorders because it increases seizure risk. A normal weight does not remove the contraindication, and it is fluoxetine, not bupropion, that reduces binge-purge frequency.', false),
  ('eating', 40, 'A client with anorexia nervosa who has eaten very little for months will begin oral nutritional supplements this evening. Which laboratory values should the nurse monitor MOST closely over the coming days?', '[{"id": "a", "text": "Glucose, sodium, and chloride"}, {"id": "b", "text": "Phosphorus, potassium, and magnesium"}, {"id": "c", "text": "Calcium, sodium, and hemoglobin"}, {"id": "d", "text": "Albumin, chloride, and serum bicarbonate"}]'::jsonb, '["b"]', 'When beginning refeeding, phosphorus, potassium, and magnesium are monitored closely because insulin drives these electrolytes into cells and serum levels drop. The other panels do not reflect the electrolytes at risk in refeeding syndrome.', false),
  ('eating', 41, 'A 16-year-old client with anorexia nervosa at a significantly low body weight tells the nurse, ''I don''t know why everyone is upset. I''m fine, and I like how disciplined I am.'' Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Ego-dystonic behavior with significant distress"}, {"id": "b", "text": "Insight into the problem, with shame and guilt"}, {"id": "c", "text": "Behavior contrary to the client''s personal values"}, {"id": "d", "text": "Little insight, with ego-syntonic behavior"}]'::jsonb, '["d"]', 'Anorexia shows little insight, and the behavior is ego-syntonic (consistent with the client''s values). Behavior contrary to values (ego-dystonic) describes bulimia.', false),
  ('eating', 42, 'A client with bulimia nervosa who has been vomiting 5 to 6 times a day is admitted to the medical unit. Which findings require IMMEDIATE follow-up by the nurse? Select all that apply.', '[{"id": "a", "text": "Enlarged parotid glands"}, {"id": "b", "text": "Cardiac arrhythmias on the monitor"}, {"id": "c", "text": "Calluses on the dorsum of the hand"}, {"id": "d", "text": "Hypokalemia"}, {"id": "e", "text": "Erosion of dental enamel"}]'::jsonb, '["b", "d"]', 'Cardiac arrhythmias require immediate follow-up because hypokalemia leads to cardiac arrhythmias, the biggest danger in bulimia. Hypokalemia requires immediate follow-up because it is the most dangerous purging finding. Parotid enlargement, calluses on the dorsum of the hand, and dental erosion are expected purging signs that are not immediately life-threatening.', true),
  ('eating', 43, 'A client with anorexia nervosa, binge-purge type, has a recorded intake far below output over 2 days, and staff note frequent bathroom trips shortly after the client is left alone. Which interpretation by the nurse is MOST likely?', '[{"id": "a", "text": "Expected diuresis from cold intolerance"}, {"id": "b", "text": "Normal output while weight is being restored"}, {"id": "c", "text": "Heart failure developing from refeeding"}, {"id": "d", "text": "Laxative abuse or vomiting patterns"}]'::jsonb, '["d"]', 'Monitoring I&O detects laxative abuse or vomiting patterns, and bathroom trips when alone suggest purging. Heart failure from refeeding would not explain output exceeding intake with bathroom trips when unsupervised.', false),
  ('eating', 44, 'A 23-year-old client with bulimia nervosa who purges daily is receiving teaching about the physical effects of purging. Which statement by the client indicates understanding?', '[{"id": "a", "text": "\"The fine hair growing on my arms comes from vomiting.\""}, {"id": "b", "text": "\"The calluses on my knuckles are from lifting weights.\""}, {"id": "c", "text": "\"My swollen cheeks are from repeated vomiting.\""}, {"id": "d", "text": "\"My tooth erosion is from eating too many sweets.\""}]'::jsonb, '["c"]', 'Parotid gland enlargement (''chipmunk cheeks'') results from repeated vomiting. Knuckle calluses (Russell''s sign) come from inducing vomiting, dental erosion comes from stomach acid, and lanugo is a sign of anorexia.', false),
  ('eating', 45, 'A 21-year-old client of normal weight is diagnosed with bulimia nervosa after reporting weekly binge–purge cycles for 6 months. Which elements does the nurse anticipate in the treatment plan? Select all that apply.', '[{"id": "a", "text": "CBT"}, {"id": "b", "text": "Weight restoration as the priority"}, {"id": "c", "text": "Fluoxetine"}, {"id": "d", "text": "Nutritional counseling"}, {"id": "e", "text": "Group therapy"}]'::jsonb, '["a", "c", "d", "e"]', 'CBT, fluoxetine (FDA approved), nutritional counseling, and group therapy are each listed treatments for bulimia nervosa, so all four are anticipated. Weight restoration as the priority is wrong because that is the anorexia priority, and this client is of normal weight.', true),
  ('eating', 46, 'A client hospitalized for bulimia nervosa complains, ''Why do I have to sit in the dayroom with staff for an hour after every meal? I''m not a child.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "\"It''s a unit rule, and each patient on the unit has to follow it.\""}, {"id": "b", "text": "\"Sitting with you after meals prevents purging.\""}, {"id": "c", "text": "\"It gives you time to count the calories you just ate.\""}, {"id": "d", "text": "\"It lets us check that your weight is not dropping.\""}]'::jsonb, '["b"]', 'Sitting with the patient during and after meals for at least 1 hour prevents purging immediately after eating. Counting calories focuses on food, which feeds the power struggle.', false),
  ('eating', 47, 'A client with bulimia nervosa tearfully admits to the nurse, ''I''ve been making myself throw up in the shower. I''m so ashamed — please don''t think I''m disgusting.'' Which approach by the nurse is BEST?', '[{"id": "a", "text": "Point out the dental damage that vomiting is causing"}, {"id": "b", "text": "Tell the client firmly that purging is a choice that must stop"}, {"id": "c", "text": "Be non-judgmental; this reduces shame and promotes trust"}, {"id": "d", "text": "Focus the conversation on how many calories were lost"}]'::jsonb, '["c"]', 'A non-judgmental therapeutic relationship reduces shame and promotes trust. Telling the client purging must stop is confrontational, and talking about calories focuses on food.', false),
  ('eating', 48, 'A client with anorexia nervosa is admitted for medical stabilization after fainting at school. Which assessment findings require IMMEDIATE follow-up by the nurse? Select all that apply.', '[{"id": "a", "text": "Cardiac dysrhythmias"}, {"id": "b", "text": "Prolonged QT interval"}, {"id": "c", "text": "Lanugo hair on the back"}, {"id": "d", "text": "Bradycardia"}, {"id": "e", "text": "Dry skin and cold intolerance"}]'::jsonb, '["a", "b", "d"]', 'Cardiac dysrhythmias require immediate follow-up because they are the biggest danger in anorexia. A prolonged QT interval requires immediate follow-up because cardiac monitoring for QT prolongation is the anorexia priority. Bradycardia requires immediate follow-up for the same reason. Lanugo hair, dry skin, and cold intolerance are expected physical signs that are not immediately life-threatening.', true),
  ('eating', 49, 'A 17-year-old client with anorexia nervosa is being assessed to determine the subtype. Which reported behaviors are consistent with the restricting type? Select all that apply.', '[{"id": "a", "text": "Self-induced vomiting after meals"}, {"id": "b", "text": "Caloric restriction"}, {"id": "c", "text": "Fasting"}, {"id": "d", "text": "Episodes of bingeing"}, {"id": "e", "text": "Excessive exercise"}]'::jsonb, '["b", "c", "e"]', 'Caloric restriction is a restricting-type behavior. Fasting is a restricting-type behavior. Excessive exercise is a restricting-type behavior. Self-induced vomiting and episodes of bingeing are wrong because they define the binge-purge type.', true),
  ('eating', 50, 'A nurse precepting a new graduate on an eating disorders unit asks the graduate to explain the reasons for several interventions in a client''s plan of care. Which explanations are accurate? Select all that apply.', '[{"id": "a", "text": "Daily weights in the same clothes detect water-loading"}, {"id": "b", "text": "Monitoring I&O prevents purging right after meals"}, {"id": "c", "text": "Removing diet pills reduces power struggles over food"}, {"id": "d", "text": "Behavioral contracts provide structure and involvement"}, {"id": "e", "text": "Avoiding food talk prevents purging after eating"}]'::jsonb, '["a", "d"]', 'Daily weights at the same time in the same clothes are correct because they track progress and detect water-loading or weight manipulation. Behavioral contracts are correct because they provide structure and promote patient involvement in recovery. Monitoring I&O is wrong because it detects laxative abuse or vomiting rather than preventing purging. Removing diet pills is wrong because its purpose is safety by preventing purging methods. Avoiding food talk is wrong because its purpose is to reduce power struggles; sitting with the patient after meals is what prevents purging.', true),
  ('substance', 1, 'A client admitted for a hip fracture reports drinking a fifth of vodka daily, and the last drink was 30 hours ago. The client is tremulous and diaphoretic but oriented. Which complication is the client MOST at risk for at this time?', '[{"id": "a", "text": "Delirium tremens"}, {"id": "b", "text": "Onset of tremors and anxiety"}, {"id": "c", "text": "Withdrawal seizures"}, {"id": "d", "text": "Wernicke''s encephalopathy from glucose"}]'::jsonb, '["c"]', 'Alcohol withdrawal seizures peak at 24–48 hours, so at 30 hours seizure risk is highest. Delirium tremens develops later, at 48–72 hours, and tremors begin at 6–12 hours.', false),
  ('substance', 2, 'A client with heavy daily alcohol use was admitted for elective surgery, and the last drink was 8 hours ago. Which findings does the nurse expect at this time? Select all that apply.', '[{"id": "a", "text": "Tremors"}, {"id": "b", "text": "Delirium with fever"}, {"id": "c", "text": "Tachycardia"}, {"id": "d", "text": "Pinpoint pupils"}, {"id": "e", "text": "Diaphoresis"}]'::jsonb, '["a", "c", "e"]', 'At 6–12 hours of alcohol withdrawal, tremors are expected. Tachycardia is expected at 6–12 hours. Diaphoresis is expected at 6–12 hours. Delirium with fever is wrong because delirium tremens occurs at 48–72 hours. Pinpoint pupils are wrong because they are part of the opioid intoxication triad.', true),
  ('substance', 3, 'A client 60 hours after the last drink becomes confused and agitated, with fever, hypertension, tachycardia, and profuse diaphoresis, and is picking at unseen objects in the air. Which order should the nurse implement FIRST?', '[{"id": "a", "text": "Lorazepam IV as ordered"}, {"id": "b", "text": "Disulfiram by mouth as ordered"}, {"id": "c", "text": "Naloxone IV as ordered"}, {"id": "d", "text": "Acamprosate by mouth as ordered"}]'::jsonb, '["a"]', 'Autonomic instability with confusion and hallucinations at 48–72 hours is delirium tremens, a medical emergency for which benzodiazepines such as lorazepam are the priority. Disulfiram is never started until the patient is fully sober, and naloxone treats opioid overdose.', false),
  ('substance', 4, 'A malnourished client with long-standing alcohol use disorder is admitted confused, with a low fingerstick glucose. The provider orders IV thiamine and IV dextrose. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Give the dextrose first because hypoglycemia is the priority"}, {"id": "b", "text": "Give the thiamine before the glucose"}, {"id": "c", "text": "Give both at the same time through one line"}, {"id": "d", "text": "Hold the thiamine until the glucose normalizes"}]'::jsonb, '["b"]', 'In alcohol patients, thiamine is given before glucose to prevent Wernicke''s encephalopathy. Giving dextrose first is the tempting choice for a low glucose but risks precipitating Wernicke''s.', false),
  ('substance', 5, 'A client with chronic alcohol use is confused, has an unsteady, wide-based gait, and cannot move the eyes normally. The client''s spouse asks, ''Is this permanent?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Yes, this condition is usually permanent once it appears.\""}, {"id": "b", "text": "\"It improves only if glucose is given before any vitamins.\""}, {"id": "c", "text": "\"This is caused by the alcohol itself, not a vitamin problem.\""}, {"id": "d", "text": "\"It is often reversible if treated with thiamine.\""}]'::jsonb, '["d"]', 'Confusion, ataxia, and ophthalmoplegia are the classic triad of Wernicke''s encephalopathy from thiamine (B1) deficiency, which is reversible if treated with thiamine. Being often irreversible describes Korsakoff syndrome.', false),
  ('substance', 6, 'A client in alcohol withdrawal 55 hours after the last drink is febrile, hypertensive, tachycardic, diaphoretic, confused, and agitated. Which orders does the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Benzodiazepines such as lorazepam"}, {"id": "b", "text": "IV fluids"}, {"id": "c", "text": "Disulfiram to deter further drinking"}, {"id": "d", "text": "Thiamine (B1) before glucose"}, {"id": "e", "text": "Safety measures for confusion"}]'::jsonb, '["a", "b", "d", "e"]', 'These findings at 48–72 hours indicate delirium tremens. Benzodiazepines are correct because they are the priority treatment. IV fluids are correct as part of DT treatment. Thiamine before glucose is correct to prevent Wernicke''s encephalopathy. Safety measures are correct because the nurse maintains safety for fall risk, confusion, and agitation. Disulfiram is wrong because the patient must be fully sober before starting it.', true),
  ('substance', 7, 'A client with a 25-year history of heavy drinking cheerfully describes a trip ''last week'' to a city the family says the client has not visited in years, and cannot recall the nurse''s name 5 minutes after an introduction. Which interpretation is MOST accurate?', '[{"id": "a", "text": "Wernicke''s encephalopathy, reversible with thiamine"}, {"id": "b", "text": "Delirium tremens from recent alcohol withdrawal"}, {"id": "c", "text": "Korsakoff syndrome, which is often irreversible"}, {"id": "d", "text": "Alcohol intoxication with impaired judgment"}]'::jsonb, '["c"]', 'Confabulation (making up memories) and severe anterograde amnesia indicate Korsakoff syndrome from chronic thiamine deficiency, which is often irreversible. Wernicke''s presents with confusion, ataxia, and ophthalmoplegia and is reversible with thiamine.', false),
  ('substance', 8, 'A client is found unresponsive in a hospital bathroom with a syringe nearby. Respirations are slow and shallow, and the pupils are pinpoint. After calling for help and opening the airway, which action should the nurse take NEXT?', '[{"id": "a", "text": "Administer naloxone IM or IV immediately"}, {"id": "b", "text": "Assess withdrawal severity with the COWS scale"}, {"id": "c", "text": "Give lorazepam IV for possible seizures"}, {"id": "d", "text": "Obtain a urine drug screen to confirm the drug"}]'::jsonb, '["a"]', 'Pinpoint pupils, respiratory depression, and altered consciousness are the opioid triad; naloxone is given IM or IV immediately while the airway is maintained. COWS assesses opioid withdrawal, not overdose.', false),
  ('substance', 9, 'A client who received naloxone for a heroin overdose 20 minutes ago is now awake, irritable, and demanding to leave the emergency department. Which concern is the nurse''s PRIORITY when talking with the client?', '[{"id": "a", "text": "Opioid withdrawal is life-threatening without treatment"}, {"id": "b", "text": "Naloxone is short-acting, so re-sedation can occur"}, {"id": "c", "text": "Naloxone may cause seizures after the first dose"}, {"id": "d", "text": "The client must start methadone before discharge"}]'::jsonb, '["b"]', 'Naloxone has a short duration, so the client may need repeated doses and must be watched for re-sedation. Opioid withdrawal is not life-threatening.', false),
  ('substance', 10, 'A client is brought to the emergency department after taking ''a handful of pain pills'' at a party and is difficult to arouse. Which findings would indicate that the pills were opioids? Select all that apply.', '[{"id": "a", "text": "Dilated pupils"}, {"id": "b", "text": "Pinpoint pupils"}, {"id": "c", "text": "Respiratory depression"}, {"id": "d", "text": "Piloerection"}, {"id": "e", "text": "Altered consciousness"}]'::jsonb, '["b", "c", "e"]', 'Pinpoint pupils are part of the opioid triad. Respiratory depression is part of the opioid triad. Altered consciousness (CNS depression) is part of the opioid triad. Dilated pupils are wrong because they occur in opioid withdrawal and stimulant intoxication. Piloerection is wrong because it is an opioid withdrawal finding.', true),
  ('substance', 11, 'A client who stopped using heroin 2 days ago is yawning and has a runny nose, muscle aches, abdominal cramping, dilated pupils, and goose flesh on the arms. Which nursing action is BEST to assess the severity of these symptoms?', '[{"id": "a", "text": "Score the symptoms using the CIWA-Ar scale"}, {"id": "b", "text": "Check pupils hourly for a return of miosis"}, {"id": "c", "text": "Assess the client using the opioid triad"}, {"id": "d", "text": "Score the symptoms using the COWS scale"}]'::jsonb, '["d"]', 'These are opioid withdrawal findings, and the validated scale for opioid withdrawal is COWS. CIWA-Ar is used for alcohol withdrawal, and the opioid triad describes intoxication.', false),
  ('substance', 12, 'The nurse on a detoxification unit receives report on four clients who were admitted overnight. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Patient in opioid withdrawal with rhinorrhea, yawning, and myalgia"}, {"id": "b", "text": "Patient in stimulant withdrawal with hypersomnia"}, {"id": "c", "text": "Patient in benzodiazepine withdrawal with tremors and diaphoresis"}, {"id": "d", "text": "Patient after cannabis use with red eyes and dry mouth"}]'::jsonb, '["c"]', 'Sedative/benzodiazepine withdrawal can be life-threatening, like alcohol withdrawal, with a risk of seizures and delirium. Opioid and stimulant withdrawal are not life-threatening, and red eyes with dry mouth are expected cannabis effects.', false),
  ('substance', 13, 'A client brought in after using cocaine is agitated and paranoid, with dilated pupils, tachycardia, hypertension, and a high temperature, and says bugs are crawling under the skin. Which new finding requires IMMEDIATE intervention?', '[{"id": "a", "text": "New cardiac arrhythmias on the monitor"}, {"id": "b", "text": "Pupils that remain dilated in bright light"}, {"id": "c", "text": "Report of feeling unusually euphoric"}, {"id": "d", "text": "Continued belief that bugs are on the skin"}]'::jsonb, '["a"]', 'Stimulant intoxication carries a risk of MI, stroke, and cardiac arrhythmias, so new arrhythmias require immediate intervention. Dilated pupils, euphoria, and formication are expected stimulant intoxication findings that are not themselves life-threatening.', false),
  ('substance', 14, 'A client who has used oxycodone daily for a year ran out 2 days ago and comes to the clinic asking for help. Which findings does the nurse expect? Select all that apply.', '[{"id": "a", "text": "Yawning and rhinorrhea"}, {"id": "b", "text": "Dilated pupils"}, {"id": "c", "text": "Piloerection"}, {"id": "d", "text": "Withdrawal seizures"}, {"id": "e", "text": "Abdominal cramping"}]'::jsonb, '["a", "b", "c", "e"]', 'Yawning and rhinorrhea are flu-like opioid withdrawal findings. Dilated pupils are an opioid withdrawal finding. Piloerection (goose flesh) is an opioid withdrawal finding. Abdominal cramping is an opioid withdrawal finding. Withdrawal seizures are wrong because opioid withdrawal is not life-threatening; seizure precautions are for alcohol and sedative withdrawal.', true),
  ('substance', 15, 'A client who used methamphetamine daily for 3 weeks stopped 2 days ago, has slept 14 hours a day, is eating large amounts, feels dysphoric, and reports intense cravings. Vital signs are stable. Which nursing approach is BEST?', '[{"id": "a", "text": "Seizure precautions and a benzodiazepine taper"}, {"id": "b", "text": "Supportive care for an expected crash"}, {"id": "c", "text": "Naloxone as ordered for the sedation"}, {"id": "d", "text": "Thiamine before glucose for the appetite change"}]'::jsonb, '["b"]', 'Hypersomnia, increased appetite, dysphoria, and intense cravings are the stimulant withdrawal crash, which is not life-threatening and is treated with supportive care. Seizure precautions and a benzodiazepine taper are for sedative withdrawal.', false),
  ('substance', 16, 'An adolescent is brought to the school nurse giggling, with red eyes, dry mouth, a rapid pulse, and a sudden craving for snacks, and says the class ''has lasted for hours.'' Which substance is MOST likely responsible?', '[{"id": "a", "text": "Cocaine (stimulant)"}, {"id": "b", "text": "Heroin (opioid)"}, {"id": "c", "text": "Alcohol"}, {"id": "d", "text": "Cannabis"}]'::jsonb, '["d"]', 'Euphoria, altered time perception, conjunctival injection, increased appetite, tachycardia, and dry mouth indicate cannabis intoxication. Cocaine causes dilated pupils, hypertension, and hyperthermia rather than red eyes and increased appetite.', false),
  ('substance', 17, 'A client found at a party is drowsy and confused, with slurred speech and an unsteady gait, cannot remember events since arriving, and has a bottle of alprazolam in a pocket. Which assessment is the nurse''s PRIORITY?', '[{"id": "a", "text": "Pupil size, to rule out opioid use"}, {"id": "b", "text": "Memory, to fully document the anterograde amnesia"}, {"id": "c", "text": "Respiratory status, for respiratory depression"}, {"id": "d", "text": "Skin, for formication and scratching"}]'::jsonb, '["c"]', 'Sedative intoxication causes CNS depression, slurred speech, ataxia, confusion, anterograde amnesia, and respiratory depression; breathing is the priority. Anterograde amnesia is expected but not life-threatening.', false),
  ('substance', 18, 'A client completing alcohol detoxification will start disulfiram (Antabuse) at discharge. Which statements by the client indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"A small sip of wine at dinner won''t cause a reaction.\""}, {"id": "b", "text": "\"I''ll avoid cough syrups that contain alcohol.\""}, {"id": "c", "text": "\"I can take my dose while I still have alcohol in me.\""}, {"id": "d", "text": "\"No mouthwash or aftershave with alcohol for me.\""}, {"id": "e", "text": "\"If I drink, it will only reduce my craving.\""}]'::jsonb, '["b", "d"]', 'Avoiding cough syrups with alcohol is correct because all forms of alcohol must be avoided. Avoiding mouthwash and aftershave with alcohol is correct for the same reason. A small sip of wine is wrong because even small amounts cause a severe disulfiram reaction. Taking the dose with alcohol in the system is wrong because the patient must be fully sober before starting. Reduced craving is wrong because disulfiram causes a severe reaction when alcohol is consumed; reducing craving describes naltrexone and acamprosate.', true),
  ('substance', 19, 'A client taking disulfiram (Antabuse) is reviewing a meal plan with the nurse before discharge. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"Cooking wine is fine in sauces; the heat removes alcohol.\""}, {"id": "b", "text": "\"I''ll skip salad dressings that are made with vinegars.\""}, {"id": "c", "text": "\"I''ll check the label on my aftershave to see if it has alcohol.\""}, {"id": "d", "text": "\"I''ll avoid desserts that are flavored with liqueurs.\""}]'::jsonb, '["a"]', 'Clients taking disulfiram must avoid alcohol in all forms, including cooking wine and sauces, because even small amounts cause a severe reaction. Avoiding vinegars and checking aftershave are correct.', false),
  ('substance', 20, 'A client with alcohol use disorder was admitted this morning with a blood alcohol level still elevated from last night''s drinking. The provider writes an order to begin disulfiram today. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Give the initial dose with breakfast as ordered"}, {"id": "b", "text": "Hold it; the patient must be fully sober before starting"}, {"id": "c", "text": "Teach the client to avoid mouthwash, then give the dose"}, {"id": "d", "text": "Give the dose with a benzodiazepine to prevent a reaction"}]'::jsonb, '["b"]', 'The patient must be completely alcohol-free before starting disulfiram, so the nurse holds the dose and clarifies the order. Teaching about mouthwash is appropriate but does not make it safe to give the drug while alcohol is present.', false),
  ('substance', 21, 'A client who started disulfiram last week calls the clinic after a restaurant dinner, reporting flushing, nausea, vomiting, and dizziness; on arrival the nurse notes a low blood pressure and a rapid pulse. Which interpretation is MOST likely?', '[{"id": "a", "text": "Opioid withdrawal from a missed dose"}, {"id": "b", "text": "Stimulant intoxication with hyperthermia"}, {"id": "c", "text": "Alcohol withdrawal at 6–12 hours"}, {"id": "d", "text": "Disulfiram reaction to hidden alcohol"}]'::jsonb, '["d"]', 'Flushing, nausea, vomiting, hypotension, and tachycardia after a restaurant meal indicate a disulfiram reaction to small amounts of alcohol, such as cooking wine. Stimulant intoxication causes hypertension and hyperthermia, not hypotension.', false),
  ('substance', 22, 'A client brought to the emergency department after a night of using cocaine is pacing, talking rapidly, and accusing staff of plotting against the client. Which additional findings does the nurse expect? Select all that apply.', '[{"id": "a", "text": "Dilated pupils"}, {"id": "b", "text": "Hypersomnia"}, {"id": "c", "text": "Hyperthermia"}, {"id": "d", "text": "Formication"}, {"id": "e", "text": "Hypertension"}]'::jsonb, '["a", "c", "d", "e"]', 'Dilated pupils are expected in stimulant intoxication. Hyperthermia is expected in stimulant intoxication. Formication (bugs crawling on skin) is expected with stimulant paranoia and hallucinations. Hypertension is expected in stimulant intoxication. Hypersomnia is wrong because it belongs to the stimulant withdrawal crash.', true),
  ('substance', 23, 'A client in early recovery from alcohol use disorder is prescribed naltrexone. Which statement by the client indicates understanding of how the medication works?', '[{"id": "a", "text": "\"If I drink, it will make me flush and vomit.\""}, {"id": "b", "text": "\"It replaces alcohol with a long-acting substitute.\""}, {"id": "c", "text": "\"It reduces my craving and the reward from alcohol.\""}, {"id": "d", "text": "\"It reverses the effects if I drink too much.\""}]'::jsonb, '["c"]', 'Naltrexone reduces craving and reward from alcohol. Flushing and vomiting after drinking describe a disulfiram reaction.', false),
  ('substance', 24, 'A client who completed alcohol detoxification last week wants medication to help maintain abstinence but says, ''I don''t want anything that makes me violently sick if I slip.'' Which medication does the nurse anticipate as the BEST fit?', '[{"id": "a", "text": "Acamprosate"}, {"id": "b", "text": "Disulfiram (Antabuse)"}, {"id": "c", "text": "Methadone"}, {"id": "d", "text": "Naloxone (Narcan)"}]'::jsonb, '["a"]', 'Acamprosate reduces craving and helps maintain abstinence without causing a reaction to alcohol. Disulfiram causes a severe reaction (flushing, vomiting, palpitations) when alcohol is consumed.', false),
  ('substance', 25, 'A client with opioid use disorder starting methadone maintenance asks, ''Can I just get a month''s supply so I don''t have to keep coming in?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Yes, methadone is prescribed in the office like any refill.\""}, {"id": "b", "text": "\"Methadone is dispensed daily at the clinic.\""}, {"id": "c", "text": "\"Methadone has a ceiling effect, so a month''s supply is safe.\""}, {"id": "d", "text": "\"You only need it until withdrawal symptoms peak.\""}]'::jsonb, '["b"]', 'Methadone is a long-acting opioid agonist dispensed daily at a clinic. Office-based prescribing and a ceiling effect describe buprenorphine, not methadone.', false),
  ('substance', 26, 'A client who has taken high-dose alprazolam daily for 2 years is admitted to stop using it. Which actions does the nurse anticipate in the plan of care? Select all that apply.', '[{"id": "a", "text": "Stop the alprazolam abruptly today"}, {"id": "b", "text": "Seizure precautions"}, {"id": "c", "text": "Supportive care only, as withdrawal is not dangerous"}, {"id": "d", "text": "Naloxone as ordered to block withdrawal"}, {"id": "e", "text": "A slow taper using another benzodiazepine"}]'::jsonb, '["b", "e"]', 'Seizure precautions are correct because sedative withdrawal can cause seizures. A slow taper with another benzodiazepine is correct because it is the stated treatment. Stopping abruptly is wrong because sedative withdrawal is life-threatening. Supportive care only is wrong because that applies to stimulant withdrawal, not sedative withdrawal. Naloxone is wrong because it is an opioid antagonist used for opioid overdose.', true),
  ('substance', 27, 'A client with opioid use disorder asks why the provider recommends buprenorphine (Suboxone) instead of continuing to buy pills on the street. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"It is a full opioid agonist that gives a stronger effect.\""}, {"id": "b", "text": "\"It causes a severe reaction whenever you use any other opioids.\""}, {"id": "c", "text": "\"It is an opioid antagonist that reverses an overdose.\""}, {"id": "d", "text": "\"It is a partial agonist with a ceiling effect on overdose.\""}]'::jsonb, '["d"]', 'Buprenorphine is a partial opioid agonist whose ceiling effect reduces overdose risk. Reversing an overdose describes naloxone, an opioid antagonist.', false),
  ('substance', 28, 'A client admitted for pneumonia drinks heavily every day, and the last drink was 20 hours ago. The client has mild tremors and anxiety. When planning care for the coming 24 hours, which nursing intervention is the PRIORITY?', '[{"id": "a", "text": "Encourage attendance at an AA meeting on the unit"}, {"id": "b", "text": "Screen for co-occurring depression and PTSD"}, {"id": "c", "text": "Institute seizure precautions"}, {"id": "d", "text": "Teach about disulfiram for use after discharge"}]'::jsonb, '["c"]', 'Alcohol withdrawal seizures peak at 24–48 hours, so a client at 20 hours is entering the peak window and needs seizure precautions. Screening for co-occurring disorders and encouraging AA are important but not the priority over safety.', false),
  ('substance', 29, 'A caller who identifies herself as a client''s employer phones the substance use treatment unit and asks whether the client is a patient there and how detox is going. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Substance abuse records have extra protections; I can''t share that.\""}, {"id": "b", "text": "\"I can confirm the client was admitted, but I can''t discuss the detox.\""}, {"id": "c", "text": "\"Since you are the employer, I can give you a brief update on progress.\""}, {"id": "d", "text": "\"I can share the information once you fax a written request.\""}]'::jsonb, '["a"]', 'Substance abuse records have extra confidentiality protections (42 CFR Part 2), so the nurse does not confirm or share information. Confirming admission already discloses protected information.', false),
  ('substance', 30, 'A college-age client is brought to the clinic by a roommate after smoking a high-THC strain and is now anxious and convinced someone is following the client. Which additional findings does the nurse expect? Select all that apply.', '[{"id": "a", "text": "Conjunctival injection"}, {"id": "b", "text": "Tachycardia and dry mouth"}, {"id": "c", "text": "Pinpoint pupils"}, {"id": "d", "text": "Increased appetite"}, {"id": "e", "text": "Hyperthermia"}]'::jsonb, '["a", "b", "d"]', 'Paranoia and anxiety after a high-THC strain indicate cannabis intoxication. Conjunctival injection (red eyes) is expected. Tachycardia and dry mouth are expected. Increased appetite is expected. Pinpoint pupils are wrong because they indicate opioid intoxication. Hyperthermia is wrong because it is a stimulant intoxication finding.', true),
  ('substance', 31, 'A client admitted for alcohol withdrawal looks away and says, ''You probably think I''m a weak, terrible person for letting this happen.'' Which response by the nurse is MOST therapeutic?', '[{"id": "a", "text": "\"Everyone makes mistakes; just try harder not to drink again.\""}, {"id": "b", "text": "\"Addiction is a disease, not a moral failure. I''m here to help.\""}, {"id": "c", "text": "\"Why did you keep drinking when you knew it was harmful?\""}, {"id": "d", "text": "\"Don''t worry, I''m sure you will stay sober after this stay.\""}]'::jsonb, '["b"]', 'The nurse uses a non-judgmental, therapeutic approach because addiction is a disease, not a moral failure. Telling the client to try harder implies a moral failing.', false),
  ('substance', 32, 'A client tells the clinic nurse, ''Two beers used to relax me. Now I need six or seven to feel anything, and I''ve been drinking more every month.'' Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Withdrawal from abrupt cessation"}, {"id": "b", "text": "Intoxication from recent use"}, {"id": "c", "text": "Physical dependence with withdrawal symptoms"}, {"id": "d", "text": "Tolerance: needs more for the same effect"}]'::jsonb, '["d"]', 'Needing increasing amounts to achieve the same effect is tolerance. Dependence is physical adaptation shown by withdrawal symptoms when the substance is stopped, which the client does not describe.', false),
  ('substance', 33, 'A client who has taken prescribed oxycodone exactly as directed for 3 months after spinal surgery develops yawning, rhinorrhea, and muscle aches when the dose is stopped. The client shows no drug-seeking behavior. Which interpretation is MOST accurate?', '[{"id": "a", "text": "Addiction, shown by loss of control over use"}, {"id": "b", "text": "Opioid intoxication with CNS depression"}, {"id": "c", "text": "Dependence, a physical adaptation to the drug"}, {"id": "d", "text": "Substance use disorder requiring naltrexone"}]'::jsonb, '["c"]', 'Withdrawal symptoms when a substance is stopped reflect dependence, a physical adaptation. Addiction requires compulsive drug-seeking despite harmful consequences and loss of control, which this client does not show.', false),
  ('substance', 34, 'A client is admitted for alcohol detoxification 10 hours after the last drink with tremors, tachycardia, and diaphoresis. Which nursing actions should be included in the plan of care? Select all that apply.', '[{"id": "a", "text": "Assess severity using the CIWA-Ar"}, {"id": "b", "text": "Monitor vital signs q1–4h by severity"}, {"id": "c", "text": "IV fluids and electrolyte replacement as needed"}, {"id": "d", "text": "Score symptoms using the COWS"}, {"id": "e", "text": "Fall risk and safety measures"}]'::jsonb, '["a", "b", "c", "e"]', 'The CIWA-Ar is correct because it is the validated scale for alcohol withdrawal. Monitoring vital signs q1–4h by severity is correct during withdrawal. IV fluids and electrolyte replacement as needed are correct. Fall risk and safety measures are correct because the nurse maintains safety for fall risk, confusion, and agitation. COWS is wrong because it assesses opioid withdrawal.', true),
  ('substance', 35, 'A clinic nurse reviews alcohol screening results for four clients, each of whom reports some problems related to drinking. Which client''s results MOST clearly meet the threshold for a substance use disorder?', '[{"id": "a", "text": "2 DSM-5 criteria present within the past 12 months"}, {"id": "b", "text": "1 DSM-5 criterion present for each of the past 3 years"}, {"id": "c", "text": "Social drinking twice monthly with no impairment"}, {"id": "d", "text": "2 criteria present, but only during a period 4 years ago"}]'::jsonb, '["a"]', 'A substance use disorder requires at least 2 of 11 DSM-5 criteria within 12 months. A single criterion, even over several years, or criteria met only 4 years ago does not meet the threshold.', false),
  ('substance', 36, 'A client brought in from a bar has slurred speech, an unsteady gait, and a flushed face. Over the following hour, the client becomes difficult to arouse, and respirations become slow and shallow. Which action is the nurse''s PRIORITY?', '[{"id": "a", "text": "Assess withdrawal severity using the CIWA-Ar"}, {"id": "b", "text": "Maintain the airway and monitor respiratory rate"}, {"id": "c", "text": "Give thiamine before any glucose is started"}, {"id": "d", "text": "Begin seizure precautions for withdrawal"}]'::jsonb, '["b"]', 'Alcohol intoxication causes respiratory depression at a high BAC, so maintaining the airway and monitoring respirations is the priority. The CIWA-Ar and seizure precautions apply to withdrawal, not acute intoxication.', false),
  ('substance', 37, 'The nurse on a medical unit receives report on four clients with substance use disorders. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Opioid withdrawal at 48 hours with diarrhea, cramping, and myalgia"}, {"id": "b", "text": "Stimulant withdrawal with fatigue and intense cravings"}, {"id": "c", "text": "Alcohol withdrawal at 8 hours with mild tremors and anxiety"}, {"id": "d", "text": "Alcohol withdrawal at 60 hours with fever, confusion, agitation"}]'::jsonb, '["d"]', 'Fever, confusion, and agitation at 48–72 hours indicate delirium tremens, the most severe, life-threatening stage. Opioid and stimulant withdrawal are not life-threatening, and tremors at 8 hours are an early stage.', false),
  ('substance', 38, 'A client with long-standing alcohol use disorder and poor nutrition is admitted, and thiamine is ordered before any glucose. The nurse assesses for the condition this order is meant to prevent. Which findings would indicate that condition? Select all that apply.', '[{"id": "a", "text": "Confusion"}, {"id": "b", "text": "Confabulation"}, {"id": "c", "text": "Ataxia"}, {"id": "d", "text": "Severe anterograde amnesia"}, {"id": "e", "text": "Ophthalmoplegia (eye movement disorder)"}]'::jsonb, '["a", "c", "e"]', 'Thiamine before glucose prevents Wernicke''s encephalopathy. Confusion is part of its classic triad. Ataxia is part of the triad. Ophthalmoplegia is part of the triad. Confabulation and severe anterograde amnesia are wrong because they describe Korsakoff syndrome from chronic thiamine deficiency.', true),
  ('substance', 39, 'A client hospitalized after a fall had the last drink 18 hours ago. The client is oriented to person, place, and time but reports seeing small animals on the wall and feeling bugs on the skin. Vital signs are mildly elevated. Which interpretation is MOST accurate?', '[{"id": "a", "text": "Delirium tremens, a life-threatening medical emergency"}, {"id": "b", "text": "Stimulant intoxication causing formication"}, {"id": "c", "text": "Alcohol withdrawal hallucinations at 12–24 hours"}, {"id": "d", "text": "Korsakoff syndrome with confabulation"}]'::jsonb, '["c"]', 'Visual and tactile hallucinations at 12–24 hours after the last drink are an expected stage of alcohol withdrawal. Delirium tremens occurs at 48–72 hours with confusion and severe autonomic instability, which this oriented client does not have.', false),
  ('substance', 40, 'A client is brought to the emergency department euphoric and hyperactive, with dilated pupils, tachycardia, hypertension, and a temperature well above normal. Which condition is MOST consistent with these findings?', '[{"id": "a", "text": "Stimulant intoxication"}, {"id": "b", "text": "Opioid withdrawal at its peak"}, {"id": "c", "text": "Cannabis intoxication"}, {"id": "d", "text": "Alcohol withdrawal"}]'::jsonb, '["a"]', 'Euphoria, hyperactivity, dilated pupils, tachycardia, hypertension, and hyperthermia indicate stimulant intoxication. Opioid withdrawal also causes dilated pupils but presents as flu-like symptoms without euphoria or hyperthermia.', false),
  ('substance', 41, 'A client who has taken lorazepam nightly for years and recently added diazepam during the day wants to stop ''everything, starting tomorrow.'' Which plan does the nurse anticipate as BEST?', '[{"id": "a", "text": "Stop both drugs at once with supportive care"}, {"id": "b", "text": "A slow taper using another benzodiazepine"}, {"id": "c", "text": "Naloxone to reverse dependence before stopping"}, {"id": "d", "text": "Switch to buprenorphine for the withdrawal"}]'::jsonb, '["b"]', 'Sedative withdrawal is life-threatening and is treated with a slow taper using another benzodiazepine. Stopping at once with only supportive care is the approach for stimulant withdrawal, not sedatives.', false),
  ('substance', 42, 'A client starting methadone and a client starting buprenorphine attend the same group teaching session for opioid use disorder. Which statements made during the session indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"Methadone is long-acting and reduces withdrawal and cravings.\""}, {"id": "b", "text": "\"Buprenorphine is a full agonist with no ceiling effect.\""}, {"id": "c", "text": "\"Methadone reverses an overdose if I take too much.\""}, {"id": "d", "text": "\"Buprenorphine allows office-based prescribing.\""}, {"id": "e", "text": "\"Buprenorphine causes a severe reaction if I drink.\""}]'::jsonb, '["a", "d"]', 'Methadone being long-acting and reducing withdrawal and cravings is correct. Office-based prescribing of buprenorphine is correct. A full agonist with no ceiling effect is wrong because buprenorphine is a partial agonist with a ceiling effect. Reversing an overdose is wrong because that is naloxone, an opioid antagonist. A severe reaction with drinking is wrong because that describes disulfiram.', true),
  ('substance', 43, 'A client completing alcohol detoxification reports trouble sleeping, nightmares about a past assault, and feeling hopeless most days. Which action by the nurse is MOST important before discharge planning?', '[{"id": "a", "text": "Teach that these are expected withdrawal symptoms"}, {"id": "b", "text": "Encourage the client to focus only on sobriety now"}, {"id": "c", "text": "Recommend disulfiram to prevent an early relapse"}, {"id": "d", "text": "Screen for co-occurring depression and PTSD"}]'::jsonb, '["d"]', 'Nurses screen for co-occurring mental health disorders such as depression and PTSD, which these findings suggest. Labeling them as withdrawal symptoms misses a co-occurring disorder.', false),
  ('substance', 44, 'A client who received naloxone IV for an opioid overdose woke up and was talking 30 minutes ago. The nurse now finds the client drowsy with slow, shallow respirations. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Allow the client to sleep off the remaining drug"}, {"id": "b", "text": "Assess severity using the COWS scale"}, {"id": "c", "text": "Give repeat dosing of naloxone"}, {"id": "d", "text": "Give lorazepam to prevent withdrawal seizures"}]'::jsonb, '["c"]', 'Naloxone is short-acting and may need repeat dosing, so re-sedation with respiratory depression calls for another dose. COWS assesses opioid withdrawal, not re-sedation.', false),
  ('substance', 45, 'The nurse is assigning beds near the nurses'' station on a detoxification unit, and each client listed stopped the substance within the past day. Which types of withdrawal carry a risk of seizures and are potentially life-threatening? Select all that apply.', '[{"id": "a", "text": "Alcohol withdrawal"}, {"id": "b", "text": "Benzodiazepine withdrawal"}, {"id": "c", "text": "Opioid withdrawal"}, {"id": "d", "text": "Stimulant withdrawal"}, {"id": "e", "text": "Cannabis cessation"}]'::jsonb, '["a", "b"]', 'Alcohol withdrawal is correct because it carries seizures and DTs. Benzodiazepine withdrawal is correct because sedative withdrawal is life-threatening, like alcohol, with seizures. Opioid withdrawal is wrong because it is not life-threatening. Stimulant withdrawal is wrong because it is not life-threatening and needs supportive care. Cannabis cessation is wrong because seizure precautions are needed only for alcohol and sedative withdrawal.', true),
  ('substance', 46, 'A client on day 2 of opioid withdrawal is miserable with diarrhea, cramping, and muscle aches and asks, ''How long is this going to last?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Symptoms peak at 36–72 hours and resolve in 1–2 weeks.\""}, {"id": "b", "text": "\"Symptoms peak at 24–48 hours, when seizures are likely.\""}, {"id": "c", "text": "\"Symptoms last only 6–12 hours after the last dose.\""}, {"id": "d", "text": "\"Symptoms usually continue for several months.\""}]'::jsonb, '["a"]', 'Opioid withdrawal peaks at 36–72 hours and resolves in 1–2 weeks. A seizure peak at 24–48 hours describes alcohol withdrawal.', false),
  ('substance', 47, 'A client has both alcohol use disorder and opioid use disorder and is no longer using opioids. The provider wants one medication that reduces alcohol craving and is also used for opioid use disorder. Which medication does the nurse anticipate as the BEST choice?', '[{"id": "a", "text": "Acamprosate"}, {"id": "b", "text": "Naltrexone"}, {"id": "c", "text": "Disulfiram"}, {"id": "d", "text": "Methadone"}]'::jsonb, '["b"]', 'Naltrexone reduces craving and reward from alcohol and is also used for opioid use disorder. Acamprosate reduces alcohol craving but is not listed for opioid use disorder, and methadone treats opioid use disorder only.', false),
  ('substance', 48, 'A client is brought to the emergency department by friends after several hours of heavy drinking at a wedding. Which findings does the nurse expect? Select all that apply.', '[{"id": "a", "text": "Slurred speech"}, {"id": "b", "text": "Unsteady gait"}, {"id": "c", "text": "Pinpoint pupils"}, {"id": "d", "text": "Disinhibition"}, {"id": "e", "text": "Flushed face"}]'::jsonb, '["a", "b", "d", "e"]', 'Slurred speech is an alcohol intoxication sign. Unsteady gait is an alcohol intoxication sign. Disinhibition is an alcohol intoxication sign. Flushed face is an alcohol intoxication sign. Pinpoint pupils are wrong because they are part of the opioid intoxication triad.', true),
  ('substance', 49, 'A client who has completed alcohol detoxification is preparing for discharge and wants to stay sober. Which discharge plan elements are appropriate? Select all that apply.', '[{"id": "a", "text": "Release records to the employer without consent"}, {"id": "b", "text": "Encourage participation in AA and support groups"}, {"id": "c", "text": "Start disulfiram while the client is still intoxicated"}, {"id": "d", "text": "Discuss naltrexone or acamprosate to reduce craving"}, {"id": "e", "text": "Use naloxone daily to prevent alcohol relapse"}]'::jsonb, '["b", "d"]', 'Encouraging AA and support groups is correct. Discussing naltrexone or acamprosate is correct because both reduce craving. Releasing records without consent is wrong because substance abuse records have extra protections. Starting disulfiram while intoxicated is wrong because the patient must be fully sober. Naloxone is wrong because it is an opioid antagonist for opioid overdose.', true),
  ('substance', 50, 'A client who binged on cocaine for 3 days stopped yesterday and is now admitted to a detoxification unit for observation. Which findings does the nurse expect? Select all that apply.', '[{"id": "a", "text": "Hypersomnia"}, {"id": "b", "text": "Withdrawal seizures"}, {"id": "c", "text": "Increased appetite"}, {"id": "d", "text": "Hyperthermia"}, {"id": "e", "text": "Intense cravings"}]'::jsonb, '["a", "c", "e"]', 'Hypersomnia is expected in the stimulant crash. Increased appetite is expected in the crash. Intense cravings are expected in the crash. Withdrawal seizures are wrong because stimulant withdrawal is not life-threatening. Hyperthermia is wrong because it is a stimulant intoxication finding.', true),
  ('bipolar', 1, 'A client who has taken lithium for 2 years had 3 days of vomiting and diarrhea from a stomach virus. Today the client has a coarse hand tremor and is drowsy, and the serum lithium level is 1.8 mEq/L. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Mild toxicity, likely from dehydration due to vomiting and diarrhea"}, {"id": "b", "text": "A therapeutic level for acute treatment; the tremor is an expected effect"}, {"id": "c", "text": "Moderate toxicity; ataxia, tinnitus, and slurred speech should be present"}, {"id": "d", "text": "Severe toxicity; seizures, coma, and cardiac dysrhythmias are expected"}]'::jsonb, '["a"]', 'A level of 1.8 mEq/L falls in the mild toxicity range (1.5–2.0), which causes coarse tremor, N/V/D, drowsiness, and confusion; vomiting and diarrhea cause dehydration and toxicity risk. Moderate toxicity (ataxia, tinnitus, slurred speech) begins at 2.0 mEq/L.', false),
  ('bipolar', 2, 'A client admitted for acute mania has received lithium for 6 days. The client still has pressured speech and sleeps about 2 hours a night. Today''s serum lithium level is 0.7 mEq/L. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The level is in the mild toxicity range and lithium should be held"}, {"id": "b", "text": "The level is therapeutic because it falls between 0.6 and 1.2 mEq/L"}, {"id": "c", "text": "The level is below the therapeutic range for acute mania"}, {"id": "d", "text": "The level is above the maintenance range and suggests toxicity"}]'::jsonb, '["c"]', 'The therapeutic range for acute mania is 0.8–1.4 mEq/L, so 0.7 mEq/L is below range, which fits the persistent manic symptoms. The 0.6–1.2 mEq/L range applies to long-term maintenance, not acute treatment.', false),
  ('bipolar', 3, 'A client taking lithium is brought to the emergency department after an intentional extra ingestion. The serum lithium level is 2.8 mEq/L. Which finding is MOST characteristic of this degree of toxicity?', '[{"id": "a", "text": "Coarse tremor with nausea"}, {"id": "b", "text": "Seizures"}, {"id": "c", "text": "Ataxia with tinnitus"}, {"id": "d", "text": "Blurred vision with slurred speech"}]'::jsonb, '["b"]', 'A level above 2.5 mEq/L is severe toxicity, characterized by seizures, coma, cardiac dysrhythmias, and death. Coarse tremor and nausea mark mild toxicity, and ataxia, tinnitus, blurred vision, and slurred speech mark moderate toxicity (2.0–2.5 mEq/L).', false),
  ('bipolar', 4, 'The nurse reviews morning serum lithium levels for four clients. Which client should the nurse see FIRST?', '[{"id": "a", "text": "A patient on maintenance lithium with a level of 1.0 mEq/L"}, {"id": "b", "text": "A patient in acute mania with a level of 1.3 mEq/L and pressured speech"}, {"id": "c", "text": "A patient on maintenance lithium with a level of 1.6 mEq/L and nausea"}, {"id": "d", "text": "A patient with a level of 2.7 mEq/L who is newly confused"}]'::jsonb, '["d"]', 'A level above 2.5 mEq/L is severe toxicity that can cause seizures, coma, cardiac dysrhythmias, and death, so this client is seen first. A level of 1.6 mEq/L is mild toxicity and needs prompt follow-up, while 1.0 and 1.3 mEq/L are within the maintenance and acute ranges.', false),
  ('bipolar', 5, 'A client takes a single daily dose of lithium at 2100. The provider orders a serum lithium level for the next day. Which time is MOST appropriate for the blood draw?', '[{"id": "a", "text": "0900 the next morning"}, {"id": "b", "text": "2300 that same evening"}, {"id": "c", "text": "0300 early the next morning"}, {"id": "d", "text": "2100 the following evening"}]'::jsonb, '["a"]', 'Lithium levels are drawn 12 hours after the last dose; 2100 plus 12 hours is 0900 the next morning. A draw at 2300 or 0300 is too soon after the dose, and 2100 the next evening is 24 hours later.', false),
  ('bipolar', 6, 'A client on lithium sprained an ankle while jogging and asks the nurse about managing the pain at home. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll keep up my 2 to 3 liters of fluid every day.\""}, {"id": "b", "text": "\"I can take NSAIDs with lithium for the pain.\""}, {"id": "c", "text": "\"I''ll keep taking my lithium with food as usual.\""}, {"id": "d", "text": "\"I''ll call if I get a coarse tremor or diarrhea.\""}]'::jsonb, '["b"]', 'NSAIDs raise lithium levels and increase the risk of toxicity, so the client should not assume an over-the-counter NSAID is safe. Adequate fluid, taking lithium with food, and reporting tremor or diarrhea are all correct.', false),
  ('bipolar', 7, 'A client who has taken lithium for 5 years is newly diagnosed with hypertension, and the provider prescribes a thiazide diuretic. Which action by the nurse is BEST?', '[{"id": "a", "text": "Give the diuretic with breakfast along with the lithium dose"}, {"id": "b", "text": "Teach the patient to reduce sodium intake to lower blood pressure"}, {"id": "c", "text": "Clarify the order, because thiazides raise lithium levels"}, {"id": "d", "text": "Teach the patient to increase fluid intake to 4 to 5 L per day"}]'::jsonb, '["c"]', 'Thiazide diuretics raise lithium levels, so the prescription should be clarified with the provider. Reducing sodium is also dangerous because a low sodium diet increases lithium reabsorption by the kidneys.', false),
  ('bipolar', 8, 'A client stabilized on lithium tells the nurse, "I found an online program, and I''m going to cut out almost all salt to lose weight before summer." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Cutting salt is fine as long as you keep drinking 2 to 3 liters a day.\""}, {"id": "b", "text": "\"That plan is safe if you take your lithium with food to protect your stomach.\""}, {"id": "c", "text": "\"Lowering salt will reduce your lithium level, so your dose may need to go up.\""}, {"id": "d", "text": "\"Low sodium increases lithium reabsorption; keep your salt intake consistent.\""}]'::jsonb, '["d"]', 'A low sodium diet increases lithium reabsorption by the kidneys and raises the risk of toxicity, so the client needs consistent fluid and salt intake. Lowering salt raises, not lowers, the lithium level, and adequate fluid does not offset a low-sodium diet.', false),
  ('bipolar', 9, 'A client who takes lithium works outdoors as a landscaper and reports heavy sweating during the summer months. Which teaching point is the PRIORITY for this client?', '[{"id": "a", "text": "Maintain consistent fluid/salt intake"}, {"id": "b", "text": "Take an extra lithium dose on very hot days"}, {"id": "c", "text": "Reduce salt intake to prevent fluid retention"}, {"id": "d", "text": "Skip lithium on days of very heavy sweating"}]'::jsonb, '["a"]', 'Sweating leads to dehydration and lithium toxicity risk, so the client must maintain consistent fluid and salt intake. Reducing salt increases lithium reabsorption, and skipping doses (stopping abruptly) risks rebound mania.', false),
  ('bipolar', 10, 'A client who has taken lithium for 3 months says, "I feel completely normal now, so I''m going to stop the lithium this weekend." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"That''s reasonable now that you have had no manic symptoms for weeks.\""}, {"id": "b", "text": "\"Do not stop lithium abruptly; it can cause rebound mania.\""}, {"id": "c", "text": "\"Cut your dose in half for one week first, and then you can stop taking it.\""}, {"id": "d", "text": "\"Once you stop, you will no longer need your blood levels to be checked.\""}]'::jsonb, '["b"]', 'Lithium must not be stopped abruptly because doing so can cause rebound mania, and bipolar disorder requires lifelong management. Self-tapering is still stopping without the provider and does not address the risk.', false),
  ('bipolar', 11, 'A client started lithium 1 week ago and has a level of 0.9 mEq/L. The client reports mild stomach upset after taking lithium on an empty stomach but has no tremor, vomiting, or diarrhea. Which instruction is BEST?', '[{"id": "a", "text": "Hold lithium until the stomach upset completely resolves"}, {"id": "b", "text": "Reduce fluid intake to lessen the feeling of nausea"}, {"id": "c", "text": "Take lithium with food to reduce GI upset"}, {"id": "d", "text": "Follow a bland, low-sodium diet for several days"}]'::jsonb, '["c"]', 'With a therapeutic level and no signs of toxicity, taking lithium with food reduces GI upset. Holding doses risks rebound mania, and reducing fluid or sodium raises the risk of toxicity.', false),
  ('bipolar', 12, 'A 26-year-old client with bipolar disorder is prescribed valproate (Depakote) and mentions that she and her partner hope to start a family next year. Which information is the PRIORITY for the nurse to address?', '[{"id": "a", "text": "Lithium levels must be drawn 12 hours after the last dose"}, {"id": "b", "text": "Valproate should be taken with food to reduce stomach upset"}, {"id": "c", "text": "Valproate commonly causes weight gain during treatment"}, {"id": "d", "text": "Valproate is teratogenic and can cause neural tube defects"}]'::jsonb, '["d"]', 'Valproate is teratogenic (neural tube defects), the most important risk for a client planning pregnancy. Weight gain is a true effect but is not the priority, and the 12-hour level timing applies to lithium.', false),
  ('bipolar', 13, 'A client with bipolar disorder has been started on carbamazepine (Tegretol). Which laboratory test is the PRIORITY for the nurse to monitor because of this medication''s key risk?', '[{"id": "a", "text": "CBC (agranulocytosis risk)"}, {"id": "b", "text": "Serum level 12 hours after the dose"}, {"id": "c", "text": "Thyroid function studies"}, {"id": "d", "text": "Fasting lipids for metabolic syndrome"}]'::jsonb, '["a"]', 'Carbamazepine requires CBC monitoring because of agranulocytosis risk. Thyroid monitoring and 12-hour levels are lithium-related, and metabolic syndrome monitoring applies to atypical antipsychotics.', false),
  ('bipolar', 14, 'A client in acute mania is shouting, throwing chairs in the dayroom, and cannot be calmed verbally. Staff have cleared other clients from the area. Which medication would the nurse MOST expect the provider to prescribe for this acute agitation?', '[{"id": "a", "text": "An extra oral dose of lithium"}, {"id": "b", "text": "Valproate (Depakote) by mouth"}, {"id": "c", "text": "Lorazepam IM"}, {"id": "d", "text": "Carbamazepine (Tegretol) by mouth"}]'::jsonb, '["c"]', 'Benzodiazepines such as lorazepam IM are used short-term for acute agitation in mania. Lithium, valproate, and carbamazepine are mood-stabilizing treatments rather than the short-term treatment for acute agitation.', false),
  ('bipolar', 15, 'A client recovering from a manic episode says, "The lorazepam calms me down so much better than lithium. Can I just take lorazepam from now on instead?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Yes, lorazepam is a good choice for long-term mood stabilization.\""}, {"id": "b", "text": "\"Lorazepam will work if you take it every day along with valproate.\""}, {"id": "c", "text": "\"You can switch to it once your lithium level reaches 1.2 mEq/L.\""}, {"id": "d", "text": "\"It is short-term, for acute agitation, not a mood stabilizer.\""}]'::jsonb, '["d"]', 'Benzodiazepines such as lorazepam are for short-term treatment of acute agitation in mania and are not long-term mood stabilizers; lithium is the gold standard mood stabilizer. None of the other statements reflects this limit.', false),
  ('bipolar', 16, 'A client with bipolar I disorder has taken quetiapine as an adjunct for acute mania for 4 months. Which ongoing assessment is the PRIORITY for the nurse because of this medication?', '[{"id": "a", "text": "Monitor for metabolic syndrome"}, {"id": "b", "text": "Serum levels 12 hours after a dose"}, {"id": "c", "text": "Liver function tests every month"}, {"id": "d", "text": "Weekly CBC for agranulocytosis"}]'::jsonb, '["a"]', 'Atypical antipsychotics such as quetiapine require monitoring for metabolic syndrome. Twelve-hour levels apply to lithium, liver function applies to valproate, and CBC for agranulocytosis applies to carbamazepine.', false),
  ('bipolar', 17, 'A client with newly diagnosed bipolar I disorder is to begin lithium. Which baseline laboratory studies would the nurse MOST expect to be ordered because of this medication?', '[{"id": "a", "text": "Liver function and a CBC"}, {"id": "b", "text": "Renal function and thyroid"}, {"id": "c", "text": "A CBC alone for agranulocytosis"}, {"id": "d", "text": "Fasting glucose and lipid levels"}]'::jsonb, '["b"]', 'Lithium requires monitoring of levels, renal function, and thyroid. Liver function and CBC are monitored with valproate, CBC alone with carbamazepine, and metabolic labs with atypical antipsychotics.', false),
  ('bipolar', 18, 'A client reports a 5-day period of elevated mood, needing little sleep, and starting several projects, which did not require hospitalization. Last year the client had a major depressive episode. The client has never had a full manic episode. Which diagnosis would the nurse MOST expect?', '[{"id": "a", "text": "Bipolar I disorder"}, {"id": "b", "text": "Cyclothymic disorder"}, {"id": "c", "text": "Bipolar II disorder"}, {"id": "d", "text": "Bipolar I with psychotic features"}]'::jsonb, '["c"]', 'Bipolar II requires at least one hypomanic episode (≥4 days) plus at least one major depressive episode with no full mania. Bipolar I requires a full manic episode (≥7 days or hospitalization), which this client has never had.', false),
  ('bipolar', 19, 'A client was hospitalized after 3 days of no sleep, grandiose plans, and reckless driving. Which statement by a nursing student requires follow-up by the nurse?', '[{"id": "a", "text": "\"Her decreased need for sleep fits the S in the DIG FAST mnemonic.\""}, {"id": "b", "text": "\"Her reckless driving reflects impulsivity and poor judgment.\""}, {"id": "c", "text": "\"Her grandiose plans reflect an inflated sense of self-esteem.\""}, {"id": "d", "text": "\"It can''t be a manic episode because it has lasted only 3 days.\""}]'::jsonb, '["d"]', 'A manic episode requires ≥7 days or any duration if hospitalized, so a 3-day episode that required hospitalization still qualifies. The other statements correctly link decreased sleep, reckless driving, and grandiosity to mania.', false),
  ('bipolar', 20, 'A client describes 3 years of frequent mood swings, with periods of feeling unusually energetic and periods of feeling low, but none has ever been severe enough to meet the criteria for mania or major depression. Which condition would the nurse MOST expect?', '[{"id": "a", "text": "Cyclothymic disorder"}, {"id": "b", "text": "Bipolar II disorder"}, {"id": "c", "text": "Bipolar I disorder"}, {"id": "d", "text": "A single manic episode"}]'::jsonb, '["a"]', 'Cyclothymic disorder is chronic, fluctuating mood with hypomanic and depressive symptoms for ≥2 years that does not meet full criteria for mania or MDD. Bipolar II requires at least one major depressive episode, which this client has never had.', false),
  ('bipolar', 21, 'A client in acute mania is admitted after not eating for 2 days. The client is climbing on the dayroom furniture and talking rapidly, and the admission search finds a belt and a razor in the client''s bag. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Offer high-calorie finger foods the patient can eat while moving"}, {"id": "b", "text": "Remove dangerous objects and monitor the patient''s behavior"}, {"id": "c", "text": "Move the patient to a quiet room with limited visitors"}, {"id": "d", "text": "Set a firm, clear limit about climbing on the furniture"}]'::jsonb, '["b"]', 'Safety comes first in mania: remove dangerous objects and monitor behavior, because impulsivity and poor judgment are safety risks. Nutrition is the second priority, followed by reducing stimulation and setting limits.', false),
  ('bipolar', 22, 'A client in acute mania has lost 2 kg this week. At each meal the client takes one bite, jumps up to talk with peers, and does not return to the table. Which intervention is BEST?', '[{"id": "a", "text": "Require the patient to stay seated until the meal is finished"}, {"id": "b", "text": "Serve three large, balanced meals in the busy dining room"}, {"id": "c", "text": "Offer high-calorie finger foods, frequent small meals"}, {"id": "d", "text": "Postpone meals until the patient is calm enough to sit"}]'::jsonb, '["c"]', 'A manic client is too busy and distracted to sit and eat and has a high metabolic demand, so high-calorie finger foods and frequent small meals are best. Requiring the client to stay seated creates a power struggle, and a busy dining room adds stimulation.', false),
  ('bipolar', 23, 'A client in acute mania is pacing and becoming louder as the evening goes on. Six family members arrive together and ask to visit in the client''s room. Which action by the nurse is BEST?', '[{"id": "a", "text": "Allow all six to visit, since family support will calm the patient"}, {"id": "b", "text": "Move the visit to the busy dayroom so staff can observe the group"}, {"id": "c", "text": "Allow the visit if the family agrees to keep the conversation light"}, {"id": "d", "text": "Limit visitors and keep the environment quiet"}]'::jsonb, '["d"]', 'Overstimulation worsens agitation in mania, so the nurse reduces stimulation with a quiet environment and limited visitors. Moving the group to a busy dayroom or allowing a large visit increases stimulation.', false),
  ('bipolar', 24, 'A client in acute mania keeps walking into other clients'' rooms and argues loudly each time staff ask him to leave. Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "Set firm, clear limits in a calm, consistent approach"}, {"id": "b", "text": "Explain in detail why the unit has rules about privacy"}, {"id": "c", "text": "Warn that he will lose all privileges if it happens again"}, {"id": "d", "text": "Let it go this time to avoid an argument with him"}]'::jsonb, '["a"]', 'Firm, clear limits delivered with a calm, consistent approach establish boundaries without a power struggle, and walking together channels energy. Threats create a power struggle, long explanations exceed the client''s concentration, and ignoring the behavior sets no limit.', false),
  ('bipolar', 25, 'A client in acute mania with flight of ideas and distractibility needs teaching about lithium before a weekend pass. Which teaching approach is BEST?', '[{"id": "a", "text": "One detailed 45-minute session covering all of the information"}, {"id": "b", "text": "Short, simple interactions in brief sessions"}, {"id": "c", "text": "A 10-page handout to read independently in the busy dayroom"}, {"id": "d", "text": "A group class with other patients going on weekend passes"}]'::jsonb, '["b"]', 'A manic client cannot concentrate on long conversations, so short, simple interactions are best. Long sessions, lengthy handouts, and group classes demand concentration and add stimulation.', false),
  ('bipolar', 26, 'A client in acute mania is receiving lithium. Over the last 24 hours the client has been pacing constantly and sweating, and the intake and output record shows an oral intake of 900 mL. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Document the intake and reassess at the end of the next shift"}, {"id": "b", "text": "Offer a high-sodium snack in place of the next lithium dose"}, {"id": "c", "text": "Restrict fluids until the patient is calm enough to sit and drink"}, {"id": "d", "text": "Report the low intake and the dehydration risk to the provider"}]'::jsonb, '["d"]', 'Pacing, sweating, and an intake far below the 2–3 L/day needed on lithium create dehydration, which raises lithium levels and toxicity risk, so the nurse reports it. Waiting a shift delays action, and restricting fluids worsens dehydration.', false),
  ('bipolar', 27, 'While the nurse is completing an admission assessment, a client in acute mania stops mid-sentence to comment on a cart rolling by, then on a phone ringing at the desk, then on a visitor''s shoes. Which DIG FAST feature BEST describes this behavior?', '[{"id": "a", "text": "Flight of ideas"}, {"id": "b", "text": "Talkativeness (pressured speech)"}, {"id": "c", "text": "Impulsivity"}, {"id": "d", "text": "Distractibility"}]'::jsonb, '["d"]', 'Shifting attention to every outside stimulus is distractibility, the D in DIG FAST. Flight of ideas refers to racing thoughts, and talkativeness refers to pressured speech, rather than attention pulled away by the environment.', false),
  ('bipolar', 28, 'A client in severe mania tells the nurse that God speaks to him through the radio and has chosen him to save the world. A nursing student says, "This means he must have schizophrenia instead of bipolar disorder." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"You''re right; hearing voices rules out a diagnosis of bipolar disorder.\""}, {"id": "b", "text": "\"Severe mania may have psychotic features, like grandiose delusions.\""}, {"id": "c", "text": "\"Psychotic features occur only in bipolar II, during hypomanic phases.\""}, {"id": "d", "text": "\"These features show that his episode is cyclothymic disorder instead.\""}]'::jsonb, '["b"]', 'Severe mania may have psychotic features such as grandiose delusions and hallucinations, so these findings do not rule out bipolar disorder. Hypomania and cyclothymic disorder are milder presentations that do not meet full criteria for mania.', false),
  ('bipolar', 29, 'A client newly started on lithium asks why blood must be drawn so often when the client feels well. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Blood work shows whether you are taking enough fluids each day.\""}, {"id": "b", "text": "\"Lithium has a narrow therapeutic range, so levels are monitored.\""}, {"id": "c", "text": "\"Lithium can damage your liver, so we must check liver function weekly.\""}, {"id": "d", "text": "\"Lithium can cause agranulocytosis, so a weekly CBC is needed.\""}]'::jsonb, '["b"]', 'Lithium has a narrow therapeutic range, so levels, renal function, and thyroid are monitored. Liver monitoring belongs with valproate, and CBC for agranulocytosis belongs with carbamazepine.', false),
  ('bipolar', 30, 'A client on lithium calls the home health nurse and says, "I''ve had diarrhea since yesterday, and now my hands are shaking." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Take your next lithium dose with food to help settle your stomach.\""}, {"id": "b", "text": "\"Drink less fluid until the diarrhea has completely stopped.\""}, {"id": "c", "text": "\"These are early signs of toxicity; you need a level drawn today.\""}, {"id": "d", "text": "\"Avoid salt for a few days until your stomach feels better.\""}]'::jsonb, '["c"]', 'Diarrhea and a coarse tremor are early signs of lithium toxicity that must be reported immediately, and diarrhea also causes dehydration. Reducing fluid or salt would further raise the lithium level.', false),
  ('bipolar', 31, 'A client in acute mania has been racing around the unit, rearranging furniture and talking over others, and says, "I have way too much energy to sit still." Which activity is BEST for this client right now?', '[{"id": "a", "text": "Leading a group discussion for the unit''s other patients"}, {"id": "b", "text": "Walking the hallway with a staff member"}, {"id": "c", "text": "Sitting quietly to read a novel for an hour"}, {"id": "d", "text": "A fast-paced team game in the crowded dayroom"}]'::jsonb, '["b"]', 'Channeling energy into activities redirects energy safely and prevents harm, and a walk with staff does so without adding stimulation. A crowded team game and leading a group increase stimulation, and reading for an hour requires concentration the client does not have.', false),
  ('bipolar', 32, 'The nurse has removed dangerous objects from the room of a client in acute mania and has arranged close monitoring of the client''s behavior. Which intervention is the HIGHEST priority NEXT?', '[{"id": "a", "text": "Ensure nutrition and hydration"}, {"id": "b", "text": "Set firm, clear limits on behavior"}, {"id": "c", "text": "Channel energy into activities"}, {"id": "d", "text": "Reduce stimulation on the unit"}]'::jsonb, '["a"]', 'After safety, the next priority in mania is nutrition and hydration, because the client is too busy to eat and has a high metabolic demand. Reducing stimulation, setting limits, and channeling energy follow in that order.', false),
  ('bipolar', 33, 'A client in acute mania undresses in the dayroom and makes sexual comments to other clients. Which action by the nurse is BEST?', '[{"id": "a", "text": "Ignore the behavior so that it is not reinforced by attention"}, {"id": "b", "text": "Calmly set firm, clear limits and escort the patient out"}, {"id": "c", "text": "Discuss the reasons behind the behavior in a long conversation"}, {"id": "d", "text": "Ask the other patients to tell the patient how they feel about it"}]'::jsonb, '["b"]', 'Hypersexuality is a manic behavior, and a firm, clear limit set with a calm, consistent approach establishes boundaries without a power struggle while protecting others. Long conversations exceed the client''s concentration, and ignoring the behavior leaves others at risk.', false),
  ('bipolar', 34, 'A client with bipolar disorder takes valproate (Depakote). Which laboratory results should the nurse review MOST closely at each follow-up visit?', '[{"id": "a", "text": "Renal function and thyroid"}, {"id": "b", "text": "Lithium level 12 hours after a dose"}, {"id": "c", "text": "Fasting glucose and lipid profile"}, {"id": "d", "text": "Liver function and CBC"}]'::jsonb, '["d"]', 'Valproate requires monitoring of liver function and CBC. Renal function, thyroid, and 12-hour levels apply to lithium, and glucose and lipids are monitored for metabolic syndrome with atypical antipsychotics.', false),
  ('bipolar', 35, 'A client in acute mania slept 2 hours last night and tells the nurse, "I feel totally rested and ready to go; sleep is a waste of time." Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Accept the report, since the patient feels rested and is not tired"}, {"id": "b", "text": "Encourage the patient to use the extra hours for group activities"}, {"id": "c", "text": "Monitor sleep, because sleep deprivation worsens mania"}, {"id": "d", "text": "Wake the patient during the night for a long talk about feelings"}]'::jsonb, '["c"]', 'Decreased need for sleep (feeling rested after 2–3 hours) is a manic feature, and sleep deprivation worsens mania, so the nurse monitors sleep. Feeling rested does not make the short sleep harmless, and extra activity or long talks increase stimulation.', false),
  ('bipolar', 36, 'The nurse is reviewing the history of a client who takes lithium. Which findings increase this client''s risk for lithium toxicity? Select all that apply.', '[{"id": "a", "text": "Takes NSAIDs with lithium"}, {"id": "b", "text": "Drinks 2 to 3 L of fluid per day"}, {"id": "c", "text": "Takes thiazide diuretics"}, {"id": "d", "text": "Follows a low sodium diet"}, {"id": "e", "text": "Vomiting for 3 days this week"}]'::jsonb, '["a", "c", "d", "e"]', 'NSAIDs and thiazide diuretics raise lithium levels; a low sodium diet increases lithium reabsorption by the kidneys; and vomiting causes dehydration and toxicity risk. Drinking 2–3 L/day is the adequate fluid intake the client is taught to maintain.', true),
  ('bipolar', 37, 'The nurse is teaching a client who is being discharged on lithium. Which client statements indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"I''ll take my lithium with food to reduce GI upset.\""}, {"id": "b", "text": "\"If I feel sick to my stomach, I''ll stop it for a few days.\""}, {"id": "c", "text": "\"My blood levels are drawn 12 hours after my last dose.\""}, {"id": "d", "text": "\"I need adequate fluid, 2 to 3 L/day.\""}, {"id": "e", "text": "\"I''ll take my dose right before my blood is drawn.\""}]'::jsonb, '["a", "c", "d"]', 'Lithium is taken with food to reduce GI upset, levels are drawn 12 hours after the last dose, and adequate fluid of 2–3 L/day is essential. Stopping lithium abruptly risks rebound mania, and taking the dose right before the draw would not give a level 12 hours after the last dose.', true),
  ('bipolar', 38, 'A client''s serum lithium level is 2.2 mEq/L. Which findings would the nurse expect at this level? Select all that apply.', '[{"id": "a", "text": "Ataxia"}, {"id": "b", "text": "Seizures"}, {"id": "c", "text": "Tinnitus"}, {"id": "d", "text": "Coma"}, {"id": "e", "text": "Blurred vision"}]'::jsonb, '["a", "c", "e"]', 'A level of 2.2 mEq/L is moderate toxicity (2.0–2.5 mEq/L), which causes ataxia, blurred vision, tinnitus, and slurred speech. Seizures and coma are features of severe toxicity above 2.5 mEq/L.', true),
  ('bipolar', 39, 'A client in acute mania has been admitted to the inpatient unit. Which interventions should the nurse include in the plan of care? Select all that apply.', '[{"id": "a", "text": "Quiet environment, limited visitors"}, {"id": "b", "text": "Short, simple interactions"}, {"id": "c", "text": "Long talks to explore the patient''s feelings"}, {"id": "d", "text": "Set firm, clear limits"}, {"id": "e", "text": "Channel energy into activities"}]'::jsonb, '["a", "b", "d", "e"]', 'A quiet environment with limited visitors reduces stimulation, short and simple interactions fit the client''s poor concentration, firm and clear limits establish boundaries, and channeling energy into activities redirects energy safely. Long conversations are not appropriate because the client cannot concentrate on them.', true),
  ('bipolar', 40, 'The nurse reviews the psychiatric history of a client being evaluated for bipolar II disorder. Which findings are consistent with this diagnosis? Select all that apply.', '[{"id": "a", "text": "A manic episode that lasted 8 days"}, {"id": "b", "text": "A hypomanic episode lasting 5 days"}, {"id": "c", "text": "Hospitalization for a manic episode"}, {"id": "d", "text": "At least one major depressive episode"}, {"id": "e", "text": "Subsyndromal cycling for 3 years"}]'::jsonb, '["b", "d"]', 'Bipolar II requires at least one hypomanic episode (≥4 days) plus at least one major depressive episode with NO full mania. A manic episode of ≥7 days or one requiring hospitalization indicates bipolar I, and subsyndromal cycling for ≥2 years describes cyclothymic disorder.', true),
  ('bipolar', 41, 'A 30-year-old client with bipolar disorder is starting valproate (Depakote). Which client statements indicate understanding of the teaching? Select all that apply.', '[{"id": "a", "text": "\"I''ll need my thyroid checked because of this drug.\""}, {"id": "b", "text": "\"I''ll need liver function and CBC tests while on it.\""}, {"id": "c", "text": "\"This medicine should help me lose some weight.\""}, {"id": "d", "text": "\"It is teratogenic and can cause neural tube defects.\""}, {"id": "e", "text": "\"My levels are drawn 12 hours after my last dose.\""}]'::jsonb, '["b", "d"]', 'Valproate requires liver function and CBC monitoring and is teratogenic (neural tube defects). Thyroid monitoring and 12-hour levels are lithium teaching, and valproate causes weight gain rather than weight loss.', true),
  ('bipolar', 42, 'The charge nurse reviews monitoring plans for clients on different medications for bipolar disorder. Which medication–monitoring pairs are correct? Select all that apply.', '[{"id": "a", "text": "Lithium — renal function and thyroid"}, {"id": "b", "text": "Valproate — thyroid function only"}, {"id": "c", "text": "Carbamazepine — CBC (agranulocytosis)"}, {"id": "d", "text": "Olanzapine — metabolic syndrome"}, {"id": "e", "text": "Valproate — liver function and CBC"}]'::jsonb, '["a", "c", "d", "e"]', 'Lithium requires monitoring of levels, renal function, and thyroid; carbamazepine requires CBC for agranulocytosis; atypical antipsychotics such as olanzapine require monitoring for metabolic syndrome; and valproate requires liver function and CBC. Thyroid monitoring alone is not the valproate plan.', true),
  ('bipolar', 43, 'The nurse is caring for a client in acute mania who takes lithium. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Lithium level of 2.1 mEq/L with slurred speech"}, {"id": "b", "text": "Pressured speech when describing grand plans"}, {"id": "c", "text": "Dangerous objects in the patient''s belongings"}, {"id": "d", "text": "Oral intake of 800 mL in 24 hours with sweating"}, {"id": "e", "text": "Grandiose statements about owning a company"}]'::jsonb, '["a", "c", "d"]', 'A level of 2.1 mEq/L with slurred speech is moderate toxicity; a razor is a dangerous object that must be removed because impulsivity and poor judgment are safety risks; and very low intake with sweating causes dehydration and toxicity risk. Pressured speech and grandiosity are expected manic features (DIG FAST).', true),
  ('bipolar', 44, 'A client''s history is reviewed to confirm a diagnosis of bipolar I disorder. Which findings would establish this diagnosis? Select all that apply.', '[{"id": "a", "text": "A hypomanic episode lasting 4 days"}, {"id": "b", "text": "A manic episode lasting 9 days"}, {"id": "c", "text": "Two years of subsyndromal cycling"}, {"id": "d", "text": "Mania lasting 3 days that required hospitalization"}, {"id": "e", "text": "A major depressive episode with no mania"}]'::jsonb, '["b", "d"]', 'Bipolar I requires at least one full manic episode lasting ≥7 days or any duration if hospitalized; depressive episodes are common but not required. A hypomanic episode alone does not establish bipolar I, two years of subsyndromal cycling is cyclothymic disorder, and depression without mania does not meet bipolar I criteria.', true),
  ('bipolar', 45, 'A client is admitted in acute mania and has been extremely agitated. The nurse reviews the medication orders. Which medications would the nurse expect as appropriate for this phase? Select all that apply.', '[{"id": "a", "text": "Lithium as a mood stabilizer"}, {"id": "b", "text": "Lorazepam IM for acute agitation"}, {"id": "c", "text": "Lorazepam as a long-term mood stabilizer"}, {"id": "d", "text": "Olanzapine for acute mania"}, {"id": "e", "text": "Valproate for a patient who is pregnant"}]'::jsonb, '["a", "b", "d"]', 'Lithium is the gold standard mood stabilizer, lorazepam IM treats acute agitation in mania, and atypical antipsychotics such as olanzapine treat acute mania. Lorazepam is not a long-term mood stabilizer, and valproate is teratogenic (neural tube defects).', true),
  ('bipolar', 46, 'The nurse reviews discharge teaching with a client who will continue lithium at home. Which client statements indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "\"I''ll stop lithium once my mood has been stable.\""}, {"id": "b", "text": "\"I can take NSAIDs with lithium for headaches.\""}, {"id": "c", "text": "\"I''ll take my lithium with food to reduce GI upset.\""}, {"id": "d", "text": "\"I''ll take my morning dose right before my blood draw.\""}, {"id": "e", "text": "\"With heavy sweating, I''ll follow a low sodium diet.\""}]'::jsonb, '["a", "b", "d", "e"]', 'Stopping lithium abruptly causes rebound mania; NSAIDs raise lithium levels; levels must be drawn 12 hours after the last dose; and reducing salt after sweating increases lithium reabsorption and toxicity risk. Taking lithium with food to reduce GI upset is correct.', true),
  ('bipolar', 47, 'The nurse reviews serum lithium levels for several clients. Which results are within the therapeutic range for that client''s phase of treatment? Select all that apply.', '[{"id": "a", "text": "Acute mania: 1.3 mEq/L"}, {"id": "b", "text": "Maintenance: 0.7 mEq/L"}, {"id": "c", "text": "Maintenance: 1.4 mEq/L"}, {"id": "d", "text": "Acute mania: 0.6 mEq/L"}, {"id": "e", "text": "Maintenance: 1.0 mEq/L"}]'::jsonb, '["a", "b", "e"]', 'The acute mania range is 0.8–1.4 mEq/L, so 1.3 is therapeutic, and the maintenance range is 0.6–1.2 mEq/L, so 0.7 and 1.0 are therapeutic. A maintenance level of 1.4 is above the 1.2 maintenance limit, and an acute level of 0.6 is below the 0.8 acute minimum.', true),
  ('bipolar', 48, 'A client in acute mania on lithium paces constantly, takes only a few bites at meals, and drinks little. Which nursing actions are appropriate to meet nutrition and hydration needs? Select all that apply.', '[{"id": "a", "text": "High-calorie finger foods"}, {"id": "b", "text": "Restrict fluids to reduce trips to the bathroom"}, {"id": "c", "text": "Three large meals at set times in the dining room"}, {"id": "d", "text": "Monitor sleep and I&O"}, {"id": "e", "text": "A low-sodium diet to prevent fluid retention"}]'::jsonb, '["a", "d"]', 'High-calorie finger foods suit a client too busy to sit and eat, and monitoring I&O addresses dehydration risk. Restricting fluids or sodium increases lithium reabsorption and toxicity, and large meals in a busy dining room do not meet the client''s needs.', true),
  ('bipolar', 49, 'The nurse teaches a client on lithium which symptoms are early signs of toxicity that must be reported immediately. Which symptoms should the nurse include? Select all that apply.', '[{"id": "a", "text": "Coarse tremor"}, {"id": "b", "text": "Weight gain"}, {"id": "c", "text": "Tinnitus"}, {"id": "d", "text": "N/V/D"}, {"id": "e", "text": "Coma"}]'::jsonb, '["a", "d"]', 'Coarse tremor and N/V/D are early signs of lithium toxicity that the client must report immediately. Tinnitus is a moderate-toxicity finding, coma is a severe-toxicity finding, and weight gain is listed for valproate.', true),
  ('bipolar', 50, 'A client with bipolar disorder who takes several other medications is started on carbamazepine (Tegretol). Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Draw levels 12 hours after each dose"}, {"id": "b", "text": "Monitor the CBC for agranulocytosis"}, {"id": "c", "text": "Review all medications for interactions"}, {"id": "d", "text": "Teach a low sodium diet"}, {"id": "e", "text": "Note that it induces CYP450"}]'::jsonb, '["b", "c", "e"]', 'Carbamazepine requires CBC monitoring for agranulocytosis, has many drug interactions, and induces CYP450, so the full medication list must be reviewed. Twelve-hour levels apply to lithium, and a low sodium diet is not part of carbamazepine care.', true),
  ('schizophrenia', 1, 'A client admitted with schizophrenia has been quietly hearing voices that call him worthless. During evening rounds he says, "Now they''re telling me to cut my arms before the night shift comes." Which action should the nurse take FIRST?', '[{"id": "a", "text": "Initiate safety protocols, increase the monitoring level, and notify the provider"}, {"id": "b", "text": "Engage the patient in a simple, grounding activity such as sorting cards at the table"}, {"id": "c", "text": "Say, \"I don''t hear the voices, but I can see that they are frightening you tonight.\""}, {"id": "d", "text": "Give the scheduled evening antipsychotic dose and then reassess the voices in an hour"}]'::jsonb, '["a"]', 'Voices commanding the client to hurt himself are a safety emergency, so safety protocols, a higher monitoring level, and provider notification come first. Acknowledging the voices and grounding activities are appropriate for routine hallucinations but do not address the command to self-harm.', false),
  ('schizophrenia', 2, 'A client with schizophrenia sits rigidly in the dayroom staring at the corner and whispering. When the nurse approaches, the client asks, "Do you hear the man telling me I can''t leave this room?" Which response by the nurse is MOST therapeutic?', '[{"id": "a", "text": "\"There is no man talking to you; it''s only your illness playing tricks on your mind.\""}, {"id": "b", "text": "\"Tell the man that you are safe here and that he has no right to keep you in this room.\""}, {"id": "c", "text": "\"I don''t hear a voice, but I can see that what you hear is frightening you.\""}, {"id": "d", "text": "\"Let''s sit together quietly and wait to see whether the man says anything else to us.\""}]'::jsonb, '["c"]', 'The nurse acknowledges the client''s experience without denying it and without validating the voice as real. Telling the client there is no man denies the experience, while talking back to the voice or waiting for it to speak plays along with the hallucination.', false),
  ('schizophrenia', 3, 'The nurse reviews shift documentation for a 24-year-old client with schizophrenia. Which entries should the nurse identify as negative symptoms? Select all that apply.', '[{"id": "a", "text": "Fixed, false belief that the news sends him secret messages"}, {"id": "b", "text": "Brief, empty replies when asked about his weekend plans"}, {"id": "c", "text": "Inability to initiate goal-directed activity such as showering"}, {"id": "d", "text": "Repeats words or phrases spoken by the nurse during rounds"}, {"id": "e", "text": "Inability to experience pleasure, even from his favorite music"}]'::jsonb, '["b", "c", "e"]', 'Brief, empty replies are alogia (poverty of speech); being unable to start showering is avolition (inability to initiate goal-directed activity); no pleasure even from music is anhedonia — all negative symptoms. A fixed, false belief is a delusion, and repeating the nurse''s words is echolalia, a disorganized-speech finding; both are positive symptoms.', true),
  ('schizophrenia', 4, 'When the nurse asks a client with schizophrenia, "How has your mood been today?" the client answers, "My mood is like the weather, and the weather on Jupiter has huge storms, and Jupiter has dozens of moons that circle it…" and continues without returning to the question. Which documentation by the nurse is MOST accurate?', '[{"id": "a", "text": "Loose associations"}, {"id": "b", "text": "Tangentiality"}, {"id": "c", "text": "Clang associations"}, {"id": "d", "text": "Word salad"}]'::jsonb, '["b"]', 'Tangentiality is a response that starts on topic but drifts away and never returns, as when a client asked about mood rambles about planets. Loose associations are ideas that shift with no clear connection and are not anchored to a question that was asked.', false),
  ('schizophrenia', 5, 'A client with schizophrenia has refused three meal trays, telling the nurse, "The kitchen staff are putting poison in my food so I''ll stay quiet." Which intervention is BEST for meeting this client''s nutritional needs?', '[{"id": "a", "text": "Taste a bite of the food in front of the patient to prove the tray is safe"}, {"id": "b", "text": "Explain that the hospital kitchen follows strict rules that keep food safe"}, {"id": "c", "text": "Ask the provider for a supplement drink to be mixed into each meal tray"}, {"id": "d", "text": "Offer sealed packaged foods or allow the patient to open their own food"}]'::jsonb, '["d"]', 'When a delusion involves refusing food because it is poisoned, the nurse offers sealed packaged foods or lets the client open their own food. Tasting the food or explaining kitchen rules argues with the delusion, which the nurse should not do.', false),
  ('schizophrenia', 6, 'A client with paranoid schizophrenia backs away from the nurse and says, "The FBI put a chip in my tooth to track me, and you''re working with them, aren''t you?" Which response by the nurse is MOST therapeutic?', '[{"id": "a", "text": "\"There''s no chip in your tooth; a dentist would have seen it on your last x-ray.\""}, {"id": "b", "text": "\"I can see you feel frightened. I''m here to help keep you safe.\""}, {"id": "c", "text": "\"If they are tracking you, I can move you to a room away from the windows.\""}, {"id": "d", "text": "\"How do you think the FBI was able to put a chip into your tooth?\""}]'::jsonb, '["b"]', 'The nurse acknowledges the feeling behind the delusion without arguing with or reinforcing it. Pointing to the x-ray argues with the delusion, and moving rooms or exploring how the chip was placed reinforces the paranoid belief.', false),
  ('schizophrenia', 7, 'The nurse is caring for several clients on an acute psychiatric unit. Which findings should the nurse document as positive symptoms of schizophrenia? Select all that apply.', '[{"id": "a", "text": "Says \"cat blue shoe running democracy morning\" when asked about lunch"}, {"id": "b", "text": "Shows diminished emotional expression when told his mother will visit"}, {"id": "c", "text": "Spends the day alone in his room and has reduced social interaction"}, {"id": "d", "text": "Misinterpretation of real stimuli: a coat on the door seen as a man"}, {"id": "e", "text": "Lacks motivation and cannot initiate getting dressed for breakfast"}]'::jsonb, '["a", "d"]', 'An incoherent mix of words is word salad (disorganized speech), and misinterpreting a real coat as a man is an illusion — both positive symptoms (excess/distortion). Diminished emotional expression is flat affect, reduced social interaction is asociality, and inability to initiate activity is avolition — all negative symptoms.', true),
  ('schizophrenia', 8, 'The nurse has just acknowledged the fear of a client who believes the hospital television is recording her for a government agency. The client is still tense and repeating the belief. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Turn the television around to show the patient that no camera is attached"}, {"id": "b", "text": "Ask the patient to describe which agency is recording her and the reason"}, {"id": "c", "text": "Redirect the patient to a different topic or activity on the unit"}, {"id": "d", "text": "Redirect to reality by explaining a television cannot record anyone"}]'::jsonb, '["c"]', 'After acknowledging the feeling, the nurse redirects the client to a different topic or activity. Explaining why the television cannot record (even when framed as redirecting to reality) argues with the delusion, while inspecting the television or exploring details about the agency plays along with it.', false),
  ('schizophrenia', 9, 'A client with schizophrenia has taken haloperidol for 6 months. The voices have stopped, but he still shows flat affect, avolition, and asociality, and his family asks whether a medication change might help. Which change would the nurse expect to be MOST likely to target these remaining symptoms?', '[{"id": "a", "text": "Risperidone in place of haloperidol"}, {"id": "b", "text": "Chlorpromazine in place of haloperidol"}, {"id": "c", "text": "Benztropine added to the haloperidol"}, {"id": "d", "text": "Fluphenazine in place of haloperidol"}]'::jsonb, '["a"]', 'The remaining symptoms are negative symptoms, which respond better to atypical antipsychotics such as risperidone. Chlorpromazine and fluphenazine are typical antipsychotics like haloperidol, with limited effect on negative symptoms; benztropine treats pseudoparkinsonism.', false),
  ('schizophrenia', 10, 'A client with schizophrenia has been readmitted for the fourth time this year. Each time, the voices returned within weeks after he stopped taking his oral medication at home. Which option is MOST appropriate for the nurse to discuss with the provider?', '[{"id": "a", "text": "Clozapine with weekly white blood cell monitoring"}, {"id": "b", "text": "Benztropine added to the current oral regimen"}, {"id": "c", "text": "Valbenazine (Ingrezza) at the time of discharge"}, {"id": "d", "text": "Haloperidol IM depot (long-acting)"}]'::jsonb, '["d"]', 'The client relapses because he stops oral medication, and haloperidol is available as a long-acting IM depot that is good for non-compliant patients. Clozapine is reserved for treatment-resistant schizophrenia, which this client''s quick response to medication does not show.', false),
  ('schizophrenia', 11, 'A client with schizophrenia that has not improved with two other antipsychotics is started on clozapine. Which client statements indicate understanding of the teaching? Select all that apply.', '[{"id": "a", "text": "\"Since this is a newer medicine, I don''t need to watch my weight or sugar.\""}, {"id": "b", "text": "\"It is the most effective drug for treatment-resistant schizophrenia.\""}, {"id": "c", "text": "\"This drug carries the same high risk of EPS that my haloperidol did.\""}, {"id": "d", "text": "\"I need weekly WBC monitoring because of the agranulocytosis risk.\""}, {"id": "e", "text": "\"I''ll take benztropine each day so I don''t develop agranulocytosis.\""}]'::jsonb, '["b", "d"]', 'Clozapine is the most effective drug for treatment-resistant schizophrenia and carries a risk of agranulocytosis requiring weekly WBC monitoring. As an atypical antipsychotic it has a higher risk of metabolic syndrome (weight gain, diabetes), so weight and sugar still matter, and it has a lower risk of EPS than haloperidol. Benztropine is an anticholinergic for EPS and does not prevent agranulocytosis.', true),
  ('schizophrenia', 12, 'A client on haloperidol has been pacing the hallway for hours and tells the nurse, "I can''t sit still no matter how hard I try; I have to keep moving." The client denies hearing voices. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Worsening positive symptoms that call for an extra antipsychotic dose"}, {"id": "b", "text": "Pseudoparkinsonism that should be treated with an anticholinergic"}, {"id": "c", "text": "Akathisia, an extrapyramidal side effect of the antipsychotic"}, {"id": "d", "text": "Early tardive dyskinesia that is likely to become irreversible"}]'::jsonb, '["c"]', 'Restlessness, inability to sit still, and pacing are the features of akathisia, an EPS of typical antipsychotics such as haloperidol. Pseudoparkinsonism instead shows tremor at rest, rigidity, bradykinesia, and shuffling gait, and giving more antipsychotic would not treat an adverse effect.', false),
  ('schizophrenia', 13, 'Four hours after a first IM dose of haloperidol, a 20-year-old client cries out as his neck twists sharply to one side, his eyes roll upward and stay fixed, and his tongue spasms. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Give benztropine or diphenhydramine IM"}, {"id": "b", "text": "Complete an AIMS assessment of the movements"}, {"id": "c", "text": "Give oral propranolol and recheck in 30 minutes"}, {"id": "d", "text": "Hold the next dose and report it at shift change"}]'::jsonb, '["a"]', 'Sudden severe spasms of the neck, eyes (oculogyric crisis), and tongue are acute dystonia, which is treated with benztropine or diphenhydramine IM immediately. Propranolol treats akathisia, and the AIMS assesses tardive dyskinesia.', false),
  ('schizophrenia', 14, 'During a routine AIMS assessment, the nurse notes new lip smacking and tongue protrusion in a client who has taken fluphenazine for 9 years. Which actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Give the PRN benztropine to reduce the involuntary movements"}, {"id": "b", "text": "Report the involuntary movements to the provider immediately"}, {"id": "c", "text": "Anticipate an order to reduce or stop the antipsychotic"}, {"id": "d", "text": "Reassure the patient that the movements will go away within days"}, {"id": "e", "text": "Anticipate a prescription for valbenazine (Ingrezza)"}]'::jsonb, '["b", "c", "e"]', 'Lip smacking and tongue protrusion after years of a typical antipsychotic indicate tardive dyskinesia, which must be reported immediately; treatment is to reduce/stop the antipsychotic and possibly valbenazine. Anticholinergics such as benztropine worsen TD, and TD is potentially irreversible, so promising that the movements will go away is false reassurance.', true),
  ('schizophrenia', 15, 'A client who has taken haloperidol for 12 years now has facial grimacing, lip smacking, and writhing choreoathetoid movements of the hands. Which new prescription requires follow-up before the nurse gives it?', '[{"id": "a", "text": "Valbenazine (Ingrezza) once daily"}, {"id": "b", "text": "Reduce the haloperidol dose by half"}, {"id": "c", "text": "AIMS assessment at regular intervals"}, {"id": "d", "text": "Benztropine (anticholinergic) PRN"}]'::jsonb, '["d"]', 'These late-onset involuntary movements are tardive dyskinesia, and anticholinergics such as benztropine worsen TD, so this order needs clarification. Valbenazine, reducing the antipsychotic, and regular AIMS assessment are all consistent with TD care.', false),
  ('schizophrenia', 16, 'A client who has taken haloperidol for 3 years is newly confused and diaphoretic. Vital signs: temperature 40.4°C (104.7°F), heart rate 128/min, blood pressure 174/98 mm Hg. The arms show severe "lead pipe" rigidity. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Administer the PRN benztropine IM for the rigidity"}, {"id": "b", "text": "Stop the antipsychotic and notify the provider now"}, {"id": "c", "text": "Give the scheduled haloperidol dose for confusion"}, {"id": "d", "text": "Perform an AIMS assessment to rate the rigidity"}]'::jsonb, '["b"]', 'Fever above 40°C, encephalopathy, unstable vitals, and lead-pipe rigidity point to neuroleptic malignant syndrome, which can occur even after years of use and requires stopping the antipsychotic immediately. Benztropine treats acute dystonia and pseudoparkinsonism, not NMS.', false),
  ('schizophrenia', 17, 'A client receiving both an antipsychotic and a serotonergic drug develops fever and muscle stiffness. Which findings would MOST strongly support neuroleptic malignant syndrome (NMS) rather than serotonin syndrome? Select all that apply.', '[{"id": "a", "text": "Develops slowly over days–weeks"}, {"id": "b", "text": "Clonus and hyperreflexia on exam"}, {"id": "c", "text": "Severe \"lead pipe\" rigidity"}, {"id": "d", "text": "Bradyreflexia on exam"}, {"id": "e", "text": "Agitation within a few hours"}]'::jsonb, '["a", "c", "d"]', 'NMS develops slowly (days–weeks) with lead-pipe rigidity and bradyreflexia. Clonus/hyperreflexia, rapid development within hours, and more agitation point to serotonin syndrome instead.', true),
  ('schizophrenia', 18, 'A client taking chlorpromazine has a temperature of 40.6°C (105°F), confusion, tachycardia, and severe muscle rigidity. The provider suspects neuroleptic malignant syndrome. Which laboratory result would the nurse MOST expect to support this suspicion?', '[{"id": "a", "text": "Decreased white blood cell count"}, {"id": "b", "text": "Elevated fasting lipid levels"}, {"id": "c", "text": "Elevated CK (creatine kinase)"}, {"id": "d", "text": "Elevated fasting blood glucose"}]'::jsonb, '["c"]', 'In NMS, creatine kinase is elevated from muscle breakdown. A low WBC count reflects clozapine-related agranulocytosis, and high lipids or glucose reflect the metabolic syndrome seen with atypical antipsychotics.', false),
  ('schizophrenia', 19, 'The nurse is preparing the plan of care for a client diagnosed with neuroleptic malignant syndrome after starting haloperidol. Which interventions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Stop the antipsychotic immediately"}, {"id": "b", "text": "Give benztropine IM for the rigidity"}, {"id": "c", "text": "Dantrolene (muscle relaxant)"}, {"id": "d", "text": "Bromocriptine (dopamine agonist)"}, {"id": "e", "text": "Supportive care"}]'::jsonb, '["a", "c", "d", "e"]', 'NMS treatment is to stop the antipsychotic immediately, provide supportive care, and give dantrolene (muscle relaxant) and bromocriptine (dopamine agonist). Benztropine IM is the immediate treatment for acute dystonia, not NMS.', true),
  ('schizophrenia', 20, 'A client with schizophrenia has taken olanzapine for 6 months and has gained 7 kg. Which problems should the nurse monitor for because of this medication''s adverse effect profile? Select all that apply.', '[{"id": "a", "text": "Agranulocytosis on a weekly WBC"}, {"id": "b", "text": "Continued weight gain"}, {"id": "c", "text": "Diabetes"}, {"id": "d", "text": "Elevated CK each week"}, {"id": "e", "text": "Dyslipidemia"}]'::jsonb, '["b", "c", "e"]', 'Atypical antipsychotics such as olanzapine carry a higher risk of metabolic syndrome — weight gain, diabetes, and dyslipidemia. Weekly WBC monitoring for agranulocytosis is required for clozapine, and an elevated CK is the marker of muscle breakdown in NMS, not routine monitoring.', true),
  ('schizophrenia', 21, 'The nurse receives report on four clients with schizophrenia. Which client should the nurse see FIRST?', '[{"id": "a", "text": "A patient on risperidone who has gained 3 kg since admission last month"}, {"id": "b", "text": "A patient on olanzapine who answers every question with one empty word"}, {"id": "c", "text": "A patient on haloperidol who paces and says he cannot sit still in group"}, {"id": "d", "text": "A patient on fluphenazine for 5 years with new confusion and rigidity"}]'::jsonb, '["d"]', 'New confusion and rigidity in a client on a typical antipsychotic, even after years of use, suggests neuroleptic malignant syndrome, a life-threatening emergency. Weight gain, alogia, and akathisia need attention but are not life-threatening.', false),
  ('schizophrenia', 22, 'The parents of a 19-year-old recently diagnosed with schizophrenia attend a family teaching session. Which statement by a parent indicates understanding of the illness?', '[{"id": "a", "text": "\"It is a chronic illness that requires lifelong treatment.\""}, {"id": "b", "text": "\"Because he is male, his symptoms began later than they would in a girl.\""}, {"id": "c", "text": "\"Once the voices stop, he can taper off his medicine and stay well.\""}, {"id": "d", "text": "\"Developing this after age 15 is very rare, so it must be something else.\""}]'::jsonb, '["a"]', 'Schizophrenia is a severe, chronic illness that requires lifelong treatment. Males have an earlier onset than females, and onset typically occurs from the late teens to the early 30s, so his age fits the usual pattern.', false),
  ('schizophrenia', 23, 'The nurse reviews teaching with the family of a client with schizophrenia. Which statements by family members indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"The most common hallucination in schizophrenia is auditory.\""}, {"id": "b", "text": "\"Haloperidol IM depot (long-acting) can help if he stops his pills.\""}, {"id": "c", "text": "\"His withdrawal should respond better to haloperidol than newer drugs.\""}, {"id": "d", "text": "\"Paranoid delusions are the most common kind of delusions.\""}, {"id": "e", "text": "\"Negative symptoms respond better to atypical antipsychotics.\""}]'::jsonb, '["a", "b", "d", "e"]', 'Auditory hallucinations are the most common type, paranoid delusions are the most common delusions, haloperidol is available as a long-acting IM depot for non-compliant patients, and negative symptoms respond better to atypical antipsychotics. Withdrawal (asociality) is a negative symptom on which a typical antipsychotic like haloperidol has limited effect.', true),
  ('schizophrenia', 24, 'A client with schizophrenia is actively hallucinating and keeps turning to answer someone the nurse cannot see. Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Tell the patient firmly that the voices are not real and should be ignored"}, {"id": "b", "text": "Answer the voices along with the patient to build trust and rapport"}, {"id": "c", "text": "Acknowledge the patient''s experience without saying the voices are real"}, {"id": "d", "text": "Engage the patient in simple, grounding activities to redirect to reality"}, {"id": "e", "text": "Present evidence that no one else on the unit can hear the voices"}]'::jsonb, '["c", "d"]', 'The nurse acknowledges the client''s experience and redirects to reality through simple, grounding activities. Telling the client the voices are not real or presenting evidence denies the experience, and answering the voices plays along and validates the hallucination as real.', true),
  ('schizophrenia', 25, 'A client with schizophrenia believes the neighbors are spying on him through the television in his room. Which action by a newly hired nurse requires IMMEDIATE correction by the charge nurse?', '[{"id": "a", "text": "Saying, \"I can see you feel frightened, and I''m here to keep you safe.\""}, {"id": "b", "text": "Unplugging the television and checking it for cameras with the patient"}, {"id": "c", "text": "Inviting the patient to help set up a card game in the dayroom"}, {"id": "d", "text": "Avoiding a debate with the patient about whether the spying is real"}]'::jsonb, '["b"]', 'Checking the television for cameras plays along with and reinforces the paranoid belief, which the nurse must never do. Acknowledging the fear, redirecting to an activity, and not arguing are all correct responses to a delusion.', false),
  ('schizophrenia', 26, 'The nurse is caring for four clients with schizophrenia who are starting haloperidol. For which client is this medication MOST likely to produce clear improvement in the presenting symptoms?', '[{"id": "a", "text": "A patient with alogia who gives brief, empty answers"}, {"id": "b", "text": "A patient with anhedonia who enjoys no activities"}, {"id": "c", "text": "A patient with hallucinations and paranoid delusions"}, {"id": "d", "text": "A patient with avolition who cannot begin any task"}]'::jsonb, '["c"]', 'Typical antipsychotics such as haloperidol are effective for positive symptoms like hallucinations and paranoid delusions but have limited effect on negative symptoms. Alogia, anhedonia, and avolition are negative symptoms.', false),
  ('schizophrenia', 27, 'At dusk, a client with schizophrenia points at a bathrobe hanging on the back of the door and says, "There''s a man standing there watching me." When the light is turned on, the client says, "Oh, it''s only my robe." Which documentation by the nurse is MOST accurate?', '[{"id": "a", "text": "Illusions"}, {"id": "b", "text": "Visual hallucinations"}, {"id": "c", "text": "Paranoid delusions"}, {"id": "d", "text": "Neologisms"}]'::jsonb, '["a"]', 'An illusion is a misinterpretation of a real stimulus — here, a real robe seen as a man. A hallucination is a false sensory perception with no real stimulus, and a delusion is a fixed, false belief that would not be corrected by turning on the light.', false),
  ('schizophrenia', 28, 'When asked what she would like for lunch, a client with schizophrenia replies, "Window purple fork singing government Tuesday," and then looks at the nurse expectantly. Which documentation of this speech is MOST accurate?', '[{"id": "a", "text": "Clang associations"}, {"id": "b", "text": "Tangentiality"}, {"id": "c", "text": "Loose associations"}, {"id": "d", "text": "Word salad"}]'::jsonb, '["d"]', 'Word salad is a completely incoherent mix of words and phrases with no structure at all. Loose associations still form connected sentences whose ideas shift without a clear link, and clang associations are rhyming speech.', false),
  ('schizophrenia', 29, 'The spouse of a client who received a first dose of haloperidol IM this morning calls the nurse because the client''s eyes are rolled upward and the neck is twisted. The spouse asks, "Is this that tardive dyskinesia I read about?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"This is acute dystonia; it is treated with benztropine IM immediately.\""}, {"id": "b", "text": "\"Yes, this is tardive dyskinesia, and the movements may be permanent now.\""}, {"id": "c", "text": "\"This is akathisia, which is treated with propranolol or a lower dose.\""}, {"id": "d", "text": "\"This is neuroleptic malignant syndrome, so the haloperidol will stop.\""}]'::jsonb, '["a"]', 'Sudden, severe muscle spasms of the neck and eyes (oculogyric crisis) soon after starting an antipsychotic are acute dystonia, treated immediately with benztropine or diphenhydramine IM. Tardive dyskinesia is a late-onset problem of involuntary movements such as lip smacking, not a sudden spasm after a first dose.', false),
  ('schizophrenia', 30, 'A client with schizophrenia asks why her new medication, risperidone, has helped both her voices and her lack of motivation when haloperidol only helped the voices. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Risperidone blocks D2 dopamine receptors more strongly than haloperidol.\""}, {"id": "b", "text": "\"Risperidone works like benztropine by blocking cholinergic receptors.\""}, {"id": "c", "text": "\"Risperidone blocks D2 dopamine receptors and serotonin receptors.\""}, {"id": "d", "text": "\"Risperidone is a dopamine agonist that restores normal dopamine levels.\""}]'::jsonb, '["c"]', 'Atypical antipsychotics such as risperidone block D2 plus serotonin receptors and are effective for both positive and negative symptoms. Typical antipsychotics block only D2 receptors and have limited effect on negative symptoms; a dopamine agonist (bromocriptine) is used for NMS.', false),
  ('schizophrenia', 31, 'A client with schizophrenia developed severe tremor, rigidity, and shuffling gait while taking haloperidol and is afraid of having these effects again. Which medication would the nurse expect the provider to consider to BEST lower this client''s risk?', '[{"id": "a", "text": "Chlorpromazine (Thorazine)"}, {"id": "b", "text": "Haloperidol given as IM depot"}, {"id": "c", "text": "Fluphenazine taken orally"}, {"id": "d", "text": "Aripiprazole"}]'::jsonb, '["d"]', 'Tremor, rigidity, and shuffling gait are pseudoparkinsonism, an EPS; atypical antipsychotics such as aripiprazole have a lower risk of EPS. Chlorpromazine, fluphenazine, and haloperidol depot are typical antipsychotics with a high risk of EPS.', false),
  ('schizophrenia', 32, 'The nurse is assessing a client who has received haloperidol for several months. Which findings indicate extrapyramidal side effects (EPS)? Select all that apply.', '[{"id": "a", "text": "Tremor at rest with a shuffling gait"}, {"id": "b", "text": "Restlessness and inability to sit still"}, {"id": "c", "text": "Weight gain with new dyslipidemia"}, {"id": "d", "text": "Sudden, severe muscle spasms of the neck"}, {"id": "e", "text": "Lip smacking and tongue protrusion"}]'::jsonb, '["a", "b", "d", "e"]', 'Tremor at rest with shuffling gait (pseudoparkinsonism), restlessness (akathisia), sudden neck spasm (acute dystonia), and lip smacking with tongue protrusion (tardive dyskinesia) are all EPS types. Weight gain and dyslipidemia are features of metabolic syndrome, a risk of atypical antipsychotics.', true),
  ('schizophrenia', 33, 'A newly admitted client with schizophrenia tells the nurse, "The voices started again last night, and they won''t leave me alone." Which question is the PRIORITY for the nurse to ask?', '[{"id": "a", "text": "\"Are the voices commanding you to harm yourself or others?\""}, {"id": "b", "text": "\"How many different voices are you hearing at this moment?\""}, {"id": "c", "text": "\"Did you stop taking your medicine before the voices began?\""}, {"id": "d", "text": "\"Do the voices sound like someone that you know very well?\""}]'::jsonb, '["a"]', 'The nurse must assess whether voices are commanding harm to self or others because that is the safety priority. The other questions gather useful history but do not address safety.', false),
  ('schizophrenia', 34, 'A nursing assistant (UAP) is sitting with a client with schizophrenia who is hearing voices. Which action by the UAP requires the nurse to intervene IMMEDIATELY?', '[{"id": "a", "text": "Inviting the patient to help fold towels at the table"}, {"id": "b", "text": "Telling the voices to leave the patient alone"}, {"id": "c", "text": "Reporting that the patient said the voices sound angry"}, {"id": "d", "text": "Staying calm while the patient describes what he hears"}]'::jsonb, '["b"]', 'Speaking to the voices plays along with the hallucination and validates it as real, which staff must not do. Engaging the client in a simple grounding activity and reporting what the voices are saying are appropriate.', false),
  ('schizophrenia', 35, 'A client with schizophrenia has had persistent hallucinations and delusions despite adequate trials of haloperidol and risperidone. The provider plans a different antipsychotic. Which medication and monitoring plan would the nurse MOST expect?', '[{"id": "a", "text": "Fluphenazine, with an AIMS assessment every week"}, {"id": "b", "text": "Clozapine, with weekly WBC monitoring"}, {"id": "c", "text": "Quetiapine, with weekly creatine kinase levels"}, {"id": "d", "text": "Chlorpromazine, with weekly white blood cell counts"}]'::jsonb, '["b"]', 'Clozapine is the most effective drug for treatment-resistant schizophrenia and carries a risk of agranulocytosis, so weekly WBC monitoring is required. Fluphenazine and chlorpromazine are typical antipsychotics, and CK is the NMS marker rather than routine weekly monitoring.', false),
  ('schizophrenia', 36, 'A client who has taken haloperidol without problems for 6 years now has a temperature of 40.2°C (104.4°F) and new muscle rigidity. Which statement by a nurse colleague requires follow-up?', '[{"id": "a", "text": "\"His temperature and rigidity could signal neuroleptic malignant syndrome.\""}, {"id": "b", "text": "\"A creatine kinase level would help show whether muscle breakdown is present.\""}, {"id": "c", "text": "\"It can''t be NMS, because he has tolerated haloperidol for six years.\""}, {"id": "d", "text": "\"Typical drugs such as haloperidol are the ones most often linked to NMS.\""}]'::jsonb, '["c"]', 'NMS can occur at any time, even after years of use, so long tolerance does not rule it out. NMS is most often linked to typical antipsychotics, and an elevated CK reflects muscle breakdown.', false),
  ('schizophrenia', 37, 'The nurse reviews documented speech samples from clients with schizophrenia. Which entries correctly match the client''s speech to the thought disorder? Select all that apply.', '[{"id": "a", "text": "\"I need my blurpsit before group.\" — neologism"}, {"id": "b", "text": "\"I feel real, the deal, the wheel, the zeal.\" — loose associations"}, {"id": "c", "text": "\"Cat blue shoe running democracy morning.\" — echolalia"}, {"id": "d", "text": "Asked about mood; rambles about planets — clang associations"}, {"id": "e", "text": "\"I like pizza. Pizza is round. The earth is round.\" — loose associations"}]'::jsonb, '["a", "e"]', 'Inventing a new word such as "blurpsit" is a neologism, and ideas shifting from pizza to the earth with no clear connection are loose associations. Rhyming speech is clang associations, not loose associations; an incoherent mix of words is word salad, not echolalia; and drifting from mood to planets is tangentiality, not clang associations.', true),
  ('schizophrenia', 38, 'A client on haloperidol has been pacing the unit, cannot sit through meals, and says she feels driven to keep moving. Which interventions should the nurse anticipate for this adverse effect? Select all that apply.', '[{"id": "a", "text": "Propranolol"}, {"id": "b", "text": "Valbenazine (Ingrezza)"}, {"id": "c", "text": "A benzodiazepine"}, {"id": "d", "text": "Dantrolene"}, {"id": "e", "text": "Reduce the dose"}]'::jsonb, '["a", "c", "e"]', 'Pacing and inability to sit still are akathisia, which is treated with propranolol, a benzodiazepine, or a dose reduction. Valbenazine treats tardive dyskinesia, and dantrolene is a muscle relaxant used for NMS.', true),
  ('schizophrenia', 39, 'The nurse receives report on four clients with schizophrenia who are hearing voices. Which client should the nurse see FIRST?', '[{"id": "a", "text": "A patient who says the voices comment on every outfit she wears"}, {"id": "b", "text": "A patient hearing voices commanding him to harm his roommate"}, {"id": "c", "text": "A patient who hears his name called whenever the hallway is quiet"}, {"id": "d", "text": "A patient who says the voices make it hard for her to fall asleep"}]'::jsonb, '["b"]', 'Voices commanding harm to others are a safety emergency that requires immediate action. Commenting voices, hearing one''s name, and voices that disturb sleep are hallucinations that need routine nursing interventions.', false),
  ('schizophrenia', 40, 'A client with schizophrenia believes that the staff are trying to poison him and refuses to eat. Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Acknowledge the feeling without arguing with the delusion"}, {"id": "b", "text": "Offer sealed packaged foods at meals"}, {"id": "c", "text": "Redirect to a different topic or activity"}, {"id": "d", "text": "Show him the kitchen''s inspection report"}, {"id": "e", "text": "Allow the patient to open their own food"}]'::jsonb, '["a", "b", "c", "e"]', 'The nurse acknowledges the feeling without arguing, offers sealed packaged foods or lets the client open his own food, and redirects to a different topic or activity. Showing an inspection report argues with the delusion, which the nurse must not do.', true),
  ('schizophrenia', 41, 'A client on haloperidol has new muscle rigidity. Which additional finding requires the MOST IMMEDIATE follow-up by the nurse?', '[{"id": "a", "text": "A tremor at rest in both hands"}, {"id": "b", "text": "Slow movement with shuffling gait"}, {"id": "c", "text": "Hyperthermia of 40.3°C (104.5°F)"}, {"id": "d", "text": "Small, slow steps when walking"}]'::jsonb, '["c"]', 'Rigidity with hyperthermia above 40°C suggests neuroleptic malignant syndrome, a life-threatening emergency. Tremor at rest, bradykinesia, and shuffling gait with rigidity describe pseudoparkinsonism, which is treated with an anticholinergic and is not an emergency.', false),
  ('schizophrenia', 42, 'A client with schizophrenia also has type 2 diabetes and dyslipidemia. The nurse reviews the client''s medication history. Which antipsychotics require the closest monitoring of this client''s metabolic status? Select all that apply.', '[{"id": "a", "text": "Haloperidol"}, {"id": "b", "text": "Olanzapine"}, {"id": "c", "text": "Chlorpromazine"}, {"id": "d", "text": "Fluphenazine"}, {"id": "e", "text": "Quetiapine"}]'::jsonb, '["b", "e"]', 'Olanzapine and quetiapine are atypical antipsychotics with a higher risk of metabolic syndrome (weight gain, diabetes, dyslipidemia). Haloperidol, chlorpromazine, and fluphenazine are typical antipsychotics whose key risk is EPS.', true),
  ('schizophrenia', 43, 'The mother of a client with schizophrenia says, "He''s just lazy. He won''t start anything on his own, not even brushing his teeth, unless I push him." Which response by the nurse is MOST helpful?', '[{"id": "a", "text": "\"He may be more depressed than lazy, so try to cheer him up more often.\""}, {"id": "b", "text": "\"Lack of motivation is one of the negative symptoms of his illness.\""}, {"id": "c", "text": "\"If you stop pushing him, he will learn to start these things himself.\""}, {"id": "d", "text": "\"Why do you think he refuses to do the things that you ask of him?\""}]'::jsonb, '["b"]', 'Avolition — lack of motivation and inability to initiate goal-directed activity — is a negative symptom of schizophrenia, so the nurse explains it as part of the illness. Labeling it depression or advising the mother to stop prompting does not reflect the description of negative symptoms.', false),
  ('schizophrenia', 44, 'A client with schizophrenia was switched from haloperidol to risperidone 8 weeks ago because of persistent negative symptoms. Which finding BEST indicates that the new medication is achieving this goal?', '[{"id": "a", "text": "The patient no longer reports hearing voices at night"}, {"id": "b", "text": "The patient has no tremor at rest or shuffling gait"}, {"id": "c", "text": "The patient shows improved motivation and social interaction"}, {"id": "d", "text": "The patient no longer believes the staff are poisoning him"}]'::jsonb, '["c"]', 'Improved motivation and social interaction show improvement in avolition and asociality, the negative symptoms the switch was meant to treat. Absence of voices and paranoid beliefs reflects positive symptoms, and absence of tremor reflects fewer EPS.', false),
  ('schizophrenia', 45, 'A client with schizophrenia believes he is a famous scientist and says, "I have to leave now; the president is waiting for my report." Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "\"You''re a patient here, not a scientist, and no one is waiting for you.\""}, {"id": "b", "text": "\"I can see this feels important. Let''s go to the art group together.\""}, {"id": "c", "text": "\"What kind of report does the president want you to bring him today?\""}, {"id": "d", "text": "\"I''ll call the president''s office and let them know your report is late.\""}]'::jsonb, '["b"]', 'The nurse acknowledges the feeling without arguing or reinforcing the delusion and then redirects to a different activity. Contradicting the belief argues with it, while asking about the report or calling the office plays along.', false),
  ('schizophrenia', 46, 'The nurse reviews PRN prescriptions for four clients taking antipsychotics. For which client is giving the PRN benztropine MOST appropriate?', '[{"id": "a", "text": "Tremor at rest, rigidity, shuffling gait"}, {"id": "b", "text": "New lip smacking after years of fluphenazine"}, {"id": "c", "text": "Temperature of 40.5°C and lead pipe rigidity"}, {"id": "d", "text": "Pacing and says she cannot sit still in group"}]'::jsonb, '["a"]', 'Tremor at rest, rigidity, and shuffling gait are pseudoparkinsonism, treated with an anticholinergic such as benztropine. Anticholinergics worsen tardive dyskinesia, NMS requires stopping the antipsychotic, and akathisia is treated with propranolol, a benzodiazepine, or dose reduction.', false),
  ('schizophrenia', 47, 'The nurse is reviewing four clients who take antipsychotic medication. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Oculogyric crisis with a sudden neck spasm"}, {"id": "b", "text": "New lip smacking and tongue protrusion"}, {"id": "c", "text": "Weight gain of 2 kg over the past month"}, {"id": "d", "text": "Brief, empty replies during group therapy"}, {"id": "e", "text": "Fever of 40.4°C with lead pipe rigidity"}]'::jsonb, '["a", "b", "e"]', 'An oculogyric crisis with neck spasm is acute dystonia needing immediate benztropine or diphenhydramine IM; new involuntary movements suggest tardive dyskinesia, which must be reported immediately; and fever with lead-pipe rigidity suggests NMS, a life-threatening emergency. Modest weight gain reflects metabolic risk to monitor, and brief empty replies are alogia, a negative symptom.', true),
  ('schizophrenia', 48, 'A father asks why his son''s social withdrawal has not improved even though the son stopped hearing voices soon after starting medication. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Withdrawal is a negative symptom, and those are harder to treat.\""}, {"id": "b", "text": "\"Withdrawal means the dose is too low to control his hallucinations.\""}, {"id": "c", "text": "\"Withdrawal is a side effect that should end when he stops the drug.\""}, {"id": "d", "text": "\"Withdrawal is a positive symptom, so it should resolve soon as well.\""}]'::jsonb, '["a"]', 'Social withdrawal (asociality) is a negative symptom, a loss of normal function that is harder to treat than positive symptoms such as hallucinations. It is not a positive symptom or a drug side effect.', false),
  ('schizophrenia', 49, 'A client with schizophrenia sits motionless in a rigid, unusual posture for hours, believes a neighbor is controlling her thoughts, and has stopped talking with peers. Which statements about this client''s care are accurate? Select all that apply.', '[{"id": "a", "text": "Catatonic behavior is one of her positive symptoms"}, {"id": "b", "text": "Her belief is a delusion — a fixed, false belief"}, {"id": "c", "text": "The nurse should not argue with the delusion"}, {"id": "d", "text": "Social withdrawal reflects asociality"}, {"id": "e", "text": "Agreeing with her belief will build early trust"}]'::jsonb, '["a", "b", "c", "d"]', 'Catatonic behavior is a positive symptom, a fixed false belief is a delusion, and social withdrawal is asociality, a negative symptom. The nurse must not argue with the delusion and must not reinforce (play along with) it, so agreeing with the belief is wrong.', true),
  ('schizophrenia', 50, 'During an admission interview, a client with schizophrenia answers every question with "Fine," "No," or "Okay" and offers nothing more, although he sits calmly and makes eye contact. Which documentation by the nurse is MOST accurate?', '[{"id": "a", "text": "Avolition"}, {"id": "b", "text": "Anhedonia"}, {"id": "c", "text": "Flat affect"}, {"id": "d", "text": "Alogia"}]'::jsonb, '["d"]', 'Alogia is poverty of speech with brief, empty replies. Avolition is a lack of motivation to initiate activity, anhedonia is an inability to experience pleasure, and flat affect is diminished emotional expression rather than diminished speech.', false),
  ('cognitive', 1, 'The parents of an 8-year-old with an IQ of 42 who has limited academic skills and needs help with complex tasks ask what the future may hold for their son as an adult. Which outcome is MOST realistic for this level of intellectual disability?', '[{"id": "a", "text": "Require total care in all areas with motor impairment"}, {"id": "b", "text": "Hold a job with supervision in supervised living"}, {"id": "c", "text": "Live independently with minimal support in the community"}, {"id": "d", "text": "Require significant daily support for basic self-care"}]'::jsonb, '["b"]', 'An IQ of 35–50 is moderate intellectual disability: limited academic skills, support with complex tasks, jobs with supervision, and supervised living. Independent living with minimal support describes mild ID (50–70).', false),
  ('cognitive', 2, 'A nurse reviews a 16-year-old''s evaluation for possible intellectual disability. Which findings must be present to support this diagnosis? Select all that apply.', '[{"id": "a", "text": "Onset before age 18"}, {"id": "b", "text": "Symptoms in 2 or more settings"}, {"id": "c", "text": "IQ of 75 with poor grades"}, {"id": "d", "text": "Deficits in adaptive behavior"}, {"id": "e", "text": "IQ ≤70"}]'::jsonb, '["a", "d", "e"]', 'Intellectual disability requires an IQ of 70 or lower, deficits in adaptive behavior, and onset before age 18. An IQ above 70 does not meet the criterion, and symptoms in 2 or more settings is an ADHD criterion.', true),
  ('cognitive', 3, 'A 15-year-old with an IQ of 72 has difficulty with conceptual, social, and practical skills, and the parents ask whether their son has intellectual disability. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Criteria are met, because the deficits began before age 18"}, {"id": "b", "text": "Criteria are not met, because onset must occur before age 12"}, {"id": "c", "text": "Criteria are met, because adaptive behavior deficits are present"}, {"id": "d", "text": "Criteria are not met, because IQ must be ≤70"}]'::jsonb, '["d"]', 'Intellectual disability requires significant limitations in intellectual functioning (IQ ≤70) AND adaptive behavior; an IQ of 72 does not meet the intellectual criterion. Onset before age 12 is an ADHD criterion; ID onset must be before 18.', false),
  ('cognitive', 4, 'A 25-year-old client sustained a brain injury at age 23 and now has an IQ of 60 with deficits in adaptive behavior. A nursing student labels the client as having intellectual disability. Which response by the nurse is BEST?', '[{"id": "a", "text": "''ID requires onset during the developmental period, before age 18.''"}, {"id": "b", "text": "''ID requires an IQ in the moderate range, 35 to 50, or lower.''"}, {"id": "c", "text": "''You are correct, because the IQ is 70 or lower with adaptive deficits.''"}, {"id": "d", "text": "''ID requires that the symptoms be present in 2 or more settings first.''"}]'::jsonb, '["a"]', 'Intellectual disability requires onset during the developmental period (before age 18); this client''s deficits began at 23. Symptoms in 2 or more settings is an ADHD criterion, and mild ID includes IQs of 50–70.', false),
  ('cognitive', 5, 'A 9-year-old with an IQ of 64 shows age-appropriate self-care, social, and practical skills at home and school, and the parents ask whether a diagnosis of intellectual disability fits. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "''No, because ID requires onset after the age of 12.''"}, {"id": "b", "text": "''Yes, because the IQ is in the range for moderate disability.''"}, {"id": "c", "text": "''Yes, an IQ of 64 alone confirms mild intellectual disability.''"}, {"id": "d", "text": "''No, because ID requires adaptive behavior deficits too.''"}]'::jsonb, '["d"]', 'Intellectual disability requires both an IQ of 70 or lower AND deficits in adaptive behavior; this child''s adaptive skills are age-appropriate. An IQ of 64 falls in the mild range (50–70), not moderate, and onset must be before age 18.', false),
  ('cognitive', 6, 'A nurse in a group home plans care for a 30-year-old resident with an IQ of 27 who uses a few words and gestures to communicate. Which goal is MOST realistic for this resident?', '[{"id": "a", "text": "Live independently in an apartment with minimal outside support"}, {"id": "b", "text": "Hold a part-time job with supervision and live semi-independently"}, {"id": "c", "text": "Make slow academic progress toward a high school diploma"}, {"id": "d", "text": "Participate in self-care with significant daily support"}]'::jsonb, '["d"]', 'An IQ of 20–35 is severe intellectual disability: very limited communication and self-care, requiring significant daily support. Supervised jobs fit moderate ID, and independent living and slow academic progress fit mild ID.', false),
  ('cognitive', 7, 'A pediatric nurse admits a 6-year-old with an IQ below 20 who has minimal verbal communication and significant motor impairment. Which plan of care is MOST appropriate for this level of disability?', '[{"id": "a", "text": "Training for a supervised job program"}, {"id": "b", "text": "Coaching toward semi-independent living"}, {"id": "c", "text": "Total care required in all areas"}, {"id": "d", "text": "Teaching self-care with daily support"}]'::jsonb, '["c"]', 'An IQ below 20 is profound intellectual disability, with severe limitations in all areas and possible significant motor impairment, so total care is required. Daily support for limited self-care fits severe ID.', false),
  ('cognitive', 8, 'A nurse is teaching an adult with moderate intellectual disability how to wash hands before meals. Which teaching approach is MOST appropriate?', '[{"id": "a", "text": "Use detailed written handouts with diagrams"}, {"id": "b", "text": "Cover all hygiene topics in one long session"}, {"id": "c", "text": "Teach in short sessions with repetition"}, {"id": "d", "text": "Have the caregiver perform the task for the client"}]'::jsonb, '["c"]', 'Clients with intellectual disability learn best with short sessions and repetition, using simple, concrete language. Doing the task for the client works against maximizing independence and self-care skills.', false),
  ('cognitive', 9, 'A nurse is planning care for a young adult with mild intellectual disability who is admitted for surgery. Which actions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Teach in short sessions"}, {"id": "b", "text": "Involve caregivers in care planning"}, {"id": "c", "text": "Allow extra time for responses"}, {"id": "d", "text": "Use simple, concrete language"}, {"id": "e", "text": "Perform self-care for the client"}]'::jsonb, '["a", "b", "c", "d"]', 'Simple, concrete language, extra time for processing and responses, short teaching sessions, and involving family/caregivers in care planning are the nursing approach for intellectual disability. Performing self-care for the client works against maximizing independence and self-care skills.', true),
  ('cognitive', 10, 'The mother of a 2-day-old asks the nurse why a heel-stick blood sample is needed before discharge, saying, ''My baby looks perfectly healthy.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "''The test checks for Down syndrome, which causes problems in older babies.''"}, {"id": "b", "text": "''Newborn screening finds PKU, a preventable cause of intellectual disability.''"}, {"id": "c", "text": "''The test detects Fragile X syndrome so that it can be cured right after birth.''"}, {"id": "d", "text": "''The test checks for fetal alcohol syndrome, which is often missed at birth.''"}]'::jsonb, '["b"]', 'Phenylketonuria (PKU) is a cause of intellectual disability that is preventable with newborn screening. Down syndrome and Fragile X are genetic and inherited causes and are not described as preventable.', false),
  ('cognitive', 11, 'A nurse reviews the history of a 4-year-old referred for evaluation of intellectual disability. Which findings in the history are possible causes? Select all that apply.', '[{"id": "a", "text": "Perinatal hypoxia at birth"}, {"id": "b", "text": "Prenatal rubella infection"}, {"id": "c", "text": "Untreated congenital hypothyroidism"}, {"id": "d", "text": "PKU treated from newborn screening"}, {"id": "e", "text": "Fetal alcohol syndrome (FASD)"}]'::jsonb, '["a", "b", "c", "e"]', 'Prenatal infections such as rubella, perinatal hypoxia, untreated congenital hypothyroidism, and fetal alcohol syndrome are listed causes of intellectual disability. PKU is preventable with newborn screening, so PKU identified and treated from the newborn period is not the expected cause.', true),
  ('cognitive', 12, 'A pregnant client at 10 weeks'' gestation tells the nurse she drinks two glasses of wine each night ''to relax.'' Which teaching is the PRIORITY for the nurse to provide?', '[{"id": "a", "text": "''Alcohol in pregnancy can cause fetal alcohol syndrome (FASD).''"}, {"id": "b", "text": "''Newborn screening will detect and prevent any effects of alcohol.''"}, {"id": "c", "text": "''Alcohol mainly increases the risk of Down syndrome in the baby.''"}, {"id": "d", "text": "''Wine at night is safe once the first trimester has been completed.''"}]'::jsonb, '["a"]', 'Fetal alcohol syndrome (FASD) is a cause of intellectual disability. Newborn screening prevents ID from PKU, not alcohol exposure, and Down syndrome (Trisomy 21) is a genetic cause.', false),
  ('cognitive', 13, 'A 10-year-old with average intelligence and good school instruction reads slowly, struggles to sound out words, and makes frequent spelling errors, but solves math problems at grade level. Which condition do these findings MOST likely indicate?', '[{"id": "a", "text": "Mild intellectual disability"}, {"id": "b", "text": "Dysgraphia"}, {"id": "c", "text": "Dyscalculia"}, {"id": "d", "text": "Dyslexia"}]'::jsonb, '["d"]', 'Difficulty decoding words, reading fluency, and spelling despite adequate intelligence and instruction defines dyslexia. Dysgraphia affects handwriting and organizing written language, and mild ID would involve an IQ of 70 or lower.', false),
  ('cognitive', 14, 'A school nurse meets with a 9-year-old who reads above grade level but cannot recall basic addition facts, miscounts change, and struggles with word problems. Which condition is the MOST likely explanation for these findings?', '[{"id": "a", "text": "Auditory processing disorder"}, {"id": "b", "text": "Dyslexia"}, {"id": "c", "text": "Predominantly inattentive ADHD"}, {"id": "d", "text": "Dyscalculia"}]'::jsonb, '["d"]', 'Difficulty with number sense, arithmetic facts, calculation, and math reasoning describes dyscalculia. Dyslexia would affect reading, which is above grade level here.', false),
  ('cognitive', 15, 'A 7-year-old who reads well and explains ideas clearly out loud produces handwriting that is very hard to read, and the child''s written stories are disorganized. Which condition should the nurse suspect FIRST?', '[{"id": "a", "text": "Dysgraphia"}, {"id": "b", "text": "Autism spectrum disorder"}, {"id": "c", "text": "Dyscalculia"}, {"id": "d", "text": "Dyslexia"}]'::jsonb, '["a"]', 'Dysgraphia is a written expression disorder involving handwriting, spelling, and organizing written language. Dyslexia would impair reading, which is intact.', false),
  ('cognitive', 16, 'An 8-year-old frequently misunderstands spoken directions in class and asks for them to be repeated, yet a recent hearing test was normal and the child reads well. Which condition is MOST consistent with these findings?', '[{"id": "a", "text": "Auditory processing disorder"}, {"id": "b", "text": "Narcolepsy"}, {"id": "c", "text": "Mild intellectual disability (ID)"}, {"id": "d", "text": "Dyslexia"}]'::jsonb, '["a"]', 'Auditory processing disorder is difficulty processing and interpreting auditory information despite normal hearing ability. Dyslexia would affect reading, which is intact.', false),
  ('cognitive', 17, 'A school nurse reviews referrals for four students. Which students'' findings are consistent with a specific learning disability? Select all that apply.', '[{"id": "a", "text": "Poor eye contact and insistence on sameness"}, {"id": "b", "text": "Struggles with arithmetic facts and calculation"}, {"id": "c", "text": "IQ of 45 with limited academic skills"}, {"id": "d", "text": "Poor handwriting and organizing of written language"}, {"id": "e", "text": "Adequate intelligence; trouble decoding words"}]'::jsonb, '["b", "d", "e"]', 'Decoding difficulty despite adequate intelligence (dyslexia), trouble with arithmetic facts and calculation (dyscalculia), and problems with handwriting and organizing written language (dysgraphia) are learning disabilities. An IQ of 45 indicates moderate intellectual disability, and poor eye contact with insistence on sameness indicates autism spectrum disorder.', true),
  ('cognitive', 18, 'The teacher of a 9-year-old reports that he is easily distracted, blurts out answers, and cannot stay seated. At home and at his grandparents'' house, the parents report he is calm, organized, and focused. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "ADHD criteria are met, because the symptoms began before the age of 12 years"}, {"id": "b", "text": "ADHD criteria are not met, because inattention and hyperactivity occur together"}, {"id": "c", "text": "ADHD criteria are not met, because symptoms must occur in 2 or more settings"}, {"id": "d", "text": "ADHD criteria are met, because the symptoms interfere with school functioning"}]'::jsonb, '["c"]', 'ADHD requires symptoms present in 2 or more settings (home, school, work); this child''s symptoms occur only at school. Inattentive and hyperactive-impulsive symptoms together describe the combined presentation, which is the most common.', false),
  ('cognitive', 19, 'A 19-year-old college student reports trouble focusing, losing items, and missing deadlines at school and work. The student and parents agree the problems began at age 16, and teachers'' reports from elementary school describe no concerns. Which conclusion by the nurse is MOST accurate?', '[{"id": "a", "text": "ADHD criteria are met because symptoms occur in 2 settings"}, {"id": "b", "text": "ADHD criteria are met because symptoms interfere with work"}, {"id": "c", "text": "Several symptoms must be present before age 12 for ADHD"}, {"id": "d", "text": "Symptoms of ADHD must begin before the age of 18 to count"}]'::jsonb, '["c"]', 'ADHD requires several symptoms before age 12; this student''s symptoms began at 16. Onset before age 18 is the criterion for intellectual disability, not ADHD.', false),
  ('cognitive', 20, 'A nurse reviews the record of a child being evaluated for ADHD. Which data support the diagnosis? Select all that apply.', '[{"id": "a", "text": "Symptoms interfere with functioning"}, {"id": "b", "text": "Symptoms first noticed at age 15"}, {"id": "c", "text": "Several symptoms before age 12"}, {"id": "d", "text": "Symptoms only during summer camp"}, {"id": "e", "text": "Symptoms at home and at school"}]'::jsonb, '["a", "c", "e"]', 'ADHD requires a persistent pattern that interferes with functioning, symptoms in 2 or more settings, and several symptoms before age 12. Symptoms in one setting only or first noticed at 15 do not meet criteria.', true),
  ('cognitive', 21, 'A 10-year-old girl rarely disrupts class but is easily distracted, forgets homework, loses her belongings, and does not follow through on assignments; these problems also occur at home. Which presentation of ADHD do these findings MOST likely represent?', '[{"id": "a", "text": "Predominantly hyperactive-impulsive"}, {"id": "b", "text": "Combined presentation"}, {"id": "c", "text": "Predominantly inattentive"}, {"id": "d", "text": "Hyperactive with learning disability"}]'::jsonb, '["c"]', 'Being easily distracted, forgetful, losing items, and not following through on tasks without hyperactivity describe the predominantly inattentive type. The combined presentation requires criteria for both types.', false),
  ('cognitive', 22, 'The parents of a 7-year-old being evaluated for ADHD describe his behavior at home and at school. Which findings are consistent with the predominantly hyperactive-impulsive type? Select all that apply.', '[{"id": "a", "text": "Poor organization of tasks"}, {"id": "b", "text": "Fidgeting during meals"}, {"id": "c", "text": "Difficulty waiting his turn"}, {"id": "d", "text": "Blurts out answers in class"}, {"id": "e", "text": "Loses items at school daily"}]'::jsonb, '["b", "c", "d"]', 'Fidgeting, blurting out answers, and difficulty waiting turn are hyperactive-impulsive features. Losing items and poor organization are features of the predominantly inattentive type.', true),
  ('cognitive', 23, 'The parent of a 4-year-old newly diagnosed with ADHD asks the nurse, ''Can we start medicine right away so preschool goes better?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "''A non-stimulant is required because stimulants are controlled drugs.''"}, {"id": "b", "text": "''Medication is started first, and therapy is added only if it fails.''"}, {"id": "c", "text": "''Behavioral therapy and parent training are tried first at this age.''"}, {"id": "d", "text": "''A stimulant such as methylphenidate is first-line at any age for ADHD.''"}]'::jsonb, '["c"]', 'Non-pharmacological treatment such as behavioral therapy and parent training in behavior management is tried first in young children. Stimulants are first-line for children 6 years and older.', false),
  ('cognitive', 24, 'A nurse is teaching the parents of a 4-year-old with ADHD about the initial treatment plan. Which interventions should the nurse include? Select all that apply.', '[{"id": "a", "text": "A stimulant as first-line therapy"}, {"id": "b", "text": "Social skills training"}, {"id": "c", "text": "Parent training in behavior management"}, {"id": "d", "text": "Environmental modifications at home"}, {"id": "e", "text": "Behavioral therapy with reinforcement"}]'::jsonb, '["b", "c", "d", "e"]', 'Behavioral therapy, parent training in behavior management, environmental modifications, and social skills training are non-pharmacological treatments tried first in young children. Stimulants are first-line for children 6 years and older.', true),
  ('cognitive', 25, 'A 9-year-old has been diagnosed with combined-presentation ADHD after behavioral strategies at home and school were not enough. Which medication should the nurse anticipate as the FIRST-line drug therapy?', '[{"id": "a", "text": "Guanfacine"}, {"id": "b", "text": "Atomoxetine"}, {"id": "c", "text": "Clonidine"}, {"id": "d", "text": "Methylphenidate"}]'::jsonb, '["d"]', 'Stimulants such as methylphenidate are first-line for children 6 years and older. Atomoxetine, guanfacine, and clonidine are non-stimulants.', false),
  ('cognitive', 26, 'The parents of a 7-year-old report that he loses his homework and is easily distracted, and also fidgets, runs and climbs excessively, and cannot wait his turn, both at home and at school. Which presentation is the provider MOST likely to document?', '[{"id": "a", "text": "Predominantly inattentive presentation"}, {"id": "b", "text": "Predominantly hyperactive-impulsive type"}, {"id": "c", "text": "Learning disorder with hyperactivity"}, {"id": "d", "text": "Combined presentation, the most common"}]'::jsonb, '["d"]', 'A child who meets criteria for both inattentive and hyperactive-impulsive types has the combined presentation, which is the most common. Each single-type label leaves out half of the findings.', false),
  ('cognitive', 27, 'The mother of an 8-year-old taking methylphenidate says she gives the dose at 4 p.m. so he can focus on homework, but he now lies awake until midnight. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "Give the medication early in the day"}, {"id": "b", "text": "Give a second dose at bedtime for sleep"}, {"id": "c", "text": "Stop the drug on any night with homework"}, {"id": "d", "text": "Give the dose with a large evening meal"}]'::jsonb, '["a"]', 'Stimulants are given early in the day to avoid insomnia. A bedtime dose or an evening dose with a meal would worsen sleep.', false),
  ('cognitive', 28, 'A father reports that his 9-year-old, who takes an amphetamine (Adderall) each morning, brings most of his school lunch home uneaten. Which recommendation by the nurse is MOST appropriate?', '[{"id": "a", "text": "Expect appetite to return within a week, so no change"}, {"id": "b", "text": "Offer nutritious snacks after the medication wears off"}, {"id": "c", "text": "Give the medication at lunchtime to protect his breakfast appetite"}, {"id": "d", "text": "Withhold the medication on days he skips breakfast"}]'::jsonb, '["b"]', 'Stimulants may decrease appetite, so nutritious snacks are offered after the medication wears off. A later dose would interfere with sleep, since stimulants are given early in the day.', false),
  ('cognitive', 29, 'A 10-year-old has taken a stimulant for ADHD for 1 year and is seen for a routine follow-up. Attention at school has improved. Which assessment is the PRIORITY at this visit?', '[{"id": "a", "text": "Measure height and weight"}, {"id": "b", "text": "Repeat the IQ testing today"}, {"id": "c", "text": "Assess the child for cataplexy"}, {"id": "d", "text": "Screen the child for echolalia"}]'::jsonb, '["a"]', 'Stimulants can cause growth suppression, so height and weight are monitored. IQ testing, echolalia, and cataplexy relate to intellectual disability, autism spectrum disorder, and narcolepsy.', false),
  ('cognitive', 30, 'The parent of a 9-year-old taking methylphenidate asks whether the child must keep taking it during the long summer break. The child''s growth has slowed slightly. Which response by the nurse is BEST?', '[{"id": "a", "text": "''Stopping a stimulant for any length of time is unsafe for growing children.''"}, {"id": "b", "text": "''The drug must be taken daily or the ADHD diagnosis will be lost.''"}, {"id": "c", "text": "''Summer is the best time to increase the dose to catch up on growth.''"}, {"id": "d", "text": "''Medication-free holidays can be scheduled when school is not critical.''"}]'::jsonb, '["d"]', 'Medication-free holidays (such as summer) are scheduled when school performance is not critical, which also helps with growth suppression concerns. Stopping for holidays is part of the teaching, not unsafe.', false),
  ('cognitive', 31, 'The mother of a 12-year-old taking an amphetamine (Vyvanse) reports that the monthly prescription is running out a week early. A 17-year-old sibling lives in the home. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Teach the mother to give the dose early in the day"}, {"id": "b", "text": "Offer nutritious snacks after the dose wears off"}, {"id": "c", "text": "Assess for misuse, as this is a controlled substance"}, {"id": "d", "text": "Ask the provider to increase the daily dose amount instead"}]'::jsonb, '["c"]', 'Stimulants are controlled substances, so pills running out early requires assessment for misuse potential. Giving the dose early and offering snacks are correct teaching points that do not address this finding.', false),
  ('cognitive', 32, 'A nurse teaches the parents of an 8-year-old starting methylphenidate. Which statements by the parents indicate understanding? Select all that apply.', '[{"id": "a", "text": "''We''ll give it right at bedtime.''"}, {"id": "b", "text": "''It is not a controlled substance.''"}, {"id": "c", "text": "''Height checks aren''t needed now.''"}, {"id": "d", "text": "''We''ll offer nutritious snacks later.''"}, {"id": "e", "text": "''We''ll give it early in the day.''"}]'::jsonb, '["d", "e"]', 'Stimulants are given early in the day to avoid insomnia, and nutritious snacks are offered after the medication wears off because appetite may decrease. A bedtime dose causes insomnia, stimulants are controlled substances, and height and weight are monitored for growth suppression.', true),
  ('cognitive', 33, 'The parent of an 11-year-old with ADHD is concerned about controlled substances and asks about medications that are not stimulants. Which medications are non-stimulants? Select all that apply.', '[{"id": "a", "text": "Clonidine"}, {"id": "b", "text": "Guanfacine (Intuniv)"}, {"id": "c", "text": "Atomoxetine (Strattera)"}, {"id": "d", "text": "Amphetamine (Vyvanse)"}, {"id": "e", "text": "Methylphenidate (Concerta)"}]'::jsonb, '["a", "b", "c"]', 'Atomoxetine, guanfacine, and clonidine are non-stimulants. Methylphenidate (Concerta) and amphetamine (Vyvanse) are stimulants.', true),
  ('cognitive', 34, 'A nurse reviews data for several children taking stimulants for ADHD. Which findings require follow-up? Select all that apply.', '[{"id": "a", "text": "New insomnia"}, {"id": "b", "text": "Height and weight falling behind"}, {"id": "c", "text": "Eats nutritious snacks after dose"}, {"id": "d", "text": "Improved attention at school"}, {"id": "e", "text": "Pills running out a week early"}]'::jsonb, '["a", "b", "e"]', 'Falling height and weight suggest growth suppression, pills running out early suggests misuse of a controlled substance, and insomnia from a late-day dose means the dose should be given early in the day. Improved attention is the desired effect, and snacks after the dose wears off are recommended.', true),
  ('cognitive', 35, 'A 2-year-old''s parents report that he rarely makes eye contact, flaps his hands when excited, and screams if his cup is not the same blue one. Which additional finding would the nurse MOST expect?', '[{"id": "a", "text": "Difficulty decoding words despite intelligence"}, {"id": "b", "text": "Echolalia when he speaks"}, {"id": "c", "text": "Brief loss of muscle tone when he laughs"}, {"id": "d", "text": "Sudden sleep attacks during daytime play"}]'::jsonb, '["b"]', 'Poor eye contact, hand-flapping, and insistence on sameness suggest autism spectrum disorder, in which language may include echolalia. Sleep attacks and loss of muscle tone with laughing describe narcolepsy, and decoding difficulty describes dyslexia.', false),
  ('cognitive', 36, 'A nurse assesses a 3-year-old referred for possible autism spectrum disorder. Which findings support this diagnosis? Select all that apply.', '[{"id": "a", "text": "Does not respond to name"}, {"id": "b", "text": "Falls asleep suddenly at play"}, {"id": "c", "text": "Insistence on sameness"}, {"id": "d", "text": "Hand-flapping and rocking"}, {"id": "e", "text": "Poor eye contact"}]'::jsonb, '["a", "c", "d", "e"]', 'Poor eye contact and not responding to name are social communication deficits, and hand-flapping, rocking, and insistence on sameness are repetitive behaviors in ASD. Sudden sleep attacks describe narcolepsy.', true),
  ('cognitive', 37, 'A 6-year-old with autism spectrum disorder is hospitalized and is scheduled for an MRI tomorrow morning, which will replace the usual breakfast routine. Which action by the nurse is BEST?', '[{"id": "a", "text": "Tell the child about the MRI only as it is happening"}, {"id": "b", "text": "Warn of the change in advance with a visual schedule"}, {"id": "c", "text": "Change several routines today so the child gets used to it"}, {"id": "d", "text": "Wait until morning so the child does not worry tonight"}]'::jsonb, '["b"]', 'Changes in routine cause significant distress in ASD, so upcoming changes are warned about in advance, and visual schedules support understanding. Surprises and extra changes increase distress.', false),
  ('cognitive', 38, 'In a busy, noisy playroom, a 5-year-old with autism spectrum disorder covers his ears, screams, and drops to the floor. His father says, ''He''s just being defiant.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "''He needs a time-out so he learns this behavior is not allowed here.''"}, {"id": "b", "text": "''Let''s keep him in the playroom so he learns to tolerate the noise.''"}, {"id": "c", "text": "''Meltdowns are often responses to overwhelm, not defiance.''"}, {"id": "d", "text": "''You''re right. Ignore him until he decides to stop the screaming.''"}]'::jsonb, '["c"]', 'Meltdowns are often responses to overwhelm, not willful defiance, and sensory overstimulation (noise) should be reduced. Keeping the child in the noisy room increases overwhelm.', false),
  ('cognitive', 39, 'During a clinic visit, a nurse tells a 7-year-old with autism spectrum disorder, ''Hop up on the scale.'' The child begins hopping up and down beside it. Which action by the nurse is BEST?', '[{"id": "a", "text": "Ask the parent to lift the child onto the scale instead"}, {"id": "b", "text": "Use clear instructions and simple language"}, {"id": "c", "text": "Tell the child firmly to stop playing games right now"}, {"id": "d", "text": "Repeat the same words more slowly again"}]'::jsonb, '["b"]', 'Children with ASD may take language literally, so the nurse uses clear instructions and simple language. Repeating the same figurative phrase does not solve the problem.', false),
  ('cognitive', 40, 'A nurse is caring for a hospitalized 8-year-old with autism spectrum disorder who is nonverbal and uses a tablet-based communication device. Which actions should the nurse take? Select all that apply.', '[{"id": "a", "text": "Require speech before the device"}, {"id": "b", "text": "Respect use of the AAC device"}, {"id": "c", "text": "Reduce noise and bright lighting"}, {"id": "d", "text": "Keep consistent routines"}, {"id": "e", "text": "Rotate nurses for new faces"}]'::jsonb, '["b", "c", "d"]', 'Consistent routines, reduced sensory overstimulation (noise, lighting, touch), and respect for communication preferences such as AAC devices are ASD nursing care. Rotating caregivers disrupts routine, and requiring speech ignores the child''s communication preferences.', true),
  ('cognitive', 41, 'The parents of a 3-year-old newly diagnosed with autism spectrum disorder ask which treatment has the strongest evidence. Which response by the nurse is BEST?', '[{"id": "a", "text": "''Sodium oxybate improves social and communication skills most.''"}, {"id": "b", "text": "''Applied Behavior Analysis is most effective when started early.''"}, {"id": "c", "text": "''Treatment is best delayed until school age, when demands rise.''"}, {"id": "d", "text": "''A stimulant is first-line once the child is at least 6 years old.''"}]'::jsonb, '["b"]', 'Applied Behavior Analysis (ABA) is the most evidence-based treatment for ASD and is most effective when started early. Stimulants treat ADHD, and sodium oxybate treats cataplexy in narcolepsy.', false),
  ('cognitive', 42, 'A 4-year-old with autism spectrum disorder is nonverbal, has marked repetitive behaviors, and needs constant help with every daily routine. The parent asks what severity level this means. Which level should the nurse identify as BEST matching these needs?', '[{"id": "a", "text": "Level 3 (requiring very substantial support)"}, {"id": "b", "text": "Level 2, the middle level of support"}, {"id": "c", "text": "No level until school demands exceed capacity"}, {"id": "d", "text": "Level 1 (requiring support) only"}]'::jsonb, '["a"]', 'ASD severity ranges from Level 1 (requiring support) to Level 3 (requiring very substantial support); a nonverbal child needing constant help fits Level 3.', false),
  ('cognitive', 43, 'A 16-year-old is referred to a psychiatric clinic for ''possible ADHD and psychosis'' after falling asleep in class daily, collapsing briefly when laughing, and reporting vivid images while falling asleep. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Begin a stimulant trial for the ADHD-related inattention"}, {"id": "b", "text": "Advocate for evaluation by neurology or sleep medicine"}, {"id": "c", "text": "Reassure the parents this is normal teenage fatigue"}, {"id": "d", "text": "Start psychosis precautions because of hallucinations"}]'::jsonb, '["b"]', 'Excessive daytime sleepiness, cataplexy triggered by laughing, and hypnagogic hallucinations suggest narcolepsy, a neurologic sleep-wake disorder managed by neurology or sleep medicine. It can resemble ADHD or psychosis but is not a primary mental illness.', false),
  ('cognitive', 44, 'A 17-year-old recently diagnosed with narcolepsy says, ''I just got my driver''s license, and I want to drive myself to school.'' Which response by the nurse is the PRIORITY?', '[{"id": "a", "text": "''Driving may be unsafe with sudden sleep attacks.''"}, {"id": "b", "text": "''Driving is fine as long as you take scheduled naps.''"}, {"id": "c", "text": "''Driving is fine if you drink coffee before you go.''"}, {"id": "d", "text": "''Driving is safe after a full night of sleep.''"}]'::jsonb, '["a"]', 'Safety is a priority in narcolepsy; driving, operating machinery, and working at heights may be unsafe because sleep attacks are abrupt and irresistible. Scheduled naps or a full night of sleep are part of management but do not remove this safety risk.', false),
  ('cognitive', 45, 'A 22-year-old client tells the nurse, ''Sometimes when I''m drifting off to sleep I see a person standing at the foot of my bed, but it never happens during the day.'' The client also has excessive daytime sleepiness. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Visual hallucinations caused by a learning disability"}, {"id": "b", "text": "Echolalia from an autism spectrum disorder in adults"}, {"id": "c", "text": "Psychiatric hallucinations that require psychosis precautions"}, {"id": "d", "text": "Hypnagogic hallucinations at sleep onset, not psychosis"}]'::jsonb, '["d"]', 'Hypnagogic hallucinations occur only at the boundary of sleep and waking in narcolepsy and are not the same as psychiatric hallucinations. Reports of hallucinations should not be dismissed without considering a sleep-wake etiology.', false),
  ('cognitive', 46, 'A client with narcolepsy reports frequent episodes in which the knees buckle and the client briefly slumps to the floor whenever laughing hard at a joke. Which medication should the nurse anticipate for this symptom?', '[{"id": "a", "text": "Atomoxetine (Strattera)"}, {"id": "b", "text": "Guanfacine (Intuniv)"}, {"id": "c", "text": "Sodium oxybate"}, {"id": "d", "text": "Clonidine"}]'::jsonb, '["c"]', 'A sudden, brief loss of muscle tone triggered by strong emotion is cataplexy, which is treated with sodium oxybate. Guanfacine, atomoxetine, and clonidine are ADHD non-stimulants.', false),
  ('cognitive', 47, 'A 15-year-old with excessive daytime sleepiness is evaluated for narcolepsy. Which findings support this diagnosis? Select all that apply.', '[{"id": "a", "text": "Sudden, irresistible sleep attacks"}, {"id": "b", "text": "Symptoms only when at school"}, {"id": "c", "text": "Hears voices all day while awake"}, {"id": "d", "text": "Loss of muscle tone when laughing"}, {"id": "e", "text": "Cannot move for a moment on waking"}]'::jsonb, '["a", "d", "e"]', 'Sudden sleep attacks, cataplexy triggered by laughing, and sleep paralysis on waking are narcolepsy features. Narcolepsy hallucinations occur only at the boundary of sleep and waking, not all day while awake.', true),
  ('cognitive', 48, 'A nurse provides discharge teaching to a 20-year-old client newly diagnosed with narcolepsy and the client''s family. Which statements by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "''This is chronic but manageable.''"}, {"id": "b", "text": "''This disorder can be cured quickly.''"}, {"id": "c", "text": "''Avoid working at heights.''"}, {"id": "d", "text": "''Sleep-onset hallucinations mean psychosis.''"}, {"id": "e", "text": "''Psychiatry will manage this illness.''"}]'::jsonb, '["a", "c"]', 'Narcolepsy is chronic but manageable, and working at heights may be unsafe. It is a neurologic disorder managed by neurology or sleep medicine, its sleep-onset hallucinations are not psychosis, and it is not curable.', true),
  ('cognitive', 49, 'A 19-year-old with an IQ of 62 is preparing to leave high school. The parents ask what to expect for their daughter''s future. Which outcomes are realistic for this level of intellectual disability? Select all that apply.', '[{"id": "a", "text": "Live independently with minimal support"}, {"id": "b", "text": "Slow academic progress"}, {"id": "c", "text": "Minimal verbal communication"}, {"id": "d", "text": "Requires total care in all areas"}, {"id": "e", "text": "Requires significant daily support"}]'::jsonb, '["a", "b"]', 'An IQ of 50–70 is mild intellectual disability, with slow academic progress, and most can live independently with minimal support. Total care and minimal verbal communication describe profound ID, and significant daily support describes severe ID.', true),
  ('cognitive', 50, 'A nurse supports the family of a 6-year-old with autism spectrum disorder during an admission. Which actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Delay ABA until the child is older"}, {"id": "b", "text": "Treat meltdowns as willful defiance"}, {"id": "c", "text": "Use visual schedules for the day"}, {"id": "d", "text": "Warn of upcoming changes"}, {"id": "e", "text": "Provide resources and referrals"}]'::jsonb, '["c", "d", "e"]', 'Supporting family caregivers with resources and referrals, using visual schedules, and warning of upcoming changes in advance are ASD nursing care. Meltdowns are often responses to overwhelm, not willful defiance, and ABA is most effective when started early.', true),
  ('alzheimers', 1, 'The wife of a client with Alzheimer''s disease who now needs help with toileting reports that he accuses her of hiding his wallet and repeatedly opens and closes the same drawer. She asks whether he is ''going crazy.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "''He needs an antipsychotic right away to stop these new behaviors from getting worse.''"}, {"id": "b", "text": "''Paranoia and repetitive movements are behavioral symptoms of the middle stage.''"}, {"id": "c", "text": "''These new behaviors mean he has now reached the late stage of the disease.''"}, {"id": "d", "text": "''Show him where the wallet is each time so that you correct his thinking.''"}]'::jsonb, '["b"]', 'Needing help with toileting plus paranoia and repetitive movements fit the behavioral symptoms of the middle (moderate) stage. Antipsychotics carry a black box warning and are used only when other interventions have failed, and the nurse redirects rather than corrects.', false),
  ('alzheimers', 2, 'A client recently diagnosed with Alzheimer''s disease still lives alone and manages most daily activities. Which findings would the nurse expect at this stage of the disease? Select all that apply.', '[{"id": "a", "text": "Gets lost in familiar places"}, {"id": "b", "text": "Cannot recall the name of spouse"}, {"id": "c", "text": "Difficulty with finances and planning"}, {"id": "d", "text": "Difficulty finding words"}, {"id": "e", "text": "Misplaces objects frequently"}]'::jsonb, '["a", "c", "d", "e"]', 'A client who is still relatively independent is in the early (mild) stage, which includes misplacing objects, difficulty finding words, getting lost in familiar places, and difficulty with complex tasks such as finances and planning. Inability to recall the name of a spouse is a middle-stage finding.', true),
  ('alzheimers', 3, 'A client in the early stage of Alzheimer''s disease is seen in the clinic every 6 months. Which new finding reported by the client''s daughter would indicate that the disease has progressed to the middle stage?', '[{"id": "a", "text": "He has more difficulty finding the right words"}, {"id": "b", "text": "He gets lost when driving to a familiar store"}, {"id": "c", "text": "He misplaces his keys and glasses more frequently"}, {"id": "d", "text": "He cannot recall the name of his spouse"}]'::jsonb, '["d"]', 'Inability to recall the name of a spouse or family members is a middle (moderate) stage finding. Misplacing objects, difficulty finding words, and getting lost in familiar places all occur in the early stage.', false),
  ('alzheimers', 4, 'A client with late-stage Alzheimer''s disease coughs frequently during meals and has a weak swallow. The nurse is preparing the client for lunch. Which action is the PRIORITY?', '[{"id": "a", "text": "Upright position (90°) for meals"}, {"id": "b", "text": "Recline to 45° so the client can rest while eating"}, {"id": "c", "text": "Elevate the head of the bed to 30° for the meal"}, {"id": "d", "text": "Position on the left side with the head slightly raised"}]'::jsonb, '["a"]', 'Late-stage dysphagia carries a high aspiration risk, so the client is placed in an upright position at 90° for meals. Lower angles such as 30° or 45° do not meet this standard.', false),
  ('alzheimers', 5, 'Lunch ended 10 minutes ago for a client with late-stage Alzheimer''s disease and dysphagia. The UAP asks whether the client may lie flat for a nap now. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "Position the client flat on the side in 15 more minutes"}, {"id": "b", "text": "Lower the head of the bed to 30° in 10 more minutes"}, {"id": "c", "text": "Lay the client flat now, since the meal is finished"}, {"id": "d", "text": "Keep the client upright 30–60 minutes after eating"}]'::jsonb, '["d"]', 'The client must remain upright 30–60 minutes after eating because of high aspiration risk. Lying flat at 10, 20, or 25 minutes after the meal falls short of the minimum 30 minutes.', false),
  ('alzheimers', 6, 'A nurse is planning mealtime care for a client with late-stage Alzheimer''s disease who has dysphagia. Which interventions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Check cheeks for food pocketing"}, {"id": "b", "text": "Keep suction at the bedside"}, {"id": "c", "text": "Soft or thickened foods as ordered"}, {"id": "d", "text": "Offer small bites"}, {"id": "e", "text": "Thin liquids to ease swallowing"}]'::jsonb, '["a", "b", "c", "d"]', 'Small bites, checking for food pocketing in the cheeks, suction at the bedside, and soft or thickened foods/liquids as ordered by speech therapy reduce aspiration risk. Thin liquids are not appropriate when thickened liquids are ordered for dysphagia.', true),
  ('alzheimers', 7, 'A nurse on a memory-care unit receives report on four clients with Alzheimer''s disease. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Middle stage: more confused as afternoon turns to evening"}, {"id": "b", "text": "Middle stage: pacing in the secure enclosed courtyard"}, {"id": "c", "text": "Early stage: upset after misplacing her reading glasses"}, {"id": "d", "text": "Late stage: coughing with food pocketing in cheeks"}]'::jsonb, '["d"]', 'A late-stage client with dysphagia who is coughing with food pocketed in the cheeks is at high aspiration risk. Pacing in a secure enclosed area, misplacing objects, and sundowning are expected findings that are already safely managed.', false),
  ('alzheimers', 8, 'A client with mild Alzheimer''s disease started donepezil 2 weeks ago. During a home visit, which finding requires IMMEDIATE follow-up by the nurse?', '[{"id": "a", "text": "Mild nausea when the dose is given with food"}, {"id": "b", "text": "Occasional difficulty finding the right words"}, {"id": "c", "text": "A slow heart rate (bradycardia)"}, {"id": "d", "text": "Misplaces objects several times each day"}]'::jsonb, '["c"]', 'Bradycardia is a key side effect of cholinesterase inhibitors such as donepezil and must be followed up. Mild GI upset is an expected side effect, and word-finding difficulty and misplacing objects are early-stage disease findings.', false),
  ('alzheimers', 9, 'The husband of a client taking donepezil reports that she vomits shortly after he gives the tablet each morning before breakfast. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "Stop the drug, since it does not cure the disease anyway"}, {"id": "b", "text": "Give the dose every other day to reduce the nausea"}, {"id": "c", "text": "Give the drug with food"}, {"id": "d", "text": "Give the dose at bedtime on an empty stomach instead"}]'::jsonb, '["c"]', 'Cholinesterase inhibitors cause N/V/D and should be given with food. The drug does not cure, but it slows progression, so stopping it is not appropriate.', false),
  ('alzheimers', 10, 'The wife of a client with mild-moderate Alzheimer''s disease is taught about donepezil before discharge. Which statements by the wife indicate understanding of the teaching? Select all that apply.', '[{"id": "a", "text": "''It is used mainly in the severe stage.''"}, {"id": "b", "text": "''It will cure his memory loss over time.''"}, {"id": "c", "text": "''It can slow his heart rate (bradycardia).''"}, {"id": "d", "text": "''I''ll give it with food.''"}, {"id": "e", "text": "''It will slow progression, not cure it.''"}]'::jsonb, '["c", "d", "e"]', 'Donepezil is given with food, slows progression without curing, and can cause bradycardia. Cholinesterase inhibitors are used for mild-moderate disease, and they do not cure.', true),
  ('alzheimers', 11, 'A client with Alzheimer''s disease who has taken donepezil for 3 years now needs help with all ADLs and no longer speaks in sentences. The provider adds memantine, and the daughter asks why. Which response by the nurse is BEST?', '[{"id": "a", "text": "''It is used to control agitation and aggression in the late stage.''"}, {"id": "b", "text": "''It blocks excess glutamate and is often combined with donepezil.''"}, {"id": "c", "text": "''It replaces the donepezil, which no longer works at this stage.''"}, {"id": "d", "text": "''It will reverse the memory loss that the plaques have caused.''"}]'::jsonb, '["b"]', 'Memantine is an NMDA antagonist that blocks excess glutamate in moderate-severe disease and is often combined with donepezil. Atypical antipsychotics, not memantine, are used for agitation and aggression, and no drug reverses the disease.', false),
  ('alzheimers', 12, 'A 70-year-old client is newly diagnosed with mild Alzheimer''s disease, lives independently, and has no behavioral symptoms. Which medication should the nurse anticipate the provider will prescribe FIRST?', '[{"id": "a", "text": "Galantamine"}, {"id": "b", "text": "A tricyclic antidepressant"}, {"id": "c", "text": "Memantine alone"}, {"id": "d", "text": "Risperidone"}]'::jsonb, '["a"]', 'Cholinesterase inhibitors such as galantamine are used for mild-moderate disease. Memantine is for moderate-severe disease, antipsychotics are for agitation or psychosis after other interventions fail, and TCAs worsen cognition.', false),
  ('alzheimers', 13, 'The son of a client starting rivastigmine asks, ''How is this supposed to help Mom''s memory?'' Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "''It replaces the tau protein lost from inside neurons.''"}, {"id": "b", "text": "''It blocks the excess glutamate that damages and destroys the neurons over time.''"}, {"id": "c", "text": "''It dissolves the amyloid plaques between the neurons.''"}, {"id": "d", "text": "''It inhibits acetylcholinesterase to increase acetylcholine.''"}]'::jsonb, '["d"]', 'Acetylcholine, the major neurotransmitter for memory and learning, is lost in Alzheimer''s; cholinesterase inhibitors such as rivastigmine inhibit acetylcholinesterase to increase ACh. Blocking excess glutamate is the mechanism of memantine.', false),
  ('alzheimers', 14, 'The daughter of a client with Alzheimer''s disease asks what is happening in her father''s brain. Which explanations by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "Neurofibrillary tangles form inside neurons"}, {"id": "b", "text": "The hippocampus swells, then recovers"}, {"id": "c", "text": "Brain changes reverse with treatment"}, {"id": "d", "text": "Acetylcholine builds up in excess"}, {"id": "e", "text": "Amyloid plaques form between neurons"}]'::jsonb, '["a", "e"]', 'Amyloid plaques are clumps of beta-amyloid between neurons, and neurofibrillary tangles are twisted tau strands inside neurons. Acetylcholine is lost, not in excess; the hippocampus undergoes atrophy; and the disease is irreversible.', true),
  ('alzheimers', 15, 'On admission to a long-term care facility, a client with moderate Alzheimer''s disease who becomes agitated each evening is prescribed risperidone. The care plan shows no other interventions have been tried. Which action by the nurse is BEST?', '[{"id": "a", "text": "Increase the dose if agitation continues after one dose"}, {"id": "b", "text": "Give the risperidone each evening, since it is first-line"}, {"id": "c", "text": "Give risperidone and stop the nondrug calming measures"}, {"id": "d", "text": "Ask that other interventions be tried before risperidone"}]'::jsonb, '["d"]', 'Atypical antipsychotics carry a black box warning for increased risk of death in elderly patients with dementia and are used only when other interventions have failed. They are not first-line and are used cautiously at a low dose.', false),
  ('alzheimers', 16, 'The daughter of a client with Alzheimer''s disease asks whether olanzapine, prescribed for aggression after other measures failed, has any serious risks. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "''It carries a black box warning for increased risk of death.''"}, {"id": "b", "text": "''Its main risk is worse memory from anticholinergic effects.''"}, {"id": "c", "text": "''It has no serious risks when it is given at a low dose.''"}, {"id": "d", "text": "''Its main risk is bradycardia, so we will check the pulse.''"}]'::jsonb, '["a"]', 'Atypical antipsychotics such as olanzapine carry a black box warning for increased mortality in elderly patients with dementia. Anticholinergic effects that worsen cognition describe TCAs, and bradycardia is a side effect of cholinesterase inhibitors.', false),
  ('alzheimers', 17, 'A client with moderate Alzheimer''s disease develops depression and anxiety, and the provider prescribes a tricyclic antidepressant (TCA). Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Question the TCA, as anticholinergic effects worsen cognition"}, {"id": "b", "text": "Give the TCA with food to prevent nausea and bradycardia"}, {"id": "c", "text": "Give the TCA, since antidepressants treat comorbid depression"}, {"id": "d", "text": "Ask to replace the TCA with memantine for the depression"}]'::jsonb, '["a"]', 'TCAs should be avoided because their anticholinergic effects worsen cognition; SSRIs such as sertraline are used for comorbid depression and anxiety. Memantine treats moderate-severe AD, not depression.', false),
  ('alzheimers', 18, 'During a home visit, the wife of a client with middle-stage Alzheimer''s disease says she has put standard door locks on every exit to prevent his wandering. Which recommendation by the nurse is BEST?', '[{"id": "a", "text": "Lock the client in the bedroom each night to stop the wandering"}, {"id": "b", "text": "Remove the locks so the client is not trapped in an emergency"}, {"id": "c", "text": "Use door alarms and coded locks instead of standard locks"}, {"id": "d", "text": "Keep the standard locks and add a second deadbolt to each exit"}]'::jsonb, '["c"]', 'Door alarms and coded locks are recommended because a client may know how to use standard door locks. Adding more standard locks does not solve this problem.', false),
  ('alzheimers', 19, 'A client with middle-stage Alzheimer''s disease on a memory-care unit repeatedly stands at the exit door pushing on the handle. Which intervention by the nurse is MOST appropriate?', '[{"id": "a", "text": "Tell the client firmly that the door is locked"}, {"id": "b", "text": "Move the client to a room next to the exit door"}, {"id": "c", "text": "Cover the door with a curtain to camouflage it"}, {"id": "d", "text": "Post a large, bright ''EXIT'' sign on the door"}]'::jsonb, '["c"]', 'Camouflaging or covering doors with curtains or mirrors reduces exit-seeking in wandering. A bright sign or a room next to the exit draws attention to the door.', false),
  ('alzheimers', 20, 'A client with Alzheimer''s disease walked away from home and was found 2 miles away by police. Which measures should the nurse recommend to the family? Select all that apply.', '[{"id": "a", "text": "Standard door locks on all exits"}, {"id": "b", "text": "Remove door alarms to reduce noise"}, {"id": "c", "text": "GPS tracking devices"}, {"id": "d", "text": "Identification bracelet with name and phone number"}, {"id": "e", "text": "Register with the Safe Return Program"}]'::jsonb, '["c", "d", "e"]', 'An identification bracelet with name and phone number, GPS tracking devices, and registration with the Safe Return Program help locate a client who wanders. Standard door locks are avoided because the client may know how to use them, and door alarms are recommended.', true),
  ('alzheimers', 21, 'A client with middle-stage Alzheimer''s disease paces constantly and becomes more agitated when kept indoors on the unit. Which intervention is BEST?', '[{"id": "a", "text": "Give an antipsychotic each morning to stop pacing"}, {"id": "b", "text": "Keep the client in the room with the door closed"}, {"id": "c", "text": "Provide secure enclosed outdoor areas for walking"}, {"id": "d", "text": "Seat the client in a chair with a lap belt for safety"}]'::jsonb, '["c"]', 'Secure enclosed outdoor areas allow safe wandering. Antipsychotics are reserved for when other interventions have failed because of the black box warning.', false),
  ('alzheimers', 22, 'The wife of a client with Alzheimer''s disease reports that he becomes increasingly confused late each afternoon. To help him sleep, she turns off every light in the house at sunset. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "Let him nap in a dark room through the late afternoon"}, {"id": "b", "text": "Give him coffee in the afternoon so that he stays alert"}, {"id": "c", "text": "Provide soft lighting at dusk and avoid abrupt darkness"}, {"id": "d", "text": "Continue turning off the lights so he learns it is bedtime"}]'::jsonb, '["c"]', 'Increased confusion in the late afternoon/evening is sundowning, managed with soft lighting at dusk and avoiding abrupt darkness. Caffeine in the afternoon should be avoided.', false),
  ('alzheimers', 23, 'A nurse is teaching the daughter of a client with Alzheimer''s disease who has sundowning. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Increase activity and sunlight during the day"}, {"id": "b", "text": "Maintain a consistent daily routine"}, {"id": "c", "text": "Turn the lights off abruptly at dusk"}, {"id": "d", "text": "Plan busy, noisy visits in the evening"}, {"id": "e", "text": "Offer caffeine with the afternoon snack"}]'::jsonb, '["a", "b"]', 'A consistent daily routine and increased activity and sunlight exposure during the day reduce sundowning. Caffeine in the afternoon, abrupt darkness, and a noisy evening environment worsen it; evenings should be calm and quiet.', true),
  ('alzheimers', 24, 'A home health nurse visits a client with moderate Alzheimer''s disease who has had two near-falls this month. Which finding in the home requires follow-up FIRST?', '[{"id": "a", "text": "A night-light in the hallway"}, {"id": "b", "text": "Grab bars installed beside the toilet and tub"}, {"id": "c", "text": "Handrails along the stairway"}, {"id": "d", "text": "Throw rugs in the hallway to the bathroom"}]'::jsonb, '["d"]', 'Throw rugs and clutter should be removed to prevent falls. Grab bars, handrails, and adequate lighting are recommended fall-prevention measures already in place.', false),
  ('alzheimers', 25, 'A hospitalized client with Alzheimer''s disease repeatedly tries to climb out of bed during the night. Which intervention is MOST appropriate?', '[{"id": "a", "text": "Raise the bed to its highest position"}, {"id": "b", "text": "Give a TCA at bedtime to promote sleep"}, {"id": "c", "text": "Turn off all lights so the client sleeps"}, {"id": "d", "text": "Low bed position and bed alarms"}]'::jsonb, '["d"]', 'A low bed position and bed alarms prevent falls. A high bed increases fall risk, adequate lighting is needed, and TCAs worsen cognition through anticholinergic effects.', false),
  ('alzheimers', 26, 'The son of a client with Alzheimer''s disease asks how to make the home safer from falls. Which recommendations should the nurse make? Select all that apply.', '[{"id": "a", "text": "Place throw rugs over slick floors"}, {"id": "b", "text": "Leave items on the floor within reach"}, {"id": "c", "text": "Keep the bed in a high position"}, {"id": "d", "text": "Install grab bars and handrails"}, {"id": "e", "text": "Ensure adequate lighting"}]'::jsonb, '["d", "e"]', 'Grab bars, handrails, and adequate lighting prevent falls. Throw rugs and clutter should be removed, and the bed should be kept in a low position.', true),
  ('alzheimers', 27, 'A UAP walks up behind a client with Alzheimer''s disease and touches her shoulder. The client startles and swings her arm at the UAP. Which instruction should the nurse give the UAP FIRST?', '[{"id": "a", "text": "Approach from the front and establish eye contact"}, {"id": "b", "text": "Speak loudly from the doorway before entering the room"}, {"id": "c", "text": "Ask a second staff member to hold her arms during care"}, {"id": "d", "text": "Approach quietly from behind so she is not alarmed"}]'::jsonb, '["a"]', 'Approaching from the front and establishing eye contact reduces the startle response and helps focus attention. Approaching from behind caused the startle, and raising the voice should be avoided.', false),
  ('alzheimers', 28, 'A client with Alzheimer''s disease whose legal name is Margaret responds only when called ''Peggy.'' A new nurse asks why the staff use the nickname. Which explanation is BEST?', '[{"id": "a", "text": "Staff should switch to her legal name to keep her reoriented"}, {"id": "b", "text": "A preferred name is personally meaningful and retained longer"}, {"id": "c", "text": "A nickname makes the client feel younger and less confused overall"}, {"id": "d", "text": "Using her legal name would be a breach of the client''s privacy"}]'::jsonb, '["b"]', 'Using the patient''s preferred name is personally meaningful and may be retained longer than other information. Switching to an unfamiliar legal name does not help communication.', false),
  ('alzheimers', 29, 'A nurse is helping a client with middle-stage Alzheimer''s disease get dressed for the day. Which approach by the nurse is MOST appropriate?', '[{"id": "a", "text": "Give one step at a time in short, simple sentences"}, {"id": "b", "text": "Lay out several outfits and ask her to choose among them all"}, {"id": "c", "text": "Explain all of the steps first so she knows the whole plan"}, {"id": "d", "text": "Speak loudly so that each instruction is clearly heard"}]'::jsonb, '["a"]', 'Short, simple sentences given one step at a time reduce cognitive overload. Explaining every step at once or offering many choices increases overload, and raising the voice should be avoided.', false),
  ('alzheimers', 30, 'During morning care, a client with Alzheimer''s disease does not seem to understand the words being used and becomes tense. The UAP begins speaking louder. Which action by the nurse is BEST?', '[{"id": "a", "text": "Speak louder and repeat the words more quickly"}, {"id": "b", "text": "Stop all talking and finish the care in silence"}, {"id": "c", "text": "Write out the instructions for the client to read"}, {"id": "d", "text": "Use a slow, calm tone; avoid raising the voice"}]'::jsonb, '["d"]', 'Patients respond to emotional tone even when words are not understood, so a slow, calm tone is used and the voice is not raised. Silence removes a calming emotional cue.', false),
  ('alzheimers', 31, 'A client with Alzheimer''s disease becomes tearful and says, ''I need to call my mother. She''ll be worried about me.'' The client''s mother died 30 years ago. Which response by the nurse is MOST therapeutic?', '[{"id": "a", "text": "''Your mother died many years ago. Don''t you remember that?''"}, {"id": "b", "text": "''I''m sure she is fine. I will call her for you a little later this afternoon.''"}, {"id": "c", "text": "''You miss your mother. Let''s look at your photo album together.''"}, {"id": "d", "text": "''Why do you think that your mother is still alive today?''"}]'::jsonb, '["c"]', 'The nurse validates the emotion and gently redirects to another activity, which reduces distress. Arguing with the confusion increases agitation, a ''why'' question is nontherapeutic, and promising to call is false reassurance.', false),
  ('alzheimers', 32, 'A client with Alzheimer''s disease no longer follows spoken requests during care but watches the nurse closely. Which communication technique is BEST?', '[{"id": "a", "text": "Ask the client to repeat each request back"}, {"id": "b", "text": "Use visual cues such as pointing and gestures"}, {"id": "c", "text": "Repeat the spoken request in a louder voice"}, {"id": "d", "text": "Give a detailed spoken explanation of each step before starting"}]'::jsonb, '["b"]', 'Visual cues such as pointing and gestures compensate for declining verbal comprehension. Louder speech and detailed explanations add stress and cognitive overload.', false),
  ('alzheimers', 33, 'A client with middle-stage Alzheimer''s disease becomes agitated during evening care. Which approaches should the nurse use? Select all that apply.', '[{"id": "a", "text": "Use a slow, calm tone"}, {"id": "b", "text": "Redirect to another activity"}, {"id": "c", "text": "Use visual cues and gestures"}, {"id": "d", "text": "Raise voice so words are heard"}, {"id": "e", "text": "Correct the confused statements"}]'::jsonb, '["a", "b", "c"]', 'A slow, calm tone, redirection to another activity, and visual cues reduce distress and compensate for declining comprehension. Correcting or arguing with confusion increases agitation, and the voice should not be raised.', true),
  ('alzheimers', 34, 'The husband of a client with Alzheimer''s disease says, ''I''m exhausted. I haven''t seen my friends in months, and I cry every night.'' Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Advise him to place his wife in long-term care right now"}, {"id": "b", "text": "Assess for caregiver burnout and discuss respite care"}, {"id": "c", "text": "Suggest he spend more time with his wife in the evening"}, {"id": "d", "text": "Teach him more about the medications his wife takes"}]'::jsonb, '["b"]', 'Fatigue, social isolation, and depression are signs of caregiver burnout, so the nurse assesses the caregiver and discusses respite care such as adult day care. Medication teaching does not address his distress.', false),
  ('alzheimers', 35, 'A client is diagnosed with early-stage Alzheimer''s disease and still manages finances with some help. Which topic is the PRIORITY for the nurse to address with the client and family now?', '[{"id": "a", "text": "Thickened liquids and suction at the bedside for dysphagia"}, {"id": "b", "text": "Incontinence products for bowel and bladder"}, {"id": "c", "text": "Advance directives and power of attorney early"}, {"id": "d", "text": "Bed alarms and a low bed position at night"}]'::jsonb, '["c"]', 'Legal and financial planning, including advance directives and power of attorney, should be done early while the client can participate. Dysphagia and bowel and bladder incontinence are late-stage concerns.', false),
  ('alzheimers', 36, 'The wife of a client with moderate Alzheimer''s disease says, ''I feel like I''m losing him already, and then I feel guilty when I get frustrated with him.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "''He isn''t gone yet, so try to stay positive for his sake each day.''"}, {"id": "b", "text": "''Grief, frustration, and guilt are common feelings for caregivers.''"}, {"id": "c", "text": "''Why do you think you feel so frustrated with your husband lately?''"}, {"id": "d", "text": "''You shouldn''t feel guilty at all; you are doing a wonderful job.''"}]'::jsonb, '["b"]', 'The nurse validates caregiver emotions, including anticipatory grief, frustration, and guilt. Telling her not to feel guilty dismisses her feelings, and a ''why'' question is nontherapeutic.', false),
  ('alzheimers', 37, 'A nurse assesses the daughter who is the primary caregiver for her father with Alzheimer''s disease. Which findings suggest caregiver burnout? Select all that apply.', '[{"id": "a", "text": "Social isolation"}, {"id": "b", "text": "Attends a support group"}, {"id": "c", "text": "Uses adult day care"}, {"id": "d", "text": "Fatigue most days"}, {"id": "e", "text": "Signs of depression"}]'::jsonb, '["a", "d", "e"]', 'Depression, fatigue, and social isolation are signs of caregiver burnout. Attending a support group and using adult day care (respite) are protective resources the nurse recommends.', true),
  ('alzheimers', 38, 'A nurse is developing a support plan for the son who cares for his mother with Alzheimer''s disease. Which interventions should the plan include? Select all that apply.', '[{"id": "a", "text": "Educate on disease progression"}, {"id": "b", "text": "Refer to the Alzheimer''s Association"}, {"id": "c", "text": "Delay advance directives until late stage"}, {"id": "d", "text": "Assist with legal/financial planning early"}, {"id": "e", "text": "Discuss respite care options"}]'::jsonb, '["a", "b", "d", "e"]', 'Referral to the Alzheimer''s Association, respite care, education on disease progression, and early legal/financial planning support the caregiver. Advance directives should be completed early, not delayed until the late stage.', true),
  ('alzheimers', 39, 'A client with late-stage Alzheimer''s disease is bedridden, has dysphagia, and is incontinent of bowel and bladder. Which complication is this client at HIGHEST risk for?', '[{"id": "a", "text": "Sundowning with agitation"}, {"id": "b", "text": "Aspiration and pneumonia"}, {"id": "c", "text": "Getting lost in familiar places"}, {"id": "d", "text": "Wandering and elopement"}]'::jsonb, '["b"]', 'Late-stage dysphagia carries a high aspiration risk, and late-stage clients are susceptible to infections such as pneumonia and UTIs. Wandering, sundowning, and getting lost occur in earlier stages in clients who are still mobile.', false),
  ('alzheimers', 40, 'A hospice nurse admits a client with Alzheimer''s disease. Which findings indicate that the client is in the late (severe) stage? Select all that apply.', '[{"id": "a", "text": "Loss of basic reflexes"}, {"id": "b", "text": "Misplaces objects frequently"}, {"id": "c", "text": "Incontinence of bowel and bladder"}, {"id": "d", "text": "Does not recognize family members"}, {"id": "e", "text": "Loss of ability to communicate verbally"}]'::jsonb, '["a", "c", "d", "e"]', 'Loss of verbal communication, not recognizing family members, bowel and bladder incontinence, and loss of basic reflexes are late-stage findings. Misplacing objects frequently is an early-stage finding.', true),
  ('alzheimers', 41, 'After learning that donepezil will not cure her husband''s Alzheimer''s disease, the client''s wife asks, ''Then what is the point of any treatment?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "''Treatment focuses on slowing progression and managing symptoms.''"}, {"id": "b", "text": "''Treatment will restore his memory if it is started early enough.''"}, {"id": "c", "text": "''Treatment mainly prevents dysphagia from developing in the late stage.''"}, {"id": "d", "text": "''Treatment aims to reverse the plaques before the late stage begins.''"}]'::jsonb, '["a"]', 'No cure exists for this progressive, irreversible disease; treatment focuses on slowing progression and managing symptoms. Plaques are not reversed and memory is not restored.', false),
  ('alzheimers', 42, 'A nurse on a memory-care unit reviews findings for several clients. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Lying flat 10 minutes after eating with dysphagia"}, {"id": "b", "text": "More confusion in the late afternoon"}, {"id": "c", "text": "Suction not available at a dysphagia bedside"}, {"id": "d", "text": "Misplaces objects frequently"}, {"id": "e", "text": "New bradycardia in a client on donepezil"}]'::jsonb, '["a", "c", "e"]', 'Bradycardia is a donepezil side effect requiring follow-up, and a client with dysphagia must remain upright 30–60 minutes after eating and have suction at the bedside. Late-afternoon confusion (sundowning) and misplacing objects are expected findings.', true),
  ('alzheimers', 43, 'The daughter of a client with early Alzheimer''s disease asks, ''Why is it Mom''s memory for recent things that is going first?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "''Recent memories are stored in tau protein, which is lost first.''"}, {"id": "b", "text": "''Atrophy affects the hippocampus, the memory center, early.''"}, {"id": "c", "text": "''Plaques form first in the brainstem, which controls reflexes.''"}, {"id": "d", "text": "''Excess acetylcholine overstimulates the memory center.''"}]'::jsonb, '["b"]', 'Progressive neuron death and brain atrophy especially affect the hippocampus, the memory center, explaining early short-term memory loss. Acetylcholine is lost, not in excess.', false),
  ('alzheimers', 44, 'The daughter of a client newly diagnosed with Alzheimer''s disease has been taught about the stages of the disease. Which statement by the daughter indicates understanding?', '[{"id": "a", "text": "''In the late stage, she will need total help with all ADLs.''"}, {"id": "b", "text": "''In the middle stage, she will become fully independent again.''"}, {"id": "c", "text": "''In the late stage, she will mainly misplace her objects.''"}, {"id": "d", "text": "''In the early stage, she will lose the ability to swallow.''"}]'::jsonb, '["a"]', 'Total dependence for all ADLs occurs in the late stage. Dysphagia is a late-stage finding, the middle stage requires help with ADLs, and misplacing objects is early stage.', false),
  ('alzheimers', 45, 'Speech therapy has ordered thickened liquids for a client with late-stage Alzheimer''s disease. A visiting son brings a cup of regular juice and asks to give it to his mother. Which response by the nurse is BEST?', '[{"id": "a", "text": "''She may have small sips if the head of the bed is at 30°.''"}, {"id": "b", "text": "''She may have it if she lies down afterward to rest a while.''"}, {"id": "c", "text": "''Regular juice is fine if she drinks it slowly through a straw.''"}, {"id": "d", "text": "''She needs thickened liquids as ordered by speech therapy.''"}]'::jsonb, '["d"]', 'Late-stage dysphagia carries a high aspiration risk, so soft or thickened foods/liquids are given as ordered by speech therapy. The client must be upright at 90° and remain upright after eating, so lying down or 30° is unsafe.', false),
  ('alzheimers', 46, 'A client with Alzheimer''s disease hits staff during bathing even after calm approaches and redirection have been used consistently. Olanzapine is prescribed. Which statement by the nurse to the family is MOST accurate?', '[{"id": "a", "text": "''It is given to raise acetylcholine levels in the brain.''"}, {"id": "b", "text": "''It has no special warnings for elderly clients with dementia.''"}, {"id": "c", "text": "''It is used at a low dose and cautiously for aggression.''"}, {"id": "d", "text": "''It is a first-line drug that slows disease progression.''"}]'::jsonb, '["c"]', 'Atypical antipsychotics such as olanzapine are used at a low dose and cautiously for agitation, psychosis, and aggression. Cholinesterase inhibitors raise ACh and slow progression, and antipsychotics carry a black box warning in elderly dementia patients.', false),
  ('alzheimers', 47, 'A nurse assesses a client with Alzheimer''s disease who has progressed beyond the early stage but can still walk and feed himself. Which findings are consistent with the middle (moderate) stage? Select all that apply.', '[{"id": "a", "text": "Forgets personal history"}, {"id": "b", "text": "Wandering behavior"}, {"id": "c", "text": "Confusion about time and place"}, {"id": "d", "text": "Does not recognize family members"}, {"id": "e", "text": "Needs help with dressing and bathing"}]'::jsonb, '["a", "b", "c", "e"]', 'Forgetting personal history, confusion about time and place, needing help with dressing and bathing, and wandering are middle-stage findings. Not recognizing family members is a late-stage finding, whereas in the middle stage the client cannot recall their names.', true),
  ('alzheimers', 48, 'A client with moderate-severe Alzheimer''s disease also has depression. Which medications would the nurse expect to see on this client''s regimen? Select all that apply.', '[{"id": "a", "text": "Risperidone as first-line"}, {"id": "b", "text": "Donepezil (Aricept)"}, {"id": "c", "text": "Memantine (Namenda)"}, {"id": "d", "text": "Sertraline for depression"}, {"id": "e", "text": "A TCA for depression"}]'::jsonb, '["b", "c", "d"]', 'Memantine is often combined with donepezil for moderate-severe disease, and SSRIs such as sertraline treat comorbid depression. TCAs are avoided because anticholinergic effects worsen cognition, and antipsychotics are a last resort.', true),
  ('alzheimers', 49, 'After teaching about Alzheimer''s disease, the nurse evaluates the client''s spouse. Which statements by the spouse indicate understanding? Select all that apply.', '[{"id": "a", "text": "''Memantine will cure her in the severe stage.''"}, {"id": "b", "text": "''Her short-term memory will be lost last.''"}, {"id": "c", "text": "''It is the most common form of dementia.''"}, {"id": "d", "text": "''The disease is progressive and irreversible.''"}, {"id": "e", "text": "''Once the plaques clear, memory will return.''"}]'::jsonb, '["c", "d"]', 'Alzheimer''s disease is the most common form of dementia and is progressive and irreversible. Plaques do not clear, memantine does not cure, and short-term memory loss occurs early, not last.', true),
  ('alzheimers', 50, 'A nurse prepares to help a client with middle-stage Alzheimer''s disease take a bath. Which actions should the nurse take? Select all that apply.', '[{"id": "a", "text": "Begin care from behind"}, {"id": "b", "text": "Give one step at a time"}, {"id": "c", "text": "Use the preferred name"}, {"id": "d", "text": "Approach from the front"}, {"id": "e", "text": "Explain every step at once"}]'::jsonb, '["b", "c", "d"]', 'Approaching from the front reduces the startle response, the preferred name is personally meaningful, and one step at a time reduces cognitive overload. Explaining every step at once causes overload, and approaching from behind startles the client.', true)
  ) AS v(source_key, display_order, stem, options, correct_answer, rationale, is_multi)
  JOIN _mh_seed_map m USING (source_key)
 CROSS JOIN _mh_seed_config c;

DO $$
DECLARE
  v_bad text;
BEGIN
  SELECT string_agg(format('%s=%s', m.source_key, coalesce(n.cnt, 0)), ', ')
    INTO v_bad
    FROM _mh_seed_map m
    LEFT JOIN (SELECT category, count(*) AS cnt FROM test_questions GROUP BY category) n
      ON n.category = m.category
   WHERE coalesce(n.cnt, 0) <> 50;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'Mental Health seed post-check failed (expected 50 per topic): %', v_bad;
  END IF;
END $$;

COMMIT;
